    # custom logging 
    struct TerminateOnWarningLogger <: Logging.AbstractLogger 
        min_level::Logging.LogLevel 
    end 

    function Logging.handle_message(logger::TerminateOnWarningLogger, level, message, _module, group, id, file, line; kwargs...) 
        if level >= logger.min_level
            error("Script terminated due to warning: $message") 
        else 
            Logging.handle_message(current_logger(), level, message, _module, group, id, file, line; kwargs...) 
        end 
    end 

    Logging.shouldlog(logger::TerminateOnWarningLogger, level, _module, group, id) = level >= Logging.Warn
    Logging.min_enabled_level(logger::TerminateOnWarningLogger) = Logging.Warn
    Logging.catch_exceptions(logger::TerminateOnWarningLogger) = true



