    # General functions 

    function is_array(s) 

        return (isa(s,Array) || isa(s,SubArray))
    end 

    function str_cut(s, cutmode, delim, defaultmode) 

        rs = ""
        s_pos = 0
        if (lowercase(strip(cutmode)) == "left" || lowercase(strip(cutmode)) == "right") && isa(delim,String) == true && isa(defaultmode,String) == true
            if delim != "" && length(delim) > 0
                s_pos = get_substrindex(s, delim, "first")
            end
        elseif lowercase(strip(cutmode)) == "mid"
            if isa(delim,String) == true
                if delim != "" && length(delim) > 0
                    s_pos = get_substrindex(s, delim, "first")
                    s_delim = [delim; delim]
                end
            else
                if size(delim,1) == 1
                    if delim[1] != "" && length(delim[1]) > 0
                        s_pos = get_substrindex(s, delim[1], "first")
                        s_delim = [delim[1]; delim[1]]
                    end
                elseif size(delim,1) == 2
                    if delim[1] != "" && length(delim[1]) > 0 && delim[2] != "" && length(delim[2]) > 0
                        s_pos = get_substrindex(s, delim[1], "first")
                        s_delim = [delim[1]; delim[2]]
                    end
                end
            end
        end
        if s_pos > 0
            if lowercase(strip(cutmode)) == "left"
                if s_pos > 1
                    rs = join(SubString(s,1,(s_pos-1)), "")
                end
            elseif lowercase(strip(cutmode)) == "right"
                if s_pos < length(s)
                    rs = join(SubString(s,s_pos+length(delim),length(s)), "")
                end
            elseif lowercase(strip(cutmode)) == "mid"
                if isa(defaultmode,String) == true
                    rs = str_cut(str_cut(s, "right", s_delim[1], defaultmode), "left", s_delim[2], defaultmode) 
                else
                    if size(defaultmode,1) == 1
                        rs = str_cut(str_cut(s, "right", s_delim[1], defaultmode[1]), "left", s_delim[2], defaultmode[1]) 
                    elseif size(defaultmode,1) == 2 
                        rs = str_cut(str_cut(s, "right", s_delim[1], defaultmode[1]), "left", s_delim[2], defaultmode[2])
                    end
                end
            end
        else
            if isa(defaultmode,String) == true
                rs = (lowercase(strip(defaultmode)) == "original") ? s : rs
            else
                if size(defaultmode,1) == 1
                    rs = (lowercase(strip(defaultmode[1])) == "original") ? s : rs
                end
            end
        end

        return rs
    end 

    function str_trim(s) 

        if is_array(s) 
            rs = similar(s, String)
            for i in eachindex(s) 
                @inbounds rs[i] = str_trim(s[i])
            end
        else 
            rs = string(join(strip(join(s, "")), "")) 
        end 
        
        return rs
    end 

    function str_trim_phrase(s, p, mode) 

        if is_array(s) 
            rs = fill("",size(s))
            for i in eachindex(s) 
                @inbounds rs[i] = str_trim_phrase(s[i], p, mode)
            end
        else
            rs = s 
            if length(rs) > 0
                if is_array(p) 
                    xp = p
                else
                    xp = [p]
                end
                xflag = true
                while xflag == true 
                    xflag = false 
                    for i in axes(xp,1)
                        if startswith(rs, xp[i]) && (mode == "prfx" || mode == "both")
                            while startswith(rs, xp[i]) 
                                rs = (length(rs) > length(xp[i])) ? join(SubString(rs,(length(xp[i])+1):length(rs)), "") : "" 
                            end 
                            xflag = true
                        end 
                        if endswith(rs, xp[i]) && (mode == "sffx" || mode == "both")
                            while endswith(rs, xp[i]) 
                                rs = (length(rs) > length(xp[i])) ? join(SubString(rs,1:(length(rs)-length(xp[i]))), "") : "" 
                            end 
                            xflag = true
                        end 
                    end 
                end
            end 
        end
        
        return rs
    end 

    function str_precfloat(s,prec) 

        if eltype(s) <: Float64 
            rs = str_precnum(s,prec,Float64) 
        else 
            rs = str_precnum(s,prec,eltype(s)) 
        end 

        return rs
    end 

    function str_precfloat_m(s,prec,usemacro)

        if usemacro == true 
            if eltype(s) <: Float64 
                rs = str_precnum_m(s,prec,Float64,usemacro) 
            else 
                rs = str_precnum_m(s,prec,eltype(s),usemacro) 
            end 
        else
            if eltype(s) <: Float64 
                rs = str_precnum(s,prec,Float64) 
            else 
                rs = str_precnum(s,prec,eltype(s)) 
            end 
        end

        return rs
    end

    function str_precnum(s,prec,numtype::Type) 

        if is_array(s) 
            rs = fill("",size(s))
            for i in eachindex(s) 
                if eltype(s[i]) <: ForwardDiff.Dual
                    rs[i] = str_enforcenumprecision(convert(numtype,s[i].value),prec)
                else
                    rs[i] = str_enforcenumprecision(convert(numtype,s[i]),prec)
                end
            end
        else
            if eltype(s) <: ForwardDiff.Dual
                rs = str_enforcenumprecision(convert(numtype,s.value),prec)
            else 
                rs = str_enforcenumprecision(convert(numtype,s),prec)
            end 
        end

        return rs
    end 

    function str_precnum_m(s,prec,numtype::Type,usemacro) 

        if is_array(s) 
            rs = fill("",size(s))
            for i in eachindex(s) 
                if usemacro == true 
                    if eltype(s[i]) <: ForwardDiff.Dual
                        rs[i] = str_enforcenumprecision_m(convert(numtype,s[i].value),prec,usemacro)
                    else
                        rs[i] = str_enforcenumprecision_m(convert(numtype,s[i]),prec,usemacro)
                    end
                else
                    if eltype(s[i]) <: ForwardDiff.Dual
                        rs[i] = str_enforcenumprecision(convert(numtype,s[i].value),prec)
                    else
                        rs[i] = str_enforcenumprecision(convert(numtype,s[i]),prec)
                    end
                end 
            end
        else
            if usemacro == true 
                if eltype(s) <: ForwardDiff.Dual
                    rs = str_enforcenumprecision_m(convert(numtype,s.value),prec,usemacro)
                else 
                    rs = str_enforcenumprecision_m(convert(numtype,s),prec,usemacro)
                end 
            else
                if eltype(s) <: ForwardDiff.Dual
                    rs = str_enforcenumprecision(convert(numtype,s.value),prec)
                else 
                    rs = str_enforcenumprecision(convert(numtype,s),prec)
                end 
            end
        end

        return rs
    end 

    function str_enforcenumprecision(s, prec) 

        if is_array(s) 
            rs = fill("",size(s))
            for i in eachindex(s) 
                rs[i] = str_enforcenumprecision(s[i], prec)
            end
        else
            rs = "" 
            if s !== nothing 
                rs = string(s) 
                xtype = Float64 
                if isa(s,Number)
                    xtype = eltype(s)
                end 
                if tryparse(xtype, string(s)) !== nothing 
                    if isinteger(tryparse(xtype,rs)) == true && get_substrindex(lowercase(rs),"e","first") <= 0
                        rs = string(get_trunc(tryparse(xtype,rs)))
                    else
                        if get_substrindex(rs,".","first") > 0
                            xprec = get_trunc(prec)
                            if xprec >= 0 
                                if get_substrindex(lowercase(rs),"e","first") > 0
                                    x__exp = join(SubString(rs,get_substrindex(lowercase(rs),"e","first"),length(rs)),"")
                                    x__pre = join(SubString(rs,1,get_substrindex(lowercase(rs),"e","first")-1),"")
                                    if xprec > 0 
                                        while get_substrindex(x__pre,".","first") > length(x__pre) - xprec
                                            x__pre = string(x__pre, "0")
                                        end
                                        if get_substrindex(x__pre,".","first") < length(x__pre) - xprec
                                            x__pre = join(SubString(x__pre,1,get_substrindex(x__pre,".","first") + xprec),"")
                                        end
                                    else 
                                        if get_substrindex(x__pre,".","first") > 1 
                                            x__pre = join(SubString(x__pre,1,get_substrindex(x__pre,".","first") - 1),"")
                                        else 
                                            x__pre = "0"
                                        end 
                                    end 
                                    rs = string(x__pre,x__exp)
                                else
                                    if xprec > 0 
                                        while get_substrindex(rs,".","first") > length(rs) - xprec
                                            rs = string(rs, "0")
                                        end
                                        if get_substrindex(rs,".","first") < length(rs) - xprec
                                            rs = join(SubString(rs,1,get_substrindex(rs,".","first") + xprec),"")
                                        end
                                    else 
                                        if get_substrindex(rs,".","first") > 1 
                                            rs = join(SubString(rs,1,get_substrindex(rs,".","first") - 1),"")
                                        else 
                                            rs = "0"
                                        end 
                                    end 
                                end
                            end
                        end
                    end
                end
            end
        end

        return rs
    end 
    
    function str_enforcenumprecision_m(s, prec, usemacro) 

        if is_array(s) 
            rs = fill("",size(s))
            for i in eachindex(s) 
                if usemacro == true 
                    rs[i] = str_enforcenumprecision_m(s[i], prec, usemacro)
                else
                    rs[i] = str_enforcenumprecision(s[i], prec)
                end
            end
        else
            if usemacro == true 
                rs = "" 
                if s !== nothing 
                    if eltype(s) <: ForwardDiff.Dual
                        rs = string(s.value) 
                    else
                        rs = string(s) 
                    end 
                    xtype = Float64 
                    if isa(s,Number) && xtype >: ForwardDiff.Dual
                        xtype = eltype(s) 
                    end 
                    if tryparse(xtype, rs) !== nothing && usemacro == true 
                        if usemacro == true 
                            fx = Printf.Format("%.$(prec)g") 
                            rx = tryparse(xtype,rs) 
                            rs = Printf.format(fx,rx) 
                        end 
                    end 
                    if tryparse(xtype, string(s)) !== nothing 
                        if isinteger(tryparse(xtype,rs)) == true && get_substrindex(lowercase(rs),"e","first") <= 0 
                            rs = string(get_trunc(tryparse(xtype,rs))) 
                        else 
                            if get_substrindex(rs,".","first") > 0 
                                xprec = get_trunc(prec) 
                                if xprec >= 0 
                                    if get_substrindex(lowercase(rs),"e","first") > 0 
                                        x__exp = join(SubString(rs,get_substrindex(lowercase(rs),"e","first"),length(rs)),"") 
                                        x__pre = join(SubString(rs,1,get_substrindex(lowercase(rs),"e","first")-1),"") 
                                        if xprec > 0 
                                            while get_substrindex(x__pre,".","first") > length(x__pre) - xprec 
                                                x__pre = string(x__pre, "0") 
                                            end 
                                            if get_substrindex(x__pre,".","first") < length(x__pre) - xprec 
                                                x__pre = join(SubString(x__pre,1,get_substrindex(x__pre,".","first") + xprec),"") 
                                            end 
                                        else 
                                            if get_substrindex(x__pre,".","first") > 1 
                                                x__pre = join(SubString(x__pre,1,get_substrindex(x__pre,".","first") - 1),"") 
                                            else 
                                                x__pre = "0" 
                                            end 
                                        end 
                                        rs = string(x__pre,x__exp) 
                                    else 
                                        if xprec > 0 
                                            while get_substrindex(rs,".","first") > length(rs) - xprec 
                                                rs = string(rs, "0") 
                                            end 
                                            if get_substrindex(rs,".","first") < length(rs) - xprec 
                                                rs = join(SubString(rs,1,get_substrindex(rs,".","first") + xprec),"") 
                                            end 
                                        else 
                                            if get_substrindex(rs,".","first") > 1 
                                                rs = join(SubString(rs,1,get_substrindex(rs,".","first") - 1),"") 
                                            else 
                                                rs = "0" 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
            else 
                rs = str_enforcenumprecision(s, prec) 
            end 
        end 

        return rs 
    end 

    function str_enforcelength(s, len, fstr, dir) 

        if is_array(s) 
            rs = fill("",size(s))
            for i in eachindex(s) 
                rs[i] = str_enforcelength(s[i], len, fstr, dir)
            end
        else
            xlen = get_trunc(len)
            if xlen > 0 
                rs = string(s) 
                if length(rs) > xlen 
                    if dir == "L2R"
                        rs = join(SubString(rs,1,xlen),"")
                    elseif dir == "R2L"
                        rs = join(SubString(rs,length(rs)-xlen+1,xlen),"")
                    end 
                elseif length(rs) < xlen 
                    while length(rs) < xlen
                        if dir == "L2R"
                            rs = string(rs, fstr)
                        elseif dir == "R2L"
                            rs = string(fstr, rs)
                        end 
                    end
                end 
            else 
                rs = ""
            end
        end

        return rs
    end 

    function str_getstdbool(x) 

        return (x ? "true " : "false")
    end 

    function str_getstdnum(x,len,fval,mode) 

        rs = string(x) 
        while length(rs) < len
            if mode == "prfx" 
                rs = string(fval,rs)
            elseif mode == "sffx" 
                rs = string(rs,fval)
            end 
        end 

        return rs
    end 

    function conv_Vec2Row(x) 

        if is_array(x) 
            rs = reshape(vec(x),1,size(vec(x),1))
        else 
            rs = [x]
        end

        return rs
    end 

    function conv_value(physcnsts, physconvs, val, units_ini, units_fin) 

        if is_array(val) 
            rs = deepcopy(val) 
            for i in eachindex(val) 
                if is_array(units_ini) 
                    if is_array(units_fin) 
                        rs[i] = conv_value(physcnsts, physconvs, val[i], units_ini[i], units_fin[i])
                    else
                        rs[i] = conv_value(physcnsts, physconvs, val[i], units_ini[i], units_fin)
                    end
                else
                    if is_array(units_fin) 
                        rs[i] = conv_value(physcnsts, physconvs, val[i], units_ini, units_fin[i])
                    else
                        rs[i] = conv_value(physcnsts, physconvs, val[i], units_ini, units_fin)
                    end
                end
            end
        else 
            rs = val
            x_units_ini = replace(replace(replace(lowercase(str_trim(units_ini)), " " => ""), "sec" => "s"), "-" => "*") 
            x_units_fin = replace(replace(replace(lowercase(str_trim(units_fin)), " " => ""), "sec" => "s"), "-" => "*")  
            if x_units_ini != x_units_fin 
                if x_units_ini == "ev" 
                    if x_units_fin == "j" || x_units_fin == "joule"
                        rs = rs * physconvs.J_eV
                    end
                elseif x_units_ini == "j" || x_units_ini == "joule"
                    if x_units_fin == "ev"
                        rs = rs / physconvs.J_eV
                    end
                elseif x_units_ini == "bar"
                    if x_units_fin == "pa" || x_units_fin == "pascal"
                        rs = rs * physconvs.Pa_bar
                    end
                elseif x_units_ini == "pa" || x_units_ini == "pascal"
                    if x_units_fin == "bar"
                        rs = rs / physconvs.Pa_bar
                    end
                elseif x_units_ini == "g" || x_units_ini == "gram" 
                    if x_units_fin == "kg"
                        rs = rs / physconvs.g_kg
                    end
                elseif x_units_ini == "kg" 
                    if x_units_fin == "g" || x_units_fin == "gram"
                        rs = rs * physconvs.g_kg
                    end
                elseif x_units_ini == "g/mol" || x_units_ini == "gram/mol" 
                    if x_units_fin == "kg/mol"
                        rs = rs / physconvs.g_kg
                    end
                elseif x_units_ini == "kg/mol" 
                    if x_units_fin == "g/mol" || x_units_fin == "gram/mol"
                        rs = rs * physconvs.g_kg
                    end
                elseif x_units_ini == "m"
                    if x_units_fin == "cm"
                        rs = rs / physconvs.m_cm
                    elseif x_units_fin == "angstrom"
                        rs = rs / physconvs.m_Ang
                    end
                elseif x_units_ini == "cm" 
                    if x_units_fin == "m"
                        rs = rs * physconvs.m_cm
                    end
                elseif x_units_ini == "angstrom" 
                    if x_units_fin == "m"
                        rs = rs * physconvs.m_Ang
                    end
                elseif x_units_ini == "1/cm" 
                    if x_units_fin == "1/m"
                        rs = rs / physconvs.m_cm
                    end
                elseif x_units_ini == "1/m" 
                    if x_units_fin == "1/cm"
                        rs = rs * physconvs.m_cm
                    end
                elseif x_units_ini == "angstrom^2" 
                    if x_units_fin == "m^2"
                        rs = rs * physconvs.m_Ang * physconvs.m_Ang
                    end
                elseif x_units_ini == "m^2" 
                    if x_units_fin == "angstrom^2"
                        rs = rs / (physconvs.m_Ang * physconvs.m_Ang)
                    end
                elseif x_units_ini == "amu*angstrom"
                    if x_units_fin == "kg*m"
                        rs = rs * (physcnsts.amu.value * physconvs.m_Ang) 
                    end
                elseif x_units_ini == "kg*m"
                    if x_units_fin == "amu*angstrom"
                        rs = rs / (physcnsts.amu.value * physconvs.m_Ang) 
                    end
                elseif x_units_ini == "amu*angstrom^2"
                    if x_units_fin == "kg*m^2" 
                        rs = rs * (physcnsts.amu.value * (physconvs.m_Ang * physconvs.m_Ang)) 
                    end
                elseif x_units_ini == "kg*m^2"
                    if x_units_fin == "amu*angstrom^2"
                        rs = rs / (physcnsts.amu.value * (physconvs.m_Ang * physconvs.m_Ang)) 
                    end
                elseif x_units_ini == "c"
                    if x_units_fin == "k"
                        rs = rs + 273.15
                    end
                elseif x_units_ini == "k"
                    if x_units_fin == "c"
                        rs = rs - 273.15
                    end
                elseif x_units_ini == "ev/k"
                    if x_units_fin == "j/k" || x_units_fin == "joule/k"
                        rs = rs * physconvs.J_eV
                    end
                elseif x_units_ini == "j/k" || x_units_ini == "joule/k"
                    if x_units_fin == "ev/k"
                        rs = rs / physconvs.J_eV
                    end
                elseif x_units_ini == "ev*s"
                    if x_units_fin == "j*s" || x_units_fin == "joule*s" 
                        rs = rs * physconvs.J_eV
                    end
                elseif x_units_ini == "j*s" || x_units_ini == "joule*s" 
                    if x_units_fin == "ev*s"
                        rs = rs / physconvs.J_eV
                    end
                elseif x_units_ini == "ev*m"
                    if x_units_fin == "j*m" || x_units_fin == "joule*m" 
                        rs = rs * physconvs.J_eV
                    end
                elseif x_units_ini == "j*m" || x_units_ini == "joule*m" 
                    if x_units_fin == "ev*m" 
                        rs = rs / physconvs.J_eV
                    end
                elseif x_units_ini == "h" || x_units_ini == "hr" 
                    if x_units_fin == "s" || x_units_fin == "sec" 
                        rs = rs * physconvs.s_hr 
                    end
                elseif x_units_ini == "s" || x_units_ini == "sec" 
                    if x_units_fin == "h" || x_units_fin == "hr" 
                        rs = rs / physconvs.s_hr 
                    end
                else
                    println("ERROR -- UNITS CONVERSION NOT FOUND: {",x_units_ini,"} {",x_units_fin,"}")
                end
            end
        end

        return rs
    end 

    function conv_str2numary(s, delim, datatype) 
        
        trs = Array{String,1}(undef,0) 
        x__ary = split(s, delim)
        for i in axes(x__ary,1)
            x__ary[i] = join(x__ary[i], "")
            if x__ary[i] !== nothing
                if x__ary[i] != "" && tryparse(datatype, x__ary[i]) !== nothing
                    push!(trs, string(tryparse(datatype, x__ary[i])))  
                end
            end
        end 
        rs = zeros(datatype,(size(trs,1),1)) 
        for i in axes(trs,1)
            rs[i] = tryparse(datatype, trs[i])
        end 

        return rs
    end

    function join_ary(err_flag, err_msg, a, b, delim) 

        rs = nothing
        if err_flag == false 
            if is_array(a) && is_array(b)
                if size(a) != size(b) 
                    err_flag = true 
                end 
            end 
        end 
        if err_flag == false 
            if is_array(a) 
                rs = fill("",size(a))
                for i in eachindex(a)
                    if is_array(b)
                        rs[i] = string(a[i],delim,b[i]) 
                    else 
                        rs[i] = string(a[i],delim,b) 
                    end 
                end 
            else 
                if is_array(b)
                    rs = fill("",size(b))
                    for i in eachindex(b)
                        rs[i] = string(a,delim,b[i]) 
                    end 
                else 
                    rs = string(a,delim,b) 
                end 
            end 
        end 

        return rs
    end 

    function try_parse(err_flag, err_msg, s, dflt) 

        vld_flag = false 
        if is_array(s) == true 
            rs = similar(s,typeof(dflt))
            rs .= dflt 
            for i in eachindex(s) 
                err_flag, err_msg, vld_flag, trs = try_parse(err_flag, err_msg, s[i], dflt) 
                if err_flag == false && vld_flag == true 
                    rs[i] = trs 
                end 
                if err_flag == true 
                    break 
                end 
            end 
        else 
            rs = dflt 
            trs = tryparse(typeof(dflt),string(s)) 
            if trs !== nothing 
                vld_flag = true 
                rs = trs 
            end 
        end 

        return err_flag, err_msg, vld_flag, rs 
    end 

    function try_parse_v2(err_flag, err_msg, s, dflt) 

        vld_flag = false 
        if is_array(s) == true 
            rs = similar(s,typeof(dflt))
            rs .= dflt 
            for i in eachindex(s) 
                err_flag, err_msg, vld_flag, trs = try_parse(err_flag, err_msg, s[i], dflt) 
                if err_flag == false && vld_flag == true 
                    rs[i] = trs 
                end 
                if err_flag == true 
                    break 
                end 
            end 
        else 
            rs = dflt 
            if typeof(dflt) == Double64 
                trs = tryparse(BigFloat,string(s))
            else 
                trs = tryparse(typeof(dflt),string(s)) 
            end 
            if trs !== nothing 
                vld_flag = true 
                if typeof(dflt) == Double64 
                    rs = tryparse(typeof(dflt),string(s)) 
                else 
                    rs = trs 
                end 
            end 
        end 

        return err_flag, err_msg, vld_flag, rs 
    end 

    function get_trunc(s) 

        if is_array(s) == true 
            rs = zeros(Int,size(s)) 
            for i in eachindex(s) 
                rs[i] = get_trunc(s[i]) 
            end 
        else 
            if s > zero(s)
                rs = floor(Int,s)
            elseif s < zero(s) 
                rs = -1 * floor(Int,abs(s))
            else
                rs = convert(Int,0)
            end 
        end 

        return rs 
    end 

    function get_realvalue(s) 

        if is_array(s) == true 
            if eltype(s) <: ForwardDiff.Dual
                rs = zeros(eltype(get_realvalue(s[1])),size(s)) 
                for i in eachindex(s) 
                    rs[i] = get_realvalue(s[i]) 
                end 
            else
                rs = deepcopy(s)
            end
        else 
            if eltype(s) <: ForwardDiff.Dual 
                rs = get_realvalue(s.value)
            else 
                rs = s
            end 
        end 

        return rs 
    end 

    function get_pairdists_dist(a, b, dims, sqrtflag, x__zero, x__posone, x__negone, x__isdual) 

        x__sx_flag = false 
        @inbounds for k in 1:dims 
            x__a = a[k] 
            x__b = b[k] 
            if x__isdual == true 
                x__rx = x__a - x__b
                if x__sx_flag == true 
                    x__sx += x__rx * x__rx 
                else 
                    x__sx  = x__rx * x__rx 
                    x__sx_flag = true 
                end 
            else 
                if x__a == x__zero 
                    if x__b == x__zero 

                    elseif x__b == x__posone 
                        if x__sx_flag == true 
                            x__sx += x__posone
                        else 
                            x__sx  = x__posone
                            x__sx_flag = true 
                        end 
                    elseif x__b == x__negone 
                        if x__sx_flag == true 
                            x__sx += x__posone
                        else 
                            x__sx  = x__posone
                            x__sx_flag = true 
                        end 
                    else 
                        if x__sx_flag == true 
                            x__sx += x__b * x__b 
                        else 
                            x__sx  = x__b * x__b 
                            x__sx_flag = true 
                        end 
                    end 
                elseif x__a == x__posone 
                    if x__b == x__zero 
                        if x__sx_flag == true 
                            x__sx += x__posone
                        else 
                            x__sx   = x__posone
                            x__sx_flag = true 
                        end 
                    elseif x__b == x__posone 

                    elseif x__b == x__negone 
                        if x__sx_flag == true 
                            x__sx += 4 * x__posone
                        else 
                            x__sx  = 4 * x__posone
                            x__sx_flag = true 
                        end 
                    else 
                        x__rx  = x__a - x__b 
                        if x__sx_flag == true 
                            x__sx += x__rx * x__rx
                        else 
                            x__sx  = x__rx * x__rx
                            x__sx_flag = true 
                        end 
                    end 
                elseif x__a == x__negone 
                    if x__b == x__zero 
                        if x__sx_flag == true 
                            x__sx += x__posone
                        else 
                            x__sx   = x__posone
                            x__sx_flag = true 
                        end 
                    elseif x__b == x__posone 
                        if x__sx_flag == true 
                            x__sx += 4 * x__posone
                        else 
                            x__sx  = 4 * x__posone
                            x__sx_flag = true 
                        end 
                    elseif x__b == x__negone 

                    else 
                        x__rx  = x__a - x__b 
                        if x__sx_flag == true 
                            x__sx += x__rx * x__rx
                        else 
                            x__sx  = x__rx * x__rx
                            x__sx_flag = true 
                        end 
                    end 
                else 
                    if x__b == x__zero 
                        if x__sx_flag == true 
                            x__sx += x__a * x__a
                        else 
                            x__sx  = x__a * x__a
                            x__sx_flag = true 
                        end 
                    elseif x__b == x__posone 
                        x__rx  = x__a - x__b 
                        if x__sx_flag == true 
                            x__sx += x__rx * x__rx
                        else 
                            x__sx  = x__rx * x__rx
                            x__sx_flag = true 
                        end 
                    elseif x__b == x__negone 
                        x__rx  = x__a - x__b 
                        if x__sx_flag == true 
                            x__sx += x__rx * x__rx
                        else 
                            x__sx  = x__rx * x__rx
                            x__sx_flag = true 
                        end 
                    else 
                        x__rx  = x__a - x__b 
                        if x__sx_flag == true 
                            x__sx += x__rx * x__rx
                        else 
                            x__sx  = x__rx * x__rx
                            x__sx_flag = true 
                        end 
                    end 
                end
            end 
        end 
        if x__sx_flag == false 
            x__sx = x__zero 
        end 
        if x__isdual == true
            if sqrtflag == true 
                rs = sqrt(x__sx) 
            else 
                rs = x__sx 
            end 
        else 
            if x__sx > x__zero 
                if sqrtflag == true 
                    if x__sx != x__posone
                        rs = sqrt(x__sx) 
                    else
                        rs = x__sx 
                    end
                else 
                    rs = x__sx 
                end 
            else 
                rs = x__zero 
            end 
        end
    
        return rs 
    end 

    function get_pairdists_self(pairdists, A, dims, sqrtflag, threaded) 

        x__zero   = zero(eltype(pairdists)) 
        x__posone = one(eltype(pairdists)) 
        x__negone = -1 * one(eltype(pairdists)) 
        x__isdual = (eltype(A) <: ForwardDiff.Dual) 
        @inbounds for i in 1:size(A,2)
            for j in 1:(i-1)
                pairdists[j,i] = get_pairdists_dist(view(A,:,j), view(A,:,i), dims, sqrtflag, x__zero, x__posone, x__negone, x__isdual) 
                pairdists[i,j] = pairdists[j,i]
            end 
            pairdists[i,i] = x__zero
        end 
        Symmetric(pairdists)
    end 

    function get_view(ary) 

        if length(ary) > 0 
            rs = fill(ary[1],size(ary))
            for i in eachindex(ary)
                rs[i] = ary[i]
            end 
        else 
            rs = Array{eltype(ary),ndims(ary)}(undef,ntuple(_ -> 0, ndims(ary)))
        end 

        return rs
    end 

    function get_transpose(ary) 

        if length(ary) > 0 
            if ndims(ary) == 1 
                rs = get_view(reshape(ary,1,size(ary,1)))
                for i in axes(ary,1)
                    rs[1,i] = ary[i]
                end 
            elseif ndims(ary) == 2 
                rs = fill(ary[1],size(ary,2),size(ary,1))
                for i in axes(ary,1)
                    for j in axes(ary,2)
                        rs[j,i] = ary[i,j]
                    end 
                end 
            else 
                rs = Array{eltype(ary),ndims(ary)}(undef,ntuple(_ -> 0, ndims(ary)))
            end 
        else 
            rs = Array{eltype(ary),ndims(ary)}(undef,ntuple(_ -> 0, ndims(ary)))
        end 

        return rs
    end 

    function get_configdata(config_data, id_str, node, prfx) 

        # config_data::Dict{String,Array{ct__ConfigRecord(id_str::String, index=Int, vals=Dict{String,String})}} 

        # Create temporary array of current node
        if isa(node,Array{OrderedCollections.OrderedDict}) 
            xnodes = node 
        elseif isa(node,OrderedCollections.OrderedDict) 
            xnodes = OrderedCollections.OrderedDict[node] 
        elseif isa(node,Array{Any})
            xnodes = node 
        else 
            xnodes = Array{OrderedCollections.OrderedDict,1}(undef,0)
        end 
        
        # process node(s) 
        if size(xnodes,1) > 0 

            # Detect whether dataroot is present
            init_pos = (i=0, j=0) 
            for i in axes(xnodes,1) 
                xkeys = collect(keys(xnodes[i]))
                for j in axes(xkeys,1) 
                    if xkeys[j] == "dataroot" 
                        init_pos = (i=i, j=j) 
                        id_str = "" 
                        break  
                    end 
                end 
                if init_pos.i > 0 
                    break 
                end 
            end 

            # Detect whether there are any array child nodes 
            ary_flag = false 
            for i in axes(xnodes,1) 
                if init_pos.i <= 0 || (init_pos.i > 0 && i == init_pos.i) 
                    xkeys = collect(keys(xnodes[i]))
                    for j in axes(xkeys,1)
                        if init_pos.i <= 0 || (init_pos.i > 0 && j == init_pos.j)
                            if isa(xnodes[i][xkeys[j]],Array{OrderedCollections.OrderedDict}) || isa(xnodes[i][xkeys[j]],OrderedCollections.OrderedDict) || isa(xnodes[i][xkeys[j]],Array{Any})
                                ary_flag = true 
                            end 
                        end 
                        if ary_flag == true 
                            break 
                        end 
                    end 
                end 
                if ary_flag == true 
                    break 
                end 
            end 

            # process current node(s) 
            for i in axes(xnodes,1) 
                if init_pos.i <= 0 || (init_pos.i > 0 && i == init_pos.i) 
                    xkeys = collect(keys(xnodes[i]))
                    if ary_flag == false 
                        if haskey(config_data,id_str) == false 
                            config_data[id_str] = Array{ct__ConfigRecord,1}(undef,0) 
                        end 
                        vals = Dict{String,String}()
                    end 
                    for j in axes(xkeys,1) 
                        if init_pos.i <= 0 || (init_pos.i > 0 && j == init_pos.j)
                            if isa(xnodes[i][xkeys[j]],Array{OrderedCollections.OrderedDict}) || isa(xnodes[i][xkeys[j]],OrderedCollections.OrderedDict) || isa(xnodes[i][xkeys[j]],Array{Any})
                                x_id_str = id_str 
                                if xkeys[j] != "dataroot" 
                                    x_id_str = string(id_str,(length(id_str) > 0 ? "|" : ""),xkeys[j])
                                end 
                                get_configdata(config_data, x_id_str, xnodes[i][xkeys[j]], string(prfx,"    ")) 
                            else 
                                if ary_flag == false 
                                    vals[xkeys[j]] = string(xnodes[i][xkeys[j]]) 
                                end 
                            end 
                        end 
                    end 
                    if ary_flag == false 
                        index = size(config_data[id_str],1)
                        push!(config_data[id_str],ct__ConfigRecord(id_str,index,deepcopy(vals)))
                    end 
                end 
            end 
        end 
    end 

    function get_configrecords(err_flag, err_msg, config_data, id_str) 
        
        # config_data::Dict{String,Array{ct__ConfigRecord(id_str::String, index::Int, vals::Dict{String,String})}}
        
        rs = Array{ct__ConfigRecord,1}(undef,0) 
        if err_flag == false 
            if haskey(config_data,id_str)
                err_flag = false 
                err_msg = "" 
                for i in 1:size(config_data[id_str],1)
                    push!(rs,config_data[id_str][i])
                end 
            end 
        end 

        return err_flag, err_msg, rs
    end 

    function get_configproperty(err_flag, err_msg, props, dflts, keyfield, keyname, valfield, valdefault, datatype, allowblank, strtrim, strtextcase) 

        # config_data::Dict{String,Array{ct__ConfigRecord(id_str::String, index::Int, vals::Dict{String,String})}}

        rs = Array{String,1}(undef,0)
        if err_flag == false 
            err_flag = true 
            err_msg = "key field is not present"
            rsflag = false 
            x__keyfield = Array{String,1}(undef,0)
            x__keyname = Array{String,1}(undef,0) 
            if is_array(keyfield) == true && is_array(keyname) == true 
                if size(keyfield,1) > 0 && size(keyfield,1) == size(keyname,1) 
                    for i in axes(keyfield,1)
                        if isa(keyfield[i],String) == true && isa(keyname[i],String) == true 
                            if keyfield[i] != "" || keyname[i] != "" 
                                err_flag = false
                                push!(x__keyfield,keyfield[i])
                                push!(x__keyname,keyname[i])
                            end
                        end 
                    end 
                end 
            elseif isa(keyfield,String) == true && isa(keyname,String) == true 
                if keyfield != "" || keyname != "" 
                    err_flag = false
                    push!(x__keyfield,keyfield)
                    push!(x__keyname,keyname)
                end
            end 
            if size(x__keyfield,1) <= 0 || size(x__keyfield,1) != size(x__keyname,1)
                err_flag = true 
                err_msg = "key field array length does not match key name array length" 
            end 
            if err_flag == false 
                if rsflag == false && props !== nothing 
                    if isa(props,Array{ct__ConfigRecord})
                        for i in axes(props,1) 
                            x__indxs = Array{Int,1}(undef,0)
                            for j in axes(x__keyfield,1)
                                if x__keyfield[j] == "" || haskey(props[i].vals, x__keyfield[j]) == true 
                                    if j == size(x__keyfield,1) 
                                        push!(x__indxs,j)
                                    end
                                else 
                                    break 
                                end 
                            end
                            if size(x__indxs,1) > 0 
                                for j in axes(x__indxs,1)
                                    if get_objectpropertyvalue(props[i].vals, x__keyfield[x__indxs[j]], "") == x__keyname[x__indxs[j]]
                                        if j == size(x__indxs,1) 
                                            if haskey(props[i].vals,valfield) 
                                                if string(props[i].vals[valfield]) != "" || allowblank == true 
                                                    push!(rs,string(props[i].vals[valfield])) 
                                                    rsflag = true 
                                                end 
                                            end 
                                        end 
                                    else
                                        break
                                    end
                                end 
                            end 
                            if rsflag == true 
                                break 
                            end 
                        end
                    elseif isa(props,Dict) && size(x__keyfield,1) == 1
                        if haskey(props,x__keyname[1]) 
                            if string(props[x__keyname[1]]) != "" || allowblank == true 
                                push!(rs,string(props[x__keyname[1]])) 
                                rsflag = true 
                            end 
                        end 
                    end
                end
                if rsflag == false && dflts !== nothing 
                    if isa(dflts,Array{ct__ConfigRecord})
                        for i in axes(dflts,1) 
                            x__indxs = Array{Int,1}(undef,0)
                            for j in axes(x__keyfield,1)
                                if x__keyfield[j] == "" || haskey(dflts[i].vals, x__keyfield[j]) == true 
                                    if j == size(x__keyfield,1) 
                                        push!(x__indxs,j)
                                    end
                                else 
                                    break 
                                end 
                            end
                            if size(x__indxs,1) > 0 
                                for j in axes(x__indxs,1)
                                    if get_objectpropertyvalue(dflts[i].vals, x__keyfield[x__indxs[j]], "") == x__keyname[x__indxs[j]]
                                        if j == size(x__indxs,1) 
                                            if haskey(dflts[i].vals,valfield) 
                                                if string(dflts[i].vals[valfield]) != "" || allowblank == true 
                                                    push!(rs,string(dflts[i].vals[valfield])) 
                                                    rsflag = true 
                                                end 
                                            end 
                                        end 
                                    else
                                        break
                                    end
                                end 
                            end 
                            if rsflag == true 
                                break 
                            end 
                        end
                    elseif isa(dflts,Dict) && size(x__keyfield,1) == 1
                        if haskey(dflts,x__keyname[1]) 
                            if string(dflts[x__keyname[1]]) != "" || allowblank == true 
                                push!(rs,string(dflts[x__keyname[1]])) 
                                rsflag = true 
                            end 
                        end 
                    end
                end
                if rsflag == false
                    push!(rs,string(valdefault))
                end
                if lowercase(str_trim(datatype)) == "string" 
                    if strtrim == true 
                        rs .= str_trim(rs) 
                    end 
                    if lowercase(strip(strtextcase)) == "upper" 
                        rs .= uppercase.(rs) 
                    elseif lowercase(strip(strtextcase)) == "lower" 
                        rs .= lowercase.(rs) 
                    end 
                end
                if rsflag == false && allowblank == false 
                    err_flag = true 
                    err_msg = "a blank value is disallowed"
                end
            end
        end 
        if size(rs,1) <= 0 
            push!(rs,"")
        end 

        return err_flag, err_msg, datatype, rs
    end 

    function get_confignumber(err_flag::Bool, err_msg::String, prop_type::Type, prop_value::String, prop_default::String, strtrim::Bool, removedashes::Bool, requirepresent::Bool, requirepositive::Bool, requirenonnegative::Bool) 

        trs = zeros(prop_type,(1,1)) 
        trs[1] = tryparse(prop_type, prop_default) 
        if err_flag == false 
            err_flag = true 
            x_val = string(prop_value) 
            x_val = removedashes ? replace(x_val, "--" => "") : x_val 
            x_val = strtrim ? str_trim(x_val) : x_val 
            if requirepresent == false || (requirepresent == true && length(x_val) > 0) 
                if length(x_val) > 0 
                    n_val = tryparse(prop_type, x_val) 
                    trs[1] = n_val !== nothing ? n_val : trs[1] 
                end 
                if requirepositive == true 
                    if trs[1] > zero(trs[1]) 
                        err_flag = false 
                    end 
                else 
                    err_flag = false 
                    if requirenonnegative == true 
                        trs[1] = max(trs[1],zero(trs[1])) 
                    end 
                end 
            end 
        end 
        rs = trs[1] 
        
        return err_flag, err_msg, rs 
    end 

    function get_objectpropertyvalue(obj, prop, dflt) 

        rs = dflt 
        if haskey(obj, prop)
            rs = obj[prop]
        end 

        return rs
    end

    function get_substrindex(s, v, mode) 

        rs = -1
        rsx = (lowercase(strip(mode)) == "first") ? findfirst(v,s) : findlast(v,s)   # returns a range variable
        if isa(rsx, Nothing) == false
            if length(rsx) > 0
                rs = rsx[1]          # the beginning of the substring is at element [1] of the range variable
            end
        end

        return rs
    end 

    function get_bool(s) 

        return ((isa(s, Bool) == true) ? s : ((lowercase(str_trim(s)) == "true") ? true : false))
    end

    function get_number(s, datatype) 

        return ((isa(s, Number) == true) ? s : parse(getfield(Base, Symbol(datatype)),s))
    end

    function get_elem(m, index) 

        return m[index]
    end

    function get_elemindex(vec, val, default::Int) 

        if is_array(val) == true 
            rs = similar(val, Int)
            rs .= default 
        else 
            rs = default 
        end 
        if is_array(vec) == true 
            if is_array(val) == true 
                for i in eachindex(val) 
                    @inbounds rs[i] = get_elemindex(vec, val[i], default) 
                end 
            else 
                for i in eachindex(vec) 
                    if vec[i] == val 
                        rs = i 
                        break 
                    end 
                end 
            end 
        end 
        
        return rs
    end

    function get_power(a, b) 
        
        if is_array(a) == true || is_array(b) == true 
            rs = a .^ b 
        else 
            rs = a ^ b
        end 

        return rs
    end 

    function get_floor(a) 

        return floor(a) 
    end

    function get_numberclass(v) 

        if isa(v,BigFloat)
            rs = "bigfloat"
        elseif isa(v,Double64)
            rs = "double64"
        else 
            rs = "float64"
        end

        return rs
    end 

    function get_decimaldigits(s) 

        if is_array(s) 
            rs = similar(s,Int)
            @inbounds for i in eachindex(s) 
                rs[i] = get_decimaldigits(s[i])
            end
        else
            rs = 0 
            if length(string(s)) > 0 
                pos = get_substrindex(string(s),".","first")
                if pos > 0 
                    rs = max((length(string(s)) - pos),0)
                end 
            end 
        end

        return rs
    end 

    function get_uniquerowindxs(ary,tol) 

        rs = Array{Int,1}(undef,0) 
        for i in 1:size(ary,1)
            x__flag = true 
            for j in 1:i-1 
                if ndims(ary) == 1 
                    if tol > 0 
                        if abs(ary[i] - ary[j]) < tol
                            x__flag = false 
                        end 
                    else 
                        if ary[i] == ary[j]
                            x__flag = false 
                        end
                    end 
                elseif ndims(ary) == 2 
                    for k in axes(ary,2)
                        if tol > 0 
                            if abs(ary[i,k] - ary[j,k]) >= tol
                                break
                            else 
                                if k == size(ary,2) 
                                    x__flag = false 
                                end 
                            end 
                        else 
                            if ary[i,k] != ary[j,k]
                                break
                            else 
                                if k == size(ary,2) 
                                    x__flag = false 
                                end 
                            end 
                        end 
                    end 
                end 
                if x__flag == false 
                    break 
                end 
            end 
            if x__flag == true 
                push!(rs,i)
            end 
        end 

        return rs
    end 

    function get_uniquecolindxs(ary,tol) 

        rs = Array{Int,1}(undef,0)
        if ndims(ary) == 1 
            if size(ary,1) > 0 
                push!(rs,1)
            end
        elseif ndims(ary) == 2 
            if size(ary,2) > 0 
                for i in axes(ary,2)
                    x__flag = true 
                    for j in 1:i-1
                        for k in axes(ary,1)
                            if tol > 0 
                                if abs(ary[k,i] - ary[k,j]) >= tol 
                                    break 
                                else 
                                    if k == size(ary,1)
                                        x__flag = false
                                    end 
                                end 
                            else 
                                if ary[k,i] != ary[k,j]
                                    break
                                else 
                                    if k == size(ary,1)
                                        x__flag = false
                                    end 
                                end 
                            end 
                        end
                        if x__flag == false 
                            break 
                        end 
                    end 
                    if x__flag == true 
                        push!(rs,i)
                    end 
                end 
            end 
        end

        return rs
    end 

    function get_multiplier(molexprn) 
        
        rs_factor = 0.0
        rs_item = ""
        if length(molexprn) > 0 
            x__factor = ""
            x__molexprn = str_trim(molexprn)
            rs_factor = 1.0
            rs_item = x__molexprn
            for i in 1:length(x__molexprn)
                x__chr = join(SubString(x__molexprn, i, i), "")
                if tryparse(Float64, x__chr) !== nothing || tryparse(Float64, join(SubString(x__molexprn, 1, i), "")) !== nothing
                    x__factor = string(x__factor, x__chr)
                else 
                    rs_item = join(SubString(x__molexprn, i, length(x__molexprn)), "")
                    break
                end 
            end 
            if startswith(x__factor,".") == true 
                x__factor = string("0",x__factor)
            end 
            if endswith(x__factor,".") == true 
                x__factor = string(x__factor,"0")
            end 
            x__val = tryparse(Float64, x__factor)
            if x__val !== nothing 
                rs_factor = x__val
            end 
        end

        return rs_factor, rs_item
    end

    function get_atomcounts(molexprn) 

        x__factor, x__molecule = get_multiplier(molexprn)
        while get_substrindex(x__molecule, "<Pd111> ", "first") > 0
            x__molecule = replace(x__molecule,"<Pd111> " => "")
        end
        while get_substrindex(x__molecule, "<gas> ", "first") > 0
            x__molecule = replace(x__molecule,"<gas> " => "")
        end
        while get_substrindex(x__molecule, "**", "first") > 0
            x__molecule = replace(x__molecule,"**" => "*")
        end
        while get_substrindex(x__molecule, "_m", "first") > 0
            x__molecule = replace(x__molecule,"_m" => "")
        end
        while get_substrindex(x__molecule, "_b", "first") > 0
            x__molecule = replace(x__molecule,"_b" => "")
        end
        x__molecule = replace(x__molecule,"co-" => "")
        x__molexprn = x__molecule 
        if endswith(x__molexprn,"(g)") == true 
            x__molexprn = join(SubString(x__molexprn, 1, length(x__molexprn) - length("(g)")), "") 
        elseif endswith(x__molexprn,"(lat)") == true 
            x__molexprn = join(SubString(x__molexprn, 1, length(x__molexprn) - length("(lat)")), "") 
        elseif endswith(x__molexprn,"*") == true 
            x__molexprn = join(SubString(x__molexprn, 1, length(x__molexprn) - length("*")), "") 
        elseif startswith(x__molexprn,"TS: ") == true 
            x__molexprn = join(SubString(x__molexprn, 1 + length("TS: "), length(x__molexprn)), "") 
        end
        while get_substrindex(x__molexprn, "*", "first") > 0
            x__molexprn = replace(x__molexprn,"*" => "")
        end
        x__atoms = Array{String,1}(undef,0)
        x__atoms_factors = Array{Float64,1}(undef,0)
        if isempty(x__molexprn) == false 
            x__atom = ""
            x__atom_factor = ""
            for i in 1:length(x__molexprn)
                x__chr = join(SubString(x__molexprn, i, i), "")
                if x__chr == "-"
                    if length(x__atom) > 0 
                        push!(x__atoms,x__atom)
                        if startswith(x__atom_factor,".") == true 
                            x__atom_factor = string("0",x__atom_factor)
                        end 
                        if endswith(x__atom_factor,".") == true 
                            x__atom_factor = string(x__atom_factor,"0")
                        end 
                        if length(x__atom_factor) > 0 && tryparse(Float64, x__atom_factor) !== nothing
                            push!(x__atoms_factors,tryparse(Float64, x__atom_factor))
                        else 
                            push!(x__atoms_factors,1.0)
                        end
                    end
                    x__atom = ""
                    x__atom_factor = ""
                else
                    if tryparse(Float64, x__chr) !== nothing || tryparse(Float64, join(SubString(x__molexprn, 1, i), "")) !== nothing
                        if length(x__atom) > 0 
                            x__atom_factor = string(x__atom_factor,x__chr)
                        end
                    else 
                        if x__chr == uppercase(x__chr)
                            if length(x__atom) > 0 
                                push!(x__atoms,x__atom)
                                if startswith(x__atom_factor,".") == true 
                                    x__atom_factor = string("0",x__atom_factor)
                                end 
                                if endswith(x__atom_factor,".") == true 
                                    x__atom_factor = string(x__atom_factor,"0")
                                end 
                                if length(x__atom_factor) > 0 && tryparse(Float64, x__atom_factor) !== nothing
                                    push!(x__atoms_factors,tryparse(Float64, x__atom_factor))
                                else 
                                    push!(x__atoms_factors,1.0)
                                end
                            end
                            x__atom = x__chr 
                            x__atom_factor = ""
                        else 
                            x__atom = string(x__atom,x__chr)
                        end 
                    end
                end
                if i == length(x__molexprn) && length(x__atom) > 0
                    push!(x__atoms,x__atom)
                    if startswith(x__atom_factor,".") == true 
                        x__atom_factor = string("0",x__atom_factor)
                    end 
                    if endswith(x__atom_factor,".") == true 
                        x__atom_factor = string(x__atom_factor,"0")
                    end 
                    if length(x__atom_factor) > 0 && tryparse(Float64, x__atom_factor) !== nothing 
                        push!(x__atoms_factors,tryparse(Float64, x__atom_factor))
                    else 
                        push!(x__atoms_factors,1.0)
                    end
                end
            end
        end
        rs_atoms = Array{String,1}(undef,0)
        rs_atoms_counts = Dict{String,Float64}()
        for i in axes(x__atoms,1)
            if haskey(rs_atoms_counts,x__atoms[i]) == false 
                push!(rs_atoms,x__atoms[i])
                rs_atoms_counts[x__atoms[i]] = 0.0
            end
            rs_atoms_counts[x__atoms[i]] = rs_atoms_counts[x__atoms[i]] + x__atoms_factors[i]
        end
        if get_substrindex(x__molecule, "--", "first") > 0
            for i in axes(rs_atoms,1)
                rs_atoms_counts[rs_atoms[i]] = 0.5 * rs_atoms_counts[rs_atoms[i]]
            end 
        end 
        rs_atoms_tot = 0.0
        rs_atoms_all = ""
        for i in axes(rs_atoms,1)
            if rs_atoms_counts[rs_atoms[i]] > 0
                x__factor = rs_atoms_counts[rs_atoms[i]]
                x__factor_s = string(x__factor)
                rs_atoms_tot = rs_atoms_tot + x__factor 
                if x__factor == 1
                    x__factor_s = "" 
                elseif isinteger(x__factor) == true
                    x__factor_s = string(get_trunc(x__factor))
                end
                rs_atoms_all = string(rs_atoms_all,(length(rs_atoms_all) > 0 ? ", " : ""),x__factor_s,rs_atoms[i])
            end
        end

        return rs_atoms, rs_atoms_counts, rs_atoms_tot, rs_atoms_all
    end

    function get_configurationcomposition(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms, molecules, phases, odespecies, composition, coeffs_index, coeffs_phases, coeffs_states, coeffs_sites, tst_configs, tst_dindxs, tst_names, tst_phases, tst_compounds, tst_states, tst_sites) 
        
        # [Pd111]: 2H2(g) / Pd111(lat) / 2H*:2* + co-H2O*:* | [Pd123]: H2(g) / Pd123(lat) / H*:* + co-H2O*:* 
        
        # Check error state 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Parse phases
            if err_flag == false 
                x__phases_ary = str_trim(string.(split(composition, "|")))
                for i in axes(x__phases_ary,1)
                    if length(x__phases_ary[i]) > 0 
                        x__phases_ary[i] = join(x__phases_ary[i],"") 

                        # Retrieve phase information 
                        if err_flag == false 
                            x__phase_index = get_elemindex(phases.reflattices,x__phases_ary[i],0) 
                            x__phase_cnt = 1 
                            if x__phase_index > 0 
                                x__phase_name = x__phases_ary[i] 
                                x__phase_dat = "" 
                                coeffs_phases[coeffs_index,x__phase_index] += x__phase_cnt  
                            else 
                                err_flag = true 
                                x__phase_name = "" 
                                x__phase_nid = str_trim(str_cut(x__phases_ary[i], "left" , ":", "original"))
                                x__phase_dat = str_trim(str_cut(x__phases_ary[i], "right", ":", "delete"  ))
                                if length(x__phase_nid) > 0 
                                    x__phase_cnt, x__phase_name = get_multiplier(x__phase_nid)
                                    if x__phase_cnt > 0
                                        x__phase_name = str_trim_phrase(x__phase_name, "<", "prfx") 
                                        x__phase_name = str_trim_phrase(x__phase_name, ">", "sffx") 
                                    end 
                                end 
                                if length(x__phase_name) > 0 
                                    if haskey(phases.phases_dindxs,x__phase_name) == true 
                                        err_flag = (length(x__phase_dat) <= 0) 
                                    else 
                                        err_flag = false 
                                        x__phase_cnt = 1
                                        x__phase_name = ""
                                        x__phase_dat = x__phases_ary[i] 
                                    end 
                                end 
                            end 
                        end 
                        
                        # Verify phase 
                        if err_flag == false 
                            if x__phase_index <= 0 && length(x__phase_dat) > 0 
                                x__molecules_ary = str_trim(String.(split(x__phase_dat, "+")))
                                x__molecules_phase = "" 
                                for j in axes(x__molecules_ary,1)
                                    x__molecules_ary[j] = join(x__molecules_ary[j],"")
                                    if length(x__molecules_ary[j]) > 0 
                                        err_flag = true 
                                        x__molecule_nid = str_trim(str_cut(x__molecules_ary[j], "left" , ":", "original"))
                                        x__molecule_dat = str_trim(str_cut(x__molecules_ary[j], "right", ":", "delete"))
                                        x__molecule_name = ""
                                        if length(x__molecule_nid) > 0 
                                            x__molecule_cnt, x__molecule_name = get_multiplier(x__molecule_nid)
                                            if x__molecule_cnt > 0
                                                x__molecule_name = str_trim_phrase(x__molecule_name, "{", "prfx") 
                                                x__molecule_name = str_trim_phrase(x__molecule_name, "}", "sffx") 
                                            end
                                        end
                                        if length(x__molecule_name) > 0 
                                            x__molecule_phase = "" 
                                            if get_substrindex(x__molecule_name, "--", "first") > 0 
                                                x__molecule_phase = "tst"
                                            else 
                                                if haskey(molecules.dindxs,x__molecule_name) == true 
                                                    x__molecule_index = molecules.dindxs[x__molecule_name]
                                                    if x__molecule_index > 0 
                                                        x__molecule_phase = molecules.phases[x__molecule_index]
                                                    end 
                                                end 
                                            end 
                                            if length(x__molecule_phase) > 0 
                                                if x__molecule_phase != "gas" 
                                                    if length(x__phase_name) > 0 
                                                        x__molecule_phase = x__phase_name 
                                                    else 
                                                        if phases.phases_cnt == 2 
                                                            x__molecule_phase = phases.phases_names[2] 
                                                        else 
                                                            x__molecule_phase = "" 
                                                        end 
                                                    end 
                                                end 
                                            end 
                                            if length(x__molecule_phase) > 0  
                                                if haskey(phases.phases_dindxs,x__molecule_phase) 
                                                    err_flag = false 
                                                    if length(x__molecules_phase) > 0 
                                                        if x__molecules_phase != x__molecule_phase 
                                                            err_flag = true
                                                        end 
                                                    else
                                                        x__molecules_phase = x__molecule_phase 
                                                        x__phase_index = phases.phases_dindxs[x__molecule_phase] 
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                    if err_flag == true 
                                        break 
                                    end 
                                end 
                                err_flag = (err_flag || (x__phase_index <= 0))
                                if err_flag == false 
                                    x__phase_name = phases.phases_names[x__phase_index]
                                    coeffs_phases[coeffs_index,x__phase_index] += x__phase_cnt  
                                end 
                            end 
                        end 
                        
                        # Parse molecules 
                        if err_flag == false 
                            if length(x__phase_dat) > 0
                                x__molecules_ary = str_trim(String.(split(x__phase_dat, "+")))
                                for j in axes(x__molecules_ary,1)
                                    x__molecules_ary[j] = join(x__molecules_ary[j],"")
                                    if length(x__molecules_ary[j]) > 0 

                                        # Retrieve molecule information
                                        x__molecule_cnt = 0 
                                        x__molecule_name = "" 
                                        x__molecule_name_p = "" 
                                        x__molecule_dat = "" 
                                        if err_flag == false 
                                            err_flag = true 
                                            x__molecule_nid = str_trim(str_cut(x__molecules_ary[j], "left" , ":", "original"))
                                            x__molecule_dat = str_trim(str_cut(x__molecules_ary[j], "right", ":", "delete"  ))
                                            if length(x__molecule_nid) > 0 
                                                x__molecule_cnt, x__molecule_name = get_multiplier(x__molecule_nid)
                                                if x__molecule_cnt > 0
                                                    x__molecule_name = str_trim_phrase(x__molecule_name, "{", "prfx") 
                                                    x__molecule_name = str_trim_phrase(x__molecule_name, "}", "sffx") 
                                                end
                                            end
                                            if length(x__molecule_name) > 0 
                                                x__molecule_name_p = string("<",x__phase_name,"> ",x__molecule_name)
                                                if get_substrindex(x__molecule_name, "--", "first") > 0 
                                                    err_flag = false
                                                    if get_elemindex(tst_names,x__molecule_name_p,0) <= 0
                                                        push!(tst_names,x__molecule_name_p) 
                                                        push!(tst_phases,x__phase_name) 
                                                        push!(tst_compounds,x__molecule_name) 
                                                    end 
                                                    if haskey(tst_configs,x__molecule_name_p) == false 
                                                        tst_configs[x__molecule_name_p] = Array{Int,1}(undef,0) 
                                                    end 
                                                    push!(tst_configs[x__molecule_name_p],coeffs_index)
                                                    if haskey(tst_dindxs,x__molecule_name_p) == false 
                                                        err_flag = true 
                                                        x__indx = get_elemindex(tst_names,x__molecule_name_p,0)
                                                        if x__indx > 0 
                                                            err_flag = false
                                                            tst_dindxs[x__molecule_name_p] = x__indx
                                                        end 
                                                    end 
                                                    if err_flag == false 
                                                        if haskey(tst_states,x__molecule_name_p) == false 
                                                            tst_states[x__molecule_name_p] = fill(0.0,(size(coeffs_sites,1),phases.phases_cnt))
                                                        end 
                                                        tst_states[x__molecule_name_p][coeffs_index,x__phase_index] = tst_states[x__molecule_name_p][coeffs_index,x__phase_index] + x__phase_cnt * x__molecule_cnt
                                                    end 
                                                else 
                                                    if haskey(molecules.dindxs,x__molecule_name) == true 
                                                        x__molecule_index = molecules.dindxs[x__molecule_name]
                                                        if x__molecule_index > 0 
                                                            err_flag = false 
                                                            coeffs_states[coeffs_index,x__phase_index,x__molecule_index] += x__phase_cnt * x__molecule_cnt
                                                        end 
                                                    end 
                                                end 
                                            end 
                                        end 

                                        # Parse sites
                                        if err_flag == false 
                                            if x__phase_name != "gas" 
                                                x__sites_ary = str_trim(String.(split(x__molecule_dat, ",")))
                                                for k in axes(x__sites_ary,1)
                                                    x__sites_ary[k] = join(x__sites_ary[k],"")
                                                    if length(x__sites_ary[k]) > 0 
    
                                                        # Retrieve site information
                                                        x__site_cnt = 0 
                                                        x__site_name = "" 
                                                        x__site_dat = "" 
                                                        if err_flag == false 
                                                            err_flag = true 
                                                            x__site_nid = str_trim(str_cut(x__sites_ary[k], "left" , ":", "original"))
                                                            x__site_dat = str_trim(str_cut(x__sites_ary[k], "right", ":", "delete"  ))
                                                            if length(x__site_nid) > 0 
                                                                x__site_cnt, x__site_name = get_multiplier(x__site_nid)
                                                                if x__site_cnt > 0
                                                                    x__site_name = str_trim_phrase(x__site_name, "(", "prfx") 
                                                                    x__site_name = str_trim_phrase(x__site_name, ")", "sffx") 
                                                                end
                                                            end 
                                                            if length(x__site_name) > 0 
                                                                if haskey(phases.sites_dindxs,x__site_name) == true 
                                                                    x__site_index = phases.sites_dindxs[x__site_name] 
                                                                    if x__site_index > 0 
                                                                        err_flag = false 
                                                                        if get_substrindex(x__molecule_name, "--", "first") > 0 
                                                                            if haskey(tst_sites,x__molecule_name_p) == false 
                                                                                tst_sites[x__molecule_name_p] = fill(0.0,(size(coeffs_sites,1),phases.phases_cnt,1,phases.sites_cnt)) 
                                                                            end 
                                                                            tst_sites[x__molecule_name_p][coeffs_index,x__phase_index,1,x__site_index] = tst_sites[x__molecule_name_p][coeffs_index,x__phase_index,1,x__site_index] + x__phase_cnt * x__molecule_cnt * x__site_cnt
                                                                        else 
                                                                            coeffs_sites[coeffs_index,x__phase_index,x__molecule_index,x__site_index] += x__phase_cnt * x__molecule_cnt * x__site_cnt
                                                                        end 
                                                                    end 
                                                                end 
                                                            end 
                                                        end 
                                                    end 
                                                    if err_flag == true 
                                                        break 
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                    if err_flag == true 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function get_configurationcomposition_phrase(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, odespecies, phases, state_names, coeffs_index, coeffs_phases, coeffs_states, coeffs_sites) 

        # [Pd111]: 2H2(g) + 2H*:2* + co-H2O*:* | [Pd123]: H2(g) + H*:* + co-H2O*:* 
        
        # Check error state 
        rs = "" 
        if err_flag == false 
            for i in axes(phases.phases_names,1) 
                x__phase_str = "" 
                x__phase_factor = coeffs_phases[coeffs_index,i] 
                if x__phase_factor > 0 
                    for j in axes(state_names,1) 
                        x__state_str = "" 
                        x__state_factor = coeffs_states[coeffs_index,i,j] 
                        if x__state_factor > 0 
                            if phases.phases_names[i] != "gas" && get_elemindex(phases.reflattices,state_names[j],0) <= 0 
                                x__sitecnt = 0 
                                for k in axes(phases.sites_names,1)
                                    x__site_str = "" 
                                    x__site_factor = coeffs_sites[coeffs_index,i,j,k]
                                    if x__site_factor > 0 
                                        x__sitecnt += 1
                                        if x__site_factor == 1 
                                            x__site_factor = "" 
                                        elseif isinteger(x__site_factor) == true 
                                            x__site_factor = get_trunc(x__site_factor) 
                                        end 
                                        x__state_str = string(x__state_str,(length(x__state_str) > 0 ? ", " : ""),x__site_factor,phases.sites_names[k])  
                                    end
                                end 
                                if x__sitecnt > 1 
                                    x__state_str = string("(",x__state_str,")")
                                end 
                            end 
                            nonunity_flag = false
                            if x__state_factor == 1 
                                x__state_factor = "" 
                            elseif isinteger(x__state_factor) == true 
                                x__state_factor = get_trunc(x__state_factor) 
                                if x__state_factor != 1 
                                    nonunity_flag = true 
                                end 
                            end 
                            braces_flag = false 
                            if nonunity_flag == true 
                                if get_substrindex(state_names[j], "-", "first") > 0 || get_substrindex(state_names[j], "--", "first") > 0
                                    braces_flag = true 
                                end 
                            end 
                            x__phase_str = string(x__phase_str,(length(x__phase_str) > 0 ? " + " : ""),x__state_factor,(braces_flag == true ? "{" : ""),str_trim(str_cut(state_names[j], "right", ">", "original")),(braces_flag == true ? "}" : ""),(length(x__state_str) > 0 ? ":" : ""),x__state_str) 
                        end 
                    end  
                    if x__phase_factor == 1 
                        x__phase_factor = "" 
                    elseif isinteger(x__phase_factor) == true 
                        x__phase_factor = get_trunc(x__phase_factor) 
                    end 
                    rs = string(rs,(length(rs) > 0 ? " | " : ""),x__phase_factor,"<",phases.phases_names[i],">",(length(x__phase_str) > 0 ? ": " : ""),x__phase_str)  
                end 
            end 
        end

        return err_flag, err_msg, rs
    end



    # Logging functions

    function log_elapsedseconds(refts, ts, leadingdigits, roundingdigits, appsecs) 

        # elapsed time since reference time, in seconds and rounded to specified number of digits
        rs = string(round(((ts - refts) / Millisecond(1) * (1 / 1000)); digits = roundingdigits))
        if leadingdigits > 0
            rs = (size(findfirst(".",rs),1) <= 0) ? string(rs,".") : rs
            rs = (findfirst(".",rs)[1] == 1) ? string("0",rs) : rs
            while findfirst(".",rs)[1] <= leadingdigits
                rs = string(" ",rs)
            end
            while findfirst(".",rs)[1] > (length(rs) - roundingdigits)
                rs = string(rs,"0")
            end
        end
        rs = (appsecs == true) ? string(rs," seconds") : rs

        return rs
    end

    function log_message(msgrslts, msgtxtprfx, err_flag, err_msg, start_ts, seg_ts, add_ts, add_prfx, rtn_msg, rtn_msg_indx, show_msg, show_msg_indx, log_msg, log_file_openflag, log_file_fsobj, ts_prfx, msg_txt) 
        
        # Check error state
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            if msgrslts.err_flag == true 
                err_flag = msgrslts.err_flag
                err_msg = msgrslts.err_msg
            end 
        end 
        
        # process logging message
        if err_flag == false 
            
            # Reset display object 
            msgrslts.err_flag = false 
            msgrslts.err_msg = "" 
            msgrslts.rtn_msg = "" 
            msgrslts.item_cnt = 1 

            # Retrieve array sizes
            if isa(start_ts,DateTime) == false || isa(seg_ts,DateTime) == false || isa(log_msg,Bool) == false || isa(log_file_openflag,Bool) == false || isa(log_file_fsobj,IOStream) == false || isa(msgtxtprfx,String) == false
                msgrslts.item_cnt = 0 
                msgrslts.ary_sizes .= 0
                msgrslts.ary_sizes[msgrslts.cols_start_ts]   = ((isa(start_ts         ,DateTime) == false) ? size(start_ts         ,1) : 1)
                msgrslts.ary_sizes[msgrslts.cols_seg_ts]     = ((isa(seg_ts           ,DateTime) == false) ? size(seg_ts           ,1) : 1)
                msgrslts.ary_sizes[msgrslts.cols_log_msg]    = ((isa(log_msg          ,Bool    ) == false) ? size(log_msg          ,1) : 1)
                msgrslts.ary_sizes[msgrslts.cols_log_open]   = ((isa(log_file_openflag,Bool    ) == false) ? size(log_file_openflag,1) : 1)
                msgrslts.ary_sizes[msgrslts.cols_log_fsobj]  = ((isa(log_file_fsobj   ,IOStream) == false) ? size(log_file_fsobj   ,1) : 1)
                msgrslts.ary_sizes[msgrslts.cols_msgtxtprfx] = ((isa(msgtxtprfx       ,String  ) == false) ? size(msgtxtprfx       ,1) : 1)
                for i in 1:msgrslts.cols_cnt
                    if msgrslts.ary_sizes[i] > 1 
                        if msgrslts.item_cnt != 1
                            if msgrslts.ary_sizes[i] != msgrslts.item_cnt 
                                msgrslts.err_flag = true 
                                msgrslts.err_msg = "Mismatched message array(s)"
                                break 
                            end 
                        else 
                            msgrslts.item_cnt = msgrslts.ary_sizes[i] 
                        end
                    end
                end
                if msgrslts.item_cnt <= 0 
                    msgrslts.err_flag = true 
                    msgrslts.err_msg = "Empty message array(s)"
                end 
            end

            # Reset display arrays 
            msg_ts = now()
            if msgrslts.err_flag == false 
                if msgrslts.item_cnt > msgrslts.item_size 
                    msgrslts.item_size    = msgrslts.item_cnt 
                    msgrslts.ts_prfx      = fill("",msgrslts.item_size) 
                    msgrslts.dbg_prfx     = fill("",msgrslts.item_size) 
                    msgrslts.tot_prfx     = fill("",msgrslts.item_size) 
                    msgrslts.msg_txt      = fill("",msgrslts.item_size) 
                    msgrslts.tmp_start_ts = fill(msg_ts,msgrslts.item_size) 
                    msgrslts.tmp_seg_ts   = fill(msg_ts,msgrslts.item_size) 
                    msgrslts.tmp_log_msg  = fill(false,msgrslts.item_size) 
                    msgrslts.tmp_log_open = fill(false,msgrslts.item_size) 
                    msgrslts.tmp_dbg_prfx = fill("",msgrslts.item_size) 
                    msgrslts.tmp_msg_txtf = fill("",msgrslts.item_size) 
                end 
                msgrslts.ts_prfx      .= "" 
                msgrslts.dbg_prfx     .= "" 
                msgrslts.tot_prfx     .= "" 
                msgrslts.msg_txt      .= "" 
                msgrslts.tmp_start_ts .= msg_ts
                msgrslts.tmp_seg_ts   .= msg_ts
                msgrslts.tmp_log_msg  .= false 
                msgrslts.tmp_log_open .= false 
                msgrslts.tmp_dbg_prfx .= "" 
                msgrslts.tmp_msg_txtf .= ""
            end 

            # Display logging message 
            if msgrslts.err_flag == false
                
                # Fill in temporary arrays 
                for i in 1:msgrslts.item_cnt 
                    msgrslts.tmp_start_ts[i] = ((isa(start_ts,DateTime)      == false) ? start_ts[i]          : start_ts         )
                    msgrslts.tmp_seg_ts[i]   = ((isa(seg_ts,DateTime)        == false) ? seg_ts[i]            : seg_ts           )
                    msgrslts.tmp_log_msg[i]  = ((isa(log_msg,Bool)           == false) ? log_msg[i]           : log_msg          )
                    msgrslts.tmp_log_open[i] = ((isa(log_file_openflag,Bool) == false) ? log_file_openflag[i] : log_file_openflag)
                    msgrslts.tmp_dbg_prfx[i] = ((isa(msgtxtprfx,String)      == false) ? msgtxtprfx[i]        : msgtxtprfx       )
                    msgrslts.tmp_msg_txtf[i] = "" 
                end

                # Prepend timestamp and elapsed time 
                if add_ts == true 
                    ts_posx = replace(string(msg_ts),"T" => " ")
                    ts_posx = (get_substrindex(ts_posx,":","last") > get_substrindex(ts_posx,".","last")) ? string(ts_posx,".") : ts_posx
                    while get_substrindex(ts_posx,".","last") > length(ts_posx) - 2
                        ts_posx = string(ts_posx,"0")
                    end
                    ts_posx = join(SubString(ts_posx,1,get_trunc(get_substrindex(ts_posx,".","last") + 2)),"")
                    for i in 1:msgrslts.item_cnt 
                        ts_diff = string(log_elapsedseconds(msgrslts.tmp_start_ts[i], msg_ts, 5, 3, false))
                        while get_substrindex(ts_diff,".","last") > length(ts_diff) - 2
                            ts_diff = string(ts_diff,"0")
                        end
                        ts_diff = join(SubString(ts_diff,1,get_trunc(get_substrindex(ts_diff,".","last") + 2)),"")
                        msgrslts.tmp_msg_txtf[i] = string(msgrslts.tmp_msg_txtf[i],ts_prfx,ts_posx," ",ts_diff,"    ")
                        msgrslts.ts_prfx[i] = string(ts_prfx,ts_posx," ",ts_diff,"    ")
                    end 
                end 

                # Combine prefixes 
                for i in 1:msgrslts.item_cnt 
                    msgrslts.tmp_msg_txtf[i] = string(msgrslts.tmp_msg_txtf[i],((add_prfx == true) ? msgrslts.tmp_dbg_prfx[i] : ""),msg_txt)
                    msgrslts.dbg_prfx[i] = string(((add_prfx == true) ? msgrslts.tmp_dbg_prfx[i] : ""))
                    msgrslts.tot_prfx[i] = string(msgrslts.ts_prfx[i],msgrslts.dbg_prfx[i])
                    msgrslts.msg_txt[i] = string(msg_txt)
                end 

                # Show logging message in standard output
                if show_msg == true 
                    println(msgrslts.tmp_msg_txtf[show_msg_indx])
                end 

                # Save logging message to file outputs 
                for i in 1:msgrslts.item_cnt 
                    if msgrslts.tmp_log_msg[i] == true && msgrslts.tmp_log_open[i] == true 
                        if isa(log_file_fsobj,IOStream) == true
                            write(log_file_fsobj,string(msgrslts.tmp_msg_txtf[i],"\n"))
                        else
                            write(log_file_fsobj[i],string(msgrslts.tmp_msg_txtf[i],"\n"))
                        end
                    end
                end 

                # Retrieve return message
                msgrslts.rtn_msg = ((rtn_msg == true) ? msgrslts.tmp_msg_txtf[rtn_msg_indx] : "")
            end

            # Show logging error
            if msgrslts.err_flag == true 
                println("ERROR DURING LOGGING")
                err_flag = msgrslts.err_flag
                err_msg = msgrslts.err_msg
            end
        end 

        return err_flag, err_msg
    end 

    function log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, add_ts, show_msg, rtn_msg_indx, show_msg_indx, msg_txt) 

        # Check error state
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            if msgrslts.err_flag == true 
                err_flag = msgrslts.err_flag
                err_msg = msgrslts.err_msg
            end 
        end 
        
        # process logging message
        if err_flag == false 
            if isa(msgoptions,ct__MessageConfigs) == true
                for i in 1:msgoptions.cnt 
                    err_flag, err_msg = log_message(msgrslts, msgtxtprfx, err_flag, err_msg, msgoptions.vec[i].start_ts, msgoptions.vec[i].seg_ts, add_ts, true, true, rtn_msg_indx, ((i == show_msg_indx) && show_msg), show_msg_indx, msgoptions.vec[i].log_msg, true, msgoptions.vec[i].log_file_fsobj, "", msg_txt)
                    if err_flag == true 
                        break 
                    end 
                end 
            else 
                err_flag, err_msg = log_message(msgrslts, msgtxtprfx, err_flag, err_msg, msgoptions.start_ts, msgoptions.seg_ts, add_ts, true, true, rtn_msg_indx, show_msg, show_msg_indx, msgoptions.log_msg, true, msgoptions.log_file_fsobj, "", msg_txt)
            end 
        end 

        return err_flag, err_msg
    end 

    function log_value(err_flag, err_msg, val, num_prec, force_prec, force_int, force_str) 

        # Check error state
        rs = "" 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            rs = (val !== nothing) ? string(val) : "" 
            xtype = Float64 
            if isa(val,Number) 
                xtype = eltype(val)
            end 
            xval = tryparse(xtype, rs) 
            if xval !== nothing && string(rs) != "NaN" 
                if force_str == true 
                    if num_prec > 0 && force_prec == true && get_substrindex(lowercase(rs),"e","first") <= 0 
                        if get_substrindex(rs,".","first") > 0
                            if get_substrindex(rs,".","first") > 1 
                                x__prfx = str_trim(str_cut(rs, "left" , ".", "original"))
                            else 
                                x__prfx = "0" 
                            end 
                            if get_substrindex(rs,".","first") < length(rs)
                                x__sffx = str_trim(str_cut(rs, "right", ".", "delete"  ))
                            else 
                                x__sffx = ""
                            end 
                        else 
                            x__prfx = rs 
                            x__sffx = ""
                        end 
                        if length(x__sffx) > num_prec 
                            x__sffx = join(SubString(x__sffx,1,num_prec),"")
                        elseif length(x__sffx) < num_prec 
                            while length(x__sffx) < num_prec 
                                x__sffx = string(x__sffx, "0")
                            end
                        end 
                        rs = string(x__prfx,".",x__sffx)
                    end   
                else 
                    rs = xval 
                    rs_intflag = false
                    if (num_prec == 0 || force_prec == false) && force_int == true 
                        if isinteger(rs) == true
                            rs = string(get_trunc(rs))
                            rs_intflag = true
                        end
                    end 
                    if rs_intflag == false && num_prec > 0 && force_prec == true 
                        rs = str_enforcenumprecision(rs, num_prec)
                    end 
                end 
            end
        end 

        return rs
    end

    function log_table(msgrslts, msgtxtprfx, err_flag, err_msg, start_ts, seg_ts, add_ts, rtn_msg_indx, show_msg, show_msg_indx, log_msg, log_file_fsobj, table_rowheaders, table_colheaders, table_data, num_prec, force_prec, force_int, force_str) 

        # Check error state
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            if msgrslts.err_flag == true 
                err_flag = msgrslts.err_flag
                err_msg = msgrslts.err_msg
            end 
        end 

        # process logging message
        if err_flag == false 

            # Retrieve row headers sizing
            if err_flag == false 
                x__rowhdrswt = 0 
                x__rowhdrsht = 0 
                if is_array(table_rowheaders)
                    if size(table_rowheaders,1) > 0 
                        if is_array(table_rowheaders[1])
                            x__rowhdrswt = size(table_rowheaders,1)
                            x__rowhdrsht = size(table_rowheaders[1],1)
                        else 
                            x__rowhdrswt = 1
                            x__rowhdrsht = size(table_rowheaders,1)
                        end 
                    else 
                        x__rowhdrsht = size(table_data,1)
                    end 
                end 
                if x__rowhdrsht > 0 && x__rowhdrsht != size(table_data,1)
                    err_flag = true 
                end 
            end 

            # Retrieve column headers sizing 
            if err_flag == false 
                x__colhdrswt = 0 
                x__colhdrsht = 0 
                if is_array(table_colheaders)
                    if size(table_colheaders,1) > 0 
                        if is_array(table_colheaders[1])
                            x__colhdrswt = size(table_colheaders[1],1)
                            x__colhdrsht = size(table_colheaders,1)
                        else 
                            x__colhdrswt = size(table_colheaders,1)
                            x__colhdrsht = 1
                        end 
                    else 
                        x__colhdrswt = size(table_data,2)
                    end 
                end 
                if x__colhdrswt > 0 && x__colhdrswt != size(table_data,2)
                    err_flag = true 
                end 
            end 

            # Retrieve mixed negative prefix flags
            if err_flag == false 
                x__negflags = fill(false, x__colhdrswt) 
                for i in 1:x__colhdrswt 
                    x__negcnt = 0
                    for j in axes(table_data,1)
                        x__value = log_value(err_flag, err_msg, table_data[j,i], num_prec, force_prec, force_int, force_str)
                        if err_flag == false 
                            x__negcnt = x__negcnt + (startswith(string(x__value),"-") ? 1 : 0)
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end
                    x__negflags[i] = (0 < x__negcnt && x__negcnt < size(table_data,1) ? true : false)
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Retrieve column widths 
            if err_flag == false 
                x__widths = fill(0.0, (x__rowhdrswt + x__colhdrswt)) 
                for i in 1:(x__rowhdrswt + x__colhdrswt) 
                    if i <= x__rowhdrswt 
                        if is_array(table_rowheaders) 
                            if length(table_rowheaders) > 0 
                                if is_array(table_rowheaders[1])
                                    for j in axes(table_rowheaders[1],1)
                                        x__widths[i] = max(max(x__widths[i],length(string(table_rowheaders[i][j]))),0) 
                                    end 
                                else 
                                    for j in axes(table_rowheaders,1)
                                        x__widths[i] = max(max(x__widths[i],length(string(table_rowheaders[j]))),0) 
                                    end 
                                end 
                            end 
                        end 
                    else 
                        if is_array(table_colheaders) 
                            if length(table_colheaders) > 0 
                                if is_array(table_colheaders[1])
                                    for j in axes(table_colheaders,1)
                                        x__widths[i] = max(max(x__widths[i],length(string(table_colheaders[j][i-x__rowhdrswt]))),0) 
                                    end 
                                else 
                                    x__widths[i] = max(max(x__widths[i],length(string(table_colheaders[i-x__rowhdrswt]))),0) 
                                end 
                            end 
                        end 
                        for j in axes(table_data,1)
                            x__value = log_value(err_flag, err_msg, table_data[j,i-x__rowhdrswt], num_prec, force_prec, force_int, force_str)
                            if err_flag == false 
                                if x__negflags[i-x__rowhdrswt] == true && startswith(string(x__value),"-") == false
                                    x__widths[i] = max(max(x__widths[i],length(string(" ",x__value))),0) 
                                else 
                                    x__widths[i] = max(max(x__widths[i],length(string(x__value))),0) 
                                end
                            end
                            if err_flag == true 
                                break 
                            end 
                        end 
                    end 
                end 
            end 

            # Construct output rows
            if err_flag == false 
                for i in 1:(x__colhdrsht + 1 + x__rowhdrsht) 
                    x__row = "" 
                    for j in 1:(x__rowhdrswt + x__colhdrswt) 
                        x__cell = ""
                        if i <= x__colhdrsht  
                            if j <= x__rowhdrswt 
                                x__cell = ""
                            else 
                                if is_array(table_colheaders) 
                                    if length(table_colheaders) > 0 
                                        if is_array(table_colheaders[1])
                                            if length(table_colheaders) > 0 
                                                x__cell = table_colheaders[i][j-x__rowhdrswt]
                                            end 
                                        else 
                                            x__cell = table_colheaders[j-x__rowhdrswt]
                                        end 
                                    end 
                                end 
                            end 
                        elseif i > x__colhdrsht + 1
                            if j <= x__rowhdrswt 
                                if is_array(table_rowheaders) 
                                    if length(table_rowheaders) > 0 
                                        if is_array(table_rowheaders[1])
                                            x__cell = table_rowheaders[j][i-x__colhdrsht-1]
                                        else 
                                            x__cell = table_rowheaders[i-x__colhdrsht-1]
                                        end 
                                    end 
                                end 
                            else
                                x__value = log_value(err_flag, err_msg, table_data[i-x__colhdrsht-1,j-x__rowhdrswt], num_prec, force_prec, force_int, force_str)
                                if err_flag == false 
                                    x__cell = string(x__value)
                                    if x__negflags[j-x__rowhdrswt] == true && startswith(x__cell,"-") == false 
                                        x__cell = string(" ",x__cell)
                                    end 
                                end 
                            end 
                        end 
                        if err_flag == false 
                            while length(x__cell) < x__widths[j]
                                if i == x__colhdrsht + 1 && j > x__rowhdrswt
                                    x__cell = string(x__cell,"_")
                                else 
                                    x__cell = string(x__cell," ")
                                end
                            end
                        end 
                        if err_flag == false 
                            x__row = string(x__row,(length(x__row) > 0 ? "  " : ""),x__cell)
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                    if err_flag == false 
                        if (i != x__colhdrsht + 1) || (i == x__colhdrsht + 1 && x__colhdrsht > 0)
                            err_flag, err_msg = log_message(msgrslts, msgtxtprfx, err_flag, err_msg, start_ts, seg_ts, add_ts, true, true, rtn_msg_indx, show_msg, show_msg_indx, log_msg, true, log_file_fsobj, "", x__row)
                        end
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end

    function log_table_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, add_ts, show_msg, rtn_msg_indx, show_msg_indx, table_rowheaders, table_colheaders, table_data, num_prec, force_prec, force_int, force_str) 

        # Check error state
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            if msgrslts.err_flag == true 
                err_flag = msgrslts.err_flag
                err_msg = msgrslts.err_msg
            end 
        end 
        
        # process logging message
        if err_flag == false 
            if isa(msgoptions,ct__MessageConfigs) == true
                for i in 1:msgoptions.cnt 
                    err_flag, err_msg = log_table(msgrslts, msgtxtprfx, err_flag, err_msg, msgoptions.vec[i].start_ts, msgoptions.vec[i].seg_ts, false, rtn_msg_indx, ((i == show_msg_indx) && show_msg), show_msg_indx, msgoptions.vec[i].log_msg, msgoptions.vec[i].log_file_fsobj, table_rowheaders, table_colheaders, table_data, num_prec, force_prec, force_int, force_str)
                    if err_flag == true 
                        break 
                    end 
                end 
            elseif isa(msgoptions,ct__MessageConfig) == true
                err_flag, err_msg = log_table(msgrslts, msgtxtprfx, err_flag, err_msg, msgoptions.start_ts, msgoptions.seg_ts, false, rtn_msg_indx, show_msg, show_msg_indx, msgoptions.log_msg, msgoptions.log_file_fsobj, table_rowheaders, table_colheaders, table_data, num_prec, force_prec, force_int, force_str)
            end 
        end 

        return err_flag, err_msg
    end 

    function log_configurationcoeffs(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, phases, states_names, coeffs_index, coeffs_phases, coeffs_states, coeffs_sites) 

        for i in axes(phases.phases_names,1)
            if coeffs_phases[coeffs_index,i] > 0 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  phase: ",coeffs_phases[coeffs_index,i],"<",phases.phases_names[i],">"))
                for j in axes(states_names,1)
                    if coeffs_states[coeffs_index,i,j] > 0 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    state: ",coeffs_states[coeffs_index,i,j],"{",states_names[j],"}"))
                        for k in axes(phases.sites_names,1)
                            if coeffs_sites[coeffs_index,i,j,k] > 0 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      site: ",coeffs_sites[coeffs_index,i,j,k],"(",phases.sites_names[k],")"))
                            end 
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 

    function log_rxnsystem(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem) 
        
        # Check error state 
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("Reaction System Object: "))
            if err_flag == false 
                err_flag = false 
                err_msg = ""

                # Display precision
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  display precision digits   : ",rxnsystem.log_num_prec))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  display precision enforced : ",rxnsystem.log_force_prec))
                end
                
                # Physical units
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Physical Units : "))
                    if rxnsystem.physunits !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    time          : ",rxnsystem.physunits.time,       ((rxnsystem.physunits.time        != rxnsystem.physunits.time_si       ) ? string("  (",rxnsystem.physunits.time_si,       ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    distance      : ",rxnsystem.physunits.distance,   ((rxnsystem.physunits.distance    != rxnsystem.physunits.distance_si   ) ? string("  (",rxnsystem.physunits.distance_si,   ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    area          : ",rxnsystem.physunits.area,       ((rxnsystem.physunits.area        != rxnsystem.physunits.area_si       ) ? string("  (",rxnsystem.physunits.area_si,       ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    temperature   : ",rxnsystem.physunits.temperature,((rxnsystem.physunits.temperature != rxnsystem.physunits.temperature_si) ? string("  (",rxnsystem.physunits.temperature_si,")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    pressure      : ",rxnsystem.physunits.pressure,   ((rxnsystem.physunits.pressure    != rxnsystem.physunits.pressure_si   ) ? string("  (",rxnsystem.physunits.pressure_si,   ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    coverage      : ",rxnsystem.physunits.coverage,   ((rxnsystem.physunits.coverage    != rxnsystem.physunits.coverage_si   ) ? string("  (",rxnsystem.physunits.coverage_si,   ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    molecular wt  : ",rxnsystem.physunits.molwt,      ((rxnsystem.physunits.molwt       != rxnsystem.physunits.molwt_si      ) ? string("  (",rxnsystem.physunits.molwt_si,      ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    rot inertia   : ",rxnsystem.physunits.rotinertia, ((rxnsystem.physunits.rotinertia  != rxnsystem.physunits.rotinertia_si ) ? string("  (",rxnsystem.physunits.rotinertia_si, ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    energy        : ",rxnsystem.physunits.energy,     ((rxnsystem.physunits.energy      != rxnsystem.physunits.energy_si     ) ? string("  (",rxnsystem.physunits.energy_si,     ")") : ""))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    wavenumber    : ",rxnsystem.physunits.wavenumber, ((rxnsystem.physunits.wavenumber  != rxnsystem.physunits.wavenumber_si ) ? string("  (",rxnsystem.physunits.wavenumber_si, ")") : ""))) 
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Physical Units' property of reaction system object is missing"
                    end
                end

                # Physical constants
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Physical Constants : "))
                    if rxnsystem.physcnsts !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Planck's Constant    : ",rxnsystem.physcnsts.h_p.value," ",rxnsystem.physcnsts.h_p.units,((rxnsystem.physcnsts.h_p.units != rxnsystem.physcnsts.h_p.units_si) ? string("  (",rxnsystem.physcnsts.h_p.value_si," ",rxnsystem.physcnsts.h_p.units_si,")") : "")))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Speed of Light       : ",rxnsystem.physcnsts.c_v.value," ",rxnsystem.physcnsts.c_v.units,((rxnsystem.physcnsts.c_v.units != rxnsystem.physcnsts.c_v.units_si) ? string("  (",rxnsystem.physcnsts.c_v.value_si," ",rxnsystem.physcnsts.c_v.units_si,")") : "")))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Boltzmann's Constant : ",rxnsystem.physcnsts.k_b.value," ",rxnsystem.physcnsts.k_b.units,((rxnsystem.physcnsts.k_b.units != rxnsystem.physcnsts.k_b.units_si) ? string("  (",rxnsystem.physcnsts.k_b.value_si," ",rxnsystem.physcnsts.k_b.units_si,")") : "")))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Avogadro's constant  : ",rxnsystem.physcnsts.N_a.value," ",rxnsystem.physcnsts.N_a.units,((rxnsystem.physcnsts.N_a.units != rxnsystem.physcnsts.N_a.units_si) ? string("  (",rxnsystem.physcnsts.N_a.value_si," ",rxnsystem.physcnsts.N_a.units_si,")") : "")))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Standard pressure    : ",rxnsystem.physcnsts.P_o.value," ",rxnsystem.physcnsts.P_o.units,((rxnsystem.physcnsts.P_o.units != rxnsystem.physcnsts.P_o.units_si) ? string("  (",rxnsystem.physcnsts.P_o.value_si," ",rxnsystem.physcnsts.P_o.units_si,")") : "")))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Atomic mass Unit     : ",rxnsystem.physcnsts.amu.value," ",rxnsystem.physcnsts.amu.units,((rxnsystem.physcnsts.amu.units != rxnsystem.physcnsts.amu.units_si) ? string("  (",rxnsystem.physcnsts.amu.value_si," ",rxnsystem.physcnsts.amu.units_si,")") : "")))
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Physical Constants' property of reaction system object is missing"
                    end
                end

                # Physical conversions
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Physical Conversions : "))
                    if rxnsystem.physconvs !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    electron-volt to Joule : ",rxnsystem.physconvs.J_eV," J / eV"))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    bar to Pascal          : ",rxnsystem.physconvs.Pa_bar," Pa / bar"))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    kilogram to gram       : ",rxnsystem.physconvs.g_kg," gram / kilogram"))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    centimeter to meter    : ",rxnsystem.physconvs.m_cm," m / cm"))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    Angstrom to meter      : ",rxnsystem.physconvs.m_Ang," m / Angstrom"))
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Physical Conversions' property of reaction system object is missing"
                    end
                end

                # Atoms
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Atoms : "))
                    if rxnsystem.atoms !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    atoms     : ",join(rxnsystem.atoms.atoms_names,", ")))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    refatoms  : ",join(rxnsystem.atoms.refatoms_names,", "))) 
                        if size(rxnsystem.atoms.atoms_names,1) > 0 && size(rxnsystem.atoms.refatoms_names,1) > 0 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    refcoeffs : "))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, rxnsystem.atoms.refatoms_names, rxnsystem.atoms.refcmpds_names, rxnsystem.atoms.refcoeffs, 0, false, true, true)
                        end 
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Molecules' property of reaction system object is missing"
                    end
                end

                # Molecules
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Molecules : "))
                    if rxnsystem.molecules !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    count  : ",rxnsystem.molecules.cnt)) 
                        if rxnsystem.molecules.cnt > 0 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    params : "))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                            x__ary = fill("",(rxnsystem.molecules.cnt,7)) 
                            for i in 1:rxnsystem.molecules.cnt 
                                for j in axes(rxnsystem.molecules.atomcoeffs,2)
                                    x__factor = rxnsystem.molecules.atomcoeffs[i,j] 
                                    if x__factor > 0 
                                        x__factor_s = string(x__factor)
                                        if x__factor == 1 
                                            x__factor_s = "" 
                                        elseif isinteger(x__factor) == true
                                            x__factor_s = string(get_trunc(x__factor))
                                        end
                                        x__ary[i,1] = string(x__ary[i,1],(length(x__ary[i,1]) > 0 ? ", " : ""),x__factor_s,rxnsystem.atoms.atoms_names[j])
                                    end 
                                end 
                            end 
                            for i in axes(rxnsystem.molecules.indxs_active,1) 
                                x__ary[rxnsystem.molecules.indxs_active[i],2] = "x"
                            end 
                            for i in axes(rxnsystem.molecules.indxs_inactive,1) 
                                x__ary[rxnsystem.molecules.indxs_inactive[i],3] = "x"
                            end 
                            for i in axes(rxnsystem.molecules.indxs_odespecies,1) 
                                x__ary[rxnsystem.molecules.indxs_odespecies[i],4] = "x"
                            end 
                            for i in axes(rxnsystem.molecules.indxs_gas,1) 
                                x__ary[rxnsystem.molecules.indxs_gas[i],5] = "x"
                            end 
                            for i in axes(rxnsystem.molecules.indxs_ads,1) 
                                x__ary[rxnsystem.molecules.indxs_ads[i],6] = "x"
                            end 
                            for i in axes(rxnsystem.molecules.indxs_coads,1) 
                                x__ary[rxnsystem.molecules.indxs_coads[i],7] = "x"
                            end 
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.molecules.names, 
                                                    [
                                                        ["molexprn","coadsequiv","phase","atoms","active","inactive","odespecies","gas","ads","coads","molwt","spinmultiplicity","rotsymfactor","rotconstant A","rotconstant B","rotconstant C","rotpeak","rotbarrier","rotinertia","trsareafactor","trspeak","trsbarriers"], 
                                                        ["","","","","","","","","","",string("(",rxnsystem.molecules.molwts.units,")"),"","",string("(",rxnsystem.molecules.rotconstants.units,")"),string("(",rxnsystem.molecules.rotconstants.units,")"),string("(",rxnsystem.molecules.rotconstants.units,")"),"",string("(",rxnsystem.molecules.rotbarriers.units,")"),string("(",rxnsystem.molecules.rotinertias.units,")"),"","",string("(",rxnsystem.molecules.trsbarriers.units,")")]
                                                    ], 
                                                    hcat(rxnsystem.molecules.molexprns, rxnsystem.molecules.coadsequivs, rxnsystem.molecules.phases, x__ary, str_enforcenumprecision(rxnsystem.molecules.molwts.value, 2), rxnsystem.molecules.spinmultiplicities, rxnsystem.molecules.rotsymfactors, str_enforcenumprecision(rxnsystem.molecules.rotconstants.value, 2),rxnsystem.molecules.rotpeaks,str_enforcenumprecision(rxnsystem.molecules.rotbarriers.value, 2), str_enforcenumprecision(rxnsystem.molecules.rotinertias.value, 2), str_enforcenumprecision(rxnsystem.molecules.trsareafactors, 2), rxnsystem.molecules.trspeaks, str_enforcenumprecision(rxnsystem.molecules.trsbarriers.value, 2)), 
                                                    0, false, true, true
                                                ) 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    atom ref cmpds : "))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.molecules.names, 
                                                    rxnsystem.atoms.refcmpds_names, 
                                                    rxnsystem.molecules.atomrefcmpdtotals, 
                                                    0, false, true, true
                                                ) 
                        end 
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Molecules' property of reaction system object is missing"
                    end 
                end

                # Phases 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Phases : "))
                    if rxnsystem.phases !== nothing 
                        if rxnsystem.phases.phases_cnt > 0 
                            x__sites = fill("",(rxnsystem.phases.phases_cnt))
                            for i in axes(rxnsystem.phases.indxs_surfs,1)
                                for j in axes(rxnsystem.phases.sites_names,1)
                                    x__factor = rxnsystem.phases.sites_coeffs[i,j]
                                    if x__factor > 0 
                                        x__factor_s = string(x__factor)
                                        if x__factor == 1 
                                            x__factor_s = "" 
                                        elseif isinteger(x__factor) == true
                                            x__factor_s = string(get_trunc(x__factor))
                                        end
                                        x__sites[rxnsystem.phases.indxs_surfs[i]] = string(x__sites[rxnsystem.phases.indxs_surfs[i]],(length(x__sites[rxnsystem.phases.indxs_surfs[i]]) > 0 ? ", " : ""),x__factor_s,rxnsystem.phases.sites_names[j])
                                    end 
                                end 
                            end 
                            x__dists = str_enforcenumprecision(rxnsystem.phases.neighbordists.value, 2)
                            x__dists = map(x -> (tryparse(Float64,x) <= 0 ? "" : x), x__dists)
                            x__areas = str_enforcenumprecision(rxnsystem.phases.cellareas.value, 2)
                            x__areas = map(x -> (tryparse(Float64,x) <= 0 ? "" : x), x__areas)
                            x__cellcnts = map(x -> (x <= 0 ? "" : string(x)), rxnsystem.phases.cellcounts) 
                            x__shapefactors = map(x -> (x <= 0 ? "" : string(x)), rxnsystem.phases.cellshapefactors) 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    phases : ",join(rxnsystem.phases.phases_names,", ")))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    params : "))
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.phases.phases_names, 
                                                    [
                                                        ["type", "facet", "reflattice", "neighbordist", "cellarea", "cellcount", "shapefactor", "sites"], 
                                                        ["", "", "", string("(",rxnsystem.phases.neighbordists.units,")"), string("(",rxnsystem.phases.cellareas.units,")"), "", "", ""]
                                                    ], 
                                                    hcat(rxnsystem.phases.types, rxnsystem.phases.facets, rxnsystem.phases.reflattices, x__dists, x__areas, x__cellcnts, x__shapefactors, x__sites), 
                                                    0, false, true, true
                                                )
                        end 
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Cell Properties' property of reaction system object is missing"
                    end
                end

                # ODE Species
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  ODE Species : "))
                    if rxnsystem.odespecies !== nothing 
                        x__ary = fill("",(size(rxnsystem.odespecies.names,1),8))
                        for i in axes(rxnsystem.odespecies.indxs_active,1)
                            x__ary[rxnsystem.odespecies.indxs_active[i],1] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_inactive,1)
                            x__ary[rxnsystem.odespecies.indxs_inactive[i],2] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_gas,1)
                            x__ary[rxnsystem.odespecies.indxs_gas[i],3] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_nongas,1)
                            x__ary[rxnsystem.odespecies.indxs_nongas[i],4] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_site,1)
                            x__ary[rxnsystem.odespecies.indxs_site[i],5] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_nonsite,1)
                            x__ary[rxnsystem.odespecies.indxs_nonsite[i],6] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_ads,1)
                            x__ary[rxnsystem.odespecies.indxs_ads[i],7] = "x"
                        end 
                        for i in axes(rxnsystem.odespecies.indxs_coads,1)
                            x__ary[rxnsystem.odespecies.indxs_coads[i],8] = "x"
                        end 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  "))
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.odespecies.names, 
                                                    ["type","active","inactive","gas","nongas","site","nonsite","ads","coads"], 
                                                    hcat(rxnsystem.odespecies.types,x__ary), 
                                                    0, false, true, true
                                                ) 
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'ODE Species' property of reaction system object is missing"
                    end
                end 

                # Configurations
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Configurations : "))
                    if rxnsystem.configurations !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    count  : ",rxnsystem.configurations.cnt))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    params : "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        x__ary = fill("",(rxnsystem.configurations.cnt,3))
                        for i in axes(rxnsystem.configurations.names,1)
                            for j in axes(rxnsystem.configurations.vibfreqs.value,2) 
                                if rxnsystem.configurations.vibfreqs.value[i,j] <= 0 
                                    if j > 1 
                                        x__ary[i,1] = join(str_enforcenumprecision(view(rxnsystem.configurations.vibfreqs.value,i,1:(j-1)), 0),", ")
                                    end 
                                    break 
                                end 
                            end 
                            for j in axes(rxnsystem.configurations.rotfreqs.value,2) 
                                if rxnsystem.configurations.rotfreqs.value[i,j] <= 0 
                                    if j > 1 
                                        x__ary[i,2] = join(str_enforcenumprecision(view(rxnsystem.configurations.rotfreqs.value,i,1:(j-1)), 0),", ")
                                    end 
                                    break 
                                end 
                            end 
                            for j in axes(rxnsystem.configurations.trsfreqs.value,2) 
                                if rxnsystem.configurations.trsfreqs.value[i,j] <= 0 
                                    if j > 1 
                                        x__ary[i,3] = join(str_enforcenumprecision(view(rxnsystem.configurations.trsfreqs.value,i,1:(j-1)), 0),", ")
                                    end 
                                    break 
                                end 
                            end 
                        end 
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.configurations.names, 
                                                    [
                                                        ["origin","composition","enthalpy","vib freqs","rot freqs","trs freqs"], 
                                                        ["","",string("(",rxnsystem.configurations.enthalpies.units,")"),string("(",rxnsystem.configurations.vibfreqs.units,")"),string("(",rxnsystem.configurations.rotfreqs.units,")"),string("(",rxnsystem.configurations.trsfreqs.units,")")]
                                                    ], 
                                                    hcat(
                                                        rxnsystem.configurations.origins, 
                                                        rxnsystem.configurations.compositions, 
                                                        str_enforcenumprecision(rxnsystem.configurations.enthalpies.value, 2), 
                                                        x__ary
                                                    ), 
                                                    0, false, true, true
                                                ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    reference coverages :"))
                        x__unq_ary = fill("",(rxnsystem.configurations.cnt,1))
                        for i in axes(rxnsystem.configurations.uniquecovs_indxs,1)
                            x__unq_ary[rxnsystem.configurations.uniquecovs_indxs[i]] = "x"
                        end 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"        "), err_flag, err_msg, false, false, 1, 1, 
                                                view(rxnsystem.configurations.names,rxnsystem.configurations.indxs_adstst), 
                                                vcat( 
                                                    ["unique"], 
                                                    rxnsystem.phases.sites_names, 
                                                    view(rxnsystem.configurations.states_compounds,rxnsystem.configurations.states_indxs_nongas)
                                                ), 
                                                hcat( 
                                                    view(x__unq_ary,rxnsystem.configurations.indxs_adstst), 
                                                    view(rxnsystem.configurations.refsitescovs_scaled,rxnsystem.configurations.indxs_adstst,:), 
                                                    view(rxnsystem.configurations.refstatescovs_scaled,rxnsystem.configurations.indxs_adstst,rxnsystem.configurations.states_indxs_nongas)
                                                ), 
                                                rxnsystem.log_num_prec, true, false, false
                                            ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    references coefficients : ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" ")) 
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.configurations.names, 
                                                    [
                                                        rxnsystem.configurations.refGcmpdnames, 
                                                        string.(rxnsystem.configurations.refGcfgindxs), 
                                                        string.(rxnsystem.configurations.refGstateindxs)
                                                    ], 
                                                    get_transpose(rxnsystem.configurations.refGcoeffs), 
                                                    0, false, true, true 
                                                ) 
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Configurations' property of reaction system object is missing"
                    end 
                end 

                # Reactions
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  Reactions : "))
                    if rxnsystem.reactions !== nothing 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    pairs : ",rxnsystem.reactions.pairs_cnt)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        x__ary1_fwd = fill("",(rxnsystem.reactions.pairs_cnt,2))
                        for i in axes(rxnsystem.reactions.pairs_kupdmodes_fwd_const,1)
                            x__ary1_fwd[rxnsystem.reactions.pairs_kupdmodes_fwd_const[i],1] = "x"
                        end 
                        for i in axes(rxnsystem.reactions.pairs_kupdmodes_fwd_varbl,1)
                            x__ary1_fwd[rxnsystem.reactions.pairs_kupdmodes_fwd_varbl[i],2] = "x"
                        end 
                        x__ary1_rev = fill("",(rxnsystem.reactions.pairs_cnt,2))
                        for i in axes(rxnsystem.reactions.pairs_kupdmodes_rev_const,1)
                            x__ary1_rev[rxnsystem.reactions.pairs_kupdmodes_rev_const[i],1] = "x"
                        end 
                        for i in axes(rxnsystem.reactions.pairs_kupdmodes_rev_varbl,1)
                            x__ary1_rev[rxnsystem.reactions.pairs_kupdmodes_rev_varbl[i],2] = "x"
                        end 
                        x__ary_fwd = fill("",(rxnsystem.reactions.pairs_cnt,size(rxnsystem.reactions.rxnsegs_names,1)))
                        x__ary_rev = fill("",(rxnsystem.reactions.pairs_cnt,size(rxnsystem.reactions.rxnsegs_names,1)))
                        for i in 1:rxnsystem.reactions.pairs_cnt
                            for j in axes(rxnsystem.reactions.rxnsegs_names,1)
                                x__ary_fwd[i,j] = string(rxnsystem.reactions.rxnkupdmodes_names[rxnsystem.reactions.pairs_kupdmodes[i,rxnsystem.reactions.rxndirs_dindxs["fwd"],j]],": ",rxnsystem.reactions.pairs_segments_names[i,j])
                                x__ary_rev[i,j] = string(rxnsystem.reactions.rxnkupdmodes_names[rxnsystem.reactions.pairs_kupdmodes[i,rxnsystem.reactions.rxndirs_dindxs["rev"],j]],": ",rxnsystem.reactions.pairs_segments_names[i,j])
                            end 
                        end 
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.reactions.pairs_names, 
                                                    [
                                                        vcat(["molexprn","tsrbalance","tspbalance","rxntype","fwd",    "",       "",           "",      "",      ""        ],fill("",(size(rxnsystem.reactions.rxnsegs_names,1)-1)),["rev",    "",       "",           "",      "",      ""        ],fill("",(size(rxnsystem.reactions.rxnsegs_names,1)-1))), 
                                                        vcat(["",        "",          "",          "",       "kmethod","kfactor","kratefactor","kconst","kvarbl","segments"],fill("",(size(rxnsystem.reactions.rxnsegs_names,1)-1)),["kmethod","kfactor","kratefactor","kconst","kvarbl","segments"],fill("",(size(rxnsystem.reactions.rxnsegs_names,1)-1))), 
                                                        vcat(["",        "",          "",          "",       "",       "",       "",           "",      "",     ],rxnsystem.reactions.rxnsegs_names,                                ["",       "",       "",           "",      "",     ],rxnsystem.reactions.rxnsegs_names)
                                                    ], 
                                                    hcat(
                                                        rxnsystem.reactions.pairs_molexprns, 
                                                        str_enforcenumprecision(rxnsystem.reactions.pairs_tsrbalances,2), 
                                                        str_enforcenumprecision(rxnsystem.reactions.pairs_tspbalances,2), 
                                                        rxnsystem.reactions.pairs_rxntypes, 
                                                        rxnsystem.reactions.pairs_kmethods[:,rxnsystem.reactions.rxndirs_dindxs["fwd"]], 
                                                        rxnsystem.reactions.pairs_kfactors[:,rxnsystem.reactions.rxndirs_dindxs["fwd"]], 
                                                        rxnsystem.reactions.pairs_kratefactors[:,rxnsystem.reactions.rxndirs_dindxs["fwd"]], 
                                                        x__ary1_fwd, x__ary_fwd, 
                                                        rxnsystem.reactions.pairs_kmethods[:,rxnsystem.reactions.rxndirs_dindxs["rev"]], 
                                                        rxnsystem.reactions.pairs_kfactors[:,rxnsystem.reactions.rxndirs_dindxs["rev"]], 
                                                        rxnsystem.reactions.pairs_kratefactors[:,rxnsystem.reactions.rxndirs_dindxs["rev"]], 
                                                        x__ary1_rev, x__ary_rev 
                                                    ), 
                                                    0, false, true, true
                                                ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    sides : ",rxnsystem.reactions.cnt)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        x__ary1 = fill("",(rxnsystem.reactions.cnt,2))
                        for i in axes(rxnsystem.reactions.kupdmodes_const,1)
                            x__ary1[rxnsystem.reactions.kupdmodes_const[i],1] = "x"
                        end 
                        for i in axes(rxnsystem.reactions.kupdmodes_varbl,1)
                            x__ary1[rxnsystem.reactions.kupdmodes_varbl[i],2] = "x"
                        end 
                        x__ary2 = fill("",(rxnsystem.reactions.cnt,size(rxnsystem.reactions.rxnsegs_names,1)))
                        for i in 1:rxnsystem.reactions.cnt
                            for j in axes(rxnsystem.reactions.rxnsegs_names,1)
                                x__ary2[i,j] = string(rxnsystem.reactions.rxnkupdmodes_names[rxnsystem.reactions.kupdmodes[i,j]],": ",rxnsystem.reactions.segments_names[i,j])
                            end 
                        end 
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.reactions.names, 
                                                    [
                                                        vcat(["molexprn","tsrbalance","tspbalance","rxntype","kmethod","kfactor","kratefactor","kfixed","kvarbl","segments"],fill("",(size(rxnsystem.reactions.rxnsegs_names,1)-1))), 
                                                        vcat(["",        "",          "",         "",       "",       "",        "",           "",      ""      ],rxnsystem.reactions.rxnsegs_names) 
                                                    ], 
                                                    hcat(
                                                        rxnsystem.reactions.molexprns, 
                                                        str_enforcenumprecision(rxnsystem.reactions.tsrbalances,2), 
                                                        str_enforcenumprecision(rxnsystem.reactions.tspbalances,2), 
                                                        rxnsystem.reactions.rxntypes, 
                                                        rxnsystem.reactions.kmethods, 
                                                        rxnsystem.reactions.kfactors, 
                                                        rxnsystem.reactions.kratefactors, 
                                                        x__ary1, 
                                                        x__ary2
                                                    ), 
                                                    0, false, true, true
                                                ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    rate coeffs : ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      alpha: ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"        "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.reactions.names, 
                                                    rxnsystem.odespecies.names, 
                                                    transpose(rxnsystem.reactions.coeffs_alpha), 
                                                    0, false, true, true
                                                ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      beta : ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"        "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.reactions.names, 
                                                    rxnsystem.odespecies.names, 
                                                    transpose(rxnsystem.reactions.coeffs_beta), 
                                                    0, false, true, true
                                                ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      gamma: ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"        "), err_flag, err_msg, false, false, 1, 1, 
                                                    rxnsystem.reactions.names, 
                                                    rxnsystem.odespecies.names, 
                                                    transpose(rxnsystem.reactions.coeffs_gamma), 
                                                    0, false, true, true
                                                ) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    else
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    missING"))
                        err_flag = true
                        err_msg = "'Reactions' property of reaction system object is missing"
                    end
                end 

                # Finalize 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
            else 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  ERROR"))
            end 
        end 

        return err_flag, err_msg
    end

    function log_rxnrun(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, run_temps, run_temp_index) 
        
        # Check error state 
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("Reaction Run Object: "))
            if err_flag == false 
                err_flag = false 
                err_msg = ""

                # General parameters 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  name        : ",rxnrun.name))
