                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  single pathway state detection : ", rxnrun.spsoptions.analyze))
                    if rxnrun.stsoptions.analyze == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    timespan extend                 : ",rxnrun.spsoptions.timespan_extend))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    timespan extend factor          : ",rxnrun.spsoptions.timespan_extend_factor))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    timespan extend maxchg          : ",rxnrun.spsoptions.timespan_extend_maxchg))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    timespan extend cntmax          : ",rxnrun.spsoptions.timespan_extend_cntmax))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    mintime beforeonset fracofmax   : ",rxnrun.spsoptions.mintime_beforeonset_fracofmax))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    mintime beforeonset interval    : ",rxnrun.spsoptions.mintime_beforeonset_interval.value," ",rxnrun.spsoptions.mintime_beforeonset_interval.units))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    mintime afteronset fracofmax    : ",rxnrun.spsoptions.mintime_afteronset_fracofmax))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    mintime afteronset interval_min : ",rxnrun.spsoptions.mintime_afteronset_interval_min.value," ",rxnrun.spsoptions.mintime_afteronset_interval_min.units))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    mintime afteronset interval_suf : ",rxnrun.spsoptions.mintime_afteronset_interval_suf.value," ",rxnrun.spsoptions.mintime_afteronset_interval_suf.units))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    onsetoffset fracofmax           : ",rxnrun.spsoptions.onsetoffset_fracofmax))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    onsetoffset interval            : ",rxnrun.spsoptions.onsetoffset_interval.value," ",rxnrun.spsoptions.onsetoffset_interval.units)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    drcs abstol curr                : ",rxnrun.spsoptions.drcs_abstol_curr)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    drcs abstol rmdr                : ",rxnrun.spsoptions.drcs_abstol_rmdr)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    drcs fractol curr               : ",rxnrun.spsoptions.drcs_fractol_curr)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    drcs fractol rmdr               : ",rxnrun.spsoptions.drcs_fractol_rmdr)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    drcs kinetic sum err curr       : ",rxnrun.spsoptions.drcs_kineticsumerr_curr)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    drcs kinetic sum err rmdr       : ",rxnrun.spsoptions.drcs_kineticsumerr_rmdr)) 
                    end 
                end 

                # sensitivity analysis
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  sensitivity analysis : ",rxnrun.snsoptions.analyze))
                    if rxnrun.snsoptions.analyze == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    total states : ",(rxnrun.snsoptions.drc_fractions_cnt + rxnrun.snsoptions.drc_energies_cnt)))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    species      : ",join(rxnrun.snsoptions.drc_species,", "))) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    selectivity pairs : ")) 
                        for i in axes(rxnrun.snsoptions.dsc_pairs,1)
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      ",rxnrun.snsoptions.dsc_pairs[i,1]," | ",rxnrun.snsoptions.dsc_pairs[i,2])) 
                        end 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    fractions    : ",rxnrun.snsoptions.drc_fractions))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      setsize    : ",rxnrun.snsoptions.drc_fractions_setsize))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      chunksize  : ",rxnrun.snsoptions.drc_fractions_chunksize))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      cnt        : ",rxnrun.snsoptions.drc_fractions_cnt))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      gas        : ",rxnrun.snsoptions.drc_fractions_gas))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      adsorbate  : ",rxnrun.snsoptions.drc_fractions_ads))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    energies     : ",rxnrun.snsoptions.drc_energies))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      setsize    : ",rxnrun.snsoptions.drc_energies_setsize))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      chunksize  : ",rxnrun.snsoptions.drc_energies_chunksize))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      cnt        : ",rxnrun.snsoptions.drc_energies_cnt))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      gas        : ",rxnrun.snsoptions.drc_energies_gas))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      adsorbate  : ",rxnrun.snsoptions.drc_energies_ads))
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      ts state   : ",rxnrun.snsoptions.drc_energies_tst))
                    end 
                end 

                # output options
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  simulation output : "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    files format : ",rxnrun.outputoptions.files_format)) 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("    output flags "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      species "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        fractions           : ",rxnrun.outputoptions.flags_spcs_x))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate                : ",rxnrun.outputoptions.flags_spcs_r))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate integral       : ",rxnrun.outputoptions.flags_spcs_ri))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate compare        : ",rxnrun.outputoptions.flags_spcs_rc))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        molar rate          : ",rxnrun.outputoptions.flags_spcs_n))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        molar rate integral : ",rxnrun.outputoptions.flags_spcs_ni))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        molar rate compare  : ",rxnrun.outputoptions.flags_spcs_nc))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        energies            : ",rxnrun.outputoptions.flags_spcs_G))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      sites participation "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        fractions           : ",rxnrun.outputoptions.flags_sites_x))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate                : ",rxnrun.outputoptions.flags_sites_r))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        TOFs                : ",rxnrun.outputoptions.flags_sites_tof))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      configurations "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        energies            : ",rxnrun.outputoptions.flags_cfg_G))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      reactions "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        general             : ",rxnrun.outputoptions.flags_rxn_info))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        constants           : ",rxnrun.outputoptions.flags_rxn_k))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate                : ",rxnrun.outputoptions.flags_rxn_r))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate compare        : ",rxnrun.outputoptions.flags_rxn_rc))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        energies            : ",rxnrun.outputoptions.flags_rxn_G))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      reaction pairs "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate                : ",rxnrun.outputoptions.flags_rpn_r))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        rate compare        : ",rxnrun.outputoptions.flags_rpn_rc))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        energies            : ",rxnrun.outputoptions.flags_rpn_G))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("      sensitivity analysis "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        jacobian            : ",rxnrun.outputoptions.flags_sns_jac))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        DRC                 : ",rxnrun.outputoptions.flags_sns_drc))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("        DSC                 : ",rxnrun.outputoptions.flags_sns_dsc))
                end 

                # ODE fractions 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  ODE fractions : "))
                    x__ary = fill("",(rxnsystem.odespecies.cnt,2))
                    for i in axes(rxnrun.odefracs_fixed,1)
                        x__ary[rxnrun.odefracs_fixed[i],1] = "x"
                    end 
                    for i in axes(rxnrun.odefracs_varbl,1)
                        x__ary[rxnrun.odefracs_varbl[i],2] = "x"
                    end 
                    log_table_msgopts(msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, false, false, 1, 1, 
                            rxnsystem.odespecies.names, 
                            ["ref", "ini", "const", "varbl"], 
                            hcat(
                                str_precfloat_m(rxnrun.odefracs_ref,rxnsystem.log_num_prec,true), 
                                str_precfloat_m(rxnrun.odefracs_ini,rxnsystem.log_num_prec,true), 
                                x__ary
                            ), 
                            rxnsystem.log_num_prec, rxnsystem.log_force_prec, true, true
                        ) 
                end 
                
                # Finalize 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string(" "))
            else 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, false, 1, 1, string("  ERROR"))
            end
        end 
        
        return err_flag, err_msg
    end



    # Reaction system initialization functions

    function Init__RxnSystem(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, cache_method) 

        # Check error state 
        rs = ct__RxnSystem() 
        if err_flag == false
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
            
            # Retrieve general parameters
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing display precision parameters"))
                x__log_num_prec = 4
                x__log_force_prec = true 
                x__output_num_prec = 10
                x__output_force_prec = true 
                x__covs_detect_tol = 0.0001
            end 
            
            # Retrieve physical units 
            if err_flag == false  
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing physical units"))
                err_flag, err_msg, x__physunits = Init__PhysUnits(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg)
            end 

            # Retrieve physical constants
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing physical constants"))
                err_flag, err_msg, x__physcnsts = Init__PhysCnsts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg)
            end 

            # Retrieve physical conversions
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing physical conversions"))
                err_flag, err_msg, x__physconvs = Init__PhysConvs(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg)
            end 

            # Retrieve atoms
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing atoms"))
                err_flag, err_msg, x__atoms = Init__Atoms(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata)
            end 

            # Retrieve molecules
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing molecules"))
                err_flag, err_msg, x__molecules = Init__Molecules(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, x__physunits, x__physcnsts, x__physconvs, x__atoms)
            end 

            # Retrieve phases
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing phases"))
                err_flag, err_msg, x__phases = Init__Phases(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, x__physunits, x__physcnsts, x__physconvs, x__atoms, x__molecules)
            end 

            # Retrieve ODE species
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing ODE species"))
                err_flag, err_msg, x__odespecies = Init__ODESpecies(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, x__physunits, x__physcnsts, x__physconvs, x__atoms, x__molecules, x__phases)
            end 

            # Retrieve configurations
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing configurations"))
                err_flag, err_msg, x__configurations = Init__Configurations(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, x__physunits, x__physcnsts, x__physconvs, x__atoms, x__molecules, x__phases, x__odespecies)
            end 

            # Initialize reactions 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing reactions"))
                err_flag, err_msg, x__reactions = Init__Reactions(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, x__physunits, x__physcnsts, x__physconvs, x__atoms, x__molecules, x__phases, x__odespecies, x__configurations)
            end 

            # Construct reaction object
            if err_flag == false 
                rs = ct__RxnSystem(x__log_num_prec, x__log_force_prec, x__output_num_prec, x__output_force_prec, x__covs_detect_tol, cache_method, x__physunits, x__physcnsts, x__physconvs, x__atoms, x__molecules, x__phases, x__odespecies, x__configurations, x__reactions) 
            end 

            # insert spacer line
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
        end 

        return err_flag, err_msg, rs
    end

    function Init__PhysUnits(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg) 

        # Check error state 
        rs = ct__PhysUnits() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # assign units
            x__time = "s"
            x__time_si = "s"
            x__distance = "angstrom"
            x__distance_si = "m"
            x__area = "angstrom^2"
            x__area_si = "m^2"
            x__temperature = "K"
            x__temperature_si = "K"
            x__pressure = "bar"
            x__pressure_si = "Pa"
            x__coverage = "ML"
            x__coverage_si = "ML"
            x__molwt = "g / mol"
            x__molwt_si = "kg / mol"
            x__rotinertia = "amu * Angstrom^2"
            x__rotinertia_si = "kg * m^2"
            x__energy = "eV"
            x__energy_si = "J"
            x__wavenumber = "1/cm"
            x__wavenumber_si = "1/m"

            # construct object
            rs = ct__PhysUnits(x__time, x__time_si, x__distance, x__distance_si, x__area, x__area_si, x__temperature, x__temperature_si, x__pressure, x__pressure_si, x__coverage, x__coverage_si, x__molwt, x__molwt_si, x__rotinertia, x__rotinertia_si, x__energy, x__energy_si, x__wavenumber, x__wavenumber_si) 
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__PhysCnsts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg) 
        
        # Check error state 
        rs = ct__PhysCnsts() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            
            # fundamental physical constants
            x__h_p   = ct__SFloat64("h_p"  , 4.135668e-15, 6.626072e-34, false, "eV * sec", "J * sec", false)     # Planck's constant       : eV * sec
            x__c_v   = ct__SFloat64("c_v"  , 299792458   , 299792458   , false, "m / sec" , "m / sec", false)     # Speed of light (vacuum) : m / sec
            x__k_b   = ct__SFloat64("k_b"  , 8.617333e-5 , 1.380649e-23, false, "eV / K"  , "J / K"  , false)     # Boltzmann Constant      : eV / K
            x__N_a   = ct__SFloat64("N_a"  , 6.022141e23 , 6.022141e23 , false, "1 / mol" , "1 / mol", false)     # Avogadro constant       : 1 / mol
            x__P_o   = ct__SFloat64("p_o"  , 1.01325     , 101325      , false, "bar"     , "Pa"     , false)     # standard pressure       : bar
            x__amu   = ct__SFloat64("amu"  , 1.660539e-27, 1.660539e-27, false, "kg"      , "kg"     , false)     # atomic mass unit        : kg
            
            # combinations
            x__hp_cv = ct__SFloat64("hp_cv", 1.239842e-6 , 1.986446e-25, false, "eV * m"  , "J * m"  , false)     # Planck's constant x Speed of light (vacuum) : eV * m
            
            # construct object
            rs = ct__PhysCnsts(x__h_p, x__c_v, x__k_b, x__N_a, x__P_o, x__amu, x__hp_cv)
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__PhysConvs(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg) 
        
        # Check error state 
        rs = ct__PhysConvs() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            
            # Initialize physical conversions
            x__s_hr   = 3600             # seconds per hour        : sec / hr
            x__J_eV   = 1.602177e-19     # Joule per electron-volt : J / eV
            x__Pa_bar = 1e5              # Pascals per bar         : Pa / bar
            x__g_kg   = 1e3              # gram per kilogram       : g / kg
            x__m_cm   = 0.01             # meters per centimeter   : m / cm
            x__m_Ang  = 1e-10            # meters per angstrom     : m / Angstrom
            
            # construct object
            rs = ct__PhysConvs(x__s_hr, x__J_eV, x__Pa_bar, x__g_kg, x__m_cm, x__m_Ang)
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__Atoms(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata) 
        
        # Check error state 
        rs = ct__Atoms() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Retrieve atom and molecule data 
            if err_flag == false 
                err_flag, err_msg, x__atomrefs_ary  = get_configrecords(err_flag, err_msg, configdata, "ATOM_REFS|ATOM_REF") 
                err_flag, err_msg, x__molecules_ary = get_configrecords(err_flag, err_msg, configdata, "MOLECULES|MOLECULE") 
            end 
            
            # Retrieve atoms 
            if err_flag == false 
                x__atoms = Array{String,1}(undef,0) 
                for i in axes(x__molecules_ary,1)
                    if haskey(x__molecules_ary[i].vals, "name") && haskey(x__molecules_ary[i].vals, "molexprn") && haskey(x__molecules_ary[i].vals, "phase")
                        if x__molecules_ary[i].vals["name"] !== nothing && x__molecules_ary[i].vals["molexprn"] !== nothing && x__molecules_ary[i].vals["phase"] !== nothing
                            x__atoms_names, x__atoms_counts, x__atoms_tot, x__atoms_all = get_atomcounts(x__molecules_ary[i].vals["molexprn"]) 
                            for j in axes(x__atoms_names,1)
                                push!(x__atoms,string(x__atoms_names[j]))
                            end 
                        end 
                    end 
                end 
                x__atoms = unique(x__atoms) 
                sort!(x__atoms) 
                x__atoms_dindxs = Dict{String,Int}()
                for i in axes(x__atoms,1)
                    x__atoms_dindxs[x__atoms[i]] = i 
                end 
                x__atoms_refatomindxs = Array{Int,1}(undef,0)
            end 
            
            # Retrieve reference atoms and compounds 
            if err_flag == false 
                x__refatoms = Array{String,1}(undef,0) 
                x__refcmpds = Array{String,1}(undef,0) 
                for i in axes(x__atomrefs_ary,1) 
                    if haskey(x__atomrefs_ary[i].vals, "compound") && haskey(x__atomrefs_ary[i].vals, "atom") && haskey(x__atomrefs_ary[i].vals, "factor")
                        if x__atomrefs_ary[i].vals["compound"] !== nothing && x__atomrefs_ary[i].vals["atom"] !== nothing && x__atomrefs_ary[i].vals["factor"] !== nothing
                            err_flag, err_msg, vld_flag, x_val = try_parse(err_flag, err_msg, x__atomrefs_ary[i].vals["factor"], 0.0) 
                            if err_flag == false && vld_flag == true 
                                push!(x__refatoms,string(x__atomrefs_ary[i].vals["atom"])) 
                                push!(x__refcmpds,string(x__atomrefs_ary[i].vals["compound"])) 
                            end 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
                x__refatoms = unique(x__refatoms) 
                sort!(x__refatoms) 
                x__refatoms_dindxs = Dict{String,Int}()
                for i in axes(x__refatoms,1)
                    x__refatoms_dindxs[x__refatoms[i]] = i 
                    if haskey(x__atoms_dindxs,x__refatoms[i])
                        push!(x__atoms_refatomindxs,x__atoms_dindxs[x__refatoms[i]])
                    end 
                end 
                x__refcmpds = unique(x__refcmpds) 
                sort!(x__refcmpds) 
                x__refcmpds_dindxs = Dict{String,Int}()
                for i in axes(x__refcmpds,1)
                    x__refcmpds_dindxs[x__refcmpds[i]] = i 
                end 
            end 

            # Retrieve coefficients 
            if err_flag == false 
                x__refcoeffs = fill(0.0,(size(x__refatoms,1),size(x__refcmpds,1))) 
                for i in axes(x__atomrefs_ary,1) 
                    if haskey(x__atomrefs_ary[i].vals, "compound") && haskey(x__atomrefs_ary[i].vals, "atom") && haskey(x__atomrefs_ary[i].vals, "factor") 
                        if x__atomrefs_ary[i].vals["compound"] !== nothing && x__atomrefs_ary[i].vals["atom"] !== nothing && x__atomrefs_ary[i].vals["factor"] !== nothing 
                            err_flag, err_msg, vld_flag, x_factor = try_parse(err_flag, err_msg, x__atomrefs_ary[i].vals["factor"], 0.0) 
                            if err_flag == false && vld_flag == true 
                                x__refcoeffs[x__refatoms_dindxs[x__atomrefs_ary[i].vals["atom"]],x__refcmpds_dindxs[x__atomrefs_ary[i].vals["compound"]]] += x_factor 
                            end 
                        end 
                    end 
                end 
            end 
            
            # construct object
            if err_flag == false 
                rs = ct__Atoms(x__atoms, x__atoms_dindxs, x__atoms_refatomindxs, x__refatoms, x__refatoms_dindxs, x__refcmpds, x__refcmpds_dindxs, x__refcoeffs)
            end 
        end 

        return err_flag, err_msg, rs 
    end

    function Init__Molecules(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms) 
        
        # Check error state 
        rs = ct__Molecules() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Retrieve molecule data 
            if err_flag == false 
                err_flag, err_msg, x__molecules_ary              = get_configrecords(err_flag, err_msg, configdata, "MOLECULES|MOLECULE")
                err_flag, err_msg, x__molecules_ary_rotconstants = get_configrecords(err_flag, err_msg, configdata, "MOLECULE_ROT_CONSTANTS|MOLECULE_ROT_CONSTANT")    
            end 
            
            # Retrieve molecule names
            if err_flag == false 
                x__aryindxs = Array{Int,1}(undef,0)
                x__names = Array{String,1}(undef,0) 
                for i in axes(x__molecules_ary,1) 
                    if haskey(x__molecules_ary[i].vals, "name") && haskey(x__molecules_ary[i].vals, "molexprn") && haskey(x__molecules_ary[i].vals, "phase")
                        if x__molecules_ary[i].vals["name"] !== nothing && x__molecules_ary[i].vals["molexprn"] !== nothing && x__molecules_ary[i].vals["phase"] !== nothing 
                            if length(x__molecules_ary[i].vals["name"]) > 0 && length(x__molecules_ary[i].vals["molexprn"]) > 0 && length(x__molecules_ary[i].vals["phase"]) > 0 
                                push!(x__aryindxs,i)
                                push!(x__names,string(x__molecules_ary[i].vals["name"]))
                            end 
                        end
                    end
                end 
                x__cnt = size(x__names,1)
                x__dindxs = Dict{String,Int}()
                for i in axes(x__names,1)
                    x__dindxs[x__names[i]] = i 
                end 
            end 

            # Retrieve molecule parameters 
            if err_flag == false 
                x__molexprns          = fill("",(x__cnt)) 
                x__coadsequivs        = fill("",(x__cnt)) 
                x__phases             = fill("",(x__cnt)) 
                x__atomcoeffs         = fill(0.0,(x__cnt,size(atoms.atoms_names,1)))
                x__atomrefcoeffs      = fill(0.0,(x__cnt,size(atoms.refatoms_names,1),size(atoms.refcmpds_names,1)))
                x__atomrefcmpdtotals  = fill(0.0,(x__cnt,size(atoms.refcmpds_names,1)))
                x__molwts             = fill(0.0,(x__cnt)) 
                x__spinmultiplicities = fill(0.0,(x__cnt)) 
                x__rotsymfactors      = fill(0.0,(x__cnt)) 
                x__rotpeaks           = fill(0.0,(x__cnt)) 
                x__rotbarriers        = fill(0.0,(x__cnt)) 
                x__rotinertias        = fill(0.0,(x__cnt)) 
                x__trsareafactors     = fill(0.0,(x__cnt)) 
                x__trspeaks           = fill(0.0,(x__cnt)) 
                x__trsbarriers        = fill(0.0,(x__cnt)) 
                x__indxs_active       = Array{Int,1}(undef,0) 
                x__indxs_inactive     = Array{Int,1}(undef,0) 
                x__indxs_odespecies   = Array{Int,1}(undef,0) 
                x__indxs_gas          = Array{Int,1}(undef,0) 
                x__indxs_ads          = Array{Int,1}(undef,0) 
                x__indxs_coads        = Array{Int,1}(undef,0) 
                x__rotconstants       = fill(0.0,(x__cnt,3))
                for i in axes(x__names,1)
                    err_flag, err_msg, ptype_molexprn,      pval_molexprn      = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "molexprn",             "", "",    "string",  false, true,  "mixed") 
                    err_flag, err_msg, ptype_coadsequiv,    pval_coadsequiv    = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "coadsorbate_adsequiv", "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_phase,         pval_phase         = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "phase",                "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_molwt,         pval_molwt         = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "molwt",                "", 0.0,   "Float64", true,  false, ""     )
                    err_flag, err_msg, ptype_spinmult,      pval_spinmult      = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "spinmultiplicity",     "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_rotsymfactor,  pval_rotsymfactor  = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "rotsymfactor",         "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_rotpeaks,      pval_rotpeak       = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "rotpeaks",             "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_rotbarrier,    pval_rotbarrier    = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "rotbarrier",           "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_rotinertia,    pval_rotinertia    = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "rotinertia",           "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_trsareafactor, pval_trsareafactor = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "trsareafactor",        "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_trspeaks,      pval_trspeak       = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "trspeaks",             "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_trsbarrier,    pval_trsbarrier    = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "trsbarrier",           "", "",    "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_odespecies,    pval_odespecies    = get_configproperty(err_flag, err_msg, x__molecules_ary[x__aryindxs[i]].vals, nothing, "", "odespecies",           "", false, "bool",    false, true,  "mixed")
                    if err_flag == false 
                        err_flag, err_msg, x__molwts[i]             = get_confignumber(err_flag, err_msg, Float64, pval_molwt[1],         "0", true, true, true,  true,  true) 
                        err_flag, err_msg, x__spinmultiplicities[i] = get_confignumber(err_flag, err_msg, Float64, pval_spinmult[1],      "1", true, true, false, true,  true) 
                        err_flag, err_msg, x__rotsymfactors[i]      = get_confignumber(err_flag, err_msg, Float64, pval_rotsymfactor[1],  "1", true, true, false, true,  true) 
                        err_flag, err_msg, x__rotpeaks[i]           = get_confignumber(err_flag, err_msg, Float64, pval_rotpeak[1],       "1", true, true, false, true,  true) 
                        err_flag, err_msg, x__rotbarriers[i]        = get_confignumber(err_flag, err_msg, Float64, pval_rotbarrier[1],    "0", true, true, false, false, true) 
                        err_flag, err_msg, x__rotinertias[i]        = get_confignumber(err_flag, err_msg, Float64, pval_rotinertia[1],    "0", true, true, false, false, true) 
                        err_flag, err_msg, x__trsareafactors[i]     = get_confignumber(err_flag, err_msg, Float64, pval_trsareafactor[1], "0", true, true, false, false, true) 
                        err_flag, err_msg, x__trspeaks[i]           = get_confignumber(err_flag, err_msg, Float64, pval_trspeak[1],       "1", true, true, false, true,  true) 
                        err_flag, err_msg, x__trsbarriers[i]        = get_confignumber(err_flag, err_msg, Float64, pval_trsbarrier[1],    "0", true, true, false, false, true) 
                    end 
                    if err_flag == false 
                        x__molexprns[i]   = replace(pval_molexprn[1],"--" => "") 
                        x__coadsequivs[i] = replace(pval_coadsequiv[1],"--" => "") 
                        x__phases[i]      = replace(pval_phase[1],"--" => "") 
                        x__atoms_names, x__atoms_counts, x__atoms_tot, x__atoms_all = get_atomcounts(x__molexprns[i]) 
                        for j in axes(x__atoms_names,1)
                            if haskey(atoms.atoms_dindxs,x__atoms_names[j])
                                x__atomcoeffs[i,atoms.atoms_dindxs[x__atoms_names[j]]] += x__atoms_counts[x__atoms_names[j]]
                            end 
                        end 
                        x__atomrefcoeffs[i,:,:] .= view(x__atomcoeffs,i,atoms.atoms_refatomindxs) .* atoms.refcoeffs
                        x__atomrefcmpdtotals[i,:] .= vec(sum(reshape(x__atomrefcoeffs[i,:,:],size(atoms.refatoms_names,1),size(atoms.refcmpds_names,1)),dims=1))
                        if x__phases[i] != "coads"
                            push!(x__indxs_active,i)
                        else 
                            push!(x__indxs_inactive,i)
                        end 
                        if get_bool(pval_odespecies[1]) == true 
                            push!(x__indxs_odespecies,i)
                        end 
                        if x__phases[i] == "gas"
                            push!(x__indxs_gas,i)
                        elseif x__phases[i] == "ads"
                            push!(x__indxs_ads,i)
                        elseif x__phases[i] == "coads"
                            push!(x__indxs_coads,i)
                        end
                        x__ctr = 0
                        for j in axes(x__molecules_ary_rotconstants,1)
                            if haskey(x__molecules_ary_rotconstants[j].vals, "molecule") && haskey(x__molecules_ary_rotconstants[j].vals, "rotconstant")
                                if x__molecules_ary_rotconstants[j].vals["molecule"] !== nothing && x__molecules_ary_rotconstants[j].vals["rotconstant"] !== nothing
                                    if length(x__molecules_ary_rotconstants[j].vals["molecule"]) > 0 && length(x__molecules_ary_rotconstants[j].vals["rotconstant"]) > 0 
                                        if x__molecules_ary_rotconstants[j].vals["molecule"] == x__names[i] 
                                            err_flag, err_msg, vld_flag, x_rotconstant = try_parse(err_flag, err_msg, x__molecules_ary_rotconstants[j].vals["rotconstant"], 0.0) 
                                            if err_flag == false && vld_flag == true 
                                                err_flag, err_msg, ptype_rotconstant, pval_rotconstant = get_configproperty(err_flag, err_msg, x__molecules_ary_rotconstants[j].vals, nothing, "", "rotconstant", "", "", "float64", false, true, "mixed")
                                                if err_flag == false 
                                                    err_flag, err_msg, x_val = get_confignumber(err_flag, err_msg, Float64, pval_rotconstant[1], "0", true, true, false, false, true) 
                                                    if err_flag == false && x_val > 0 
                                                        x__ctr += 1 
                                                        x__rotconstants[i,x__ctr] = x_val 
                                                    end 
                                                end 
                                            end 
                                        end
                                    end 
                                end
                            end
                            if err_flag == true 
                                break 
                            end 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Attach units to molecule parameters 
            if err_flag == false 
                x__molwts_sf       = ct__SFloat64Array{1}("molwt",       x__cnt, x__molwts,       conv_value(physcnsts, physconvs, x__molwts,       physunits.molwt,      physunits.molwt_si     ), false, physunits.molwt,      physunits.molwt_si,      false) 
                x__rotbarriers_sf  = ct__SFloat64Array{1}("rotbarrier",  x__cnt, x__rotbarriers,  conv_value(physcnsts, physconvs, x__rotbarriers,  physunits.energy,     physunits.energy_si    ), false, physunits.energy,     physunits.energy_si,     false) 
                x__rotinertias_sf  = ct__SFloat64Array{1}("rotinertia",  x__cnt, x__rotinertias,  conv_value(physcnsts, physconvs, x__rotinertias,  physunits.rotinertia, physunits.rotinertia_si), false, physunits.rotinertia, physunits.rotinertia_si, false) 
                x__rotconstants_sf = ct__SFloat64Array{2}("rotconstant", x__cnt, x__rotconstants, conv_value(physcnsts, physconvs, x__rotconstants, physunits.rotinertia, physunits.rotinertia_si), false, physunits.rotinertia, physunits.rotinertia_si, false) 
                x__trsbarriers_sf  = ct__SFloat64Array{1}("trsbarrier",  x__cnt, x__trsbarriers,  conv_value(physcnsts, physconvs, x__trsbarriers,  physunits.energy,     physunits.energy_si    ), false, physunits.energy,     physunits.energy_si,     false) 
                x__molwt_kg_mol       = conv_value(physcnsts, physconvs, x__molwts_sf.value,       x__molwts_sf.units,       "kg/mol") 
                x__rotbarriers_J      = conv_value(physcnsts, physconvs, x__rotbarriers_sf.value,  x__rotbarriers_sf.units,  "J"     ) 
                x__rotconstants_kg_m2 = conv_value(physcnsts, physconvs, x__rotconstants_sf.value, x__rotconstants_sf.units, "kg*m^2") 
                x__rotinertias_kg_m2  = conv_value(physcnsts, physconvs, x__rotinertias_sf.value,  x__rotinertias_sf.units,  "kg*m^2") 
                x__trsbarriers_J      = conv_value(physcnsts, physconvs, x__trsbarriers_sf.value,  x__trsbarriers_sf.units,  "J"     ) 
            end 

            # Retrieve molecular types  
            if err_flag == false 
                x__moltypes_names = ["gas","lat","site","ads","coads","tst"]
                x__moltypes_dindxs = Dict{String,Int}()
                for i in axes(x__moltypes_names,1)
                    x__moltypes_dindxs[x__moltypes_names[i]] = i 
                end 
                x__moltypes_cnt = size(x__moltypes_names,1)
            end 

            # construct object
            if err_flag == false 
                rs = ct__Molecules(
                            x__cnt, x__names, x__dindxs, x__molexprns, x__coadsequivs, x__phases, 
                            x__atomcoeffs, x__atomrefcoeffs, x__atomrefcmpdtotals, x__molwts_sf, x__molwt_kg_mol, x__spinmultiplicities, 
                            x__rotsymfactors, x__rotconstants_sf, x__rotconstants_kg_m2, x__rotpeaks, x__rotbarriers_sf, x__rotbarriers_J, x__rotinertias_sf, x__rotinertias_kg_m2, 
                            x__trsareafactors, x__trspeaks, x__trsbarriers_sf, x__trsbarriers_J, 
                            x__indxs_active, x__indxs_inactive, x__indxs_odespecies, x__indxs_gas, x__indxs_ads, x__indxs_coads, 
                            x__moltypes_cnt, x__moltypes_dindxs, x__moltypes_names 
                        )
            end 
        end 

        return err_flag, err_msg, rs 
    end

    function Init__Phases(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms, molecules) 
        
        # Check error state 
        rs = ct__Phases() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Retrieve cell data 
            if err_flag == false 
                err_flag, err_msg, x__cells_ary = get_configrecords(err_flag, err_msg, configdata, "CELLS|CELL")
            end 

            # Retrieve cell names
            if err_flag == false 
                x__cells_names = Array{String,1}(undef,0) 
                x__aryindxs = Array{Int,1}(undef,0)
                for i in axes(x__cells_ary,1) 
                    if haskey(x__cells_ary[i].vals, "name") 
                        if x__cells_ary[i].vals["name"] !== nothing 
                            if length(x__cells_ary[i].vals["name"]) > 0 
                                push!(x__cells_names,x__cells_ary[i].vals["name"]) 
                                push!(x__aryindxs,i)
                            end 
                        end 
                    end 
                end 
                x__cells_dindxs = Dict{String,Int}()
                for i in axes(x__cells_names,1)
                    x__cells_dindxs[x__cells_names[i]] = i 
                end 
                x__cells_cnt = size(x__cells_names,1) 
            end 
            
            # Retrieve cell parameters
            if err_flag == false 
                x__cells_facets        = fill("", (x__cells_cnt)) 
                x__cells_neighbordists = fill(0.0,(x__cells_cnt)) 
                x__cells_areas         = fill(0.0,(x__cells_cnt)) 
                x__cells_counts        = fill(0.0,(x__cells_cnt)) 
                x__cells_shapefactors  = fill(0.0,(x__cells_cnt)) 
                x__cells_reflattices   = fill("", (x__cells_cnt)) 
                for i in axes(x__cells_names,1) 
                    err_flag, err_msg, ptype_facet,        pval_facet        = get_configproperty(err_flag, err_msg, x__cells_ary[x__aryindxs[i]].vals, nothing, "", "facet",        "", "",  "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_neighbordist, pval_neighbordist = get_configproperty(err_flag, err_msg, x__cells_ary[x__aryindxs[i]].vals, nothing, "", "neighbordist", "", 0.0, "Float64", true,  false, ""     )
                    err_flag, err_msg, ptype_area,         pval_area         = get_configproperty(err_flag, err_msg, x__cells_ary[x__aryindxs[i]].vals, nothing, "", "cellarea",     "", 0.0, "Float64", true,  false, ""     )
                    err_flag, err_msg, ptype_count,        pval_count        = get_configproperty(err_flag, err_msg, x__cells_ary[x__aryindxs[i]].vals, nothing, "", "cellcount",    "", 0.0, "Float64", true,  false, ""     )
                    err_flag, err_msg, ptype_shapefactor,  pval_shapefactor  = get_configproperty(err_flag, err_msg, x__cells_ary[x__aryindxs[i]].vals, nothing, "", "shapefactor",  "", 0.0, "Float64", true,  false, ""     )
                    err_flag, err_msg, ptype_reflattice,   pval_reflattice   = get_configproperty(err_flag, err_msg, x__cells_ary[x__aryindxs[i]].vals, nothing, "", "reflattice",   "", "",  "string",  false, true,  "mixed")
                    if err_flag == false 
                        err_flag, err_msg, x__cells_neighbordists[i] = get_confignumber(err_flag, err_msg, Float64, pval_neighbordist[1], "0", true, true, true, true, true) 
                        err_flag, err_msg, x__cells_areas[i]         = get_confignumber(err_flag, err_msg, Float64, pval_area[1],         "0", true, true, true, true, true) 
                        err_flag, err_msg, x__cells_counts[i]        = get_confignumber(err_flag, err_msg, Float64, pval_count[1],        "0", true, true, true, true, true) 
                        err_flag, err_msg, x__cells_shapefactors[i]  = get_confignumber(err_flag, err_msg, Float64, pval_shapefactor[1],  "0", true, true, true, true, true) 
                    end 
                    if err_flag == false 
                        x__cells_facets[i]      = string(pval_facet[1]) 
                        x__cells_reflattices[i] = string(pval_reflattice[1]) 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Attach units to cell parameters 
            if err_flag == false 
                x__cells_neighbordists_sf = ct__SFloat64Array{1}("neighbordist", x__cells_cnt, x__cells_neighbordists, conv_value(physcnsts, physconvs, x__cells_neighbordists, physunits.distance, physunits.distance_si), false, physunits.distance, physunits.distance_si, false) 
                x__cells_areas_sf         = ct__SFloat64Array{1}("cellarea",     x__cells_cnt, x__cells_areas,         conv_value(physcnsts, physconvs, x__cells_areas,         physunits.area,     physunits.area_si    ), false, physunits.area,     physunits.area_si,     false) 
                x__cells_areas_m2         = conv_value(physcnsts, physconvs, x__cells_areas_sf.value, x__cells_areas_sf.units, "m^2") 
            end 

            # Retrieve phase parameters
            if err_flag == false 
                x__phases_names = String["gas"]
                for i in axes(x__cells_names,1) 
                    push!(x__phases_names,x__cells_names[i])
                end 
                x__phases_dindxs = Dict{String,Int}()
                x__phases_types = String["gases"] 
                for i in 1:x__cells_cnt 
                    push!(x__phases_types,"surfs")
                end 
                x__indxs_gases = Array{Int,1}(undef,0)
                x__indxs_surfs = Array{Int,1}(undef,0)
                for i in axes(x__phases_names,1)
                    x__phases_dindxs[x__phases_names[i]] = i 
                    if x__phases_names[i] == "gas" 
                        push!(x__indxs_gases,i)
                    else 
                        push!(x__indxs_surfs,i)
                    end 
                end 
                x__phases_cnt = size(x__phases_names,1)                        
                x__indxs_gases_cnt = size(x__indxs_gases,1)
                x__indxs_surfs_cnt = size(x__indxs_surfs,1) 
                x__surfs_indexes = get_elemindex(x__indxs_surfs,collect(1:x__phases_cnt),0)    
                x__phases_facets = Array{String,1}(undef,0) 
                push!(x__phases_facets,"")
                for i in axes(x__cells_facets,1) 
                    push!(x__phases_facets,x__cells_facets[i])
                end 
                x__phases_reflattices = Array{String,1}(undef,0) 
                push!(x__phases_reflattices,"")
                for i in axes(x__cells_reflattices,1) 
                    push!(x__phases_reflattices,x__cells_reflattices[i])
                end 
                x__phases_cellcounts = Array{Float64,1}(undef,0) 
                push!(x__phases_cellcounts,0.0)
                for i in axes(x__cells_counts,1)
                    push!(x__phases_cellcounts,x__cells_counts[i])
                end 
                x__phases_cellshapefactors = Array{Float64,1}(undef,0) 
                push!(x__phases_cellshapefactors,0.0)
                for i in axes(x__cells_shapefactors,1)
                    push!(x__phases_cellshapefactors,x__cells_shapefactors[i])
                end 
                x__phases_neighbordists = Array{Float64,1}(undef,0) 
                push!(x__phases_neighbordists,0.0)
                for i in axes(x__cells_neighbordists_sf.value,1)
                    push!(x__phases_neighbordists,x__cells_neighbordists_sf.value[i])
                end 
                x__phases_neighbordists_sf = ct__SFloat64Array{1}("neighbordist", x__phases_cnt, x__phases_neighbordists, conv_value(physcnsts, physconvs, x__phases_neighbordists, physunits.distance, physunits.distance_si), false, physunits.distance, physunits.distance_si, false) 
                x__phases_cellareas        = vcat([0],x__cells_areas_sf.value)
                x__phases_cellareas_sf     = ct__SFloat64Array{1}("cellarea",     x__phases_cnt, x__phases_cellareas,     conv_value(physcnsts, physconvs, x__phases_cellareas,     physunits.area,     physunits.area_si    ), false, physunits.area,     physunits.area_si,     false) 
            end 

            # Retrieve site data 
            if err_flag == false 
                err_flag, err_msg, x__sites_ary = get_configrecords(err_flag, err_msg, configdata, "CELL_SITES|CELL_SITE") 
            end 
            
            # Retrieve site names
            if err_flag == false 
                x__cells_sites_names = Array{String,1}(undef,0) 
                x__aryindxs = Array{Int,1}(undef,0) 
                for i in 1:size(x__sites_ary,1)
                    if haskey(x__sites_ary[i].vals, "cell") && haskey(x__sites_ary[i].vals, "site") && haskey(x__sites_ary[i].vals, "factor") 
                        if x__sites_ary[i].vals["cell"] !== nothing && x__sites_ary[i].vals["site"] !== nothing && x__sites_ary[i].vals["factor"] !== nothing 
                            if length(x__sites_ary[i].vals["cell"]) > 0 && length(x__sites_ary[i].vals["site"]) > 0 && length(x__sites_ary[i].vals["factor"]) > 0 
                                err_flag, err_msg, vld_flag, x_factor = try_parse(err_flag, err_msg, x__sites_ary[i].vals["factor"], 0.0) 
                                if err_flag == false && vld_flag == true && x_factor > 0 
                                    push!(x__cells_sites_names,string(x__sites_ary[i].vals["site"])) 
                                    push!(x__aryindxs,i)
                                end 
                            end 
                        end 
                    end 
                end 
                x__cells_sites_dindxs = Dict{String,Int}() 
                for i in axes(x__cells_sites_names,1)
                    x__cells_sites_dindxs[x__cells_sites_names[i]] = i 
                end 
                x__cells_sites_cnt = size(x__cells_sites_names,1) 
                x__phases_sites_indxs = fill(0,x__phases_cnt * x__cells_sites_cnt) 
                x__phases_sites_indxs_surfs = fill(0,x__indxs_surfs_cnt * x__cells_sites_cnt) 
                x__phases_sites_names = fill("",x__phases_cnt * x__cells_sites_cnt) 
                x__phases_sites_names_surfs = fill("",x__indxs_surfs_cnt * x__cells_sites_cnt) 
                x__phases_sites_phases = fill("",x__phases_cnt * x__cells_sites_cnt) 
                x__phases_sites_phases_surfs = fill("",x__indxs_surfs_cnt * x__cells_sites_cnt) 
                x__phases_sites_compounds = fill("",x__phases_cnt * x__cells_sites_cnt) 
                x__phases_sites_compounds_surfs = fill("",x__indxs_surfs_cnt * x__cells_sites_cnt) 
                for i in 1:x__indxs_surfs_cnt
                    for j in axes(x__cells_sites_names,1) 
                        x__phases_sites_indxs[(x__indxs_surfs[i]-1)*x__cells_sites_cnt+j]     = j
                        x__phases_sites_indxs_surfs[(i-1)*x__cells_sites_cnt+j]               = j
                        x__phases_sites_names[(x__indxs_surfs[i]-1)*x__cells_sites_cnt+j]     = string("<",x__phases_names[x__indxs_surfs[i]],"> ",x__cells_sites_names[j]) 
                        x__phases_sites_names_surfs[(i-1)*x__cells_sites_cnt+j]               = string("<",x__phases_names[x__indxs_surfs[i]],"> ",x__cells_sites_names[j])
                        x__phases_sites_phases[(x__indxs_surfs[i]-1)*x__cells_sites_cnt+j]    = x__phases_names[x__indxs_surfs[i]]
                        x__phases_sites_phases_surfs[(i-1)*x__cells_sites_cnt+j]              = x__phases_names[x__indxs_surfs[i]]
                        x__phases_sites_compounds[(x__indxs_surfs[i]-1)*x__cells_sites_cnt+j] = x__cells_sites_names[j]
                        x__phases_sites_compounds_surfs[(i-1)*x__cells_sites_cnt+j]           = x__cells_sites_names[j]
                    end 
                end 
            end 

            # Retrieve site coefficients 
            if err_flag == false 
                x__cells_sites_coeffs = zeros((x__indxs_surfs_cnt,x__cells_sites_cnt))
                for i in 1:x__indxs_surfs_cnt 
                    for j in 1:x__cells_cnt 
                        if x__phases_names[x__indxs_surfs[i]] == x__cells_names[j] 
                            for k in 1:size(x__aryindxs,1) 
                                if x__cells_names[j] == x__sites_ary[x__aryindxs[k]].vals["cell"] 
                                    for l in 1:x__cells_sites_cnt
                                        if x__cells_sites_names[l] == x__sites_ary[x__aryindxs[k]].vals["site"] 
                                            err_flag, err_msg, vld_flag, x_factor = try_parse(err_flag, err_msg, x__sites_ary[x__aryindxs[k]].vals["factor"], 0.0) 
                                            if err_flag == false && vld_flag == true 
                                                x__cells_sites_coeffs[i,l] = x_factor 
                                            end 
                                        end 
                                        if err_flag == true 
                                            break 
                                        end 
                                    end 
                                end 
                                if err_flag == true 
                                    break 
                                end 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 
            
            # construct object
            if err_flag == false 
                rs = ct__Phases(
                        x__phases_cnt, x__phases_dindxs, x__phases_names, 
                        x__phases_types, x__phases_facets, x__phases_reflattices, x__phases_neighbordists_sf, 
                        x__phases_cellareas_sf, x__cells_areas_m2, x__phases_cellcounts, x__phases_cellshapefactors, 
                        x__cells_sites_cnt, x__cells_sites_dindxs, x__cells_sites_names, x__cells_sites_coeffs, 
                        x__indxs_gases, x__indxs_gases_cnt, x__indxs_surfs, x__indxs_surfs_cnt, x__surfs_indexes, 
                        x__phases_sites_indxs, x__phases_sites_indxs_surfs, x__phases_sites_names, x__phases_sites_names_surfs, 
                        x__phases_sites_phases, x__phases_sites_phases_surfs, x__phases_sites_compounds, x__phases_sites_compounds_surfs
                    )
            end 
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__ODESpecies(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms, molecules, phases) 
        
        # Check error state 
        rs = ct__ODESpecies() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Retrieve ODE species names 
            if err_flag == false 
                x__names     = Array{String,1}(undef,0) 
                x__compounds = Array{String,1}(undef,0) 
                for i in 1:size(molecules.indxs_gas,1)
                    push!(x__names,string("<gas> ",molecules.names[molecules.indxs_gas[i]]))
                    push!(x__compounds,string(molecules.names[molecules.indxs_gas[i]]))
                end 
                for h in 1:phases.indxs_surfs_cnt
                    for i in 1:phases.sites_cnt
                        push!(x__names,string("<",phases.phases_names[phases.indxs_surfs[h]],"> ",phases.sites_names[i]))
                        push!(x__compounds,string(phases.sites_names[i]))
                    end 
                    for i in 1:size(molecules.indxs_ads,1)
                        push!(x__names,string("<",phases.phases_names[phases.indxs_surfs[h]],"> ",molecules.names[molecules.indxs_ads[i]]))
                        push!(x__compounds,string(molecules.names[molecules.indxs_ads[i]]))
                    end 
                    for i in 1:size(molecules.indxs_coads,1)
                        push!(x__names,string("<",phases.phases_names[phases.indxs_surfs[h]],"> ",molecules.names[molecules.indxs_coads[i]]))
                        push!(x__compounds,string(molecules.names[molecules.indxs_coads[i]]))
                    end 
                end 
                x__dindxs = Dict{String,Int}()
                for i in axes(x__names,1)
                    x__dindxs[x__names[i]] = i 
                end 
                x__cnt = size(x__names,1) 
            end 

            # Retrieve ODE species types and indexes 
            if err_flag == false 
                x__types          = Array{String,1}(undef,0)
                x__phases         = Array{String,1}(undef,0)
                x__indxs_active   = Array{Int,1}(undef,0)
                x__indxs_inactive = Array{Int,1}(undef,0)
                x__indxs_gas      = Array{Int,1}(undef,0)
                x__indxs_nongas   = Array{Int,1}(undef,0)
                x__indxs_site     = Array{Int,1}(undef,0)
                x__indxs_nonsite  = Array{Int,1}(undef,0)
                x__indxs_ads      = Array{Int,1}(undef,0)
                x__indxs_coads    = Array{Int,1}(undef,0)
                for i in 1:size(molecules.indxs_gas,1)
                    push!(x__types,"gas")
                    push!(x__phases,"gas")
                    push!(x__indxs_active,size(x__types,1))
                    push!(x__indxs_gas,size(x__types,1))
                    push!(x__indxs_nonsite,size(x__types,1))
                end 
                for h in 1:phases.indxs_surfs_cnt
                    for i in 1:phases.sites_cnt
                        push!(x__types,"site")
                        push!(x__phases,phases.phases_names[phases.indxs_surfs[h]])
                        push!(x__indxs_active,size(x__types,1))
                        push!(x__indxs_nongas,size(x__types,1))
                        push!(x__indxs_site,size(x__types,1))
                    end 
                    for i in 1:size(molecules.indxs_ads,1)
                        push!(x__types,"ads")
                        push!(x__phases,phases.phases_names[phases.indxs_surfs[h]])
                        push!(x__indxs_active,size(x__types,1))
                        push!(x__indxs_nongas,size(x__types,1))
                        push!(x__indxs_nonsite,size(x__types,1))
                        push!(x__indxs_ads,size(x__types,1))
                    end 
                    for i in 1:size(molecules.indxs_coads,1)
                        push!(x__types,"coads")
                        push!(x__phases,phases.phases_names[phases.indxs_surfs[h]])
                        push!(x__indxs_inactive,size(x__types,1))
                        push!(x__indxs_nongas,size(x__types,1))
                        push!(x__indxs_nonsite,size(x__types,1))
                        push!(x__indxs_coads,size(x__types,1))
                    end 
                end 
                x__indxs_siteads      = vcat(x__indxs_site,x__indxs_ads)
                x__indxs_adsgas       = vcat(x__indxs_ads,x__indxs_gas)
                x__indxs_adscoads     = vcat(x__indxs_ads,x__indxs_coads)
                x__indxs_active_cnt   = size(x__indxs_active,1)
                x__indxs_inactive_cnt = size(x__indxs_inactive,1) 
                x__indxs_gas_cnt      = size(x__indxs_gas,1) 
                x__indxs_nongas_cnt   = size(x__indxs_nongas,1) 
                x__indxs_site_cnt     = size(x__indxs_site,1) 
                x__indxs_siteads_cnt  = size(x__indxs_siteads,1) 
                x__indxs_nonsite_cnt  = size(x__indxs_nonsite,1) 
                x__indxs_ads_cnt      = size(x__indxs_ads,1) 
                x__indxs_coads_cnt    = size(x__indxs_coads,1) 
                x__indxs_adsgas_cnt   = size(x__indxs_adsgas,1)
                x__indxs_adscoads_cnt = size(x__indxs_adscoads,1)
            end 

            # construct object
            if err_flag == false 
                rs = ct__ODESpecies(
                            x__cnt, x__names, x__compounds, x__dindxs, x__types, x__phases, 
                            x__indxs_active, x__indxs_active_cnt, x__indxs_inactive, x__indxs_inactive_cnt, 
                            x__indxs_gas, x__indxs_gas_cnt, x__indxs_nongas, x__indxs_nongas_cnt, 
                            x__indxs_site, x__indxs_site_cnt, x__indxs_siteads, x__indxs_siteads_cnt, x__indxs_nonsite, x__indxs_nonsite_cnt, 
                            x__indxs_ads, x__indxs_ads_cnt, x__indxs_coads, x__indxs_coads_cnt, x__indxs_adsgas, x__indxs_adsgas_cnt, x__indxs_adscoads, x__indxs_adscoads_cnt 
                        )
            end 
        end 

        return err_flag, err_msg, rs 
    end

    function Init__Configurations(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms, molecules, phases, odespecies) 
        
        # Check error state 
        rs = ct__Configurations() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 
            covs_detect_tol = 0.0001

            # Retrieve configuration data 
            if err_flag == false 
                err_flag, err_msg, x__configs_ary = get_configrecords(err_flag, err_msg, configdata, "CONFIGURATIONS|CONFIGURATION") 
            end 

            # Retrieve configuration names 
            if err_flag == false 
                x__configs_names = Array{String,1}(undef,0) 
                x__aryindxs = Array{Int,1}(undef,0)
                for i in axes(x__configs_ary,1) 
                    if haskey(x__configs_ary[i].vals, "name") 
                        if x__configs_ary[i].vals["name"] !== nothing 
                            x__err_flag, err_msg, ptype_enthalpy, pval_enthalpy = get_configproperty(err_flag, err_msg, x__configs_ary[i].vals, nothing, "", "enthalpy",    "", 0.0,   "Float64", true, false, "")
                            x__err_flag, err_msg, ptype_include,  pval_include  = get_configproperty(err_flag, err_msg, x__configs_ary[i].vals, nothing, "", "includeflag", "", false, "bool",    true, false, "") 
                            if x__err_flag == false 
                                x__err_flag, err_msg, x__enthalpy = get_confignumber(err_flag, err_msg, Float64, pval_enthalpy[1], "0", true, true, true, false, false) 
                                if x__err_flag == false 
                                    x__include = get_bool(pval_include[1])
                                    if x__include == true 
                                        push!(x__configs_names,x__configs_ary[i].vals["name"]) 
                                        push!(x__aryindxs,i)
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
                x__configs_dindxs = Dict{String,Int}()
                for i in axes(x__configs_names,1)
                    x__configs_dindxs[x__configs_names[i]] = i 
                end 
                x__cnt = size(x__configs_names,1) 
            end 

            # Retrieve configuration parameters 
            if err_flag == false 
                x__origins      = fill("data",(x__cnt)) 
                x__compositions = fill("",    (x__cnt)) 
                x__enthalpies   = fill(0.0,   (x__cnt)) 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_composition, pval_composition = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "composition", "", "",  "string",  false, true,  "mixed")
                    err_flag, err_msg, ptype_enthalpy,    pval_enthalpy    = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "enthalpy",    "", 0.0, "Float64", true,  false, ""     )
                    if err_flag == false 
                        err_flag, err_msg, x__enthalpies[i] = get_confignumber(err_flag, err_msg, Float64, pval_enthalpy[1], "0", true, true, true, false, false) 
                    end 
                    if err_flag == false 
                        x__compositions[i] = pval_composition[1] 
                    end 
                end 
            end 

            # Retrieve vibrational wavenumbers 
            if err_flag == false 
                x__maxcnt = 0 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_vibfreq, pval_vibfreq = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "vibfreqs", "", "", "string", false, true, "mixed")
                    if err_flag == false 
                        if pval_vibfreq[1] !== nothing && pval_vibfreq[1] != "--" 
                            x__values = conv_str2numary(pval_vibfreq[1], ",", Float64)
                            x__maxcnt = max(x__maxcnt,size(x__values,1))
                        end 
                    end
                    if err_flag == true 
                        break 
                    end 
                end 
                x__vibfreqs = fill(0.0,(x__cnt,x__maxcnt)) 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_vibfreq, pval_vibfreq = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "vibfreqs", "", "", "string", false, true, "mixed")
                    if err_flag == false 
                        if pval_vibfreq[1] !== nothing && pval_vibfreq[1] != "--" 
                            x__values = conv_str2numary(pval_vibfreq[1], ",", Float64)
                            for j in axes(x__values,1)
                                x__vibfreqs[i,j] = x__values[j]
                            end 
                        end 
                    end
                    if err_flag == true 
                        break 
                    end 
                end     
            end 

            # Retrieve rotational wavenumbers 
            if err_flag == false 
                x__maxcnt = 0 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_rotfreq, pval_rotfreq = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "rotfreqs", "", "", "string", false, true, "mixed")
                    if err_flag == false 
                        if pval_rotfreq[1] !== nothing && pval_rotfreq[1] != "--" 
                            x__values = conv_str2numary(pval_rotfreq[1], ",", Float64)
                            x__maxcnt = max(x__maxcnt,size(x__values,1))
                        end 
                    end
                    if err_flag == true 
                        break 
                    end 
                end 
                x__rotfreqs = fill(0.0,(x__cnt,x__maxcnt)) 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_rotfreq, pval_rotfreq = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "rotfreqs", "", "", "string", false, true, "mixed")
                    if err_flag == false 
                        if pval_rotfreq[1] !== nothing && pval_rotfreq[1] != "--" 
                            x__values = conv_str2numary(pval_rotfreq[1], ",", Float64)
                            for j in axes(x__values,1)
                                x__rotfreqs[i,j] = x__values[j]
                            end 
                        end 
                    end
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Retrieve translational wavenumbers 
            if err_flag == false 
                x__maxcnt = 0 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_trsfreq, pval_trsfreq = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "trsfreqs", "", "", "string", false, true, "mixed")
                    if err_flag == false 
                        if pval_trsfreq[1] !== nothing && pval_trsfreq[1] != "--" 
                            x__values = conv_str2numary(pval_trsfreq[1], ",", Float64)
                            x__maxcnt = max(x__maxcnt,size(x__values,1))
                        end 
                    end
                    if err_flag == true 
                        break 
                    end 
                end 
                x__trsfreqs = fill(0.0,(x__cnt,x__maxcnt)) 
                for i in axes(x__configs_names,1) 
                    err_flag, err_msg, ptype_trsfreq, pval_trsfreq = get_configproperty(err_flag, err_msg, x__configs_ary[x__aryindxs[i]].vals, nothing, "", "trsfreqs", "", "", "string", false, true, "mixed")
                    if err_flag == false 
                        if pval_trsfreq[1] !== nothing && pval_trsfreq[1] != "--" 
                            x__values = conv_str2numary(pval_trsfreq[1], ",", Float64)
                            for j in axes(x__values,1)
                                x__trsfreqs[i,j] = x__values[j]
                            end 
                        end 
                    end
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Attach units to configuration parameters 
            if err_flag == false 
                x__enthalpies_sf = ct__SFloat64Array{1}("enthalpy", x__cnt, x__enthalpies, conv_value(physcnsts, physconvs, x__enthalpies, physunits.energy,     physunits.energy_si    ), false, physunits.energy,     physunits.energy_si,     false) 
                x__vibfreqs_sf   = ct__SFloat64Array{2}("vibfreqs", x__cnt, x__vibfreqs,   conv_value(physcnsts, physconvs, x__vibfreqs,   physunits.wavenumber, physunits.wavenumber_si), false, physunits.wavenumber, physunits.wavenumber_si, false) 
                x__rotfreqs_sf   = ct__SFloat64Array{2}("rotfreqs", x__cnt, x__rotfreqs,   conv_value(physcnsts, physconvs, x__rotfreqs,   physunits.wavenumber, physunits.wavenumber_si), false, physunits.wavenumber, physunits.wavenumber_si, false) 
                x__trsfreqs_sf   = ct__SFloat64Array{2}("trsfreqs", x__cnt, x__trsfreqs,   conv_value(physcnsts, physconvs, x__trsfreqs,   physunits.wavenumber, physunits.wavenumber_si), false, physunits.wavenumber, physunits.wavenumber_si, false) 
            end 

            # Parse configuration components 
            if err_flag == false 
                x__coeffs_phases                 = fill(0.0,(x__cnt,phases.phases_cnt))
                x__coeffs_states                 = fill(0.0,(x__cnt,phases.phases_cnt,molecules.cnt))
                x__coeffs_sites                  = fill(0.0,(x__cnt,phases.phases_cnt,molecules.cnt,phases.sites_cnt))
                x__tst_cnt                       = 0 
                x__tst_configs                   = Dict{String,Array{Int,1}}() 
                x__tst_dindxs                    = Dict{String,Int}()
                x__tst_names                     = Array{String,1}(undef,0) 
                x__tst_phases                    = Array{String,1}(undef,0) 
                x__tst_compounds                 = Array{String,1}(undef,0) 
                x__tst_states                    = Dict{String,Array{Float64,2}}() 
                x__tst_sites                     = Dict{String,Array{Float64,4}}() 
                x__states_cnt                    = 0 
                x__states_dindxs                 = Dict{String,Int}() 
                x__states_names                  = Array{String,1}(undef,0)
                x__states_phases                 = Array{String,1}(undef,0)
                x__states_compounds              = Array{String,1}(undef,0)
                x__states_indxs_gas              = Array{Int,1}(undef,0)
                x__states_indxs_gas_cnt          = 0 
                x__states_indxs_nongas           = Array{Int,1}(undef,0)
                x__states_indxs_nongas_cnt       = 0 
                x__states_indxs_ads              = Array{Int,1}(undef,0)
                x__states_indxs_ads_cnt          = 0 
                x__states_indxs_coads            = Array{Int,1}(undef,0)
                x__states_indxs_coads_cnt        = 0 
                x__states_indxs_coadsequivs      = Array{Int,1}(undef,0)
                x__states_indxs_coadsequivs_cnt  = 0 
                x__states_indxs_noncoads         = Array{Int,1}(undef,0)
                x__states_indxs_noncoads_cnt     = 0 
                x__states_indxs_adsgas           = Array{Int,1}(undef,0)
                x__states_indxs_adsgas_cnt       = 0 
                x__states_indxs_adscoads         = Array{Int,1}(undef,0)
                x__states_indxs_adscoads_cnt     = 0 
                x__states_indxs_adststs          = Array{Int,1}(undef,0)
                x__states_indxs_adststs_cnt      = 0 
                x__states_indxs_adscoadststs     = Array{Int,1}(undef,0)
                x__states_indxs_adscoadststs_cnt = 0 
                x__states_indxs_tsts             = Array{Int,1}(undef,0)
                x__states_indxs_tsts_cnt         = 0 
                x__states_indxs_odespecies       = zeros(Int,(odespecies.cnt))
                x__states_indxs_odespecies_cnt   = 0 
                for i in 1:x__cnt 
                    err_flag, err_msg = get_configurationcomposition(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms, molecules, phases, odespecies, x__compositions[i], i, x__coeffs_phases, x__coeffs_states, x__coeffs_sites, x__tst_configs, x__tst_dindxs, x__tst_names, x__tst_phases, x__tst_compounds, x__tst_states, x__tst_sites)   
                    if err_flag == true 
                        break 
                    end 
                end 
                if err_flag == false && size(x__tst_names,1) > 0 
                    x__tst_cnt = size(x__tst_names,1) 
                    for i in axes(molecules.indxs_gas,1)
                        push!(x__states_names,string("<gas> ",molecules.names[molecules.indxs_gas[i]])) 
                        push!(x__states_phases,"gas") 
                        push!(x__states_compounds,molecules.names[molecules.indxs_gas[i]]) 
                        push!(x__states_indxs_gas,size(x__states_names,1)) 
                        push!(x__states_indxs_adsgas,size(x__states_names,1)) 
                        push!(x__states_indxs_odespecies,size(x__states_names,1)) 
                    end 
                    for i in 1:phases.indxs_surfs_cnt 
                        for j in 1:size(molecules.indxs_ads,1) 
                            push!(x__states_names,string("<",phases.phases_names[phases.indxs_surfs[i]],"> ",molecules.names[molecules.indxs_ads[j]])) 
                            push!(x__states_phases,phases.phases_names[phases.indxs_surfs[i]]) 
                            push!(x__states_compounds,molecules.names[molecules.indxs_ads[j]]) 
                            push!(x__states_indxs_nongas,size(x__states_names,1)) 
                            push!(x__states_indxs_ads,size(x__states_names,1)) 
                            push!(x__states_indxs_noncoads,size(x__states_names,1)) 
                            push!(x__states_indxs_adsgas,size(x__states_names,1)) 
                            push!(x__states_indxs_adscoads,size(x__states_names,1)) 
                            push!(x__states_indxs_adststs,size(x__states_names,1)) 
                            push!(x__states_indxs_adscoadststs,size(x__states_names,1)) 
                            push!(x__states_indxs_odespecies,size(x__states_names,1)) 
                        end 
                        for j in 1:size(molecules.indxs_coads,1) 
                            push!(x__states_names,string("<",phases.phases_names[phases.indxs_surfs[i]],"> ",molecules.names[molecules.indxs_coads[j]])) 
                            push!(x__states_phases,phases.phases_names[phases.indxs_surfs[i]]) 
                            push!(x__states_compounds,molecules.names[molecules.indxs_coads[j]]) 
                            push!(x__states_indxs_nongas,size(x__states_names,1)) 
                            push!(x__states_indxs_coads,size(x__states_names,1)) 
                            push!(x__states_indxs_coadsequivs,0) 
                            push!(x__states_indxs_adscoads,size(x__states_names,1)) 
                            push!(x__states_indxs_adscoadststs,size(x__states_names,1)) 
                            push!(x__states_indxs_odespecies,size(x__states_names,1)) 
                        end 
                    end 
                    for i in 1:x__tst_cnt 
                        push!(x__states_names,x__tst_names[i]) 
                        push!(x__states_phases,x__tst_phases[i]) 
                        push!(x__states_compounds,x__tst_compounds[i]) 
                        push!(x__states_indxs_nongas,size(x__states_names,1)) 
                        push!(x__states_indxs_noncoads,size(x__states_names,1)) 
                        push!(x__states_indxs_adststs,size(x__states_names,1)) 
                        push!(x__states_indxs_adscoadststs,size(x__states_names,1)) 
                        push!(x__states_indxs_tsts,size(x__states_names,1)) 
                    end 
                    x__states_dindxs = Dict{String,Int}() 
                    for i in axes(x__states_names,1) 
                        x__states_dindxs[x__states_names[i]] = i 
                    end 
                    x__states_cnt = size(x__states_names,1) 
                    t__coeffs_states = deepcopy(x__coeffs_states)
                    t__coeffs_sites  = deepcopy(x__coeffs_sites)
                    x__coeffs_states = fill(0.0,(x__cnt,phases.phases_cnt,x__states_cnt)) 
                    x__coeffs_sites  = fill(0.0,(x__cnt,phases.phases_cnt,x__states_cnt,phases.sites_cnt))
                    for i in 1:x__cnt 
                        for j in 1:phases.phases_cnt
                            for k in 1:molecules.cnt 
                                x__state_name = string("<",phases.phases_names[j],"> ",molecules.names[k])
                                if haskey(x__states_dindxs,x__state_name)
                                    x__state_index = x__states_dindxs[x__state_name]
                                    err_flag = true 
                                    if x__state_index > 0 
                                        err_flag = false 
                                        x__coeffs_states[i,j,x__state_index] = t__coeffs_states[i,j,k]
                                        for l in 1:phases.sites_cnt 
                                            x__coeffs_sites[i,j,x__state_index,l] = t__coeffs_sites[i,j,k,l]
                                        end 
                                    end 
                                end 
                                if err_flag == true 
                                    break 
                                end 
                            end 
                            if err_flag == true 
                                break 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                    for i in 1:x__tst_cnt
                        x__state_name = x__tst_names[i]
                        if haskey(x__states_dindxs,x__state_name) && haskey(phases.phases_dindxs,x__tst_phases[i]) && haskey(x__tst_dindxs,x__state_name)
                            err_flag = true 
                            x__phase_index = phases.phases_dindxs[x__tst_phases[i]]
                            x__state_index = x__states_dindxs[x__state_name]
                            x__tst_index   = x__tst_dindxs[x__state_name] 
                            if x__state_index > 0 && x__phase_index > 0 && x__tst_index > 0 
                                err_flag = false 
                                for j in axes(x__tst_configs[x__state_name],1) 
                                    x__cfg_index = x__tst_configs[x__state_name][j] 
                                    x__coeffs_states[x__cfg_index,x__phase_index,x__state_index] = x__tst_states[x__state_name][x__cfg_index,x__phase_index] 
                                    for k in 1:phases.sites_cnt 
                                        x__coeffs_sites[x__cfg_index,x__phase_index,x__state_index,k] = x__tst_sites[x__state_name][x__cfg_index,x__phase_index,k] 
                                    end 
                                end 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                    x__states_indxs_gas_cnt          = size(x__states_indxs_gas,1) 
                    x__states_indxs_nongas_cnt       = size(x__states_indxs_nongas,1) 
                    x__states_indxs_ads_cnt          = size(x__states_indxs_ads,1) 
                    x__states_indxs_coads_cnt        = size(x__states_indxs_coads,1) 
                    x__states_indxs_coadsequivs_cnt  = size(x__states_indxs_coadsequivs,1) 
                    x__states_indxs_noncoads_cnt     = size(x__states_indxs_noncoads,1) 
                    x__states_indxs_adsgas_cnt       = size(x__states_indxs_adsgas,1) 
                    x__states_indxs_adscoads_cnt     = size(x__states_indxs_adscoads,1) 
                    x__states_indxs_adststs_cnt      = size(x__states_indxs_adststs,1) 
                    x__states_indxs_adscoadststs_cnt = size(x__states_indxs_adscoadststs,1) 
                    x__states_indxs_tsts_cnt         = size(x__states_indxs_tsts,1) 
                    x__states_indxs_odespecies_cnt   = size(x__states_indxs_odespecies,1)
                end 
                if err_flag == false 
                    for i in 1:x__cnt 
                        err_flag, err_msg, x__composition_phrase = get_configurationcomposition_phrase(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, odespecies, phases, x__states_names, i, x__coeffs_phases, x__coeffs_states, x__coeffs_sites)
                        if err_flag == false 
                            x__compositions[i] = x__composition_phrase 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                end 
                if err_flag == false 
                    x__tst_atomcoeffs = zeros(x__tst_cnt,size(atoms.atoms_names,1)) 
                    for i in axes(x__tst_names,1) 
                        x__namesegs = str_trim(string.(split(x__tst_names[i], "--"))) 
                        for j in axes(x__namesegs,1) 
                            if length(x__namesegs[j]) > 0 
                                x__namesegs[j] = join(x__namesegs[j],"") 
                                x__atoms, x__atoms_counts, x__atoms_tot, x__atoms_all = get_atomcounts(x__namesegs[j]) 
                                for k in axes(x__atoms,1) 
                                    if haskey(atoms.atoms_dindxs,x__atoms[k]) 
                                        x__atomindx = atoms.atoms_dindxs[x__atoms[k]]
                                        if x__atomindx > 0 
                                            x__tst_atomcoeffs[i,x__atomindx] += x__atoms_counts[x__atoms[k]] 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                    x__tst_atomcoeffs = 0.5 .* x__tst_atomcoeffs
                end 
            end 

            # Retrieve coadsorbate equivalents 
            if err_flag == false 

                # Detect affected molecules 
                ceq__pairs_cnt = 0 
                if err_flag == false 
                    ceq__pairs_coads  = Array{Int,1}(undef,0) 
                    ceq__pairs_equivs = Array{Int,1}(undef,0) 
                    for i in 1:size(molecules.indxs_coads,1) 
                        if molecules.indxs_coads[i] > 0 
                            if get_elemindex(ceq__pairs_coads,molecules.indxs_coads[i],0) <= 0 && get_elemindex(ceq__pairs_equivs,molecules.dindxs[molecules.coadsequivs[molecules.indxs_coads[i]]],0) <= 0 
                                push!(ceq__pairs_coads,molecules.indxs_coads[i])
                                push!(ceq__pairs_equivs,molecules.dindxs[molecules.coadsequivs[molecules.indxs_coads[i]]])
                            end 
                        end 
                    end 
                    ceq__pairs_cnt      = size(ceq__pairs_coads,1) 
                    ceq__states_used    = Array{Int,1}(undef,0) 
                    ceq__states_notused = Array{Int,1}(undef,0) 
                    for i in 1:x__states_cnt 
                        x__flag = false 
                        for j in axes(ceq__pairs_coads,1) 
                            if x__states_compounds[i] == molecules.names[molecules.indxs_coads[j]] || x__states_compounds[i] == molecules.coadsequivs[molecules.indxs_coads[j]]
                                x__flag = true 
                                break 
                            end 
                        end 
                        if x__flag == true 
                            push!(ceq__states_used,i) 
                        else 
                            push!(ceq__states_notused,i) 
                        end 
                    end 
                    ceq__states_used_cnt = size(ceq__states_used,1)
                    ceq__states_notused_cnt = size(ceq__states_notused,1)
                end 

                # Detect affected configurations 
                ceq__pm_used_cnt = 0 
                if err_flag == false 
                    if ceq__pairs_cnt > 0 
                        ceq__cfgs_flags = fill(false,(x__cnt,phases.phases_cnt)) 
                        ceq__cfgs_used  = Array{Int,1}(undef,0) 
                        ceq__pm_tot     = 0 
                        ceq__pm_sz      = 100 
                        ceq__pm_cnts    = fill(0.0,ceq__pairs_cnt) 
                        ceq__pm_maxs    = fill(0.0,ceq__pairs_cnt) 
                        ceq__pm_dat_confgindex = fill(0,ceq__pm_sz) 
                        ceq__pm_dat_phaseindex = fill(0,ceq__pm_sz) 
                        ceq__pm_dat_cnts       = fill(0.0,(ceq__pm_sz,ceq__pairs_cnt)) 
                        ceq__pm_dat_maxs       = fill(0.0,(ceq__pm_sz,ceq__pairs_cnt)) 
                        for i in 1:x__cnt 
                            for j in 1:phases.phases_cnt 
                                if x__coeffs_phases[i,j] > 0 
                                    ceq__pm_cnts .= 0 
                                    ceq__pm_maxs .= 0 
                                    for k in 1:ceq__pairs_cnt 
                                        x__sum = 0.0 
                                        if molecules.phases[ceq__pairs_equivs[k]] == "ads" && molecules.phases[ceq__pairs_coads[k]] == "coads" 
                                            x__equiv_molecule = string("<",phases.phases_names[j],"> ",molecules.names[ceq__pairs_equivs[k]]) 
                                            x__coads_molecule = string("<",phases.phases_names[j],"> ",molecules.names[ceq__pairs_coads[k]]) 
                                            if haskey(x__states_dindxs,x__equiv_molecule) && haskey(x__states_dindxs,x__coads_molecule) 
                                                x__sum += x__coeffs_states[i,j,x__states_dindxs[x__equiv_molecule]] 
                                                x__sum += x__coeffs_states[i,j,x__states_dindxs[x__coads_molecule]] 
                                            end 
                                        end 
                                        if x__sum > 0.0 
                                            ceq__cfgs_flags[i,j] = true 
                                            push!(ceq__cfgs_used,i) 
                                            ceq__pm_maxs[k] = x__sum 
                                        end 
                                    end 
                                    if ceq__cfgs_flags[i,j] == true 
                                        x__pm_loopflag = true 
                                        while x__pm_loopflag == true 
                                            x__addflag = true 
                                            for k in 1:x__cnt 
                                                if x__coeffs_phases[k,j] > 0 
                                                    x__chkflag = true 
                                                    if ceq__states_notused_cnt > 0 
                                                        x__chkflag = (view(x__coeffs_states,i,j,ceq__states_notused) == view(x__coeffs_states,k,j,ceq__states_notused)) 
                                                    end 
                                                    if x__chkflag == true 
                                                        for l in axes(ceq__pairs_coads,1) 
                                                            x__addflag = ((ceq__pm_cnts[l] != x__coeffs_states[k,j,x__states_dindxs[string("<",phases.phases_names[j],"> ",molecules.names[ceq__pairs_coads[l]])]]) || (ceq__pm_maxs[l] - ceq__pm_cnts[l] != x__coeffs_states[k,j,x__states_dindxs[string("<",phases.phases_names[j],"> ",molecules.names[ceq__pairs_equivs[l]])]])) 
                                                            if x__addflag == true 
                                                                break 
                                                            end 
                                                        end 
                                                    end 
                                                end 
                                                if x__addflag == false 
                                                    break 
                                                end 
                                            end 
                                            if x__addflag == true 
                                                if ceq__pm_tot >= ceq__pm_sz 
                                                    t__pm_sz = ceq__pm_sz 
                                                    while ceq__pm_tot >= ceq__pm_sz
                                                        ceq__pm_sz += 100
                                                    end 
                                                    t__pm_dat_confgindex   = deepcopy(ceq__pm_dat_confgindex) 
                                                    t__pm_dat_phaseindex   = deepcopy(ceq__pm_dat_phaseindex) 
                                                    t__pm_dat_cnts         = deepcopy(ceq__pm_dat_cnts) 
                                                    t__pm_dat_maxs         = deepcopy(ceq__pm_dat_maxs) 
                                                    ceq__pm_dat_confgindex = fill(0,ceq__pm_sz) 
                                                    ceq__pm_dat_phaseindex = fill(0,ceq__pm_sz) 
                                                    ceq__pm_dat_cnts       = fill(0.0,(ceq__pm_sz,ceq__pairs_cnt)) 
                                                    ceq__pm_dat_maxs       = fill(0.0,(ceq__pm_sz,ceq__pairs_cnt)) 
                                                    ceq__pm_dat_confgindex[1:t__pm_sz] .= t__pm_dat_confgindex 
                                                    ceq__pm_dat_phaseindex[1:t__pm_sz] .= t__pm_dat_phaseindex 
                                                    ceq__pm_dat_cnts[1:t__pm_sz,:]     .= t__pm_dat_cnts 
                                                    ceq__pm_dat_maxs[1:t__pm_sz,:]     .= t__pm_dat_maxs 
                                                end 
                                                ceq__pm_tot += 1 
                                                ceq__pm_dat_confgindex[ceq__pm_tot] = i 
                                                ceq__pm_dat_phaseindex[ceq__pm_tot] = j 
                                                ceq__pm_dat_cnts[ceq__pm_tot,:]    .= ceq__pm_cnts
                                                ceq__pm_dat_maxs[ceq__pm_tot,:]    .= ceq__pm_maxs
                                            end 
                                            for k in 1:ceq__pairs_cnt 
                                                ceq__pm_cnts[ceq__pairs_cnt - k + 1] += 1 
                                                if ceq__pm_cnts[ceq__pairs_cnt - k + 1] > ceq__pm_maxs[ceq__pairs_cnt - k + 1] 
                                                    if k < ceq__pairs_cnt 
                                                        ceq__pm_cnts[ceq__pairs_cnt - k + 1] = 0 
                                                    else 
                                                        x__pm_loopflag = false 
                                                    end 
                                                else 
                                                    break
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                        ceq__cfgs_used = unique(ceq__cfgs_used) 
                        sort!(ceq__cfgs_used)
                        ceq__pm_used = Array{Int,1}(undef,0) 
                        ceq__pm_nphaseindxs = Dict{Int,Array{Int,1}}() 
                        if ceq__pm_tot > 0 
                            for i in 1:ceq__pm_tot 
                                x__uniqueflag = true 
                                if i > 1 
                                    x__phsindex = ceq__pm_dat_phaseindex[i]
                                    for j in 1:i-1
                                        if x__phsindex == ceq__pm_dat_phaseindex[j] 
                                            x__phsflag = true
                                            if phases.phases_cnt > 1 
                                                if haskey(ceq__pm_nphaseindxs,x__phsindex) == false 
                                                    ceq__pm_nphaseindxs[x__phsindex] = findall(x -> x != x__phsindex, collect(1:phases.phases_cnt)) 
                                                end 
                                                if size(ceq__pm_nphaseindxs[x__phsindex],1) > 0 
                                                    x__phsflag = (view(x__coeffs_states,ceq__pm_dat_confgindex[i],x__phsindex,ceq__pm_nphaseindxs[x__phsindex]) == view(x__coeffs_states,ceq__pm_dat_confgindex[j],x__phsindex,ceq__pm_nphaseindxs[x__phsindex]))
                                                end 
                                            end 
                                            if x__phsflag == true 
                                                x__fldsflag = true
                                                if ceq__states_notused_cnt > 0 
                                                    x__fldsflag = (view(x__coeffs_states,ceq__pm_dat_confgindex[i],x__phsindex,ceq__states_notused) == view(x__coeffs_states,ceq__pm_dat_confgindex[j],x__phsindex,ceq__states_notused))
                                                end 
                                                if x__fldsflag == true 
                                                    x__fldsflag = ((view(ceq__pm_dat_maxs,i,:) == view(ceq__pm_dat_maxs,j,:)) && (view(ceq__pm_dat_cnts,i,:) == view(ceq__pm_dat_cnts,j,:))) 
                                                end 
                                                if x__fldsflag == true 
                                                    x__uniqueflag = false 
                                                end 
                                            end 
                                        end 
                                        if x__uniqueflag == false 
                                            break
                                        end 
                                    end
                                end 
                                if x__uniqueflag == true 
                                    push!(ceq__pm_used,i)
                                end 
                            end 
                        end 
                        ceq__pm_used_cnt = size(ceq__pm_used,1)
                    end 
                end 

                # Construct combined coefficients array 
                if err_flag == false 
                    if ceq__pairs_cnt > 0 
                        if ceq__pm_used_cnt > 0 

                            # Create temporary copies of existing configurations
                            t__cnt            = x__cnt 
                            t__configs_dindxs = deepcopy(x__configs_dindxs)
                            t__configs_names  = deepcopy(x__configs_names) 
                            t__origins        = deepcopy(x__origins) 
                            t__compositions   = deepcopy(x__compositions) 
                            t__enthalpies_sf  = deepcopy(x__enthalpies_sf) 
                            t__vibfreqs_sf    = deepcopy(x__vibfreqs_sf) 
                            t__rotfreqs_sf    = deepcopy(x__rotfreqs_sf) 
                            t__trsfreqs_sf    = deepcopy(x__trsfreqs_sf) 
                            t__coeffs_phases  = deepcopy(x__coeffs_phases) 
                            t__coeffs_states  = deepcopy(x__coeffs_states) 
                            t__coeffs_sites   = deepcopy(x__coeffs_sites) 

                            # Initialize variables for updated configurations
                            x__cnt            = 0 
                            x__max            = t__cnt + ceq__pm_used_cnt
                            x__configs_names  = Array{String,1}(undef,0) 
                            x__origins        = Array{String,1}(undef,0) 
                            x__compositions   = Array{String,1}(undef,0) 
                            x__enthalpies     = fill(0.0,x__max) 
                            x__vibfreqs       = fill(0.0,(x__max,size(t__vibfreqs_sf.value,2))) 
                            x__rotfreqs       = fill(0.0,(x__max,size(t__rotfreqs_sf.value,2))) 
                            x__trsfreqs       = fill(0.0,(x__max,size(t__trsfreqs_sf.value,2))) 
                            x__coeffs_phases  = fill(0.0,(x__max,phases.phases_cnt)) 
                            x__coeffs_states  = fill(0.0,(x__max,phases.phases_cnt,x__states_cnt)) 
                            x__coeffs_sites   = fill(0.0,(x__max,phases.phases_cnt,x__states_cnt,phases.sites_cnt)) 
                            
                            # Fill in updated configurations
                            for i in 1:t__cnt 

                                # Insert unaltered version of this configuration
                                x__cnt += 1 
                                push!(x__configs_names,t__configs_names[i]) 
                                push!(x__origins,t__origins[i]) 
                                push!(x__compositions,t__compositions[i])
                                x__enthalpies[x__cnt]  = t__enthalpies_sf.value[i] 
                                x__vibfreqs[x__cnt,:] .= view(t__vibfreqs_sf.value,i,:) 
                                x__rotfreqs[x__cnt,:] .= view(t__rotfreqs_sf.value,i,:) 
                                x__trsfreqs[x__cnt,:] .= view(t__trsfreqs_sf.value,i,:) 
                                x__coeffs_phases[x__cnt,:]    .= view(t__coeffs_phases,i,:) 
                                x__coeffs_states[x__cnt,:,:]  .= view(t__coeffs_states,i,:,:) 
                                x__coeffs_sites[x__cnt,:,:,:] .= view(t__coeffs_sites,i,:,:,:) 

                                # Insert permuted versions of this configuration
                                x__pcnt = 0 
                                for j in 1:phases.phases_cnt 
                                    for k in 1:ceq__pm_used_cnt 
                                        x__confgindex = ceq__pm_dat_confgindex[ceq__pm_used[k]] 
                                        x__phaseindex = ceq__pm_dat_phaseindex[ceq__pm_used[k]] 
                                        if x__confgindex == i && x__phaseindex == j 
                                            x__pcnt += 1
                                            x__cnt += 1 
                                            x__name = string(t__configs_names[i]," - coads(",x__pcnt,")")
                                            push!(x__configs_names,x__name) 
                                            push!(x__origins,"coadsequiv") 
                                            x__enthalpies[x__cnt]  = t__enthalpies_sf.value[i] 
                                            x__vibfreqs[x__cnt,:] .= view(t__vibfreqs_sf.value,i,:) 
                                            x__rotfreqs[x__cnt,:] .= view(t__rotfreqs_sf.value,i,:) 
                                            x__trsfreqs[x__cnt,:] .= view(t__trsfreqs_sf.value,i,:) 
                                            x__coeffs_phases[x__cnt,j]     = t__coeffs_phases[i,j] 
                                            x__coeffs_states[x__cnt,j,:]  .= view(t__coeffs_states,i,j,:) 
                                            x__coeffs_sites[x__cnt,j,:,:] .= view(t__coeffs_sites,i,j,:,:) 
                                            for l in 1:ceq__pairs_cnt
                                                x__ecnt = 0 
                                                x__emax = ceq__pm_dat_maxs[ceq__pm_used[k],l] - ceq__pm_dat_cnts[ceq__pm_used[k],l] 
                                                x__ccnt = 0 
                                                x__cmax = ceq__pm_dat_cnts[ceq__pm_used[k],l] 
                                                x__coads_state_index = x__states_dindxs[string("<",phases.phases_names[j],"> ",molecules.names[ceq__pairs_coads[l]])]
                                                x__equiv_state_index = x__states_dindxs[string("<",phases.phases_names[j],"> ",molecules.names[ceq__pairs_equivs[l]])]
                                                if x__coads_state_index > 0 && x__equiv_state_index > 0 
                                                    x__sindex = get_elemindex(x__states_indxs_coads,x__coads_state_index,0) 
                                                    if x__sindex > 0 
                                                        if x__states_indxs_coadsequivs[x__sindex] > 0 
                                                            if x__states_indxs_coadsequivs[x__sindex] != x__equiv_state_index
                                                                err_flag = true 
                                                                break 
                                                            end 
                                                        else
                                                            x__states_indxs_coadsequivs[x__sindex] = x__equiv_state_index
                                                        end
                                                    end 
                                                end 
                                                if x__coeffs_states[x__cnt,j,x__equiv_state_index] > 0 && (x__ecnt < x__emax || x__ccnt < x__cmax)  
                                                    x__scnt = get_trunc(x__coeffs_states[x__cnt,j,x__equiv_state_index])
                                                    for n in 1:x__scnt 
                                                        if x__ecnt < x__emax 
                                                            x__ecnt += 1 
                                                        elseif x__ccnt < x__cmax 
                                                            x__ccnt += 1 
                                                            if x__coeffs_phases[x__cnt,j] <= 0 
                                                                x__coeffs_phases[x__cnt,j] = 1 
                                                                x__coeffs_states[x__cnt,j,x__coads_state_index] = 0
                                                            end 
                                                            x__coeffs_states[x__cnt,j,x__coads_state_index] += 1 
                                                            x__coeffs_states[x__cnt,j,x__equiv_state_index] -= 1 
                                                            if sum(x__coeffs_states[x__cnt,j,:]) <= 0 
                                                                x__coeffs_phases[x__cnt,j] = 0 
                                                                x__coeffs_states[x__cnt,j,:] .= 0 
                                                                x__coeffs_sites[x__cnt,j,:,:] .= 0 
                                                            end 
                                                            x__coeffs_sites[x__cnt,j,x__equiv_state_index,:] .= view(x__coeffs_sites,x__cnt,j,x__equiv_state_index,:) .- view(t__coeffs_sites,i,j,x__equiv_state_index,:) ./ t__coeffs_states[i,j,x__equiv_state_index] 
                                                            x__coeffs_sites[x__cnt,j,x__coads_state_index,:] .= view(x__coeffs_sites,x__cnt,j,x__coads_state_index,:) .+ view(t__coeffs_sites,i,j,x__equiv_state_index,:) ./ t__coeffs_states[i,j,x__equiv_state_index] 
                                                        end 
                                                        if x__ecnt >= x__emax && x__ccnt >= x__cmax 
                                                            break 
                                                        end 
                                                        if err_flag == true 
                                                            break 
                                                        end 
                                                    end 
                                                end 
                                                if x__coeffs_states[x__cnt,j,x__coads_state_index] > 0 && (x__ecnt < x__emax || x__ccnt < x__cmax)  
                                                    x__scnt = get_trunc(x__coeffs_states[x__cnt,j,x__coads_state_index])
                                                    for n in 1:x__scnt 
                                                        if x__ecnt < x__emax 
                                                            x__ecnt += 1 
                                                            if x__coeffs_phases[x__cnt,j] <= 0 
                                                                x__coeffs_phases[x__cnt,j] = 1 
                                                                x__coeffs_states[x__cnt,j,x__equiv_state_index] = 0
                                                            end 
                                                            x__coeffs_states[x__cnt,j,x__equiv_state_index] += 1 
                                                            x__coeffs_states[x__cnt,j,x__coads_state_index] -= 1 
                                                            if sum(x__coeffs_states[x__cnt,j,:]) <= 0 
                                                                x__coeffs_phases[x__cnt,j] = 0 
                                                                x__coeffs_states[x__cnt,j,:] .= 0 
                                                                x__coeffs_sites[x__cnt,j,:,:] .= 0 
                                                            end 
                                                            x__coeffs_sites[x__cnt,j,x__coads_state_index,:] .= view(x__coeffs_sites,x__cnt,j,x__coads_state_index,:) .- view(t__coeffs_sites,i,j,x__coads_state_index,:) ./ t__coeffs_states[i,j,x__coads_state_index]
                                                            x__coeffs_sites[x__cnt,j,x__equiv_state_index,:] .= view(x__coeffs_sites,x__cnt,j,x__equiv_state_index,:) .+ view(t__coeffs_sites,i,j,x__coads_state_index,:) ./ t__coeffs_states[i,j,x__coads_state_index] 
                                                        elseif x__ccnt < x__cmax 
                                                            x__ccnt += 1 
                                                        end 
                                                        if x__ecnt >= x__emax && x__ccnt >= x__cmax 
                                                            break 
                                                        end 
                                                        if err_flag == true 
                                                            break 
                                                        end 
                                                    end 
                                                end 
                                                if x__ecnt >= x__emax && x__ccnt >= x__cmax 
                                                    break 
                                                end 
                                                if err_flag == true 
                                                    break 
                                                end 
                                            end 
                                            if err_flag == false 
                                                err_flag, err_msg, x__composition_phrase = get_configurationcomposition_phrase(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, odespecies, phases, x__states_names, x__cnt, x__coeffs_phases, x__coeffs_states, x__coeffs_sites)
                                            end 
                                            if err_flag == false 
                                                push!(x__compositions,x__composition_phrase)
                                            end 
                                        end 
                                        if err_flag == true 
                                            break 
                                        end 
                                    end 
                                end 
                                if err_flag == true 
                                    break 
                                end 
                            end 
                            x__configs_dindxs = Dict{String,Int}() 
                            for i in axes(x__configs_names,1) 
                                x__configs_dindxs[x__configs_names[i]] = i 
                            end 
                            x__tst_cnt = size(x__tst_names,1) 

                            # Attach units to arrays
                            x__enthalpies_sf = ct__SFloat64Array{1}("enthalpy", x__cnt, x__enthalpies, conv_value(physcnsts, physconvs, x__enthalpies, t__enthalpies_sf.units, t__enthalpies_sf.units_si), false, t__enthalpies_sf.units, t__enthalpies_sf.units_si, false) 
                            x__vibfreqs_sf   = ct__SFloat64Array{2}("vibfreqs", x__cnt, x__vibfreqs,   conv_value(physcnsts, physconvs, x__vibfreqs,   t__vibfreqs_sf.units,   t__vibfreqs_sf.units_si  ), false, t__vibfreqs_sf.units,   t__vibfreqs_sf.units_si,   false) 
                            x__rotfreqs_sf   = ct__SFloat64Array{2}("rotfreqs", x__cnt, x__rotfreqs,   conv_value(physcnsts, physconvs, x__rotfreqs,   t__rotfreqs_sf.units,   t__rotfreqs_sf.units_si  ), false, t__rotfreqs_sf.units,   t__rotfreqs_sf.units_si,   false) 
                            x__trsfreqs_sf   = ct__SFloat64Array{2}("trsfreqs", x__cnt, x__trsfreqs,   conv_value(physcnsts, physconvs, x__trsfreqs,   t__trsfreqs_sf.units,   t__trsfreqs_sf.units_si  ), false, t__trsfreqs_sf.units,   t__trsfreqs_sf.units_si,   false) 
                            
                            # Check error state 
                            err_flag = (x__cnt != t__cnt + ceq__pm_used_cnt) 
                        end 
                    end 
                end 
            end 

            # Categorize configurations 
            if err_flag == false 
                x__indxs_gas = Array{Int,1}(undef,0) 
                x__indxs_ref = Array{Int,1}(undef,0) 
                x__indxs_ads = Array{Int,1}(undef,0) 
                x__indxs_tst = Array{Int,1}(undef,0) 
                for i in 1:x__cnt 
                    if get_elemindex(phases.reflattices,x__configs_names[i],0) > 0 
                        push!(x__indxs_ref,i)
                    else 
                        for j in 1:phases.phases_cnt 
                            if sum(view(x__coeffs_states,i,j,x__states_indxs_gas)) > 0 
                                push!(x__indxs_gas,i)
                                break 
                            elseif sum(view(x__coeffs_states,i,j,x__states_indxs_tsts)) > 0 
                                push!(x__indxs_tst,i) 
                                break 
                            else 
                                if j == phases.phases_cnt 
                                    push!(x__indxs_ads,i)
                                end 
                            end 
                        end 
                    end 
                end 
                x__indxs_adsref = vcat(x__indxs_ref,x__indxs_ads)
                x__indxs_adstst = vcat(x__indxs_ads,x__indxs_tst)
                x__indxs_gas_cnt = size(x__indxs_gas,1) 
                x__indxs_ref_cnt = size(x__indxs_ref,1) 
                x__indxs_ads_cnt = size(x__indxs_ads,1) 
                x__indxs_tst_cnt = size(x__indxs_tst,1) 
                x__indxs_adsref_cnt = size(x__indxs_adsref,1)
                x__indxs_adstst_cnt = size(x__indxs_adstst,1) 
            end 

            # Initialize surface coverages 
            if err_flag == false 
                x__refstatescovs_unscaled = zeros((x__cnt,x__states_cnt)) 
                x__refstatescovs_scaled   = zeros((x__cnt,x__states_cnt)) 
                x__refsitescovs_unscaled  = zeros((x__cnt,phases.sites_cnt)) 
                x__refsitescovs_scaled    = zeros((x__cnt,phases.sites_cnt)) 
                x__csitescnts             = zeros(x__cnt,phases.sites_cnt)
                x__asitescnts             = zeros(x__cnt,phases.sites_cnt)
                x__tsitescnts             = zeros(x__cnt,phases.sites_cnt)
                x__sites_all              = zeros(x__cnt,phases.indxs_surfs_cnt,phases.sites_cnt) 
                x__sites_active_all       = zeros(x__cnt,phases.indxs_surfs_cnt,phases.sites_cnt) 
                x__sites_active_unbound   = zeros(x__cnt,phases.indxs_surfs_cnt,phases.sites_cnt) 
                x__states_maxcounts       = zeros(x__cnt,phases.indxs_surfs_cnt,x__states_cnt) 
                x__dentates               = zeros(x__cnt,phases.indxs_surfs_cnt,x__states_cnt)
                for k in 1:phases.indxs_surfs_cnt 
                    x__phase_index = phases.indxs_surfs[k]

                    # calculate coverages for coadsorbates 
                    x__csitescnts .= 0.0 
                    for l in axes(odespecies.indxs_coads,1)
                        if odespecies.indxs_coads[l] > 0 
                            x__state_name = string("<",phases.phases_names[phases.indxs_surfs[k]],"> ",odespecies.compounds[odespecies.indxs_coads[l]])
                            if haskey(odespecies.dindxs,x__state_name) && haskey(x__states_dindxs,x__state_name)
                                x__state_index = x__states_dindxs[x__state_name]
                                for m in 1:x__cnt 
                                    if x__coeffs_states[m,x__phase_index,x__state_index] > 0 
                                        x__covmax = 0.0 
                                        for n in 1:phases.sites_cnt
                                            x__csitescnts[m,n] += x__coeffs_sites[m,x__phase_index,x__state_index,n]
                                            x__covmax = max(x__covmax, (x__coeffs_sites[m,x__phase_index,x__state_index,n] / (phases.cellcounts[x__phase_index] * phases.sites_coeffs[k,n]))) 
                                        end 
                                        x__refstatescovs_unscaled[m,x__state_index] = max(x__covmax,0.0) 
                                        x__refstatescovs_scaled[m,x__state_index] = max(x__covmax,0.0) 
                                    end 
                                end 
                            end 
                        end 
                    end 

                    # calculate active sites 
                    x__sites_all[:,k,:]        .= 0.0 
                    x__sites_active_all[:,k,:] .= 0.0 
                    for m in 1:x__cnt 
                        for n in 1:phases.sites_cnt
                            x__sites_all[m,k,n]        = phases.cellcounts[x__phase_index] * phases.sites_coeffs[k,n] 
                            x__sites_active_all[m,k,n] = phases.cellcounts[x__phase_index] * phases.sites_coeffs[k,n] - x__csitescnts[m,n]
                        end 
                    end 

                    # calculate coverages for adsorbates 
                    x__asitescnts .= 0.0 
                    for l in axes(odespecies.indxs_ads,1) 
                        if odespecies.indxs_ads[l] > 0 
                            x__state_name = string("<",phases.phases_names[phases.indxs_surfs[k]],"> ",odespecies.compounds[odespecies.indxs_ads[l]])
                            if haskey(odespecies.dindxs,x__state_name) && haskey(x__states_dindxs,x__state_name)
                                x__state_index = x__states_dindxs[x__state_name]
                                if x__state_index > 0 
                                    for m in 1:x__cnt 
                                        if x__coeffs_states[m,x__phase_index,x__state_index] > 0 
                                            x__covmax_scaled = 0.0 
                                            x__covmax_unscaled = 0.0 
                                            for n in 1:phases.sites_cnt 
                                                x__asitescnts[m,n] += x__coeffs_sites[m,x__phase_index,x__state_index,n] 
                                                x__covmax_scaled = max(x__covmax_scaled, (x__coeffs_sites[m,x__phase_index,x__state_index,n] / x__sites_active_all[m,k,n])) 
                                                x__covmax_unscaled = max(x__covmax_unscaled, (x__coeffs_sites[m,x__phase_index,x__state_index,n] / x__sites_all[m,k,n])) 
                                            end 
                                            x__refstatescovs_scaled[m,x__state_index] = max(x__covmax_scaled,0.0) 
                                            x__refstatescovs_unscaled[m,x__state_index] = max(x__covmax_unscaled,0.0) 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 

                    # calculate coverages for surface transition states 
                    x__tsitescnts .= 0.0 
                    for l in axes(x__tst_names,1)
                        x__state_name = x__tst_names[l]
                        if haskey(x__states_dindxs,x__state_name)
                            x__state_index = x__states_dindxs[x__state_name]
                            if x__state_index > 0 
                                for m in 1:x__cnt 
                                    if x__coeffs_states[m,x__phase_index,x__state_index] > 0 
                                        x__covmax_scaled = 0.0 
                                        x__covmax_unscaled = 0.0 
                                        for n in 1:phases.sites_cnt 
                                            x__tsitescnts[m,n] += x__coeffs_sites[m,x__phase_index,x__state_index,n] 
                                            x__covmax_scaled = max(x__covmax_scaled, (x__coeffs_sites[m,x__phase_index,x__state_index,n] / x__sites_active_all[m,k,n])) 
                                            x__covmax_unscaled = max(x__covmax_unscaled, (x__coeffs_sites[m,x__phase_index,x__state_index,n] / x__sites_all[m,k,n])) 
                                        end 
                                        x__refstatescovs_scaled[m,x__state_index] = max(x__covmax_scaled,0.0) 
                                        x__refstatescovs_unscaled[m,x__state_index] = max(x__covmax_unscaled,0.0) 
                                    end 
                                end 
                            end 
                        end 
                    end 

                    # calculate coverages for sites 
                    x__sites_active_unbound[:,k,:] .= 0.0 
                    for m in 1:x__cnt 
                        for n in 1:phases.sites_cnt
                            x__sites_active_unbound[m,k,n]  = max(x__sites_active_all[m,k,n] - x__asitescnts[m,n] - x__tsitescnts[m,n], 0.0)
                            x__refsitescovs_unscaled[m,k,n] = max((x__sites_all[m,k,n] - x__asitescnts[m,n] - x__tsitescnts[m,n]) / x__sites_all[m,k,n], 0.0)
                            x__refsitescovs_scaled[m,k,n]   = max(x__sites_active_unbound[m,k,n] / x__sites_active_all[m,k,n], 0.0)
                        end 
                    end 

                    # calculate states max counts 
                    for m in 1:x__cnt 
                        for n in 1:x__states_cnt 
                            if x__coeffs_states[m,x__phase_index,n] > 0 
                                x__minfactor = 0.0 
                                x__flag = false 
                                for o in 1:phases.sites_cnt 
                                    x__factor = 0.0
                                    if x__coeffs_sites[m,x__phase_index,n,o] > 0 
                                        x__factor = (x__coeffs_sites[m,x__phase_index,n,o] + x__sites_active_unbound[m,k,o]) / x__coeffs_sites[m,x__phase_index,n,o]
                                    end 
                                    if x__flag == true 
                                        x__minfactor = min(x__minfactor,x__factor) 
                                    else 
                                        x__minfactor = x__factor 
                                    end 
                                end 
                                x__states_maxcounts[m,k,n] = x__coeffs_states[m,x__phase_index,n] * max(x__minfactor,1.0)
                            end 
                        end 
                    end 

                    # calculate dentate factors 
                    if err_flag == false 
                        for i in 1:x__cnt 
                            for j in 1:phases.indxs_surfs_cnt 
                                for k in 1:x__states_cnt 
                                    x__dentate = 0.0 
                                    for l in 1:phases.sites_cnt 
                                        x__dentate = max(x__dentate, x__coeffs_sites[i,phases.indxs_surfs[j],k,l] / phases.sites_coeffs[j,l])
                                    end 
                                    x__dentates[i,j,k] = x__dentate
                                end 
                            end 
                        end 
                    end 
                end 
            end 

            # Retrieve surface coverages unique combinations 
            if err_flag == false 
                x__uniquecovs_indxs                     = Array{Int,1}(undef,0) 
                x__uniquecovs_indxs_adscoads            = Array{Int,1}(undef,0) 
                x__uniquecovs_indxs_adscoadststs        = Array{Int,1}(undef,0) 
                x__uniquecovs_indxs_tsts                = Array{Int,1}(undef,0) 
                x__uniquecovs_indxs_tsts_byadscoadststs = Array{Int,1}(undef,0) 
                x__idcombos                             = Dict{Int,Array{Float64,1}}() 
                x__idcombos_adscoads                    = Dict{Int,Array{Float64,1}}() 
                x__idcombos_adscoadststs                = Dict{Int,Array{Float64,1}}() 
                x__idcombos_tsts                        = Dict{Int,Array{Float64,1}}() 
                x__idcombos_tsts_byadscoadststs         = Dict{Int,Array{Float64,1}}() 
                for i in 1:x__cnt 
                    x__uniqueflag = true 
                    if x__uniqueflag == true 
                        if get_elemindex(phases.reflattices,x__configs_names[i],0) > 0 
                            if haskey(x__idcombos,i) == false 
                                x__idcombos[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                            end 
                        else 
                            if haskey(x__idcombos,i) == false 
                                x__idcombos[i] = zeros(x__states_cnt) 
                                for j in 1:x__states_cnt
                                    x__idcombos[i][j] = x__refstatescovs_scaled[i,j]
                                end 
                            end 
                            if i > 1 
                                for j in 1:i-1 
                                    if haskey(x__idcombos,j) == false 
                                        x__idcombos[j] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                        for k in 1:x__states_cnt
                                            x__idcombos[j][k] = x__refstatescovs_scaled[j,k]
                                        end 
                                    end 
                                    if maximum(abs.(x__idcombos[i] .- x__idcombos[j])) <= covs_detect_tol
                                        x__uniqueflag = false 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                        if x__uniqueflag == true 
                            push!(x__uniquecovs_indxs,i)
                        end 
                    end 
                    x__uniqueflag_adscoads = (get_elemindex(x__indxs_ref,i,0) > 0 || get_elemindex(x__indxs_ads,i,0) > 0)
                    if x__uniqueflag_adscoads == true 
                        if get_elemindex(phases.reflattices,x__configs_names[i],0) > 0 
                            if haskey(x__idcombos_adscoads,i) == false 
                                x__idcombos_adscoads[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                            end 
                        else 
                            if haskey(x__idcombos_adscoads,i) == false 
                                x__idcombos_adscoads[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                for j in axes(x__states_indxs_adscoads,1)
                                    x__idcombos_adscoads[i][x__states_indxs_adscoads[j]] = x__refstatescovs_scaled[i,x__states_indxs_adscoads[j]]
                                end 
                            end 
                            if i > 1 
                                for j in 1:i-1 
                                    if haskey(x__idcombos_adscoads,j) == false 
                                        x__idcombos_adscoads[j] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                        for k in axes(x__states_indxs_adscoads,1)
                                            x__idcombos_adscoads[j][x__states_indxs_adscoads[k]] = x__refstatescovs_scaled[j,x__states_indxs_adscoads[k]]
                                        end 
                                    end 
                                    if maximum(abs.(x__idcombos_adscoads[i] .- x__idcombos_adscoads[j])) <= covs_detect_tol
                                        x__uniqueflag_adscoads = false 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                        if x__uniqueflag_adscoads == true 
                            push!(x__uniquecovs_indxs_adscoads,i)
                        end 
                    end 
                    x__uniqueflag_adscoadststs = (get_elemindex(x__indxs_ref,i,0) > 0 || get_elemindex(x__indxs_ads,i,0) > 0 || get_elemindex(x__indxs_tst,i,0) > 0)
                    if x__uniqueflag_adscoadststs == true 
                        if get_elemindex(phases.reflattices,x__configs_names[i],0) > 0 
                            if haskey(x__idcombos_adscoadststs,i) == false 
                                x__idcombos_adscoadststs[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                            end 
                        else 
                            if haskey(x__idcombos_adscoadststs,i) == false 
                                x__idcombos_adscoadststs[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                for j in axes(x__states_indxs_adscoadststs,1)
                                    x__idcombos_adscoadststs[i][x__states_indxs_adscoadststs[j]] = x__refstatescovs_scaled[i,x__states_indxs_adscoadststs[j]]
                                end 
                            end 
                            if i > 1 
                                for j in 1:i-1 
                                    if haskey(x__idcombos_adscoadststs,j) == false 
                                        x__idcombos_adscoadststs[j] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                        for k in axes(x__states_indxs_adscoadststs,1)
                                            x__idcombos_adscoadststs[j][x__states_indxs_adscoadststs[k]] = x__refstatescovs_scaled[j,x__states_indxs_adscoadststs[k]]
                                        end 
                                    end 
                                    if maximum(abs.(x__idcombos_adscoadststs[i] .- x__idcombos_adscoadststs[j])) <= covs_detect_tol
                                        x__uniqueflag_adscoadststs = false 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                        if x__uniqueflag_adscoadststs == true 
                            push!(x__uniquecovs_indxs_adscoadststs,i)
                        end 
                    end 
                    x__uniqueflag_tsts = (get_elemindex(x__indxs_ref,i,0) > 0 || get_elemindex(x__indxs_tst,i,0) > 0)
                    if x__uniqueflag_tsts == true 
                        if get_elemindex(phases.reflattices,x__configs_names[i],0) > 0 
                            if haskey(x__idcombos_tsts,i) == false 
                                x__idcombos_tsts[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                            end 
                        else 
                            if haskey(x__idcombos_tsts,i) == false 
                                x__idcombos_tsts[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                for j in axes(x__states_indxs_tsts,1)
                                    x__idcombos_tsts[i][x__states_indxs_tsts[j]] = x__refstatescovs_scaled[i,x__states_indxs_tsts[j]]
                                end 
                            end 
                            if i > 1 
                                for j in 1:i-1 
                                    if haskey(x__idcombos_tsts,j) == false 
                                        x__idcombos_tsts[j] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                        for k in axes(x__states_indxs_tsts,1)
                                            x__idcombos_tsts[j][x__states_indxs_tsts[k]] = x__refstatescovs_scaled[j,x__states_indxs_tsts[k]] 
                                        end 
                                    end 
                                    if maximum(abs.(x__idcombos_tsts[i] .- x__idcombos_tsts[j])) <= covs_detect_tol
                                        x__uniqueflag_tsts = false 
                                    end 
                                    if x__uniqueflag_tsts == false 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                        if x__uniqueflag_tsts == true 
                            push!(x__uniquecovs_indxs_tsts,i)
                        end 
                    end 
                    if get_elemindex(x__indxs_tst,i,0) > 0 
                        x__uniqueflag_tsts_byadscoadststs = true 
                        if get_elemindex(phases.reflattices,x__configs_names[i],0) > 0 
                            if haskey(x__idcombos_tsts_byadscoadststs,i) == false 
                                x__idcombos_tsts_byadscoadststs[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                            end 
                        else 
                            if haskey(x__idcombos_tsts_byadscoadststs,i) == false 
                                x__idcombos_tsts_byadscoadststs[i] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                for j in axes(x__states_indxs_adscoadststs,1)
                                    x__idcombos_tsts_byadscoadststs[i][x__states_indxs_adscoadststs[j]] = x__refstatescovs_scaled[i,x__states_indxs_adscoadststs[j]]
                                end 
                            end 
                            if i > 1 
                                for j in 1:i-1 
                                    if haskey(x__idcombos_tsts_byadscoadststs,j) == false 
                                        x__idcombos_tsts_byadscoadststs[j] = zeros(phases.indxs_surfs_cnt * x__states_cnt) 
                                        for k in axes(x__states_indxs_adscoadststs,1)
                                            x__idcombos_tsts_byadscoadststs[j][x__states_indxs_adscoadststs[k]] = x__refstatescovs_scaled[j,x__states_indxs_adscoadststs[k]]
                                        end 
                                    end 
                                    if maximum(abs.(x__idcombos_tsts_byadscoadststs[i] .- x__idcombos_tsts_byadscoadststs[j])) <= covs_detect_tol
                                        x__uniqueflag_tsts_byadscoadststs = false 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                        if x__uniqueflag_tsts_byadscoadststs == true 
                            push!(x__uniquecovs_indxs_tsts_byadscoadststs,i)
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
                x__uniquecovs_combocovs = zeros(size(x__uniquecovs_indxs,1),phases.indxs_surfs_cnt * x__states_cnt) 
                for i in axes(x__uniquecovs_indxs,1)
                    x__uniquecovs_combocovs[i,:] .= x__idcombos[x__uniquecovs_indxs[i]] 
                end 
            end 

            # Retrieve atomic reference coefficients 
            if err_flag == false 
                x__atomcoeffs        = zeros(x__cnt,phases.phases_cnt,size(atoms.atoms_names,1)) 
                x__atomrefcoeffs     = zeros(x__cnt,phases.phases_cnt,size(atoms.refatoms_names,1),size(atoms.refcmpds_names,1)) 
                x__atomrefcmpdtotals = zeros(x__cnt,phases.phases_cnt,size(atoms.refcmpds_names,1)) 
                for i in 1:x__cnt 
                    for j in 1:phases.phases_cnt 
                        if x__coeffs_phases[i,j] > 0 
                            for k in 1:x__states_cnt 
                                if x__coeffs_states[i,j,k] > 0 
                                    x__tstindx = 0 
                                    if haskey(x__tst_dindxs,x__states_names[k]) 
                                        x__tstindx = x__tst_dindxs[x__states_names[k]]
                                        err_flag = (x__tstindx <= 0) 
                                    end 
                                    if err_flag == false 
                                        if x__tstindx > 0 
                                            for l in axes(atoms.atoms_names,1) 
                                                x__atomcoeffs[i,j,l] += x__tst_atomcoeffs[x__tstindx,l] 
                                            end 
                                        else 
                                            if haskey(molecules.dindxs,x__states_compounds[k])
                                                x__molindx = molecules.dindxs[x__states_compounds[k]]
                                                if x__molindx > 0 
                                                    for l in axes(atoms.atoms_names,1)
                                                        if molecules.atomcoeffs[x__molindx,l] > 0 
                                                            x__atomcoeffs[i,j,l] += x__coeffs_states[i,j,k] * molecules.atomcoeffs[x__molindx,l]
                                                        end 
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                                if err_flag == true 
                                    break 
                                end 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                    for j in 1:phases.phases_cnt
                        for k in axes(atoms.atoms_names,1)
                            if x__atomcoeffs[i,j,k] > 0 
                                if haskey(atoms.refatoms_dindxs,atoms.atoms_names[k])
                                    x__atomrefindx = atoms.refatoms_dindxs[atoms.atoms_names[k]]
                                    if x__atomrefindx > 0 
                                        for l in axes(atoms.refcmpds_names,1)
                                            x__atomrefcoeffs[i,j,x__atomrefindx,l] += x__atomcoeffs[i,j,k] * atoms.refcoeffs[x__atomrefindx,l] 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                    for j in 1:phases.phases_cnt
                        for k in axes(atoms.refatoms_names,1)
                            for l in axes(atoms.refcmpds_names,1) 
                                x__atomrefcmpdtotals[i,j,l] += x__atomrefcoeffs[i,j,k,l] 
                            end 
                        end 
                    end 
                end 
            end 

            # Retrieve reference lattice coefficients 
            if err_flag == false 
                x__reflatticesnames     = Array{String,1}(undef,0) 
                x__reflatticesphases    = Array{String,1}(undef,0) 
                x__reflatticescompounds = Array{String,1}(undef,0) 
                x__reflatticesindxs     = Array{Int,1}(undef,0) 
                for i in 1:phases.phases_cnt 
                    if length(phases.reflattices[i]) > 0 
                        push!(x__reflatticesnames,string("<",phases.phases_names[i],"> ",phases.reflattices[i])) 
                        push!(x__reflatticesphases,phases.phases_names[i]) 
                        push!(x__reflatticescompounds,phases.reflattices[i]) 
                        push!(x__reflatticesindxs,i) 
                    end 
                end 
                x__reflatticescnt       = size(x__reflatticesnames,1) 
                x__reflatticescoeffs    = zeros(x__cnt,phases.phases_cnt,x__reflatticescnt) 
                for i in 1:x__cnt 
                    for j in 1:x__reflatticescnt 
                        for k in 1:phases.phases_cnt 
                            if x__reflatticesphases[j] == phases.phases_names[k]  
                                x__reflatticescoeffs[i,k,j] = x__coeffs_phases[i,x__reflatticesindxs[j]] 
                                break 
                            end 
                        end 
                    end 
                end 
            end 

            # Retrieve combined reference coefficients 
            if err_flag == false 
                x__refcfgindxs = fill(0,x__cnt) 
                x__refcfgindxs_unique = Array{Int,1}(undef,0)
                for i in 1:x__cnt 
                    x__surf_flag = false 
                    for j in 1:phases.indxs_surfs_cnt 
                        if x__coeffs_phases[i,phases.indxs_surfs[j]] > 0 
                            x__surf_flag = true 
                            break 
                        end 
                    end 
                    if x__surf_flag == true 
                        for j in 1:x__cnt 
                            x__flag = true 
                            for k in 1:phases.phases_cnt 
                                if x__coeffs_phases[i,k] == x__coeffs_phases[j,k] 
                                    for l in 1:x__states_indxs_coads_cnt 
                                        if x__coeffs_states[i,k,x__states_indxs_coads[l]] != x__coeffs_states[j,k,x__states_indxs_coads[l]]
                                            x__flag = false 
                                        end 
                                        if x__flag == false 
                                            break 
                                        end 
                                    end 
                                    if x__flag == true 
                                        x__flag = (sum(view(x__coeffs_states,j,k,x__states_indxs_adststs)) <= 0)
                                    end 
                                else 
                                    x__flag = false 
                                end 
                                if x__flag == false 
                                    break 
                                end 
                            end 
                            if x__flag == true 
                                if x__refcfgindxs[i] <= 0 
                                    x__refcfgindxs[i] = j 
                                    if get_elemindex(x__refcfgindxs_unique,j,0) <= 0 
                                        push!(x__refcfgindxs_unique,j) 
                                    end 
                                else 
                                    err_flag = true 
                                end 
                            end 
                            if err_flag == true || x__refcfgindxs[i] > 0 
                                break
                            end 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
                x__refGcmpdnames     = Array{String,1}(undef,0) 
                x__refGcmpdphases    = Array{String,1}(undef,0) 
                x__refGcmpdcompounds = Array{String,1}(undef,0) 
                x__refGcmpdtypes     = Array{String,1}(undef,0)
                x__refGcfgindxs      = Array{Int,1}(undef,0)
                x__refGstateindxs    = Array{Int,1}(undef,0)
                x__refGsrcindxs      = Array{Int,1}(undef,0)
                for i in axes(atoms.refcmpds_names,1) 
                    x__cfg_index = 0 
                    x__phase_index = 0
                    x__state_index = 0 
                    for j in 1:x__cnt 
                        for k in 1:phases.phases_cnt 
                            x__state_name = string("<",phases.phases_names[k],"> ",atoms.refcmpds_names[i]) 
                            if haskey(x__states_dindxs,x__state_name) 
                                x__state_index = x__states_dindxs[x__state_name] 
                                if x__state_index > 0 
                                    if x__coeffs_states[j,k,x__state_index] > 0 || sum(x__coeffs_sites[j,k,x__state_index,:]) > 0
                                        for l in 1:x__states_cnt 
                                            if l != x__state_index 
                                                if x__coeffs_states[j,k,l] > 0 || sum(x__coeffs_sites[j,k,l,:]) > 0 
                                                    break 
                                                else 
                                                    if l == x__states_cnt 
                                                        x__cfg_index = j 
                                                        x__phase_index = k
                                                    end 
                                                end 
                                            else 
                                                if l == x__states_cnt 
                                                    x__cfg_index = j 
                                                    x__phase_index = k
                                                end 
                                            end 
                                            if x__cfg_index > 0 
                                                break 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                            if x__cfg_index > 0 
                                break 
                            end 
                        end 
                        if x__cfg_index > 0 
                            break 
                        end 
                    end 
                    if x__cfg_index > 0 
                        push!(x__refGcmpdnames,string("<",phases.phases_names[x__phase_index],"> ",atoms.refcmpds_names[i]))
                        push!(x__refGcmpdphases,phases.phases_names[x__phase_index])
                        push!(x__refGcmpdcompounds,atoms.refcmpds_names[i])
                        push!(x__refGcmpdtypes,"atom")
                        push!(x__refGcfgindxs,x__cfg_index)
                        push!(x__refGstateindxs,x__state_index)
                        push!(x__refGsrcindxs,i)
                    end 
                end 
                for i in axes(x__refcfgindxs_unique,1)
                    x__cmpd_name = x__configs_names[x__refcfgindxs_unique[i]]
                    x__cfg_index = x__refcfgindxs_unique[i]
                    if x__cfg_index > 0 
                        push!(x__refGcmpdnames,x__cmpd_name)
                        push!(x__refGcmpdphases,"")
                        push!(x__refGcmpdcompounds,x__cmpd_name)
                        push!(x__refGcmpdtypes,"reflat")
                        push!(x__refGcfgindxs,x__cfg_index)
                        push!(x__refGstateindxs,0)
                        push!(x__refGsrcindxs,i)
                    end 
                end 
                # for i in axes(x__reflatticescompounds,1) 
                    # x__cmpd_name = x__reflatticescompounds[i]
                    # x__cfg_index = get_elemindex(x__configs_names,x__cmpd_name,0)
                    # if x__cfg_index > 0 
                        # x__state_index = get_elemindex(x__states_names,string("<",x__reflatticesphases[i],"> ",x__cmpd_name),0)
                        # push!(x__refGcmpdnames,x__cmpd_name)
                        # push!(x__refGcmpdphases,x__reflatticesphases[i])
                        # push!(x__refGcmpdcompounds,x__reflatticescompounds[i])
                        # push!(x__refGcmpdtypes,"reflat")
                        # push!(x__refGcfgindxs,x__cfg_index)
                        # push!(x__refGstateindxs,x__state_index)
                        # push!(x__refGsrcindxs,i)
                    # end 
                # end 
                x__refGcmpddindxs = Dict{String,Int}()
                for i in axes(x__refGcmpdnames,1)
                    x__refGcmpddindxs[x__refGcmpdnames[i]] = i
                end 
                x__refGcmpdcnt = size(x__refGcmpdnames,1)
                x__refGcoeffs  = zeros(x__refGcmpdcnt,x__cnt)
                x__rindxs = get_elemindex(x__refGcmpdcompounds,atoms.refcmpds_names,0) 
                err_flag = (minimum(x__rindxs) <= 0)
                if err_flag == false 
                    for i in 1:x__cnt 
                        for j in 1:x__refGcmpdcnt 
                            for k in 1:phases.phases_cnt 
                                if x__refGcmpdtypes[j] == "atom"
                                    x__atomindex = get_elemindex(atoms.refcmpds_names,x__refGcmpdcompounds[j],0)
                                    if x__atomindex > 0 
                                        x__refGcoeffs[j,i] += x__atomrefcmpdtotals[i,k,x__atomindex]
                                    end 
                                end 
                                if x__refGcmpdtypes[j] == "reflat" && x__refcfgindxs[i] > 0 
                                    if x__refGcmpdnames[j] == x__configs_names[x__refcfgindxs[i]] 
                                        x__refGcoeffs[j,i] += x__coeffs_phases[x__refcfgindxs[i],k]
                                    end 
                                    # for l in 1:x__reflatticescnt 
                                        # x__refGcoeffs[j,i] += x__reflatticescoeffs[i,k,l] 
                                    # end 
                                end 
                            end 
                        end 
                        if x__refcfgindxs[i] > 0 
                            for j in 1:phases.phases_cnt 
                                for k in 1:x__states_indxs_coads_cnt 
                                    x__state_index = x__states_indxs_coads[k] 
                                    if x__state_index > 0 
                                        x__state_cmpd = x__states_compounds[x__state_index]
                                        if x__coeffs_states[i,j,x__state_index] > 0 && haskey(molecules.dindxs,x__state_cmpd) 
                                            x__mol_index = molecules.dindxs[x__state_cmpd]
                                            if x__mol_index > 0 
                                                for l in axes(atoms.refcmpds_names,1)
                                                    x__refGcoeffs[x__rindxs[l],i] -= x__coeffs_states[i,j,x__state_index] * molecules.atomrefcmpdtotals[x__mol_index,l]
                                                end 
                                            end 
                                        end
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
            end 

            # Finalize parameters with specific units
            if err_flag == false 
                x__enthalpies_eV = conv_value(physcnsts, physconvs, x__enthalpies_sf.value, x__enthalpies_sf.units, "eV") 
                x__vibfreqs_1_m = conv_value(physcnsts, physconvs, x__vibfreqs_sf.value, x__vibfreqs_sf.units, "1/m") 
                x__trsfreqs_1_m = conv_value(physcnsts, physconvs, x__trsfreqs_sf.value, x__trsfreqs_sf.units, "1/m") 
                x__rotfreqs_1_m = conv_value(physcnsts, physconvs, x__rotfreqs_sf.value, x__rotfreqs_sf.units, "1/m") 
            end 

            # construct object
            if err_flag == false 
                rs = ct__Configurations(
                            x__cnt, x__configs_dindxs, x__configs_names, x__origins, x__compositions, x__refcfgindxs, x__refcfgindxs_unique, 
                            x__atomcoeffs, x__atomrefcoeffs, x__atomrefcmpdtotals, 
                            x__reflatticescnt, x__reflatticesnames, x__reflatticesphases, x__reflatticescompounds, x__reflatticesindxs, x__reflatticescoeffs, 
                            x__refGcmpdcnt, x__refGcmpddindxs, x__refGcmpdnames, x__refGcmpdphases, x__refGcmpdcompounds, x__refGcmpdtypes, x__refGcfgindxs, x__refGstateindxs, x__refGsrcindxs, x__refGcoeffs, 
                            x__enthalpies_sf, x__enthalpies_eV, x__vibfreqs_sf, x__vibfreqs_1_m, x__rotfreqs_sf, x__rotfreqs_1_m, x__trsfreqs_sf, x__trsfreqs_1_m, 
                            x__coeffs_phases, x__coeffs_states, x__coeffs_sites, x__dentates, 
                            x__tst_cnt, x__tst_dindxs, x__tst_names, x__tst_phases, x__tst_compounds, 
                            x__states_cnt, x__states_dindxs, x__states_names, x__states_phases, x__states_compounds, 
                            x__states_indxs_gas, x__states_indxs_gas_cnt, x__states_indxs_nongas, x__states_indxs_nongas_cnt, x__states_indxs_ads, x__states_indxs_ads_cnt, 
                            x__states_indxs_coads, x__states_indxs_coads_cnt, x__states_indxs_coadsequivs, x__states_indxs_coadsequivs_cnt, x__states_indxs_noncoads, x__states_indxs_noncoads_cnt, 
                            x__states_indxs_adsgas, x__states_indxs_adsgas_cnt, x__states_indxs_adscoads, x__states_indxs_adscoads_cnt, x__states_indxs_adststs, x__states_indxs_adststs_cnt, 
                            x__states_indxs_adscoadststs, x__states_indxs_adscoadststs_cnt, x__states_indxs_tsts, x__states_indxs_tsts_cnt, x__states_indxs_odespecies, x__states_indxs_odespecies_cnt, 
                            x__sites_active_all, x__sites_active_unbound, x__states_maxcounts, 
                            x__indxs_gas, x__indxs_gas_cnt, x__indxs_ref, x__indxs_ref_cnt, x__indxs_ads, x__indxs_ads_cnt, x__indxs_tst, x__indxs_tst_cnt, 
                            x__indxs_adsref, x__indxs_adsref_cnt, x__indxs_adstst, x__indxs_adstst_cnt, 
                            x__refstatescovs_scaled, x__refstatescovs_unscaled, x__refsitescovs_scaled, x__refsitescovs_unscaled, 
                            x__uniquecovs_indxs, x__uniquecovs_indxs_adscoads, x__uniquecovs_indxs_adscoadststs, x__uniquecovs_indxs_tsts, x__uniquecovs_indxs_tsts_byadscoadststs, x__uniquecovs_combocovs
                        )
            end 
        end 

        return err_flag, err_msg, rs 
    end

    function Init__Reactions(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, physunits, physcnsts, physconvs, atoms, molecules, phases, odespecies, configurations) 
        
        # Check error state 
        rs = ct__Reactions() 
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Initialize reaction general parameters 
            if err_flag == false 
                x__rxnsegs_names = String["rcts","tsts","prds"]
                x__rxnsegs_dindxs = Dict{String,Int}() 
                for i in axes(x__rxnsegs_names,1)
                    x__rxnsegs_dindxs[x__rxnsegs_names[i]] = i
                end 
                x__rxnsegs_cnt = size(x__rxnsegs_names,1) 
                x__rxnsegs_indxs = (rcts=x__rxnsegs_dindxs["rcts"], tsts=x__rxnsegs_dindxs["tsts"], prds=x__rxnsegs_dindxs["prds"])
                x__rxnsegsext_names = String["rcts","tsts","prds","dtst","drxn","rcts_kbt","tsts_kbt","prds_kbt","dtst_kbt","drxn_kbt"]
                x__rxnsegsext_dindxs = Dict{String,Int}() 
                for i in axes(x__rxnsegsext_names,1)
                    x__rxnsegsext_dindxs[x__rxnsegsext_names[i]] = i
                end 
                x__rxnsegsext_cnt = size(x__rxnsegsext_names,1) 
                x__rxnsegsext_indxs = (
                                        rcts=x__rxnsegsext_dindxs["rcts"], tsts=x__rxnsegsext_dindxs["tsts"], prds=x__rxnsegsext_dindxs["prds"], dtst=x__rxnsegsext_dindxs["dtst"], drxn=x__rxnsegsext_dindxs["drxn"], 
                                        rcts_kbt=x__rxnsegsext_dindxs["rcts_kbt"], tsts_kbt=x__rxnsegsext_dindxs["tsts_kbt"], prds_kbt=x__rxnsegsext_dindxs["prds_kbt"], dtst_kbt=x__rxnsegsext_dindxs["dtst_kbt"], drxn_kbt=x__rxnsegsext_dindxs["drxn_kbt"]
                                    )
                x__rxndirs_names = String["fwd","rev"] 
                x__rxndirs_dindxs = Dict{String,Int}() 
                for i in axes(x__rxndirs_names,1)
                    x__rxndirs_dindxs[x__rxndirs_names[i]] = i
                end 
                x__rxndirs_cnt = size(x__rxndirs_names,1) 
                x__rxndirs_indxs = (fwd=x__rxndirs_dindxs["fwd"], rev=x__rxndirs_dindxs["rev"])
                x__rxnkmethods_names = String["assigned","ads_hke","des_keq","tst_act"] 
                x__rxnkmethods_dindxs = Dict{String,Int}() 
                for i in axes(x__rxnkmethods_names,1)
                    x__rxnkmethods_dindxs[x__rxnkmethods_names[i]] = i
                end 
                x__rxnkmethods_cnt = size(x__rxnkmethods_names,1) 
                x__rxnkmethods_indxs = (assigned=x__rxnkmethods_dindxs["assigned"], ads_hke=x__rxnkmethods_dindxs["ads_hke"], des_keq=x__rxnkmethods_dindxs["des_keq"], tst_act=x__rxnkmethods_dindxs["tst_act"])
                x__rxnkupdmodes_names = String["ref","ini","var"] 
                x__rxnkupdmodes_dindxs = Dict{String,Int}() 
                for i in axes(x__rxnkupdmodes_names,1)
                    x__rxnkupdmodes_dindxs[x__rxnkupdmodes_names[i]] = i
                end 
                x__rxnkupdmodes_cnt = size(x__rxnkupdmodes_names,1) 
                x__rxnkupdmodes_indxs = (ref=x__rxnkupdmodes_dindxs["ref"], ini=x__rxnkupdmodes_dindxs["ini"], var=x__rxnkupdmodes_dindxs["var"])
                x__rxnkupdmodes_varindx = x__rxnkupdmodes_dindxs["var"]
            end 

            # Retrieve reaction data 
            if err_flag == false 
                err_flag, err_msg, x__rxns_ary = get_configrecords(err_flag, err_msg, configdata, "REACTIONS|REACTION") 
            end 

            # Retrieve reaction pairs parameters
            if err_flag == false 
                x__aryindxs           = Array{Int,1}(undef,0) 
                x__pairs_names        = Array{String,1}(undef,0) 
                x__pairs_molexprns    = Array{String,1}(undef,0) 
                x__pairs_fwdrxncoeffs = Array{Float64,2}(undef,0,0) 
                x__pairs_revrxncoeffs = Array{Float64,2}(undef,0,0) 
                x__pairs_tsrbalances  = Array{Float64,1}(undef,0) 
                x__pairs_tspbalances  = Array{Float64,1}(undef,0) 
                x__pairs_rxntypes     = Array{String,1}(undef,0) 
                x__pairs_rxntypes_ads = Array{Int,1}(undef,0) 
                x__pairs_rxntypes_des = Array{Int,1}(undef,0) 
                x__pairs_rxntypes_srf = Array{Int,1}(undef,0) 
                x__chgindxs = Dict{Int,Int}() 
                for i in axes(x__rxns_ary,1) 
                    if haskey(x__rxns_ary[i].vals,"name") 
                        if x__rxns_ary[i].vals["name"] !== nothing 
                            err_flag, err_msg, ptype_name,      pval_name      = get_configproperty(err_flag, err_msg, x__rxns_ary[i].vals, nothing, "", "name",        "", "",    "string",  false, true, "mixed")
                            err_flag, err_msg, ptype_molexprn,  pval_molexprn  = get_configproperty(err_flag, err_msg, x__rxns_ary[i].vals, nothing, "", "molexprn",    "", "",    "string",  false, true, "mixed") 
                            err_flag, err_msg, ptype_tsbalance, pval_tsbalance = get_configproperty(err_flag, err_msg, x__rxns_ary[i].vals, nothing, "", "tsbalance",   "", 0.0,   "Float64", false, true, "mixed") 
                            err_flag, err_msg, ptype_rxntype,   pval_rxntype   = get_configproperty(err_flag, err_msg, x__rxns_ary[i].vals, nothing, "", "rxntype",     "", "",    "string",  false, true, "mixed") 
                            err_flag, err_msg, ptype_include,   pval_include   = get_configproperty(err_flag, err_msg, x__rxns_ary[i].vals, nothing, "", "includeflag", "", false, "bool",    true, false, ""     ) 
                            if err_flag == false 
                                err_flag, err_msg, pval_tsbalance_num = get_confignumber(err_flag, err_msg, Float64, pval_tsbalance[1], "0", true, true, true, false, true) 
                            end 
                            if err_flag == false 
                                err_flag == true 
                                if length(pval_name[1]) > 0 && length(pval_molexprn[1]) > 0 && length(pval_rxntype[1]) > 0 
                                    err_flag = (pval_rxntype[1] != "adsorb" && pval_rxntype[1] != "desorb" && pval_rxntype[1] != "surface") 
                                end 
                            end 
                            if err_flag == false 
                                x__include = get_bool(pval_include[1])
                                if x__include == true 
                                    if pval_rxntype[1] == "desorb" 
                                        x__pair_name = ""
                                        x__segs = str_trim(String.(split(pval_molexprn[1], "-->"))) 
                                        if size(x__segs,1) == 3 
                                            x__pair_name = string(str_trim(join(x__segs[3],""))," --> ",str_trim(join(x__segs[1],"")))
                                            x__pair_molexprn = string(str_trim(join(x__segs[3],""))," --> ",str_trim(join(x__segs[2],""))," --> ",str_trim(join(x__segs[1],"")))
                                            x__pair_tsrbalance = pval_tsbalance_num 
                                            x__pair_tspbalance = (1 - pval_tsbalance_num) 
                                            x__pair_rxntype = "adsorb"
                                            x__chgindxs[(size(x__pairs_names,1)+1)] = size(x__pairs_names,1)+1
                                        else 
                                            err_flag = true 
                                        end 
                                    else
                                        x__pair_name = pval_name[1]
                                        x__pair_molexprn = pval_molexprn[1]
                                        x__pair_tsrbalance = (1 - pval_tsbalance_num) 
                                        x__pair_tspbalance = pval_tsbalance_num
                                        x__pair_rxntype = pval_rxntype[1]
                                    end 
                                    if err_flag == false 
                                        push!(x__pairs_names,x__pair_name) 
                                        push!(x__pairs_molexprns,x__pair_molexprn) 
                                        push!(x__pairs_tsrbalances,x__pair_tsrbalance) 
                                        push!(x__pairs_tspbalances,x__pair_tspbalance) 
                                        push!(x__pairs_rxntypes,x__pair_rxntype) 
                                        if pval_rxntype[1] == "adsorb" 
                                            push!(x__pairs_rxntypes_ads,size(x__pairs_names,1))
                                        elseif pval_rxntype[1] == "desorb" 
                                            push!(x__pairs_rxntypes_des,size(x__pairs_names,1))
                                        elseif pval_rxntype[1] == "surface" 
                                            push!(x__pairs_rxntypes_srf,size(x__pairs_names,1))
                                        end 
                                        push!(x__aryindxs,i)
                                    end 
                                end 
                            end 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
                x__pairs_dindxs = Dict{String,Int}() 
                for i in axes(x__pairs_names,1) 
                    x__pairs_dindxs[x__pairs_names[i]] = i 
                end 
                x__pairs_cnt = size(x__pairs_names,1) 
                if err_flag == false 
                    x__pairs_segments_names = fill("",(x__pairs_cnt,x__rxnsegs_cnt))
                    for i in 1:x__pairs_cnt 
                        x__segs = str_trim(String.(split(x__pairs_molexprns[i], "-->"))) 
                        if size(x__segs,1) == x__rxnsegs_cnt 
                            for j in 1:x__rxnsegs_cnt 
                                x__pairs_segments_names[i,j] = join(x__segs[j],"")
                            end 
                        end 
                    end 
                end 
                if err_flag == false 
                    x__pairs_kmethods               = fill("", (x__pairs_cnt,x__rxndirs_cnt)) 
                    x__pairs_kfactors               = fill(0.0,(x__pairs_cnt,x__rxndirs_cnt)) 
                    x__pairs_kratefactors           = fill(0.0,(x__pairs_cnt,x__rxndirs_cnt)) 
                    x__pairs_kupdmodes              = fill(0,  (x__pairs_cnt,x__rxndirs_cnt,x__rxnsegs_cnt)) 
                    x__pairs_kupdmodes_fwd_const    = Array{Int,1}(undef,0)
                    x__pairs_kupdmodes_fwd_assigned = Array{Int,1}(undef,0) 
                    x__pairs_kupdmodes_fwd_varbl    = Array{Int,1}(undef,0)
                    x__pairs_kupdmodes_rev_const    = Array{Int,1}(undef,0)
                    x__pairs_kupdmodes_rev_assigned = Array{Int,1}(undef,0) 
                    x__pairs_kupdmodes_rev_varbl    = Array{Int,1}(undef,0)
                    for i in 1:x__pairs_cnt 
                        err_flag, err_msg, ptype_kupdmodercts,   pval_kupdmodercts   = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "rctsupdmode",        "", "",  "string",  false, true, "mixed") 
                        err_flag, err_msg, ptype_kupdmodetsts,   pval_kupdmodetsts   = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "tstsupdmode",        "", "",  "string",  false, true, "mixed") 
                        err_flag, err_msg, ptype_kupdmodeprds,   pval_kupdmodeprds   = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "prdsupdmode",        "", "",  "string",  false, true, "mixed") 
                        err_flag, err_msg, ptype_kmethodfwd,     pval_kmethodfwd     = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "ratekfwdcalcmode",   "", "",  "string",  false, true, "mixed") 
                        err_flag, err_msg, ptype_kfactorfwd,     pval_kfactorfwd     = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "ratekfwdcalcfactor", "", 0.0, "Float64", false, true, "mixed") 
                        err_flag, err_msg, ptype_kratefactorfwd, pval_kratefactorfwd = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "ratekfwdratefactor", "", 0.0, "Float64", false, true, "mixed") 
                        err_flag, err_msg, ptype_kmethodrev,     pval_kmethodrev     = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "ratekrevcalcmode",   "", "",  "string",  false, true, "mixed") 
                        err_flag, err_msg, ptype_kfactorrev,     pval_kfactorrev     = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "ratekrevcalcfactor", "", 0.0, "Float64", false, true, "mixed") 
                        err_flag, err_msg, ptype_kratefactorrev, pval_kratefactorrev = get_configproperty(err_flag, err_msg, x__rxns_ary[x__aryindxs[i]].vals, nothing, "", "ratekrevratefactor", "", 0.0, "Float64", false, true, "mixed") 
                        if err_flag == false 
                            err_flag = true 
                            if length(pval_kmethodfwd[1]) > 0 && length(pval_kmethodrev[1]) > 0 && length(pval_kupdmodercts[1]) > 0 && length(pval_kupdmodetsts[1]) > 0 && length(pval_kupdmodeprds[1]) > 0  
                                if haskey(x__rxnkmethods_dindxs,pval_kmethodfwd[1]) && haskey(x__rxnkmethods_dindxs,pval_kmethodrev[1]) && haskey(x__rxnkupdmodes_dindxs,pval_kupdmodercts[1]) && haskey(x__rxnkupdmodes_dindxs,pval_kupdmodetsts[1]) && haskey(x__rxnkupdmodes_dindxs,pval_kupdmodeprds[1])  
                                    err_flag = false 
                                end 
                            end 
                        end
                        if err_flag == false 
                            err_flag, err_msg, pval_kfactorfwd_num     = get_confignumber(err_flag, err_msg, Float64, pval_kfactorfwd[1],     "0", true, true, true, false, true) 
                            err_flag, err_msg, pval_kratefactorfwd_num = get_confignumber(err_flag, err_msg, Float64, pval_kratefactorfwd[1], "0", true, true, true, false, true) 
                            err_flag, err_msg, pval_kfactorrev_num     = get_confignumber(err_flag, err_msg, Float64, pval_kfactorrev[1],     "0", true, true, true, false, true) 
                            err_flag, err_msg, pval_kratefactorrev_num = get_confignumber(err_flag, err_msg, Float64, pval_kratefactorrev[1], "0", true, true, true, false, true) 
                        end 
                        if err_flag == false 
                            if haskey(x__chgindxs,i) 
                                x__pairs_kmethods[i,x__rxndirs_dindxs["rev"]] = pval_kmethodfwd[1] 
                                x__pairs_kfactors[i,x__rxndirs_dindxs["rev"]] = pval_kfactorfwd_num 
                                x__pairs_kratefactors[i,x__rxndirs_dindxs["rev"]] = pval_kratefactorfwd_num 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["rcts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodercts[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["tsts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodetsts[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["prds"]] = x__rxnkupdmodes_dindxs[pval_kupdmodeprds[1]] 
                                if (x__pairs_kmethods[i,x__rxndirs_dindxs["rev"]] != "assigned") && (x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["rcts"]] == x__rxnkupdmodes_varindx || 
                                    x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["tsts"]] == x__rxnkupdmodes_varindx || 
                                    x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["prds"]] == x__rxnkupdmodes_varindx) 
                                    push!(x__pairs_kupdmodes_rev_varbl,i)
                                else 
                                    push!(x__pairs_kupdmodes_rev_const,i)
                                end 
                                if x__pairs_kmethods[i,x__rxndirs_dindxs["rev"]] == "assigned"
                                    push!(x__pairs_kupdmodes_rev_assigned,i)
                                end 
                                x__pairs_kmethods[i,x__rxndirs_dindxs["fwd"]] = pval_kmethodrev[1] 
                                x__pairs_kfactors[i,x__rxndirs_dindxs["fwd"]] = pval_kfactorrev_num 
                                x__pairs_kratefactors[i,x__rxndirs_dindxs["fwd"]] = pval_kratefactorrev_num 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["rcts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodeprds[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["tsts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodetsts[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["prds"]] = x__rxnkupdmodes_dindxs[pval_kupdmodercts[1]] 
                                if (x__pairs_kmethods[i,x__rxndirs_dindxs["fwd"]] != "assigned") && (x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["rcts"]] == x__rxnkupdmodes_varindx || x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["tsts"]] == x__rxnkupdmodes_varindx || x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["prds"]] == x__rxnkupdmodes_varindx) 
                                    push!(x__pairs_kupdmodes_fwd_varbl,i)
                                else 
                                    push!(x__pairs_kupdmodes_fwd_const,i)
                                end 
                                if x__pairs_kmethods[i,x__rxndirs_dindxs["fwd"]] == "assigned"
                                    push!(x__pairs_kupdmodes_fwd_assigned,i)
                                end 
                            else
                                x__pairs_kmethods[i,x__rxndirs_dindxs["fwd"]] = pval_kmethodfwd[1] 
                                x__pairs_kfactors[i,x__rxndirs_dindxs["fwd"]] = pval_kfactorfwd_num 
                                x__pairs_kratefactors[i,x__rxndirs_dindxs["fwd"]] = pval_kratefactorfwd_num 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["rcts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodercts[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["tsts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodetsts[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["fwd"],x__rxnsegs_dindxs["prds"]] = x__rxnkupdmodes_dindxs[pval_kupdmodeprds[1]] 
                                if (pval_kmethodfwd[1] != "assigned") && (x__rxnkupdmodes_dindxs[pval_kupdmodercts[1]] == x__rxnkupdmodes_varindx || x__rxnkupdmodes_dindxs[pval_kupdmodetsts[1]] == x__rxnkupdmodes_varindx || x__rxnkupdmodes_dindxs[pval_kupdmodeprds[1]] == x__rxnkupdmodes_varindx) 
                                    push!(x__pairs_kupdmodes_fwd_varbl,i)
                                else 
                                    push!(x__pairs_kupdmodes_fwd_const,i)
                                end 
                                if pval_kmethodfwd[1] == "assigned"
                                    push!(x__pairs_kupdmodes_fwd_assigned,i)
                                end 
                                x__pairs_kmethods[i,x__rxndirs_dindxs["rev"]] = pval_kmethodrev[1] 
                                x__pairs_kfactors[i,x__rxndirs_dindxs["rev"]] = pval_kfactorrev_num 
                                x__pairs_kratefactors[i,x__rxndirs_dindxs["rev"]] = pval_kratefactorrev_num 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["rcts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodeprds[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["tsts"]] = x__rxnkupdmodes_dindxs[pval_kupdmodetsts[1]] 
                                x__pairs_kupdmodes[i,x__rxndirs_dindxs["rev"],x__rxnsegs_dindxs["prds"]] = x__rxnkupdmodes_dindxs[pval_kupdmodercts[1]] 
                                if (pval_kmethodrev[1] != "assigned") && (x__rxnkupdmodes_dindxs[pval_kupdmodercts[1]] == x__rxnkupdmodes_varindx || x__rxnkupdmodes_dindxs[pval_kupdmodetsts[1]] == x__rxnkupdmodes_varindx || x__rxnkupdmodes_dindxs[pval_kupdmodeprds[1]] == x__rxnkupdmodes_varindx) 
                                    push!(x__pairs_kupdmodes_rev_varbl,i)
                                else 
                                    push!(x__pairs_kupdmodes_rev_const,i)
                                end 
                                if pval_kmethodrev[1] == "assigned"
                                    push!(x__pairs_kupdmodes_rev_assigned,i)
                                end 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                end 
            end 

            # Retrieve reaction parameters 
            if err_flag == false 
                x__cnt                      = 0 
                x__dindxs                   = Dict{String,Int}() 
                x__names                    = fill("", (2*x__pairs_cnt)) 
                x__pairnames                = fill("", (2*x__pairs_cnt)) 
                x__rxndirs                  = fill("", (2*x__pairs_cnt)) 
                x__adsorb_adsrxnindxs       = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_desrxnindxs       = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_gas_odeindxs      = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_gas_cfgindxs      = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_gas_phaseindxs    = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_gas_stateindxs    = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_gas_molwts_kg_mol = fill(0.0,(2*x__pairs_cnt)) 
                x__adsorb_ads_odeindxs      = fill("", (2*x__pairs_cnt)) 
                x__adsorb_ads_cfgindxs      = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_ads_phaseindxs    = fill(0,  (2*x__pairs_cnt)) 
                x__adsorb_ads_stateindxs    = fill("", (2*x__pairs_cnt)) 
                x__molexprns                = fill("", (2*x__pairs_cnt)) 
                x__tsrbalances              = fill(0.0,(2*x__pairs_cnt)) 
                x__tspbalances              = fill(0.0,(2*x__pairs_cnt)) 
                x__rxntypes                 = fill("", (2*x__pairs_cnt)) 
                x__rxntypes_ads             = Array{Int,1}(undef,0) 
                x__rxntypes_ads_varbl       = Array{Int,1}(undef,0) 
                x__rxntypes_ads_hke         = Array{Int,1}(undef,0) 
                x__rxntypes_ads_hke_varbl   = Array{Int,1}(undef,0) 
                x__rxntypes_des             = Array{Int,1}(undef,0) 
                x__rxntypes_des_varbl       = Array{Int,1}(undef,0) 
                x__rxntypes_des_keq         = Array{Int,1}(undef,0) 
                x__rxntypes_des_keq_varbl   = Array{Int,1}(undef,0) 
                x__rxntypes_srf             = Array{Int,1}(undef,0) 
                x__rxntypes_srf_varbl       = Array{Int,1}(undef,0) 
                x__rxntypes_tst_act         = Array{Int,1}(undef,0) 
                x__rxntypes_tst_act_varbl   = Array{Int,1}(undef,0) 
                x__segments_names           = fill("", (2*x__pairs_cnt,x__rxnsegs_cnt)) 
                x__kmethods                 = fill("", (2*x__pairs_cnt)) 
                x__kfactors                 = fill(0.0,(2*x__pairs_cnt)) 
                x__kratefactors             = fill(0.0,(2*x__pairs_cnt)) 
                x__kupdmodes                = fill(0,  (2*x__pairs_cnt,x__rxnsegs_cnt)) 
                x__kupdmodes_const          = Array{Int,1}(undef,0) 
                x__kupdmodes_varbl          = Array{Int,1}(undef,0) 
                x__kupdmodes_assigned       = Array{Int,1}(undef,0) 
                x__kupdmodes_nonassigned    = Array{Int,1}(undef,0) 
                for i in 1:x__pairs_cnt 
                    for j in 1:2 
                        x__cnt += 1 
                        x__ini = (j == 1 ? "rcts" : "prds") 
                        x__fin = (j == 1 ? "prds" : "rcts") 
                        x__names[x__cnt] = string(x__pairs_segments_names[i,x__rxnsegs_dindxs[x__ini]]," --> ", x__pairs_segments_names[i,x__rxnsegs_dindxs[x__fin]]) 
                        x__dindxs[x__names[x__cnt]] = x__cnt  
                        x__rxndirs[x__cnt] = (x__pairs_names[i] == x__names[x__cnt] ? "fwd" : "rev")
                        x__pairnames[x__cnt] = x__pairs_names[i]
                        x__molexprns[x__cnt] = string(x__pairs_segments_names[i,x__rxnsegs_dindxs[x__ini]]," --> ",x__pairs_segments_names[x__rxnsegs_dindxs["tsts"]]," --> ",x__pairs_segments_names[i,x__rxnsegs_dindxs[x__fin]]) 
                        x__tsrbalances[x__cnt] = (j == 1 ? (1 - x__pairs_tspbalances[i]) : x__pairs_tspbalances[i]) 
                        x__tspbalances[x__cnt] = (j == 1 ? x__pairs_tspbalances[i] : (1 - x__pairs_tspbalances[i]))   
                        if j == 2 && x__pairs_rxntypes[i] == "adsorb" 
                            x__rxntypes[x__cnt] = "desorb" 
                        elseif j == 2 && x__pairs_rxntypes[i] == "desorb" 
                            x__rxntypes[x__cnt] = "adsorb" 
                        else 
                            x__rxntypes[x__cnt] = x__pairs_rxntypes[i] 
                        end 
                        if x__rxntypes[x__cnt] == "adsorb" 
                            push!(x__rxntypes_ads,x__cnt)
                        elseif x__rxntypes[x__cnt] == "desorb" 
                            push!(x__rxntypes_des,x__cnt)
                        elseif x__rxntypes[x__cnt] == "surface" 
                            push!(x__rxntypes_srf,x__cnt)
                        end 
                        x__segments_names[x__cnt,x__rxnsegs_dindxs["rcts"]] = x__pairs_segments_names[i,x__rxnsegs_dindxs[x__ini]]
                        x__segments_names[x__cnt,x__rxnsegs_dindxs["tsts"]] = x__pairs_segments_names[i,x__rxnsegs_dindxs["tsts"]]
                        x__segments_names[x__cnt,x__rxnsegs_dindxs["prds"]] = x__pairs_segments_names[i,x__rxnsegs_dindxs[x__fin]]
                        x__kmethods[x__cnt] = x__pairs_kmethods[i,j] 
                        x__kfactors[x__cnt] = x__pairs_kfactors[i,j] 
                        x__kratefactors[x__cnt] = x__pairs_kratefactors[i,j] 
                        x__kupdmodes[x__cnt,x__rxnsegs_dindxs["rcts"]] = x__pairs_kupdmodes[i,j,x__rxnsegs_dindxs[x__ini]] 
                        x__kupdmodes[x__cnt,x__rxnsegs_dindxs["tsts"]] = x__pairs_kupdmodes[i,j,x__rxnsegs_dindxs["tsts"]] 
                        x__kupdmodes[x__cnt,x__rxnsegs_dindxs["prds"]] = x__pairs_kupdmodes[i,j,x__rxnsegs_dindxs[x__fin]] 
                        if x__pairs_kmethods[i,j] != "assigned" 
                            if x__pairs_kupdmodes[i,j,x__rxnsegs_dindxs[x__ini]] == x__rxnkupdmodes_varindx || x__pairs_kupdmodes[i,j,x__rxnsegs_dindxs["tsts"]] == x__rxnkupdmodes_varindx || x__pairs_kupdmodes[i,j,x__rxnsegs_dindxs[x__fin]] == x__rxnkupdmodes_varindx
                                push!(x__kupdmodes_varbl,x__cnt) 
                                if x__kmethods[x__cnt] == "ads_hke"
                                    push!(x__rxntypes_ads_hke_varbl,x__cnt)
                                elseif x__kmethods[x__cnt] == "des_keq"
                                    push!(x__rxntypes_des_keq_varbl,x__cnt)
                                elseif x__kmethods[x__cnt] == "tst_act"
                                    push!(x__rxntypes_tst_act_varbl,x__cnt)
                                end 
                            else 
                                push!(x__kupdmodes_const,x__cnt) 
                            end 
                            if x__kmethods[x__cnt] == "ads_hke"
                                push!(x__rxntypes_ads_hke,x__cnt) 
                            elseif x__kmethods[x__cnt] == "des_keq"
                                push!(x__rxntypes_des_keq,x__cnt)
                            elseif x__kmethods[x__cnt] == "tst_act"
                                push!(x__rxntypes_tst_act,x__cnt)
                            end 
                        else
                            push!(x__kupdmodes_const,x__cnt) 
                            if j == 1 && get_elemindex(x__pairs_kupdmodes_fwd_assigned,i,0) > 0
                                push!(x__kupdmodes_assigned,x__cnt)
                            elseif j == 2 && get_elemindex(x__pairs_kupdmodes_rev_assigned,i,0) > 0
                                push!(x__kupdmodes_assigned,x__cnt)
                            end
                        end 
                    end 
                end 
                for i in 1:x__cnt 
                    if get_elemindex(x__kupdmodes_assigned,i,0) <= 0 
                        push!(x__kupdmodes_nonassigned,i)
                    end 
                end 
                x__adsorb_absindxs = get_elemindex(x__rxntypes_ads,collect(1:x__cnt),0)
            end 
            
            # Retrieve reaction coefficients 
            if err_flag == false 
                if err_flag == false 
                    x__coeffs_phases = fill(0.0,(x__cnt,x__rxnsegs_cnt,phases.phases_cnt))
                    x__coeffs_states = fill(0.0,(x__cnt,x__rxnsegs_cnt,phases.phases_cnt,configurations.states_cnt))
                    x__coeffs_sites  = fill(0.0,(x__cnt,x__rxnsegs_cnt,phases.phases_cnt,configurations.states_cnt,phases.sites_cnt))
                    for i in 1:x__cnt 
                        for j in 1:x__rxnsegs_cnt 
                            x__cfgindx = configurations.dindxs[x__segments_names[i,j]] 
                            x__coeffs_phases[i,j,:]    .= view(configurations.coeffs_phases,x__cfgindx,:) 
                            x__coeffs_states[i,j,:,:]  .= view(configurations.coeffs_states,x__cfgindx,:,:) 
                            x__coeffs_sites[i,j,:,:,:] .= view(configurations.coeffs_sites,x__cfgindx,:,:,:) 
                        end 
                        x__lat_maxs = vec(maximum(view(x__coeffs_phases,i,:,:),dims=1))
                        x__lat_maxs[phases.indxs_gases] .= 0 
                        x__loopflag = true 
                        while x__loopflag == true 
                            x__loopflag = false 
                            for j in 1:phases.phases_cnt 
                                for k in 1:x__rxnsegs_cnt 
                                    if x__lat_maxs[j] > x__coeffs_phases[i,k,j] 
                                        if x__coeffs_phases[i,k,j] > 0 
                                            if sum(view(x__coeffs_states,i,k,j,:)) > 0 
                                                x__flag = false 
                                                for l in 1:phases.phases_cnt
                                                    if l != j 
                                                        if phases.reflattices[l] == phases.reflattices[j] && sum(view(x__coeffs_states,i,k,l,:)) <= 0
                                                            x__coeffs_phases[i,k,l] += x__lat_maxs[j] - x__coeffs_phases[i,k,j]
                                                            if x__coeffs_phases[i,k,l] > x__lat_maxs[j] 
                                                                x__lat_maxs[j] = x__coeffs_phases[i,k,l]
                                                                x__loopflag = true 
                                                            end
                                                            x__flag = true 
                                                        end
                                                    end 
                                                    if err_flag == true || x__loopflag == true || x__flag == true 
                                                        break
                                                    end 
                                                end 
                                                if err_flag == false && x__loopflag == false && x__flag == false 
                                                    err_flag = true 
                                                    # this is the simple response -- a more robust response would be to add a phase with a bare lattice with the correct reference lattice of count equal to the current difference (x__lat_maxs[j] - x__coeffs_phases[i,k,j]) 
                                                end 
                                            else 
                                                x__coeffs_phases[i,k,j] = x__lat_maxs[j] 
                                                x__coeffs_states[i,k,j,:] .= 0 
                                            end 
                                        else 
                                            x__coeffs_phases[i,k,j] = x__lat_maxs[j] 
                                            x__coeffs_states[i,k,j,:] .= 0 
                                        end 
                                    end 
                                    if err_flag == true || x__loopflag == true 
                                        break 
                                    end 
                                end 
                                if err_flag == true || x__loopflag == true 
                                    break 
                                end 
                            end
                        end 
                    end 
                    x__rxn_tst_stateindxs = zeros(x__cnt)
                    x__rxn_tst_rxndindxs = Dict{String,Int}()
                    for i in 1:x__cnt 
                        x__state_index = 0 
                        x__segment_name = x__segments_names[i,x__rxnsegs_dindxs["tsts"]] 
                        if haskey(configurations.dindxs,x__segment_name) 
                            x__cfg_index = configurations.dindxs[x__segment_name] 
                            if x__cfg_index > 0 
                                for j in 1:phases.indxs_surfs_cnt
                                    for k in axes(configurations.states_indxs_tsts,1)
                                        if configurations.coeffs_states[x__cfg_index,phases.indxs_surfs[j],configurations.states_indxs_tsts[k]] > 0 
                                            x__state_index = configurations.states_indxs_tsts[k]
                                            break 
                                        elseif sum(configurations.coeffs_sites[x__cfg_index,phases.indxs_surfs[j],configurations.states_indxs_tsts[k],:]) > 0 
                                            x__state_index = configurations.states_indxs_tsts[k]
                                            break 
                                        end 
                                    end 
                                    if x__state_index > 0 
                                        break 
                                    end 
                                end 
                            end 
                        end
                        if x__state_index > 0 
                            x__rxn_tst_stateindxs[i] = x__state_index 
                            x__rxn_tst_rxndindxs[configurations.states_names[x__state_index]] = i 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                end 
                if err_flag == false 
                    x__coeffs_alpha = fill(0.0,(odespecies.cnt,x__cnt)) 
                    x__coeffs_beta  = fill(1.0,(odespecies.cnt,x__cnt)) 
                    x__coeffs_gamma = fill(0.0,(odespecies.cnt,x__cnt)) 
                    for i in 1:x__cnt 
                        for j in 1:odespecies.cnt 
                            x__phase_name = odespecies.phases[j]
                            x__phase_index = get_elemindex(phases.phases_names,x__phase_name,0)
                            x__phase_surf_index = get_elemindex(view(phases.phases_names,phases.indxs_surfs),x__phase_name,0)
                            x__state_name = odespecies.names[j] 
                            if x__phase_index > 0 && haskey(odespecies.dindxs,x__state_name) 
                                x__phasesite_index = get_elemindex(phases.phases_sites_names,x__state_name,0)
                                x__site_index = 0 
                                if x__phasesite_index > 0 
                                    x__site_index = phases.phases_sites_indxs[x__phasesite_index]
                                end 
                                if x__site_index > 0 
                                    if x__phase_surf_index > 0 
                                        x__coeffs_alpha[j,i] = (
                                            (phases.sites_coeffs[x__phase_surf_index,x__site_index] != 0) ? 
                                            (
                                                (
                                                    sum(vec(view(x__coeffs_sites,i,x__rxnsegs_dindxs["rcts"],x__phase_index,:,x__site_index))) .- 
                                                    sum(vec(view(x__coeffs_sites,i,x__rxnsegs_dindxs["prds"],x__phase_index,:,x__site_index)))
                                                ) / 
                                                phases.sites_coeffs[x__phase_surf_index,x__site_index]
                                            ) : 0.0
                                        ) 
                                        x__coeffs_beta[j,i]  = (phases.sites_coeffs[x__phase_surf_index,x__site_index] > 0 ? (1 / phases.sites_coeffs[x__phase_surf_index,x__site_index]) : 0.0)
                                    end 
                                elseif haskey(configurations.states_dindxs,x__state_name)
                                    x__state_index = configurations.states_dindxs[x__state_name]
                                    x__coeffs_alpha[j,i] = x__coeffs_states[i,x__rxnsegs_dindxs["prds"],x__phase_index,x__state_index] - x__coeffs_states[i,x__rxnsegs_dindxs["rcts"],x__phase_index,x__state_index]
                                    if x__phase_surf_index > 0 
                                        x__coeffs_beta[j,i]  = ((x__coeffs_alpha[j,i] != 0) ? (maximum(abs.(vec(view(x__coeffs_sites,i,x__rxnsegs_dindxs["prds"],x__phase_index,x__state_index,:)) .- vec(view(x__coeffs_sites,i,x__rxnsegs_dindxs["rcts"],x__phase_index,x__state_index,:))) ./ vec(view(phases.sites_coeffs,x__phase_surf_index,:))) / abs(x__coeffs_alpha[j,i])) : 0.0)     
                                    end 
                                end 
                                x__coeffs_beta[j,i] = isnan(x__coeffs_beta[j,i]) ? 0.0 : x__coeffs_beta[j,i] 
                                x__coeffs_gamma[j,i] = abs(min(x__coeffs_alpha[j,i],0.0))
                            end 
                        end 
                    end 
                end 
                if err_flag == false 
                    x__pairs_rxncoeffs    = zeros(x__pairs_cnt,x__cnt) 
                    x__pairs_fwdrxncoeffs = zeros(x__pairs_cnt,x__cnt)
                    x__pairs_revrxncoeffs = zeros(x__pairs_cnt,x__cnt)
                    for i in 1:x__pairs_cnt 
                        for j in 1:x__cnt 
                            if x__pairs_names[i] == x__pairnames[j] 
                                if x__names[j] == x__pairnames[j] 
                                    x__pairs_rxncoeffs[i,j]    = +1
                                    x__pairs_fwdrxncoeffs[i,j] = +1
                                else 
                                    x__pairs_rxncoeffs[i,j]    = -1
                                    x__pairs_revrxncoeffs[i,j] = +1
                                end 
                            end 
                        end 
                    end 
                end 
            end 

            # Retrieve adsorption / desorption parameters 
            if err_flag == false 
                for i in 1:x__cnt 
                    x__seg_gas = (x__rxntypes[i] == "adsorb" ? "rcts" : "prds") 
                    x__seg_ads = (x__rxntypes[i] == "adsorb" ? "prds" : "rcts") 
                    x__pairindx = 0 
                    for j in 1:x__cnt 
                        if x__names[i] != x__names[j] && x__names[i] != x__pairnames[j] && x__pairnames[i] == x__pairnames[j] 
                            x__pairindx = j 
                            break 
                        end 
                    end 
                    x__flag = false 
                    for j in axes(phases.indxs_gases,1)
                        for k in 1:configurations.states_cnt 
                            if x__coeffs_states[i,x__rxnsegs_dindxs[x__seg_gas],phases.indxs_gases[j],k] > 0 
                                x__molindex = get_elemindex(molecules.names,configurations.states_compounds[k],0)
                                x__odeindex = get_elemindex(odespecies.names,configurations.states_names[k],0)
                                if x__molindex > 0 && x__odeindex > 0 
                                    if molecules.phases[x__molindex] == "gas" && get_elemindex(odespecies.indxs_gas,x__odeindex,0) > 0 
                                        for l in axes(phases.indxs_surfs,1)
                                            if x__coeffs_phases[i,x__rxnsegs_dindxs[x__seg_ads],phases.indxs_surfs[l]] > 0 
                                                for m in axes(configurations.states_indxs_adscoads,1) 
                                                    if x__coeffs_states[i,x__rxnsegs_dindxs[x__seg_ads],phases.indxs_surfs[l],configurations.states_indxs_adscoads[m]] > 0 
                                                        x__flag = true 
                                                        if x__rxntypes[i] == "adsorb" 
                                                            x__adsorb_adsrxnindxs[i] = i 
                                                            x__adsorb_desrxnindxs[i] = x__pairindx 
                                                        else
                                                            x__adsorb_adsrxnindxs[i] = x__pairindx 
                                                            x__adsorb_desrxnindxs[i] = i 
                                                        end 
                                                        x__adsorb_gas_odeindxs[i]      = x__odeindex
                                                        x__adsorb_gas_cfgindxs[i]      = configurations.dindxs[x__segments_names[i,x__rxnsegs_dindxs[x__seg_gas]]]
                                                        x__adsorb_gas_phaseindxs[i]    = phases.indxs_gases[j]
                                                        x__adsorb_gas_stateindxs[i]    = k 
                                                        x__adsorb_gas_molwts_kg_mol[i] = molecules.molwt_kg_mol[x__molindex]
                                                        x__adsorb_ads_odeindxs[i]      = string(x__adsorb_ads_odeindxs[i],(length(x__adsorb_ads_odeindxs[i]) > 0 ? "|" : ""),get_elemindex(odespecies.names,configurations.states_names[configurations.states_indxs_adscoads[m]],0))
                                                        x__adsorb_ads_cfgindxs[i]      = configurations.dindxs[x__segments_names[i,x__rxnsegs_dindxs[x__seg_ads]]]
                                                        x__adsorb_ads_phaseindxs[i]    = phases.indxs_surfs[l]
                                                        x__adsorb_ads_stateindxs[i]    = string(x__adsorb_ads_stateindxs[i],(length(x__adsorb_ads_stateindxs[i]) > 0 ? "|" : ""),configurations.states_indxs_adscoads[m])
                                                    end 
                                                end 
                                                break 
                                            end
                                        end 
                                        break 
                                    end 
                                end 
                            end 
                        end 
                        if x__flag == true 
                            break 
                        end 
                    end 
                end 
            end 

            # Retrieve unique active surface compounds combinations 
            if err_flag == false 

                # Construct compounds list
                x__combos_cnms = get_view(view(odespecies.names,odespecies.indxs_adscoads))
                x__combos_cpms = get_view(view(odespecies.compounds,odespecies.indxs_adscoads))

                # Detect unique combinations
                x__combos_idxs = zeros(Int,x__cnt,2)
                x__combos_keys = Array{String,1}(undef,0) 
                x__combos_knms = Array{String,1}(undef,0) 
                x__combos_rids = Dict{String,Array{Int,1}}() 
                x__combos_rcxs = Dict{String,Array{Int,1}}() 
                x__combos_flgs = zeros(Int,x__cnt,odespecies.indxs_adscoads_cnt,2) 
                x__combos_indxs_nonempty = Array{Int,1}(undef,0)
                for i in 1:2 
                    x__segtype = (i == 1 ? "rcts" : "prds") 
                    for j in 1:x__cnt 
                        for k in 1:odespecies.indxs_adscoads_cnt 
                            x__phase_index = phases.phases_dindxs[odespecies.phases[odespecies.indxs_adscoads[k]]]
                            x__state_index = configurations.states_dindxs[odespecies.names[odespecies.indxs_adscoads[k]]]
                            if get_elemindex(odespecies.indxs_ads,odespecies.indxs_adscoads[k],0) > 0 
                                x__combos_flgs[j,k,i] = (x__coeffs_states[j,x__rxnsegs_dindxs[x__segtype],x__phase_index,x__state_index] > 0 ? 1 : 0)
                            else 
                                x__combos_flgs[j,k,i] = 1
                            end 
                        end 
                        x__key = join(vec(view(x__combos_flgs,j,:,i)),"|") 
                        if haskey(x__combos_rids,x__key) == false 
                            push!(x__combos_keys,x__key) 
                            x__knm = ""
                            for k in 1:odespecies.indxs_adscoads_cnt
                                if x__combos_flgs[j,k,i] != 0 
                                    if get_elemindex(view(odespecies.names,odespecies.indxs_coads),x__combos_cnms[k],0) <= 0 
                                        x__knm = string(x__knm,(length(x__knm) > 0 ? ", " : ""),x__combos_cnms[k])
                                    end 
                                end 
                            end 
                            if length(x__knm) <= 0 
                                x__knm = "(empty)"
                            end 
                            push!(x__combos_knms,x__knm) 
                            if x__knm != "(empty)"
                                push!(x__combos_indxs_nonempty,size(x__combos_knms,1))
                            end 
                            x__combos_rids[x__key] = Array{Int,1}(undef,0)
                            x__combos_rcxs[x__key] = deepcopy(vec(view(x__combos_flgs,j,:,i)))
                        end 
                        push!(x__combos_rids[x__key],j) 
                        x__combos_idxs[j,i] = get_elemindex(x__combos_keys,x__key,0)
                    end 
                end 

                # Construct unique combinations coefficients 
                x__combos_coeffs = zeros(Int,size(x__combos_keys,1),odespecies.indxs_adscoads_cnt)
                for i in axes(x__combos_keys,1)
                    x__combos_coeffs[i,:] .= x__combos_rcxs[x__combos_keys[i]]
                end
            end 

            # construct object
            if err_flag == false 
                rs = ct__Reactions(
                            x__cnt, x__dindxs, x__names, x__pairnames, x__rxndirs, 
                            x__adsorb_adsrxnindxs, x__adsorb_desrxnindxs, 
                            x__adsorb_gas_odeindxs, x__adsorb_gas_cfgindxs, x__adsorb_gas_phaseindxs, x__adsorb_gas_stateindxs, x__adsorb_gas_molwts_kg_mol, 
                            x__adsorb_ads_odeindxs, x__adsorb_ads_cfgindxs, x__adsorb_ads_phaseindxs, x__adsorb_ads_stateindxs, 
                            x__molexprns, x__tsrbalances, x__tspbalances, 
                            x__rxntypes, 
                            x__rxntypes_ads, x__rxntypes_ads_varbl, x__rxntypes_ads_hke, x__rxntypes_ads_hke_varbl, 
                            x__rxntypes_des, x__rxntypes_des_varbl, x__rxntypes_des_keq, x__rxntypes_des_keq_varbl, 
                            x__rxntypes_srf, x__rxntypes_srf_varbl, x__rxntypes_tst_act, x__rxntypes_tst_act_varbl, 
                            x__segments_names, x__rxn_tst_stateindxs, x__rxn_tst_rxndindxs, 
                            x__kmethods, x__kfactors, x__kratefactors, x__kupdmodes, x__kupdmodes_const, x__kupdmodes_assigned, x__kupdmodes_nonassigned, x__kupdmodes_varbl, 
                            x__pairs_cnt, x__pairs_dindxs, x__pairs_names, x__pairs_molexprns, x__pairs_rxncoeffs, x__pairs_fwdrxncoeffs, x__pairs_revrxncoeffs, x__pairs_tsrbalances, x__pairs_tspbalances, 
                            x__pairs_rxntypes, x__pairs_rxntypes_ads, x__pairs_rxntypes_des, x__pairs_rxntypes_srf, x__pairs_segments_names, 
                            x__pairs_kmethods, x__pairs_kfactors, x__pairs_kratefactors, 
                            x__pairs_kupdmodes, 
                            x__pairs_kupdmodes_fwd_const, x__pairs_kupdmodes_fwd_assigned, x__pairs_kupdmodes_fwd_varbl, x__pairs_kupdmodes_rev_const, x__pairs_kupdmodes_rev_assigned, x__pairs_kupdmodes_rev_varbl, 
                            x__rxnsegs_cnt, x__rxnsegs_dindxs, x__rxnsegs_names, x__rxnsegs_indxs, 
                            x__rxnsegsext_cnt, x__rxnsegsext_dindxs, x__rxnsegsext_names, x__rxnsegsext_indxs, 
                            x__rxndirs_cnt, x__rxndirs_dindxs, x__rxndirs_names, x__rxndirs_indxs, 
                            x__rxnkmethods_cnt, x__rxnkmethods_dindxs, x__rxnkmethods_names, x__rxnkmethods_indxs, 
                            x__rxnkupdmodes_cnt, x__rxnkupdmodes_dindxs, x__rxnkupdmodes_names, x__rxnkupdmodes_indxs, 
                            x__coeffs_phases, x__coeffs_states, x__coeffs_sites, x__coeffs_alpha, x__coeffs_beta, x__coeffs_gamma, 
                            x__combos_cnms, x__combos_idxs, x__combos_keys, x__combos_knms, x__combos_rids, x__combos_rcxs, x__combos_flgs, x__combos_coeffs, x__combos_indxs_nonempty
                        ) 
            end 
        end 

        return err_flag, err_msg, rs 
    end 



    # Reaction run initialization functions 

    function Init__RxnRuns(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, cl_dir, runs_dir, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, rxnsystem) 

        # Check error state 
        rs = ct__RxnRuns() 
        if err_flag == false
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
            
            # Retrieve runs data 
            if err_flag == false 
                err_flag, err_msg, x__runs_ary                  = get_configrecords(err_flag, err_msg, configdata, "RUNS|RUN"                                  ) 
                err_flag, err_msg, x__runs_ary_options          = get_configrecords(err_flag, err_msg, configdata, "RUNS_OPTIONS|RUNS_OPTION"                  ) 
                err_flag, err_msg, x__runs_ary_defaults         = get_configrecords(err_flag, err_msg, configdata, "RUNS_OPTIONS_DEFAULTS|RUNS_OPTIONS_DEFAULT") 
                err_flag, err_msg, x__runs_ary_ode_scalefactors = get_configrecords(err_flag, err_msg, configdata, "RUNS_ODE_SCALEFACTORS|RUNS_ODE_SCALEFACTOR") 
                err_flag, err_msg, x__runs_ary_drc_species      = get_configrecords(err_flag, err_msg, configdata, "RUNS_DRC_COMPOUNDS|RUNS_DRC_COMPOUND"      ) 
                err_flag, err_msg, x__runs_ary_dsc_pairs        = get_configrecords(err_flag, err_msg, configdata, "RUNS_DSC_PAIRS|RUNS_DSC_PAIR"              ) 
                err_flag, err_msg, x__runs_ary_reffractions     = get_configrecords(err_flag, err_msg, configdata, "RUNS_REF_FRACTIONS|RUNS_REF_FRACTION"      ) 
                err_flag, err_msg, x__runs_ary_inifractions     = get_configrecords(err_flag, err_msg, configdata, "RUNS_INI_FRACTIONS|RUNS_INI_FRACTION"      ) 
            end 

            # Retrieve runs parameters 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("Retrieving runs parameters..."))
                x__names     = Array{String,1}(undef,0) 
                x__nicknames = Array{String,1}(undef,0) 
                x__rxnruns   = Array{ct__RxnRun,1}(undef,0)
                for i in axes(x__runs_ary,1) 
                    if haskey(x__runs_ary[i].vals,"name") 
                        if x__runs_ary[i].vals["name"] !== nothing 
                            if length(x__runs_ary[i].vals["name"]) > 0 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("  run ",(size(x__names,1)+1),": ",x__runs_ary[i].vals["name"])) 
                                err_flag, err_msg, x__rxnrun = Init__RxnRun(msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, configdata, cl_dir, runs_dir, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, rxnsystem, x__runs_ary[i].vals["name"], x__runs_ary_options, x__runs_ary_defaults, x__runs_ary_ode_scalefactors, x__runs_ary_drc_species, x__runs_ary_dsc_pairs, x__runs_ary_reffractions, x__runs_ary_inifractions) 
                                if err_flag == false 
                                    push!(x__names,x__runs_ary[i].vals["name"]) 
                                    push!(x__nicknames,x__rxnrun.nickname) 
                                    push!(x__rxnruns,x__rxnrun) 
                                end 
                            end 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
                if err_flag == false 
                    x__dindxs = Dict{String,Int}() 
                    for i in axes(x__names,1) 
                        x__dindxs[x__names[i]] = i 
                    end 
                    x__cnt = size(x__names,1) 
                end 
            end 
        
            # Construct runs object
            if err_flag == false 
                rs = ct__RxnRuns(x__cnt, x__dindxs, x__names, x__nicknames, x__rxnruns) 
            end 

            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
        end

        return err_flag, err_msg, rs
    end 

    function Init__RxnRun(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, configdata, cl_dir, runs_dir, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, rxnsystem, rxnrun_name, runs_options, runs_defaults, runs_ode_scalefactors, runs_drc_species, runs_dsc_pairs, runs_reffractions, runs_inifractions) 

        # Check error state 
        rs = ct__RxnRun() 
        if err_flag == false
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
            
            # General parameters 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("general parameters"))
                err_flag, err_msg, ptype_nickname,    pval_nickname    = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "nickname"      ], "value", rxnrun_name, "string", true,  true,  "mixed") 
                err_flag, err_msg, ptype_showdbgflag, pval_showdbgflag = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "show_debugging"], "value", false,       "bool",   true,  false, ""     ) 
                err_flag, err_msg, ptype_temps_exprn, pval_temps_exprn = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "temperature"   ], "value", "298.15",    "string", false, true,  "mixed")
                err_flag, err_msg, ptype_temps_units, pval_temps_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "temperature"   ], "units", rxnsystem.physunits.temperature, "string", true, true, "mixed") 
                if err_flag == false 
                    x__nickname    = pval_nickname[1] 
                    x__showdbgflag = get_bool(pval_showdbgflag[1]) 
                    x__log_num_prec = rxnsystem.log_num_prec
                    x__log_force_prec = rxnsystem.log_force_prec
                    x__output_num_prec = rxnsystem.output_num_prec
                    x__output_force_prec = rxnsystem.output_force_prec
                    x__covs_detect_tol = rxnsystem.covs_detect_tol
                    x__temps_exprn = pval_temps_exprn[1]
                    x__temps_units = pval_temps_units[1] 
                end 
            end 

            # Logging options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("logging options")) 
                err_flag, err_msg, x__logopts = Init__RxnRun__LoggingOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults, cl_dir, runs_dir, run_folder)
            end 

            # Partition function options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("partition functions options")) 
                err_flag, err_msg, x__qfuncopts = Init__RxnRun__PartitionfunctionOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults)
            end 

            # Solver Options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("solver options")) 
                err_flag, err_msg, x__solveropts = Init__RxnRun__SolverOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults, runs_ode_scalefactors)
            end 

            # Stable state Options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("stable state detection options")) 
                err_flag, err_msg, x__sbsopts = Init__RxnRun__StableStateOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults)
            end 

            # Steady state Options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("steady state detection options")) 
                err_flag, err_msg, x__stsopts = Init__RxnRun__SteadyStateOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults)
            end 

            # Single pathway state Options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("single pathway state detection options")) 
                err_flag, err_msg, x__spsopts = Init__RxnRun__SinglePathwayStateOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults)
            end 

            # Sensitivity analysis Options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("sensitivity analysis options")) 
                err_flag, err_msg, x__snsopts = Init__RxnRun__SensitivityOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults, runs_drc_species, runs_dsc_pairs)
            end 

            # Output Options
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string("output options")) 
                err_flag, err_msg, x__outputopts = Init__RxnRun__OutputOptions(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults)
            end 
            
            # ODE fractions 
            if err_flag == false 
                x__odefracs_ref = fill(0.0,rxnsystem.odespecies.cnt) 
                for i in axes(runs_reffractions,1)
                    if haskey(runs_reffractions[i].vals, "run") && haskey(runs_reffractions[i].vals, "compound") && haskey(runs_reffractions[i].vals, "fraction") 
                        if runs_reffractions[i].vals["run"] !== nothing && runs_reffractions[i].vals["compound"] !== nothing && runs_reffractions[i].vals["fraction"] !== nothing 
                            if length(runs_reffractions[i].vals["run"]) > 0 && length(runs_reffractions[i].vals["compound"]) > 0 
                                if runs_reffractions[i].vals["run"] == rxnrun_name && tryparse(Float64, runs_reffractions[i].vals["fraction"]) !== nothing 
                                    err_flag, err_msg, ptype_fraction, pval_fraction = get_configproperty(err_flag, err_msg, runs_reffractions[i].vals, nothing, "", "fraction", "", "", "float64", false, true, "mixed")
                                    if err_flag == false 
                                        err_flag, err_msg, x__fraction = get_confignumber(err_flag, err_msg, Float64, pval_fraction[1], "0", true, true, true, false, true) 
                                    end 
                                    if err_flag == false 
                                        x__cmpd_name = str_trim(runs_reffractions[i].vals["compound"])
                                        for j in 1:rxnsystem.phases.phases_cnt 
                                            x__state_name = string("<",rxnsystem.phases.phases_names[j],"> ",x__cmpd_name)
                                            if haskey(rxnsystem.odespecies.dindxs,x__state_name)
                                                x__odeindex = rxnsystem.odespecies.dindxs[x__state_name]
                                                if x__odeindex > 0 
                                                    x__odefracs_ref[x__odeindex] = x__fraction 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
                x__odefracs_ini = fill(0.0,rxnsystem.odespecies.cnt) 
                x__odefracs_fixed = Array{Int,1}(undef,0) 
                for i in axes(runs_inifractions,1)
                    if haskey(runs_inifractions[i].vals, "run") && haskey(runs_inifractions[i].vals, "compound") && haskey(runs_inifractions[i].vals, "fraction") 
                        if runs_inifractions[i].vals["run"] !== nothing && runs_inifractions[i].vals["compound"] !== nothing && runs_inifractions[i].vals["fraction"] !== nothing 
                            if length(runs_inifractions[i].vals["run"]) > 0 && length(runs_inifractions[i].vals["compound"]) > 0 
                                if runs_inifractions[i].vals["run"] == rxnrun_name && tryparse(Float64, runs_inifractions[i].vals["fraction"]) !== nothing 
                                    err_flag, err_msg, ptype_fraction, pval_fraction = get_configproperty(err_flag, err_msg, runs_inifractions[i].vals, nothing, "", "fraction",      "", "",    "float64", false, true,  "mixed")
                                    err_flag, err_msg, ptype_constant, pval_constant = get_configproperty(err_flag, err_msg, runs_inifractions[i].vals, nothing, "", "constantvalue", "", false, "bool",    true,  false, ""     )
                                    if err_flag == false 
                                        err_flag, err_msg, x__fraction = get_confignumber(err_flag, err_msg, Float64, pval_fraction[1], "0", true, true, true, false, true) 
                                        x__constant = get_bool(pval_constant[1])
                                    end 
                                    if err_flag == false 
                                        x__cmpd_name = str_trim(runs_inifractions[i].vals["compound"])
                                        for j in 1:rxnsystem.phases.phases_cnt 
                                            x__state_name = string("<",rxnsystem.phases.phases_names[j],"> ",x__cmpd_name)
                                            if haskey(rxnsystem.odespecies.dindxs,x__state_name)
                                                x__odeindex = rxnsystem.odespecies.dindxs[x__state_name]
                                                if x__odeindex > 0 
                                                    x__odefracs_ini[x__odeindex] = x__fraction 
                                                    if x__constant == true 
                                                        push!(x__odefracs_fixed,x__odeindex) 
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
                x__odefracs_varbl = Array{Int,1}(undef,0) 
                for i in axes(rxnsystem.odespecies.names,1) 
                    if get_elemindex(x__odefracs_fixed,i,0) <= 0 
                        push!(x__odefracs_varbl,i) 
                    end 
                end 
            end 

            # Construct runs object
            if err_flag == false 
                rs = ct__RxnRun(
                            rxnrun_name, x__nickname, run_folder, x__showdbgflag, x__log_num_prec, x__log_force_prec, x__output_num_prec, x__output_force_prec, x__covs_detect_tol, x__temps_exprn, x__temps_units, 
                            x__logopts, x__qfuncopts, x__solveropts, x__sbsopts, x__stsopts, x__spsopts, x__snsopts, x__outputopts, 
                            x__odefracs_ref, x__odefracs_ini, x__odefracs_fixed, x__odefracs_varbl 
                        ) 
            end 

            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
        end

        return err_flag, err_msg, rs
    end 

    function Init__RxnRun__LoggingOptions(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults, cl_dir, runs_dir, run_folder) 
              
        # Check error state 
        rs = ct__RxnRun_Logging() 
        if err_flag == false
            err_flag = false 
            err_msg = "" 

            # Retrieve logging options
            if err_flag == false 
                err_flag, err_msg, ptype_folder_group,             pval_folder_group             = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_group"],             "value", "",    "string", true, true, "mixed") 
                err_flag, err_msg, ptype_folder_group_submode,     pval_folder_group_submode     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_group_submode"],     "value", "",    "string", true, true, "mixed") 
                err_flag, err_msg, ptype_folder_group_subfolder,   pval_folder_group_subfolder   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_group_subfolder"],   "value", "",    "string", true, true, "mixed") 
                err_flag, err_msg, ptype_folder_group_subparam,    pval_folder_group_subparam    = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_group_subparam"],    "value", "",    "string", true, true, "mixed") 
                err_flag, err_msg, ptype_folder_run_userunsfolder, pval_folder_run_userunsfolder = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_run_userunsfolder"], "value", false, "bool",   true, false, ""    ) 
                err_flag, err_msg, ptype_folder_run_userunfolder,  pval_folder_run_userunfolder  = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_run_userunfolder"],  "value", false, "bool",   true, false, ""    ) 
                err_flag, err_msg, ptype_folder_run_submode,       pval_folder_run_submode       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_run_submode"],       "value", "",    "string", true, true, "mixed") 
                err_flag, err_msg, ptype_folder_dft_relpath,       pval_folder_dft_relpath       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "folder_dft_relpath"],       "value", "",    "string", true, true, "mixed") 
                if err_flag == false 
                    x__folder_group             = (length(run_folder) > 0 ? run_folder : pval_folder_group[1]) 
                    x__folder_group_submode     = pval_folder_group_submode[1]
                    x__folder_group_subfolder   = pval_folder_group_subfolder[1]
                    x__folder_group_subparam    = pval_folder_group_subparam[1]
                    x__folder_run_userunsfolder = get_bool(pval_folder_run_userunsfolder[1])
                    x__folder_run_userunfolder  = get_bool(pval_folder_run_userunfolder[1])
                    x__folder_run_submode       = pval_folder_run_submode[1]
                    x__folder_dft_relpath       = pval_folder_dft_relpath[1]
                    err_flag = (x__folder_group_subparam != "timestamp" && x__folder_group_subparam != "temperature")
                end 
                if err_flag == false 
                    x__folder_dft_abspath = cl_dir
                    if x__folder_dft_relpath != ""
                        xstr = x__folder_dft_relpath
                        while startswith(xstr, "..\\") 
                            xstr = join(SubString(xstr,(length("..\\")+1):length(xstr)), "")
                            while !(endswith(x__folder_dft_abspath, "\\")) && length(x__folder_dft_abspath) > 0
                                x__folder_dft_abspath = join(SubString(x__folder_dft_abspath,1:(length(x__folder_dft_abspath)-1)), "")
                            end
                        end
                        x__folder_dft_abspath = joinpath(x__folder_dft_abspath,xstr)
                    end
                    x__path_cl = cl_dir
                    if x__folder_run_userunsfolder == true 
                        x__path_runs = joinpath(cl_dir,runs_dir)
                        x__path_runs_relativeonly = runs_dir
                    else
                        x__path_runs = cl_dir
                        x__path_runs_relativeonly = ""
                    end
                    x__path_group = x__path_runs
                    if x__folder_group != "" && length(x__folder_group) > 0
                        x__path_group = joinpath(x__path_group,x__folder_group)
                    end
                    err_flag, err_msg, ptype_messages_show, pval_messages_show = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "messages_show"], "value", false, "bool", true, false, "")
                    err_flag, err_msg, ptype_messages_log,  pval_messages_log  = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "messages_log"],  "value", false, "bool", true, false, "")
                    if err_flag == false 
                        x__messages_show = get_bool(pval_messages_show[1]) 
                        x__messages_log  = get_bool(pval_messages_log[1])  
                    end 
                end
            end 

            # Construct object 
            if err_flag == false 
                rs = ct__RxnRun_Logging(x__path_cl, x__path_runs, x__path_runs_relativeonly, x__path_group, x__folder_group, x__folder_group_submode, x__folder_group_subfolder, x__folder_group_subparam, x__folder_run_userunsfolder, x__folder_run_userunfolder, x__folder_run_submode, x__folder_dft_relpath, x__folder_dft_abspath, x__messages_show, x__messages_log) 
            end 
        end 

        return err_flag, err_msg, rs 
    end 

