    function Init__RxnRun__SolverOptions(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults, runs_ode_scalefactors) 
        
        # Check error state 
        rs = ct__RxnRun_SolverOptions() 
        if err_flag == false
            err_flag = false 
            err_msg = "" 

            # Retrieve solver options - timespan
            if err_flag == false 
                x__name = "timespan" 
                err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.time, "string", true, true, "mixed")
                err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 1.0, "Float64", true, false, "") 
                if err_flag == false 
                    err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__units    = pval_units[1] 
                    x__units_si = rxnsystem.physunits.time_si 
                    x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si) 
                    x__timespan = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false) 
                end 
            end 

            # Retrieve solver options - timestops 
            if err_flag == false 
                x__timestops = Array{Float64,1}(undef,0) 
                err_flag, err_msg, ptype_timestops_all, pval_timestops_all = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "timestops"], "value", "", "string", false, true, "mixed")
                if err_flag == false 
                    x__timestops_all = replace(pval_timestops_all[1],"--" => "")
                    x__times_grps = String.(split(x__timestops_all, ",")) 
                    x__times_uary = Array{Float64,1}(undef,0)
                    if size(x__times_grps,1) > 0 
                        for i in axes(x__times_grps,1) 
                            x__times_grps[i] = str_trim(x__times_grps[i]) 
                            x__times_grp = String.(split(x__times_grps[i], ":")) 
                            x__flag = false 
                            if size(x__times_grp,1) == 1 || size(x__times_grp,1) == 3 
                                for j in axes(x__times_grp,1)
                                    x__flag = false 
                                    if tryparse(Float64, replace(x__times_grp[j],"n" => "")) !== nothing 
                                        if tryparse(Float64, replace(x__times_grp[j],"n" => "")) >= 0 && (x__times_grp[j] == replace(x__times_grp[j],"n" => "") || j == 2)
                                            x__flag = true
                                        end 
                                    end
                                    if x__flag == false 
                                        break
                                    end
                                end
                            end
                            if x__flag == true 
                                if size(x__times_grp,1) == 1 
                                    err_flag, err_msg, x__parsed_flag, x__parsed_val_1 = try_parse(err_flag, err_msg, x__times_grp[1], 0.0)
                                    if err_flag == false && x__parsed_flag == true 
                                        push!(x__times_uary,x__parsed_val_1)
                                    end 
                                elseif size(x__times_grp,1) == 3 
                                    if x__times_grp[2] == replace(x__times_grp[2],"n" => "")
                                        err_flag, err_msg, x__parsed_flag, x__parsed_vals = try_parse(err_flag, err_msg, x__times_grp, 0.0)
                                        if err_flag == false && x__parsed_flag == true 
                                            if x__parsed_vals[3] > x__parsed_vals[1] && 0 < x__parsed_vals[2] && x__parsed_vals[2] <= x__parsed_vals[3] - x__parsed_vals[1]
                                                x__ctr = 0
                                                while x__parsed_vals[1] <= x__parsed_vals[1] + x__ctr * x__parsed_vals[2] && x__parsed_vals[1] + x__ctr * x__parsed_vals[2] <= x__parsed_vals[3]
                                                    if x__parsed_vals[1] <= x__parsed_vals[1] + x__ctr * x__parsed_vals[2] && x__parsed_vals[1] + x__ctr * x__parsed_vals[2] <= x__parsed_vals[3]
                                                        push!(x__times_uary,(x__parsed_vals[1] + x__ctr * x__parsed_vals[2]))
                                                    end
                                                    x__ctr = x__ctr + 1
                                                end
                                                push!(x__times_uary,x__parsed_vals[3])
                                            end
                                        end 
                                    else 
                                        err_flag, err_msg, x__parsed_flag_1, x__parsed_val_1 = try_parse(err_flag, err_msg, x__times_grp[1], 0.0)
                                        err_flag, err_msg, x__parsed_flag_2, x__parsed_val_2 = try_parse(err_flag, err_msg, replace(x__times_grp[2],"n" => ""), 0)
                                        err_flag, err_msg, x__parsed_flag_3, x__parsed_val_3 = try_parse(err_flag, err_msg, x__times_grp[3], 0.0)
                                        if err_flag == false && x__parsed_flag_1 == true && x__parsed_flag_2 == true && x__parsed_flag_3 == true 
                                            if x__parsed_val_3 > x__parsed_val_1 && 0 < x__parsed_val_2 
                                                push!(x__times_uary,x__parsed_val_1)
                                                if x__parsed_val_2 > 1
                                                    for j in 1:(x__parsed_val_2 - 1)
                                                        push!(x__times_uary,x__parsed_val_1 + (j / x__parsed_val_2) * (x__parsed_val_3 - x__parsed_val_1))
                                                    end
                                                end
                                                push!(x__times_uary,x__parsed_val_3)
                                            end
                                        end 
                                    end 
                                end
                            end
                        end 
                    end
                    if size(x__times_uary,1) > 0 
                        x__timestops = unique(x__times_uary)
                        sort!(x__timestops)
                    end
                end
            end

            # Retrieve solver options - timepoints
            if err_flag == false 
                x__timepoints = Array{Float64,1}(undef,0)
                err_flag, err_msg, ptype_timepoints_all, pval_timepoints_all = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "timepoints"], "value", "", "string", false, true, "mixed")
                if err_flag == false 
                    x__timepoints_all = replace(pval_timepoints_all[1],"--" => "")
                    x__times_grps = String.(split(x__timepoints_all, ",")) 
                    x__times_uary = Array{Float64,1}(undef,0)
                    if size(x__times_grps,1) > 0 
                        for i in axes(x__times_grps,1) 
                            x__times_grps[i] = str_trim(x__times_grps[i]) 
                            x__times_grp = String.(split(x__times_grps[i], ":")) 
                            x__flag = false 
                            if size(x__times_grp,1) == 1 || size(x__times_grp,1) == 3 
                                for j in axes(x__times_grp,1)
                                    x__flag = false 
                                    if tryparse(Float64, replace(x__times_grp[j],"n" => "")) !== nothing 
                                        if tryparse(Float64, replace(x__times_grp[j],"n" => "")) >= 0 && (x__times_grp[j] == replace(x__times_grp[j],"n" => "") || j == 2)
                                            x__flag = true
                                        end 
                                    end
                                    if x__flag == false 
                                        break
                                    end
                                end
                            end
                            if x__flag == true 
                                if size(x__times_grp,1) == 1 
                                    err_flag, err_msg, x__parsed_flag, x__parsed_val_1 = try_parse(err_flag, err_msg, x__times_grp[1], 0.0)
                                    if err_flag == false && x__parsed_flag == true 
                                        push!(x__times_uary,x__parsed_val_1)
                                    end 
                                elseif size(x__times_grp,1) == 3 
                                    if x__times_grp[2] == replace(x__times_grp[2],"n" => "")
                                        err_flag, err_msg, x__parsed_flag, x__parsed_vals = try_parse(err_flag, err_msg, x__times_grp, 0.0)
                                        if err_flag == false && x__parsed_flag == true 
                                            if x__parsed_vals[3] > x__parsed_vals[1] && 0 < x__parsed_vals[2] && x__parsed_vals[2] <= x__parsed_vals[3] - x__parsed_vals[1]
                                                x__ctr = 0
                                                while x__parsed_vals[1] <= x__parsed_vals[1] + x__ctr * x__parsed_vals[2] && x__parsed_vals[1] + x__ctr * x__parsed_vals[2] <= x__parsed_vals[3]
                                                    if x__parsed_vals[1] <= x__parsed_vals[1] + x__ctr * x__parsed_vals[2] && x__parsed_vals[1] + x__ctr * x__parsed_vals[2] <= x__parsed_vals[3]
                                                        push!(x__times_uary,(x__parsed_vals[1] + x__ctr * x__parsed_vals[2]))
                                                    end
                                                    x__ctr = x__ctr + 1
                                                end
                                                push!(x__times_uary,x__parsed_vals[3])
                                            end
                                        end 
                                    else 
                                        err_flag, err_msg, x__parsed_flag_1, x__parsed_val_1 = try_parse(err_flag, err_msg, x__times_grp[1], 0.0)
                                        err_flag, err_msg, x__parsed_flag_2, x__parsed_val_2 = try_parse(err_flag, err_msg, replace(x__times_grp[2],"n" => ""), 0)
                                        err_flag, err_msg, x__parsed_flag_3, x__parsed_val_3 = try_parse(err_flag, err_msg, x__times_grp[3], 0.0)
                                        if err_flag == false && x__parsed_flag_1 == true && x__parsed_flag_2 == true && x__parsed_flag_3 == true 
                                            if x__parsed_val_3[3] > x__parsed_val_1[1] && 0 < x__parsed_val_2 
                                                push!(x__times_uary,x__parsed_val_1[1])
                                                if x__parsed_val_2 > 1
                                                    for j in 1:(x__parsed_val_2 - 1)
                                                        push!(x__times_uary,x__parsed_val_1[1] + (j / x__parsed_val_2) * (x__parsed_val_3[3] - x__parsed_val_1[1]))
                                                    end 
                                                end 
                                                push!(x__times_uary,x__parsed_val_3[3]) 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                    if size(x__times_uary,1) > 0 
                        x__timepoints = unique(x__times_uary)
                        sort!(x__timepoints)
                    end
                end
            end 

            # Retrieve solver options - solver algorithm
            if err_flag == false 
                err_flag, err_msg, ptype_ode_solver,                pval_ode_solver                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_solver"],                "value", "TRBDF2", "string",  true, true,  "mixed")
                err_flag, err_msg, ptype_ode_maxiters,              pval_ode_maxiters              = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_maxiters"],              "value", 0,        "Int",     true, false, ""     ) 
                err_flag, err_msg, ptype_ode_multi_threaded,        pval_ode_multi_threaded        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_multi_threaded"],        "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_reltol,                pval_ode_reltol                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_reltol"],                "value", 0.001,    "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_ode_abstol,                pval_ode_abstol                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_abstol"],                "value", 0.001,    "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_ode_showtiming_direct,     pval_ode_showtiming_direct     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_showtiming_direct"],     "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_showtiming_solver,     pval_ode_showtiming_solver     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_showtiming_solver"],     "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_showtiming_sens,       pval_ode_showtiming_sens       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_showtiming_sens"],       "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_scaling_uscale_flag,   pval_ode_scaling_uscale_flag   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_uscale_flag"],           "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_scaling_tflag,         pval_ode_scaling_tflag         = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_tscale_flag"],           "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_scaling_tfactor,       pval_ode_scaling_tfactor       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_tscale_factor"],         "value", 1,        "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_ode_include_spcs_g,        pval_ode_include_spcs_g        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_include_spcs_g"],        "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_include_spcs_n,        pval_ode_include_spcs_n        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_include_spcs_n"],        "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_include_rxns_r,        pval_ode_include_rxns_r        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_include_rxns_r"],        "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_krate_gaspress_flag,   pval_ode_krate_gaspress_flag   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_krate_gaspress_flag"],   "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_solpts_interp_flag,    pval_ode_solpts_interp_flag    = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_solpts_interp_flag"],    "value", false,    "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_ode_solpts_interp_mag_min, pval_ode_solpts_interp_mag_min = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_solpts_interp_mag_min"], "value", "",       "string",  true, true,  "mixed")
                err_flag, err_msg, ptype_ode_solpts_interp_mag_max, pval_ode_solpts_interp_mag_max = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_solpts_interp_mag_max"], "value", "",       "string",  true, true,  "mixed")
                err_flag, err_msg, ptype_ode_solpts_interp_pts_min, pval_ode_solpts_interp_pts_min = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_solpts_interp_pts_min"], "value", "",       "string",  true, true,  "mixed")
                err_flag, err_msg, ptype_ode_solpts_interp_pts_max, pval_ode_solpts_interp_pts_max = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_solpts_interp_pts_max"], "value", "",       "string",  true, true,  "mixed")
                if err_flag == false 
                    err_flag, err_msg, x__ode_maxiters        = get_confignumber(err_flag, err_msg, Int,     pval_ode_maxiters[1],        "0", true, true, true, false, true) 
                    err_flag, err_msg, x__ode_reltol          = get_confignumber(err_flag, err_msg, Float64, pval_ode_reltol[1],          "0", true, true, true, true,  true) 
                    err_flag, err_msg, x__ode_abstol          = get_confignumber(err_flag, err_msg, Float64, pval_ode_abstol[1],          "0", true, true, true, true,  true) 
                    err_flag, err_msg, x__ode_scaling_tfactor = get_confignumber(err_flag, err_msg, Float64, pval_ode_scaling_tfactor[1], "0", true, true, true, true,  true) 
                end 
                if err_flag == false 
                    x__ode_solver                   = str_trim(pval_ode_solver[1])
                    x__ode_multi_threaded           = (get_bool(pval_ode_multi_threaded[1]) && Threads.nthreads() > 1) 
                    x__ode_showtiming_direct        = get_bool(pval_ode_showtiming_direct[1])
                    x__ode_showtiming_solver        = get_bool(pval_ode_showtiming_solver[1])
                    x__ode_showtiming_sens          = get_bool(pval_ode_showtiming_sens[1])
                    x__ode_scaling_uscale_flag      = get_bool(pval_ode_scaling_uscale_flag[1])
                    x__ode_scaling_tflag            = get_bool(pval_ode_scaling_tflag[1])
                    x__ode_scaling_tunityflag       = (x__ode_scaling_tfactor == one(x__ode_scaling_tfactor)) 
                    x__ode_include_spcs_g           = get_bool(pval_ode_include_spcs_g[1])
                    x__ode_include_spcs_n           = (get_bool(pval_ode_include_spcs_n[1]) || (x__ode_include_spcs_g == false))
                    x__ode_include_rxns_r           = get_bool(pval_ode_include_rxns_r[1])
                    x__ode_krate_gaspress_flag      = get_bool(pval_ode_krate_gaspress_flag[1])
                    x__ode_solpts_interp_flag       = get_bool(pval_ode_solpts_interp_flag[1])
                    x__ode_solpts_interp_mag_min    = str_trim(pval_ode_solpts_interp_mag_min[1])
                    if x__ode_solpts_interp_mag_min == "--" 
                        x__ode_solpts_interp_mag_min = ""
                    end 
                    if x__ode_solpts_interp_mag_min != "" 
                        err_flag, err_msg, x__parsed_flag, x__parsed_val = try_parse(err_flag, err_msg, x__ode_solpts_interp_mag_min, 0)
                        if x__parsed_flag == false 
                            err_flag = true 
                        end 
                    end 
                    x__ode_solpts_interp_mag_max    = str_trim(pval_ode_solpts_interp_mag_max[1])
                    if x__ode_solpts_interp_mag_max == "--" 
                        x__ode_solpts_interp_mag_max = ""
                    end 
                    if x__ode_solpts_interp_mag_max != "" 
                        err_flag, err_msg, x__parsed_flag, x__parsed_val = try_parse(err_flag, err_msg, x__ode_solpts_interp_mag_max, 0)
                        if x__parsed_flag == false 
                            err_flag = true 
                        end 
                    end 
                    x__ode_solpts_interp_pts_min    = str_trim(pval_ode_solpts_interp_pts_min[1])
                    if x__ode_solpts_interp_pts_min == "--" 
                        x__ode_solpts_interp_pts_min = ""
                    end 
                    if x__ode_solpts_interp_pts_min != "" 
                        err_flag, err_msg, x__parsed_flag, x__parsed_val = try_parse(err_flag, err_msg, x__ode_solpts_interp_pts_min, 0)
                        if x__parsed_flag == false 
                            err_flag = true 
                        end 
                    end 
                    x__ode_solpts_interp_pts_max    = str_trim(pval_ode_solpts_interp_pts_max[1])
                    if x__ode_solpts_interp_pts_max == "--" 
                        x__ode_solpts_interp_pts_max = ""
                    end 
                    if x__ode_solpts_interp_pts_max != "" 
                        err_flag, err_msg, x__parsed_flag, x__parsed_val = try_parse(err_flag, err_msg, x__ode_solpts_interp_pts_max, 0)
                        if x__parsed_flag == false 
                            err_flag = true 
                        end 
                    end 
                end 
                if err_flag == false 
                    x__name = "ode_ref_pressure"
                    err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.pressure, "string", true, true, "mixed")
                    err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 1.0, "Float64", true, false, "")
                    if err_flag == false 
                        err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                    end 
                    if err_flag == false 
                        x__units    = pval_units[1] 
                        x__units_si = rxnsystem.physunits.pressure_si
                        x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si)
                        x__ode_ref_pressure = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false)
                        x__ode_ref_pressure_pa = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, "Pa")
                    end
                end 
                if err_flag == false 
                    x__name = "ode_ref_coverage"
                    err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.coverage, "string", true, true, "mixed")
                    err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 1.0, "Float64", true, false, "")
                    if err_flag == false 
                        err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                    end 
                    if err_flag == false 
                        x__units    = pval_units[1] 
                        x__units_si = rxnsystem.physunits.coverage_si
                        x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si)
                        x__ode_ref_coverage = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false)
                    end
                end 
            end 

            # Retrieve solver options - scaling factors 
            if err_flag == false 
                x__ode_scaling_uscale_unityflags = fill(true,rxnsystem.odespecies.cnt) 
                x__ode_scaling_uscale_factors    = fill(1.0,rxnsystem.odespecies.cnt) 
                if x__ode_scaling_uscale_flag == true 
                    for i in axes(runs_ode_scalefactors,1)
                        if haskey(runs_ode_scalefactors[i].vals, "run") && haskey(runs_ode_scalefactors[i].vals, "compound") && haskey(runs_ode_scalefactors[i].vals, "u_scale") 
                            if runs_ode_scalefactors[i].vals["run"] !== nothing && runs_ode_scalefactors[i].vals["compound"] !== nothing && runs_ode_scalefactors[i].vals["u_scale"] !== nothing 
                                if runs_ode_scalefactors[i].vals["run"] == rxnrun_name && length(runs_ode_scalefactors[i].vals["compound"]) > 0 && tryparse(Float64, runs_ode_scalefactors[i].vals["u_scale"]) !== nothing 
                                    if get_elemindex(rxnsystem.odespecies.names,runs_ode_scalefactors[i].vals["compound"],0) > 0 || get_elemindex(rxnsystem.odespecies.compounds,runs_ode_scalefactors[i].vals["compound"],0) > 0 
                                        err_flag, err_msg, ptype_uscale, pval_uscale = get_configproperty(err_flag, err_msg, runs_ode_scalefactors[i].vals, nothing, "", "u_scale", "", "", "float64", false, true, "mixed")
                                        if err_flag == false 
                                            err_flag, err_msg, x__uscale = get_confignumber(err_flag, err_msg, Float64, pval_uscale[1], "1", true, true, true, false, true) 
                                        end 
                                        if err_flag == false 
                                            x__cmpd_name = str_trim(runs_ode_scalefactors[i].vals["compound"])
                                            for j in 1:rxnsystem.odespecies.cnt 
                                                if x__cmpd_name == rxnsystem.odespecies.names[j] || x__cmpd_name == rxnsystem.odespecies.compounds[j]
                                                    x__ode_scaling_uscale_factors[j] = x__uscale 
                                                end 
                                            end 
                                        end 
                                    end 
                                end
                            end
                        end
                    end 
                    x__ode_scaling_uscale_flag = false 
                    for i in 1:rxnsystem.odespecies.cnt 
                        if x__ode_scaling_uscale_factors[i] != one(x__ode_scaling_uscale_factors[i])
                            x__ode_scaling_uscale_flag = true 
                            x__ode_scaling_uscale_unityflags[i] = false 
                        end 
                    end 
                end 
            end 

            # Retrieve solver options - numerics
            if err_flag == false 
                err_flag, err_msg, ptype_ode_num_fmt_str, pval_ode_num_fmt_str = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_num_fmt" ], "value", "Float64", "string", true, true,  "mixed") 
                err_flag, err_msg, ptype_ode_num_prec,    pval_ode_num_prec    = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "ode_num_prec"], "value", 0,         "Int",    true, false, ""     ) 
                if err_flag == false 
                    err_flag, err_msg, x__ode_num_prec = get_confignumber(err_flag, err_msg, Int, pval_ode_num_prec[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__ode_num_fmt_str = pval_ode_num_fmt_str[1]
                    numformat = lowercase(str_trim(x__ode_num_fmt_str))
                    if numformat == "bigfloat"
                        x__ode_num_fmt_str = "BigFloat"
                        x__ode_num_fmt_class = "bigfloat" 
                    elseif numformat == "double64"
                        x__ode_num_fmt_str = "Double64"
                        x__ode_num_fmt_class = "double64"
                    else
                        x__ode_num_fmt_str = "Float64"
                        x__ode_num_fmt_class = "float64"
                    end
                end
                if err_flag == false 
                    x__ode_num_fmt_types = Dict{String,Type}() 
                    x__ode_num_fmt_types["BigFloat"] = BigFloat 
                    if x__ode_num_fmt_str == "BigFloat" 
                        if x__ode_num_prec > 0 
                            x__ode_num_fmt_types["BigFloat"] = typeof(BigFloat(string("0"), precision=round(Int, x__ode_num_prec))) 
                        else
                            x__ode_num_fmt_types["BigFloat"] = typeof(BigFloat(string("0"))) 
                        end 
                    end 
                    x__ode_num_fmt_types["Double64"] = DoubleFloats.Double64 
                    x__ode_num_fmt_types["Float64"]  = Float64 
                end 
            end
        
            # Retrieve solver options - turnover frequency
            if err_flag == false 
                err_flag, err_msg, ptype_tof_basis_type,  pval_tof_basis_type  = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "tof_basis_type"],  "value", "reactants", "string", true, true, "mixed")
                err_flag, err_msg, ptype_tof_basis_names, pval_tof_basis_names = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "tof_basis_names"], "value", "",          "string", true, true, "mixed")
                if err_flag == false 
                    x__tof_basis_type   = pval_tof_basis_type[1] 
                    x__tof_basis_names  = Array{String,1}(undef,0) 
                    x__tof_basis_counts = Dict{String,Float64}() 
                    x__tof_basis_all    = ""
                    x__ary = split(pval_tof_basis_names[1], ",") 
                    for i in axes(x__ary,1)
                        if x__ary[i] !== nothing
                            x__ary[i] = join(x__ary[i], "")
                            if x__ary[i] != "" 
                                x__count, x__name = get_multiplier(join(x__ary[i], ""))
                                if x__count > 0 && x__name != "" 
                                    if haskey(x__tof_basis_counts,x__name) == false 
                                        push!(x__tof_basis_names,x__name) 
                                        x__tof_basis_counts[x__name] = 0.0
                                    end 
                                    x__tof_basis_counts[x__name] = x__tof_basis_counts[x__name] + x__count
                                end 
                            end 
                        end 
                    end 
                    for i in axes(x__tof_basis_names,1)
                        x__factor = x__tof_basis_counts[x__tof_basis_names[i]]
                        if x__factor > 0 
                            x__factor_s = string(x__factor)
                            if x__factor == 1
                                x__factor_s = "" 
                            elseif isinteger(x__factor) == true
                                x__factor_s = string(get_trunc(x__factor))
                            end
                            x__tof_basis_all = string(x__tof_basis_all,(length(x__tof_basis_all) > 0 ? ", " : ""),x__factor_s,x__tof_basis_names[i])
                        end
                    end 
                end
            end

            # Retrieve solver options - interpolation 
            if err_flag == false 
                err_flag, err_msg, ptype_interp_callbackmode,            pval_interp_callbackmode            = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_callbackmode"           ], "value", "discrete",     "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_cmpds,                   pval_interp_cmpds                   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_compounds"              ], "value", "<all>",        "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_updmode_ode,             pval_interp_updmode_ode             = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_updmode_ode"            ], "value", "",             "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_updmode_spectator_major, pval_interp_updmode_spectator_major = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_updmode_spectator_major"], "value", "",             "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_updmode_spectator_minor, pval_interp_updmode_spectator_minor = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_updmode_spectator_minor"], "value", "",             "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_updts_covsmode,          pval_interp_updts_covsmode          = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_updts_covsmode"         ], "value", "",             "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_calcsrf_usejacflag,      pval_interp_calcsrf_usejacflag      = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_calcsrf_usejacflag"     ], "value", false,          "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_interp_diffcovs_stepcnt,        pval_interp_diffcovs_stepcnt        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_diffcovs_stepcnt"       ], "value", 0,              "Int",     true, false, ""     ) 
                err_flag, err_msg, ptype_interp_desorb_method,           pval_interp_desorb_method           = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_desorb_method"          ], "value", "tst",          "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_uchg_tol,                pval_interp_uchg_tol                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_uchg_tol"               ], "value", 0.001,          "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_interp_Gchg_tol,                pval_interp_Gchg_tol                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_Gchg_tol"               ], "value", 0.001,          "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_interp_Gadschg_tol,             pval_interp_Gadschg_tol             = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_Gadschg_tol"            ], "value", 0.001,          "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_interp_kchg_tol,                pval_interp_kchg_tol                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_kchg_tol"               ], "value", 0.001,          "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_interp_rbf_power,               pval_interp_rbf_power               = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_rbf_power"              ], "value", 0,              "Int",     true, false, ""     ) 
                err_flag, err_msg, ptype_interp_rbf_includepolynomial,   pval_interp_rbf_includepolynomial   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_rbf_includepolynomial"  ], "value", false,          "bool",    true, false, ""     ) 
                err_flag, err_msg, ptype_interp_rbf_name,                pval_interp_rbf_name                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_rbf_name"               ], "value", "polyharmonic", "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_rbf_shapeparam,          pval_interp_rbf_shapeparam          = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_rbf_shapeparam"         ], "value", 0.001,          "Float64", true, false, ""     ) 
                err_flag, err_msg, ptype_interp_desorb_method,           pval_interp_desorb_method           = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_desorb_method"          ], "value", "tst",          "string",  true, true,  "mixed") 
                err_flag, err_msg, ptype_interp_reftst_cmpds,            pval_interp_reftst_cmpds            = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "interp_reftst_compounds"       ], "value", "",             "string",  true, true,  "mixed") 
                if err_flag == false 
                    err_flag, err_msg, x__interp_diffcovs_stepcnt = get_confignumber(err_flag, err_msg, Int,     pval_interp_diffcovs_stepcnt[1], "0", true, true, true, false, true) 
                    err_flag, err_msg, x__interp_uchg_tol         = get_confignumber(err_flag, err_msg, Float64, pval_interp_uchg_tol[1],         "0", true, true, true, false, true) 
                    err_flag, err_msg, x__interp_Gchg_tol         = get_confignumber(err_flag, err_msg, Float64, pval_interp_Gchg_tol[1],         "0", true, true, true, false, true) 
                    err_flag, err_msg, x__interp_Gadschg_tol      = get_confignumber(err_flag, err_msg, Float64, pval_interp_Gadschg_tol[1],      "0", true, true, true, false, true) 
                    err_flag, err_msg, x__interp_kchg_tol         = get_confignumber(err_flag, err_msg, Float64, pval_interp_kchg_tol[1],         "0", true, true, true, false, true) 
                    err_flag, err_msg, x__interp_rbf_power        = get_confignumber(err_flag, err_msg, Int,     pval_interp_rbf_power[1],        "0", true, true, true, false, true) 
                    err_flag, err_msg, x__interp_rbf_shapeparam   = get_confignumber(err_flag, err_msg, Int,     pval_interp_rbf_shapeparam[1],   "0", true, true, true, false, true) 
                    err_flag = (err_flag || x__interp_uchg_tol < 0 || x__interp_Gchg_tol < 0 || x__interp_Gadschg_tol < 0 || x__interp_kchg_tol < 0)
                end 
                if err_flag == false 
                    x__interp_callbackmode = str_trim(pval_interp_callbackmode[1])
                    x__cmpds_str = str_trim(pval_interp_cmpds[1]) 
                    x__interp_cmpds_all_flag = false 
                    x__interp_cmpds_names = Array{String,1}(undef,0)
                    x__interp_cmpds_phases = Array{String,1}(undef,0)
                    x__interp_cmpds_compounds = Array{String,1}(undef,0)
                    x__interp_cmpds_odeindxs = Array{Int,1}(undef,0)
                    x__interp_cmpds_stateindxs = Array{Int,1}(undef,0)
                    if length(x__cmpds_str) > 0 
                        if x__cmpds_str != "<all>" && x__cmpds_str != "--" 
                            x__cmpds_ary = split(x__cmpds_str, ",") 
                            for i in axes(x__cmpds_ary,1)
                                x__cmpds_ary[i] = str_trim(join(x__cmpds_ary[i],"")) 
                                x__phase_indx = 0
                                x__cmpd_name = "" 
                                if 0 < get_substrindex(x__cmpds_ary[i],"<","first") && get_substrindex(x__cmpds_ary[i],"<","first") + 1 < get_substrindex(x__cmpds_ary[i],">","first")
                                    x__phs_name = str_trim(str_cut(str_trim(str_cut(x__cmpds_ary[i], "right", "<", "delete")), "left", ">", "delete")) 
                                    if length(x__phs_name) > 0 
                                        x__phase_indx = get_elemindex(rxnsystem.phases.phases_names,x__phs_name,0)
                                    end 
                                end 
                                if x__phase_indx > 0 
                                    x__cmpd_name = str_trim(join(str_trim(str_cut(x__cmpds_ary[i], "right", ">", "delete")),""))
                                    x__phase_indxs = Array{Int,1}(undef,0)
                                    push!(x__phase_indxs,x__phase_indx)
                                else 
                                    x__cmpd_name = str_trim(join(x__cmpds_ary[i],""))
                                    x__phase_indxs = get_view(collect(1:size(rxnsystem.phases.phases_names,1)))
                                end 
                                for j in axes(x__phase_indxs,1)
                                    x__state_name = string("<",rxnsystem.phases.phases_names[x__phase_indxs[j]],"> ",x__cmpd_name) 
                                    x__state_index = get_elemindex(rxnsystem.configurations.states_names,x__state_name,0)
                                    if haskey(rxnsystem.odespecies.dindxs,x__state_name) && x__state_index > 0 
                                        x__odeindex = rxnsystem.odespecies.dindxs[x__state_name]
                                        if x__odeindex > 0 && get_elemindex(rxnsystem.odespecies.indxs_nongas,x__odeindex,0) > 0 
                                            push!(x__interp_cmpds_names,x__state_name)
                                            push!(x__interp_cmpds_phases,rxnsystem.phases.phases_names[x__phase_indxs[j]])
                                            push!(x__interp_cmpds_compounds,x__cmpd_name)
                                            push!(x__interp_cmpds_odeindxs,x__odeindex)
                                            push!(x__interp_cmpds_stateindxs,x__state_index)
                                        end 
                                    end 
                                end 
                            end 
                        else 
                            x__interp_cmpds_all_flag = true 
                            x__interp_cmpds_names = get_view(view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_adscoads))
                            x__interp_cmpds_phases = get_view(view(rxnsystem.odespecies.phases,rxnsystem.odespecies.indxs_adscoads))
                            x__interp_cmpds_compounds = get_view(view(rxnsystem.odespecies.compounds,rxnsystem.odespecies.indxs_adscoads))
                            x__interp_cmpds_odeindxs = collect(1:size(rxnsystem.odespecies.indxs_adscoads,1))
                            x__interp_cmpds_stateindxs = get_elemindex(rxnsystem.configurations.states_names,view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_adscoads),0)
                        end 
                    end 
                    x__interp_cmpds_dindxs = Dict{String,Int}() 
                    for i in axes(x__interp_cmpds_names,1)
                        x__interp_cmpds_dindxs[x__interp_cmpds_names[i]] = i
                    end 
                    x__interp_cmpds_cnt               = size(x__interp_cmpds_names,1) 
                    x__interp_updmode_ode             = str_trim(pval_interp_updmode_ode[1]) 
                    x__interp_updmode_spectator_major = str_trim(pval_interp_updmode_spectator_major[1]) 
                    x__interp_updmode_spectator_minor = str_trim(pval_interp_updmode_spectator_minor[1]) 
                    x__interp_updts_covsmode          = str_trim(pval_interp_updts_covsmode[1]) 
                    x__interp_calcsrf_usejacflag      = get_bool(pval_interp_calcsrf_usejacflag[1]) 
                    x__interp_rbf_includepolynomial   = get_bool(pval_interp_rbf_includepolynomial[1]) 
                    x__interp_rbf_name  = str_trim(pval_interp_rbf_name[1])
                    x__interp_desorb_method  = str_trim(pval_interp_desorb_method[1])
                    x__reftst_cmpds_str = str_trim(pval_interp_reftst_cmpds[1])
                    if x__reftst_cmpds_str != "<all>" && length(x__reftst_cmpds_str) > 0 
                        x__interp_reftst_cmpds_all_flag = false 
                        x__interp_reftst_cmpds_names = Array{String,1}(undef,0)
                        x__interp_reftst_cmpds_phases = Array{String,1}(undef,0)
                        x__interp_reftst_cmpds_compounds = Array{String,1}(undef,0)
                        x__interp_reftst_cmpds_odeindxs = Array{Int,1}(undef,0)
                        x__interp_reftst_cmpds_stateindxs = Array{Int,1}(undef,0)
                        x__reftst_cmpds_ary = split(x__reftst_cmpds_str, ",") 
                        for i in axes(x__reftst_cmpds_ary,1)
                            x__reftst_cmpds_ary[i] = str_trim(join(x__reftst_cmpds_ary[i],"")) 
                            x__phase_indx = 0
                            x__cmpd_name = "" 
                            if 0 < get_substrindex(x__reftst_cmpds_ary[i],"<","first") && get_substrindex(x__reftst_cmpds_ary[i],"<","first") + 1 < get_substrindex(x__reftst_cmpds_ary[i],">","first")
                                x__phs_name = str_trim(str_cut(str_trim(str_cut(x__reftst_cmpds_ary[i], "right", "<", "delete")), "left", ">", "delete")) 
                                if length(x__phs_name) > 0 
                                    x__phase_indx = get_elemindex(rxnsystem.phases.phases_names,x__phs_name,0)
                                end 
                            end 
                            if x__phase_indx > 0 
                                x__cmpd_name = str_trim(join(str_trim(str_cut(x__reftst_cmpds_ary[i], "right", ">", "delete")),""))
                                x__phase_indxs = Array{Int,1}(undef,0)
                                push!(x__phase_indxs,x__phase_indx)
                            else 
                                x__cmpd_name = str_trim(join(x__reftst_cmpds_ary[i],""))
                                x__phase_indxs = get_view(collect(1:size(rxnsystem.phases.phases_names,1)))
                            end 
                            for j in axes(x__phase_indxs,1)
                                x__state_name = string("<",rxnsystem.phases.phases_names[x__phase_indxs[j]],"> ",x__cmpd_name) 
                                x__state_index = get_elemindex(rxnsystem.configurations.states_names,x__state_name,0)
                                if haskey(rxnsystem.odespecies.dindxs,x__state_name) && x__state_index > 0 
                                    x__odeindex = rxnsystem.odespecies.dindxs[x__state_name]
                                    if x__odeindex > 0 && get_elemindex(rxnsystem.odespecies.indxs_nongas,x__odeindex,0) > 0 
                                        push!(x__interp_reftst_cmpds_names,x__state_name)
                                        push!(x__interp_reftst_cmpds_phases,rxnsystem.phases.phases_names[x__phase_indxs[j]])
                                        push!(x__interp_reftst_cmpds_compounds,x__cmpd_name)
                                        push!(x__interp_reftst_cmpds_odeindxs,x__odeindex)
                                        push!(x__interp_reftst_cmpds_stateindxs,x__state_index)
                                    end 
                                end 
                            end 
                        end 
                    else 
                        x__interp_reftst_cmpds_all_flag   = false
                        x__interp_reftst_cmpds_names      = Array{String,1}(undef,0) 
                        x__interp_reftst_cmpds_phases     = Array{String,1}(undef,0) 
                        x__interp_reftst_cmpds_compounds  = Array{String,1}(undef,0) 
                        x__interp_reftst_cmpds_odeindxs   = Array{Int,1}(undef,0) 
                        x__interp_reftst_cmpds_stateindxs = Array{Int,1}(undef,0) 
                    end 
                    x__interp_reftst_cmpds_dindxs = Dict{String,Int}() 
                    for i in axes(x__interp_reftst_cmpds_names,1)
                        x__interp_reftst_cmpds_dindxs[x__interp_reftst_cmpds_names[i]] = i
                    end 
                    x__interp_reftst_cmpds_cnt = size(x__interp_reftst_cmpds_names,1) 
                end 
            end 

            # Construct object 
            if err_flag == false 
                rs = ct__RxnRun_SolverOptions(
                            x__timespan, x__timestops, x__timestops_all, x__timepoints, x__timepoints_all, 
                            x__ode_solver, x__ode_maxiters, x__ode_reltol, x__ode_abstol, x__ode_num_fmt_types, x__ode_num_fmt_str, x__ode_num_fmt_class, x__ode_num_prec, x__ode_multi_threaded, 
                            x__ode_ref_pressure, x__ode_ref_pressure_pa, x__ode_ref_coverage, 
                            x__ode_showtiming_direct, x__ode_showtiming_solver, x__ode_showtiming_sens, 
                            x__ode_scaling_uscale_flag, x__ode_scaling_uscale_unityflags, x__ode_scaling_uscale_factors, x__ode_scaling_tflag, x__ode_scaling_tunityflag, x__ode_scaling_tfactor, 
                            x__ode_include_spcs_g, x__ode_include_spcs_n, x__ode_include_rxns_r, x__ode_krate_gaspress_flag, 
                            x__ode_solpts_interp_flag, x__ode_solpts_interp_mag_min, x__ode_solpts_interp_mag_max, x__ode_solpts_interp_pts_min, x__ode_solpts_interp_pts_max, 
                            x__tof_basis_type, x__tof_basis_names, x__tof_basis_counts, x__tof_basis_all, 
                            x__interp_callbackmode, x__interp_cmpds_cnt, x__interp_cmpds_dindxs, x__interp_cmpds_names, x__interp_cmpds_phases, x__interp_cmpds_compounds, x__interp_cmpds_odeindxs, x__interp_cmpds_stateindxs, x__interp_cmpds_all_flag, 
                            x__interp_updmode_ode, x__interp_updmode_spectator_major, x__interp_updmode_spectator_minor, x__interp_updts_covsmode, x__interp_calcsrf_usejacflag, x__interp_diffcovs_stepcnt, 
                            x__interp_uchg_tol, x__interp_Gchg_tol, x__interp_Gadschg_tol, x__interp_kchg_tol, 
                            x__interp_rbf_power, x__interp_rbf_includepolynomial, x__interp_rbf_name, x__interp_rbf_shapeparam, x__interp_desorb_method, 
                            x__interp_reftst_cmpds_cnt, x__interp_reftst_cmpds_dindxs, x__interp_reftst_cmpds_names, x__interp_reftst_cmpds_phases, x__interp_reftst_cmpds_compounds, x__interp_reftst_cmpds_odeindxs, x__interp_reftst_cmpds_stateindxs
                        )
            end 
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__RxnRun__StableStateOptions(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults) 
        
        # Check error state 
        rs = ct__RxnRun_StableStateOptions() 
        if err_flag == false
            err_flag = false 
            err_msg = "" 

            # Retrieve stable state options - timespan 
            if err_flag == false 
                err_flag, err_msg, ptype_analyze,                pval_analyze                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sbs_analyze"],                "value", false, "bool",    true, false, "") 
                err_flag, err_msg, ptype_timespan_extend,        pval_timespan_extend        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sbs_timespan_extend"],        "value", false, "bool",    true, false, "") 
                err_flag, err_msg, ptype_timespan_extend_factor, pval_timespan_extend_factor = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sbs_timespan_extend_factor"], "value", 2.0,   "Float64", true, false, "") 
                err_flag, err_msg, ptype_timespan_extend_maxchg, pval_timespan_extend_maxchg = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sbs_timespan_extend_maxchg"], "value", 1.1,   "Float64", true, false, "") 
                err_flag, err_msg, ptype_timespan_extend_cntmax, pval_timespan_extend_cntmax = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sbs_timespan_extend_cntmax"], "value", 1,     "Int",     true, false, "") 
                if err_flag == false 
                    err_flag, err_msg, x__timespan_extend_factor = get_confignumber(err_flag, err_msg, Float64, pval_timespan_extend_factor[1], "0", true, true, true, false, true) 
                    err_flag, err_msg, x__timespan_extend_maxchg = get_confignumber(err_flag, err_msg, Float64, pval_timespan_extend_maxchg[1], "0", true, true, true, false, true) 
                    err_flag, err_msg, x__timespan_extend_cntmax = get_confignumber(err_flag, err_msg, Int,     pval_timespan_extend_cntmax[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__analyze                = get_bool(pval_analyze[1]) 
                    x__timespan_extend        = get_bool(pval_timespan_extend[1]) 
                    x__timespan_extend_maxchg = max(x__timespan_extend_maxchg,1.0) 
                end 
            end 

            # Retrieve stable state options - before onset 
            if err_flag == false 
