                err_flag, err_msg, ptype_analyze,                pval_analyze                = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_analyze"],                "value", false, "bool",    true, false, "") 
                err_flag, err_msg, ptype_timespan_extend,        pval_timespan_extend        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_timespan_extend"],        "value", false, "bool",    true, false, "") 
                err_flag, err_msg, ptype_timespan_extend_factor, pval_timespan_extend_factor = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_timespan_extend_factor"], "value", 2.0,   "Float64", true, false, "") 
                err_flag, err_msg, ptype_timespan_extend_maxchg, pval_timespan_extend_maxchg = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_timespan_extend_maxchg"], "value", 1.1,   "Float64", true, false, "") 
                err_flag, err_msg, ptype_timespan_extend_cntmax, pval_timespan_extend_cntmax = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_timespan_extend_cntmax"], "value", 1,     "Int",     true, false, "") 
                if err_flag == false 
                    err_flag, err_msg, x__timespan_extend_factor = get_confignumber(err_flag, err_msg, Float64, pval_timespan_extend_factor[1], "0", true, true, true, false, true) 
                    err_flag, err_msg, x__timespan_extend_maxchg = get_confignumber(err_flag, err_msg, Float64, pval_timespan_extend_maxchg[1], "0", true, true, true, false, true) 
                    err_flag, err_msg, x__timespan_extend_cntmax = get_confignumber(err_flag, err_msg, Int,     pval_timespan_extend_cntmax[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__analyze                = get_bool(pval_analyze[1]) 
                    x__timespan_extend        = get_bool(pval_timespan_extend[1]) 
                    x__timespan_extend_maxchg = max(x__timespan_extend_maxchg,1.0) 
                end 
            end 

            # Retrieve single pathway state options - before onset 
            if err_flag == false 
                err_flag, err_msg, ptype_mintime_beforeonset_fracofmax, pval_mintime_beforeonset_fracofmax = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_mintime_beforeonset_fracofmax"], "value", 0.0, "Float64", true, false, "")
                if err_flag == false 
                    err_flag, err_msg, x__mintime_beforeonset_fracofmax = get_confignumber(err_flag, err_msg, Float64, pval_mintime_beforeonset_fracofmax[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__name = "sps_mintime_beforeonset_interval"
                    err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.time, "string", true, true, "mixed")
                    err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 0.1, "Float64", true, false, "")
                    if err_flag == false 
                        err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                    end 
                    if err_flag == false 
                        x__units    = pval_units[1] 
                        x__units_si = rxnsystem.physunits.time_si
                        x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si)
                        x__mintime_beforeonset_interval = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false)
                    end 
                end 
            end 

            # Retrieve single pathway state options - after onset 
            if err_flag == false 
                err_flag, err_msg, ptype_mintime_afteronset_fracofmax, pval_mintime_afteronset_fracofmax = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_mintime_afteronset_fracofmax"], "value", 0.0, "Float64", true, false, "")
                if err_flag == false 
                    err_flag, err_msg, x__mintime_afteronset_fracofmax = get_confignumber(err_flag, err_msg, Float64, pval_mintime_afteronset_fracofmax[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__name = "sps_mintime_afteronset_interval_min"
                    err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.time, "string", true, true, "mixed")
                    err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 0.0, "Float64", true, false, "")
                    if err_flag == false 
                        err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                    end 
                    if err_flag == false 
                        x__units    = pval_units[1] 
                        x__units_si = rxnsystem.physunits.time_si
                        x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si)
                        x__mintime_afteronset_interval_min = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false)
                    end 
                end 
                if err_flag == false 
                    x__name = "sps_mintime_afteronset_interval_suf"
                    err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.time, "string", true, true, "mixed")
                    err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 0.0, "Float64", true, false, "")
                    if err_flag == false 
                        err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                    end 
                    if err_flag == false 
                        x__units    = pval_units[1] 
                        x__units_si = rxnsystem.physunits.time_si
                        x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si)
                        x__mintime_afteronset_interval_suf = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false)
                    end 
                end 
            end 

            # Retrieve single pathway state options - onset offset 
            if err_flag == false 
                err_flag, err_msg, ptype_onsetoffset_fracofmax, pval_onsetoffset_fracofmax = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_onsetoffset_fracofmax"], "value", 0.0, "Float64", true, false, "")
                if err_flag == false 
                    err_flag, err_msg, x__onsetoffset_fracofmax = get_confignumber(err_flag, err_msg, Float64, pval_onsetoffset_fracofmax[1], "0", true, true, true, false, true) 
                end 
                if err_flag == false 
                    x__name = "sps_onsetoffset_interval"
                    err_flag, err_msg, ptype_units, pval_units = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "units", rxnsystem.physunits.time, "string", true, true, "mixed")
                    err_flag, err_msg, ptype_value, pval_value = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, x__name], "value", 0.0, "Float64", true, false, "")
                    if err_flag == false 
                        err_flag, err_msg, x__value = get_confignumber(err_flag, err_msg, Float64, pval_value[1], "0", true, true, true, false, true) 
                    end 
                    if err_flag == false 
                        x__units    = pval_units[1] 
                        x__units_si = rxnsystem.physunits.time_si
                        x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si) 
                        x__onsetoffset_interval = ct__SFloat64(x__name, x__value, x__value_si, false, x__units, x__units_si, false) 
                    end 
                end 
            end 

            # Retrieve single pathway state options - threshold values 
            if err_flag == false 
                err_flag, err_msg, ptype_drcs_abstol_curr,        pval_drcs_abstol_curr        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_drcs_abstol_curr"],        "value", 0.0, "Float64", true, false, "")
                err_flag, err_msg, ptype_drcs_abstol_rmdr,        pval_drcs_abstol_rmdr        = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_drcs_abstol_rmdr"],        "value", 0.0, "Float64", true, false, "")
                err_flag, err_msg, ptype_drcs_fractol_curr,       pval_drcs_fractol_curr       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_drcs_fractol_curr"],       "value", 0.0, "Float64", true, false, "")
                err_flag, err_msg, ptype_drcs_fractol_rmdr,       pval_drcs_fractol_rmdr       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_drcs_fractol_rmdr"],       "value", 0.0, "Float64", true, false, "")
                err_flag, err_msg, ptype_drcs_kineticsumerr_curr, pval_drcs_kineticsumerr_curr = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_drcs_kineticsumerr_curr"], "value", 0.0, "Float64", true, false, "")
                err_flag, err_msg, ptype_drcs_kineticsumerr_rmdr, pval_drcs_kineticsumerr_rmdr = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "sps_drcs_kineticsumerr_rmdr"], "value", 0.0, "Float64", true, false, "")
                if err_flag == false 
                    err_flag, err_msg, x__drcs_abstol_curr        = get_confignumber(err_flag, err_msg, Float64, pval_drcs_abstol_curr[1],        "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drcs_abstol_rmdr        = get_confignumber(err_flag, err_msg, Float64, pval_drcs_abstol_rmdr[1],        "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drcs_fractol_curr       = get_confignumber(err_flag, err_msg, Float64, pval_drcs_fractol_curr[1],       "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drcs_fractol_rmdr       = get_confignumber(err_flag, err_msg, Float64, pval_drcs_fractol_rmdr[1],       "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drcs_kineticsumerr_curr = get_confignumber(err_flag, err_msg, Float64, pval_drcs_kineticsumerr_curr[1], "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drcs_kineticsumerr_rmdr = get_confignumber(err_flag, err_msg, Float64, pval_drcs_kineticsumerr_rmdr[1], "0", true, true, true, false, true) 
                end 
            end

            # Construct object 
            if err_flag == false 
                rs = ct__RxnRun_SinglePathwayStateOptions(
                            x__analyze, x__timespan_extend, x__timespan_extend_factor, x__timespan_extend_maxchg, x__timespan_extend_cntmax, 
                            x__mintime_beforeonset_fracofmax, x__mintime_beforeonset_interval, 
                            x__mintime_afteronset_fracofmax, x__mintime_afteronset_interval_min, x__mintime_afteronset_interval_suf, 
                            x__onsetoffset_fracofmax, x__onsetoffset_interval, 
                            x__drcs_abstol_curr, x__drcs_abstol_rmdr, x__drcs_fractol_curr, x__drcs_fractol_rmdr, x__drcs_kineticsumerr_curr, x__drcs_kineticsumerr_rmdr
                        ) 
            end 
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__RxnRun__SensitivityOptions(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun_name, runs_options, runs_defaults, runs_drc_species, runs_dsc_pairs) 
        
        # Check error state 
        rs = ct__RxnRun_SensitivityOptions() 
        if err_flag == false
            err_flag = false 
            err_msg = "" 

            # Retrieve sensitivity options - general
            if err_flag == false 
                err_flag, err_msg, ptype_analyze,            pval_analyze            = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_analyze"],            "value", false, "bool", true, false, "")
                err_flag, err_msg, ptype_ode_include_spcs_g, pval_ode_include_spcs_g = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_ode_include_spcs_g"], "value", false, "bool", true, false, "") 
                err_flag, err_msg, ptype_ode_include_spcs_n, pval_ode_include_spcs_n = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_ode_include_spcs_n"], "value", false, "bool", true, false, "") 
                err_flag, err_msg, ptype_ode_include_rxns_r, pval_ode_include_rxns_r = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_ode_include_rxns_r"], "value", false, "bool", true, false, "") 
                if err_flag == false 
                    x__analyze            = get_bool(pval_analyze[1])
                    x__ode_include_spcs_g = get_bool(pval_ode_include_spcs_g[1])
                    x__ode_include_spcs_n = (get_bool(pval_ode_include_spcs_n[1]) || (x__ode_include_spcs_g == false))
                    x__ode_include_rxns_r = get_bool(pval_ode_include_rxns_r[1])
                end 
            end
            
            # Retrieve sensitivity options - fractions perturbations
            if err_flag == false 
                err_flag, err_msg, ptype_drc_fractions_setsize,   pval_drc_fractions_setsize   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_fractions_setsize"],     "value", 0,     "Int",  true, false, "")
                err_flag, err_msg, ptype_drc_fractions_chunksize, pval_drc_fractions_chunksize = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_fractions_chunksize"],   "value", 0,     "Int",  true, false, "")
                err_flag, err_msg, ptype_drc_fractions_gas,       pval_drc_fractions_gas       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_gasfraction"],   "value", false, "bool", true, false, "")
                err_flag, err_msg, ptype_drc_fractions_ads,       pval_drc_fractions_ads       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_adsfraction"],   "value", false, "bool", true, false, "")
                err_flag, err_msg, ptype_drc_fractions_coads,     pval_drc_fractions_coads     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_coadsfraction"], "value", false, "bool", true, false, "")
                if err_flag == false 
                    err_flag, err_msg, x__drc_fractions_setsize   = get_confignumber(err_flag, err_msg, Int, pval_drc_fractions_setsize[1],   "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drc_fractions_chunksize = get_confignumber(err_flag, err_msg, Int, pval_drc_fractions_chunksize[1], "0", true, true, true, false, true) 
                end
                if err_flag == false 
                    x__drc_fractions_chunksize = max(x__drc_fractions_chunksize,0)
                    x__drc_fractions_gas       = get_bool(pval_drc_fractions_gas[1])
                    x__drc_fractions_ads       = get_bool(pval_drc_fractions_ads[1])
                    x__drc_fractions_coads     = get_bool(pval_drc_fractions_coads[1])
                    x__drc_fractions_cnt       = 0 
                    if x__drc_fractions_gas == true 
                        x__drc_fractions_cnt = x__drc_fractions_cnt + size(rxnsystem.odespecies.indxs_gas,1) 
                    end
                    if x__drc_fractions_ads == true 
                        x__drc_fractions_cnt = x__drc_fractions_cnt + size(rxnsystem.odespecies.indxs_ads,1) 
                    end
                    if x__drc_fractions_coads == true 
                        x__drc_fractions_cnt = x__drc_fractions_cnt + size(rxnsystem.odespecies.indxs_coads,1) 
                    end
                    x__drc_fractions = x__drc_fractions_gas || x__drc_fractions_ads || x__drc_fractions_coads
                end 
            end 
            
            # Retrieve sensitivity options - energies perturbations
            if err_flag == false 
                err_flag, err_msg, ptype_drc_energies_setsize,   pval_drc_energies_setsize   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_energies_setsize"],    "value", 0,     "Int",  true, false, "")
                err_flag, err_msg, ptype_drc_energies_chunksize, pval_drc_energies_chunksize = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_energies_chunksize"],  "value", 0,     "Int",  true, false, "")
                err_flag, err_msg, ptype_drc_energies_gas,       pval_drc_energies_gas       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_gasenergy"],   "value", false, "bool", true, false, "")
                err_flag, err_msg, ptype_drc_energies_ads,       pval_drc_energies_ads       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_adsenergy"],   "value", false, "bool", true, false, "")
                err_flag, err_msg, ptype_drc_energies_coads,     pval_drc_energies_coads     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_coadsenergy"], "value", false, "bool", true, false, "")
                err_flag, err_msg, ptype_drc_energies_tst,       pval_drc_energies_tst       = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "drcs_include_tsenergy"],    "value", false, "bool", true, false, "")
                if err_flag == false 
                    err_flag, err_msg, x__drc_energies_setsize   = get_confignumber(err_flag, err_msg, Int, pval_drc_energies_setsize[1],   "0", true, true, true, false, true) 
                    err_flag, err_msg, x__drc_energies_chunksize = get_confignumber(err_flag, err_msg, Int, pval_drc_energies_chunksize[1], "0", true, true, true, false, true) 
                end
                if err_flag == false 
                    x__drc_energies_chunksize = max(x__drc_energies_chunksize,0)
                    x__drc_energies_gas       = get_bool(pval_drc_energies_gas[1])
                    x__drc_energies_ads       = get_bool(pval_drc_energies_ads[1])
                    x__drc_energies_coads     = get_bool(pval_drc_energies_coads[1])
                    x__drc_energies_tst       = get_bool(pval_drc_energies_tst[1])
                    x__drc_energies_cnt       = 0
                    if x__drc_energies_gas == true 
                        x__drc_energies_cnt = x__drc_energies_cnt + size(rxnsystem.odespecies.indxs_gas,1)
                    end
                    if x__drc_energies_ads == true 
                        x__drc_energies_cnt = x__drc_energies_cnt + size(rxnsystem.odespecies.indxs_ads,1)
                    end
                    if x__drc_energies_coads == true 
                        x__drc_energies_cnt = x__drc_energies_cnt + size(rxnsystem.odespecies.indxs_coads,1)
                    end
                    if x__drc_energies_tst == true 
                        x__drc_energies_cnt = x__drc_energies_cnt + rxnsystem.reactions.pairs_cnt
                    end
                    x__drc_energies = x__drc_energies_gas || x__drc_energies_ads || x__drc_energies_coads || x__drc_energies_tst 
                end
            end 

            # Retrieve DRC species 
            if err_flag == false 
                x__drc_species = Array{String,1}(undef,0)
                for i in axes(runs_drc_species,1)
                    if haskey(runs_drc_species[i].vals, "run") && haskey(runs_drc_species[i].vals, "compound")
                        if runs_drc_species[i].vals["run"] !== nothing && runs_drc_species[i].vals["compound"] !== nothing
                            if runs_drc_species[i].vals["run"] == rxnrun_name && length(runs_drc_species[i].vals["compound"]) > 0 
                                x__odeindex = get_elemindex(rxnsystem.odespecies.names,runs_drc_species[i].vals["compound"],0)
                                if x__odeindex > 0 
                                    push!(x__drc_species,rxnsystem.odespecies.names[x__odeindex])
                                else 
                                    for j in 1:rxnsystem.odespecies.cnt 
                                        if rxnsystem.odespecies.compounds[j] == runs_drc_species[i].vals["compound"] 
                                            push!(x__drc_species,rxnsystem.odespecies.names[j])
                                        end 
                                    end 
                                end 
                            end
                        end
                    end
                end 
            end 

            # Retrieve DSC pairs
            if err_flag == false 
                x__cnt = 0 
                x__dsc_pairs_i = Array{String,1}(undef,0) 
                x__dsc_pairs_j = Array{String,1}(undef,0) 
                for i in axes(runs_dsc_pairs,1)
                    if haskey(runs_dsc_pairs[i].vals, "run") && haskey(runs_dsc_pairs[i].vals, "compound1") && haskey(runs_dsc_pairs[i].vals, "compound2")
                        if runs_dsc_pairs[i].vals["run"] !== nothing && runs_dsc_pairs[i].vals["compound1"] !== nothing && runs_dsc_pairs[i].vals["compound2"] !== nothing
                            if runs_dsc_pairs[i].vals["run"] == rxnrun_name && length(runs_dsc_pairs[i].vals["compound1"]) > 0 && length(runs_dsc_pairs[i].vals["compound2"]) > 0 
                                if runs_dsc_pairs[i].vals["compound1"] != runs_dsc_pairs[i].vals["compound2"] 
                                    o__indx_1 = get_elemindex(rxnsystem.odespecies.names,runs_dsc_pairs[i].vals["compound1"],0)
                                    o__indx_2 = get_elemindex(rxnsystem.odespecies.names,runs_dsc_pairs[i].vals["compound2"],0)
                                    if o__indx_1 > 0 
                                        if o__indx_2 > 0 
                                            x__cnt += 1 
                                            push!(x__dsc_pairs_i,rxnsystem.odespecies.names[o__indx_1])
                                            push!(x__dsc_pairs_j,rxnsystem.odespecies.names[o__indx_2])
                                        else
                                            for j in 1:rxnsystem.odespecies.cnt 
                                                if rxnsystem.odespecies.compounds[j] == runs_dsc_pairs[i].vals["compound2"] 
                                                    x__cnt += 1 
                                                    push!(x__dsc_pairs_i,rxnsystem.odespecies.names[o__indx_1])
                                                    push!(x__dsc_pairs_j,rxnsystem.odespecies.names[j])
                                                end 
                                            end 
                                        end 
                                    else
                                        if o__indx_2 > 0 
                                            for j in 1:rxnsystem.odespecies.cnt 
                                                if rxnsystem.odespecies.compounds[j] == runs_dsc_pairs[i].vals["compound1"] 
                                                    x__cnt += 1 
                                                    push!(x__dsc_pairs_i,rxnsystem.odespecies.names[j])
                                                    push!(x__dsc_pairs_j,rxnsystem.odespecies.names[o__indx_2])
                                                end 
                                            end 
                                        else
                                            for j in 1:rxnsystem.odespecies.cnt 
                                                if rxnsystem.odespecies.compounds[j] == runs_dsc_pairs[i].vals["compound1"] 
                                                    for k in 1:rxnsystem.odespecies.cnt 
                                                        if rxnsystem.odespecies.compounds[k] == runs_dsc_pairs[i].vals["compound2"] 
                                                            x__cnt += 1 
                                                            push!(x__dsc_pairs_i,rxnsystem.odespecies.names[j])
                                                            push!(x__dsc_pairs_j,rxnsystem.odespecies.names[k])
                                                        end 
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                            end
                        end
                    end
                end 
                x__dsc_pairs = fill("",x__cnt,2) 
                x__dsc_pairs_dict = Dict{String,Int}() 
                for i in 1:x__cnt 
                    x__dsc_pairs[i,1] = x__dsc_pairs_i[i]
                    x__dsc_pairs[i,2] = x__dsc_pairs_j[i]
                    x__dsc_pairs_dict[string(x__dsc_pairs_i[i]," | ",x__dsc_pairs_j[i])] = i 
                end
            end 

            # Construct object 
            if err_flag == false 
                rs = ct__RxnRun_SensitivityOptions(
                            x__analyze, x__drc_species, x__dsc_pairs, x__dsc_pairs_dict, 
                            x__drc_fractions, x__drc_fractions_setsize, x__drc_fractions_chunksize, x__drc_fractions_gas, x__drc_fractions_ads, x__drc_fractions_coads, x__drc_fractions_cnt, 
                            x__drc_energies, x__drc_energies_setsize, x__drc_energies_chunksize, x__drc_energies_gas, x__drc_energies_ads, x__drc_energies_coads, x__drc_energies_tst, x__drc_energies_cnt, 
                            x__ode_include_spcs_g, x__ode_include_spcs_n, x__ode_include_rxns_r
                        ) 
            end 
        end 

        return err_flag, err_msg, rs 
    end 

