                err_flag, err_msg, ptype_flags_sites_r,   pval_flags_sites_r   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_sites_participation_rates"],     "value", false, "bool", true, false, "") 
