                err_flag, err_msg, ptype_flags_rxn_info,  pval_flags_rxn_info  = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_reactions_info"],                "value", false, "bool", true, false, "") 
                err_flag, err_msg, ptype_flags_rxn_k,     pval_flags_rxn_k     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_reactions_rateconstants"],       "value", false, "bool", true, false, "") 
                err_flag, err_msg, ptype_flags_rxn_r,     pval_flags_rxn_r     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_reactions_rates"],               "value", false, "bool", true, false, "") 
