                err_flag, err_msg, ptype_flags_rpn_G,     pval_flags_rpn_G     = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_reactions_pair_energies"],       "value", false, "bool", true, false, "") 
                err_flag, err_msg, ptype_flags_sns_jac,   pval_flags_sns_jac   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_jacs"],                          "value", false, "bool", true, false, "") 
                err_flag, err_msg, ptype_flags_sns_drc,   pval_flags_sns_drc   = get_configproperty(err_flag, err_msg, runs_options, runs_defaults, ["run", "option"], [rxnrun_name, "output_drcs"],                          "value", false, "bool", true, false, "") 
