    function Init__RxnRun__Temperatures(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units) 

        # Check error state 
        rs = ct__SFloat64Array(1)
        if err_flag == false
            err_flag = false 
            err_msg = "" 

            # Retrieve temperatures value and units 
            if err_flag == false 
                x__temps_value = rxnrun.temperatures_exprn 
                x__temps_units = rxnrun.temperatures_units 
                if length(run_temperature_value) > 0 
                    x__temps_value = run_temperature_value 
                    x__temps_units = run_temperature_units 
                end 
            end 

            # Parse temperatures value 
            if err_flag == false 
                x__temps_all = replace(x__temps_value,"--" => "")
                x__temps_grps = String.(split(x__temps_all, ",")) 
                x__temps_uary = Array{Float64,1}(undef,0)
                if size(x__temps_grps,1) > 0 
                    for i in axes(x__temps_grps,1) 
                        err_flag = true 
                        x__temps_grps[i] = str_trim(x__temps_grps[i]) 
                        x__temps_grp = String.(split(x__temps_grps[i], ":")) 
                        x__flag = false 
                        if size(x__temps_grp,1) == 1 || size(x__temps_grp,1) == 3 
                            err_flag = false 
                            for j in axes(x__temps_grp,1)
                                x__flag = false 
                                if tryparse(Float64, replace(x__temps_grp[j],"n" => "")) !== nothing 
                                    if tryparse(Float64, replace(x__temps_grp[j],"n" => "")) >= 0 && (x__temps_grp[j] == replace(x__temps_grp[j],"n" => "") || j == 2)
                                        x__flag = true
                                    end 
                                end
                                if x__flag == false 
                                    break
                                end
                            end
                        end
                        if err_flag == false && x__flag == true 
                            if size(x__temps_grp,1) == 1 
                                err_flag, err_msg, x__parsed_flag, x__parsed_val_1 = try_parse(err_flag, err_msg, x__temps_grp[1], 0.0)
                                if err_flag == false && x__parsed_flag == true 
                                    push!(x__temps_uary,x__parsed_val_1)
                                end 
                            elseif size(x__temps_grp,1) == 3 
                                if x__temps_grp[2] == replace(x__temps_grp[2],"n" => "")
                                    err_flag, err_msg, x__parsed_flag, x__parsed_vals = try_parse(err_flag, err_msg, x__temps_grp, 0.0)
                                    if err_flag == false && x__parsed_flag == true 
                                        if x__parsed_vals[3] > x__parsed_vals[1] && 0 < x__parsed_vals[2] && x__parsed_vals[2] <= x__parsed_vals[3] - x__parsed_vals[1]
                                            x__ctr = 0
                                            while x__parsed_vals[1] <= x__parsed_vals[1] + x__ctr * x__parsed_vals[2] && x__parsed_vals[1] + x__ctr * x__parsed_vals[2] <= x__parsed_vals[3]
                                                if x__parsed_vals[1] <= x__parsed_vals[1] + x__ctr * x__parsed_vals[2] && x__parsed_vals[1] + x__ctr * x__parsed_vals[2] <= x__parsed_vals[3]
                                                    push!(x__temps_uary,(x__parsed_vals[1] + x__ctr * x__parsed_vals[2]))
                                                end
                                                x__ctr = x__ctr + 1
                                            end
                                            push!(x__temps_uary,x__parsed_vals[3])
                                        end
                                    end 
                                else 
                                    err_flag, err_msg, x__parsed_flag_1, x__parsed_val_1 = try_parse(err_flag, err_msg, x__temps_grp[1], 0.0)
                                    err_flag, err_msg, x__parsed_flag_2, x__parsed_val_2 = try_parse(err_flag, err_msg, replace(x__temps_grp[2],"n" => ""), 0)
                                    err_flag, err_msg, x__parsed_flag_3, x__parsed_val_3 = try_parse(err_flag, err_msg, x__temps_grp[3], 0.0)
                                    if err_flag == false && x__parsed_flag_1 == true && x__parsed_flag_2 == true && x__parsed_flag_3 == true 
                                        if x__parsed_val_3[3] > x__parsed_val_1[1] && 0 < x__parsed_val_2 
                                            push!(x__temps_uary,x__parsed_val_1[1])
                                            if x__parsed_val_2 > 1
                                                for j in 1:(x__parsed_val_2 - 1)
                                                    push!(x__temps_uary,x__parsed_val_1[1] + (j / x__parsed_val_2) * (x__parsed_val_3[3] - x__parsed_val_1[1]))
                                                end 
                                            end 
                                            push!(x__temps_uary,x__parsed_val_3[3]) 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                end 
                if err_flag == false 
                    if size(x__temps_uary,1) > 0 
                        x__temps = unique(x__temps_uary)
                        sort!(x__temps)
                    else 
                        push!(x__temps,298.15)
                    end
                    x__cnt = size(x__temps,1) 
                    x__units = x__temps_units 
                    x__units_si = rxnsystem.physunits.temperature_si 
                    x__units_absent = false 
                    x__value = deepcopy(x__temps) 
                    x__value_si = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__value, x__units, x__units_si) 
                    x__value_absent = false 
                end 
            end 
            
            # Construct object 
            if err_flag == false 
                rs = ct__SFloat64Array{1}("temperatures", x__cnt, x__value, x__value_si, x__value_absent, x__units, x__units_si, x__units_absent) 
            end 
        end 

        return err_flag, err_msg, rs 
    end 



    # Temperature run initialization functions 
    
    function Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, numtype::Type, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, threaded, includepoly) 
        
        # this interpolator is based on polyharmonic splines

        rs = ct__Temprun_Interpolator_Obj(numtype) 
        unq_indxs    = Array{Int,1}(undef,0) 
        unq_subindxs = Array{Int,1}(undef,0) 
        unq_subindxs_srcnzdims = Array{Int,1}(undef,0)
        if err_flag == false 
            
            # nodes 
            if err_flag == false 
                x__ary = zeros(numtype,size(nodes_rowsindxs,1),size(nodes_colsindxs,1)) 
                for i in axes(nodes_colsindxs,1) 
                    for j in axes(nodes_rowsindxs,1) 
                        x__ary[j,i] = nodes_data[nodes_rowsindxs[j],nodes_colsindxs[i]] 
                    end 
                end 
                unq_subindxs       = get_uniquecolindxs(x__ary,rxnrun.covs_detect_tol) 
                unq_indxs          = get_view(view(nodes_colsindxs,unq_subindxs))
                x__nodes_srcnzdims = Array{Int,1}(undef,0)
                for i in axes(x__ary,1)
                    for j in axes(unq_subindxs,1)
                        if x__ary[i,unq_subindxs[j]] > 0 
                            push!(x__nodes_srcnzdims,i)
                            break 
                        end 
                    end
                end
                x__nodes           = get_view(view(x__ary,x__nodes_srcnzdims,unq_subindxs)) 
                x__nodes_dims      = size(x__nodes,1) 
                x__nodes_pts       = size(x__nodes,2) 
                x__nodes_pairdists = zeros(numtype,x__nodes_pts,x__nodes_pts) 
                get_pairdists_self(x__nodes_pairdists, x__nodes, x__nodes_dims, true, threaded) 
            end  
            
            # data 
            if err_flag == false 
                x__data      = get_view(view(data,:,unq_subindxs)) 
                x__data_dims = size(data,1)
                x__data_pts  = x__nodes_pts
                x__data_t    = get_transpose(x__data)
            end 

            # radial basis distances
            if err_flag == false 
                x__rbf_name          = rxnrun.solveroptions.interp_rbf_name
                x__rbf_power         = convert(numtype,rxnrun.solveroptions.interp_rbf_power) 
                x__rbf_power_even    = (x__rbf_power % 2 == 0) 
                x__rbf_shapeparam    = convert(numtype,rxnrun.solveroptions.interp_rbf_shapeparam)
                x__rbf_shapeparam_sq = convert(numtype,rxnrun.solveroptions.interp_rbf_shapeparam * rxnrun.solveroptions.interp_rbf_shapeparam)
                x__rbf_vals          = zeros(numtype,x__nodes_pts,x__nodes_pts) 
                for i in eachindex(x__nodes_pairdists) 
                    if x__rbf_name == "polyharmonic" 
                        if x__rbf_power_even == true 
                            x__rbf_vals[i] = (x__nodes_pairdists[i] ^ x__rbf_power) * log(x__nodes_pairdists[i]) 
                        else 
                            x__rbf_vals[i] = (x__nodes_pairdists[i] ^ x__rbf_power) 
                        end 
                    elseif x__rbf_name == "inversemultiquadric" 
                        x__rbf_vals[i] = 1 / sqrt(1 + x__rbf_shapeparam_sq * x__nodes_pairdists[i] ^ 2)
                    else 
                        err_flag = true 
                        break 
                    end
                end 
                err_flag = (x__rbf_power <= 0)
            end 

            # radial basis weights
            if err_flag == false 
                x__poly_include = ((x__rbf_name == "polyharmonic" ? rxnrun.solveroptions.interp_rbf_includepolynomial : false) && includepoly == true)
                if x__poly_include == true 
                    x__poly_degree      = (x__rbf_power_even ? (convert(Int,x__rbf_power) + 1) : get_trunc(ceil(x__rbf_power / 2)))
                    x__poly_binomialcnt = binomial(x__poly_degree + x__nodes_dims, x__poly_degree) 
                    x__poly_combos_tot  = 0 
                    x__poly_combos_cnts = fill(0,x__poly_degree)
                    x__rpcs             = fill(Array{Array{Int,1},1}(undef,0),x__poly_degree)
                    for i in 1:x__poly_degree 
                        x__rpcs[i] = collect(with_replacement_combinations(1:x__nodes_dims,i))
                        x__poly_combos_cnts[i] = size(x__rpcs[i],1)
                        x__poly_combos_tot += x__poly_combos_cnts[i]
                    end 
                    x__poly_combos_indxs = zeros(Int,x__poly_combos_tot,x__poly_degree)
                    x__pos = 0 
                    for i in 1:x__poly_degree 
                        cx = x__rpcs[i]
                        for j in axes(cx,1)
                            for k in axes(cx[j],1)
                                x__poly_combos_indxs[x__pos+j,k] = cx[j][k]
                            end 
                        end 
                        x__pos += x__poly_combos_cnts[i]
                    end 
                    x__polynomial = ones(numtype, x__nodes_pts, x__poly_binomialcnt) 
                    position = 2
                    while position <= x__poly_binomialcnt 
                        for i in 1:x__poly_degree
                            cx = x__rpcs[i]
                            for combination in axes(cx,1)
                                for var in axes(cx[combination],1)
                                    x__polynomial[:, position] .*= x__nodes[cx[combination][var], :] 
                                end 
                                position += 1 
                            end 
                        end 
                    end 
                    x__E_obj = ct__Array(numtype)
                    Init__Temprun__Interpolation__Obj__Factorize(x__rbf_vals, x__polynomial, x__data_t, x__E_obj, numtype) 
                    x__E = x__E_obj.ary
                    x__poly_lambda  = -1 .* x__E 
                    x__rbf_weights = x__rbf_vals \ (I * x__data_t + x__polynomial * x__E) 
                else 
                    x__poly_degree       = 0 
                    x__poly_binomialcnt  = 1 
                    x__poly_combos_tot   = 0
                    x__poly_combos_cnts  = Array{Int,1}(undef,0) 
                    x__poly_combos_indxs = Array{Int,2}(undef,0,0) 
                    x__poly_lambda       = Array{numtype,2}(undef,0,0) 
                    x__rbf_weights       = x__rbf_vals \ x__data_t 
                end 
            end 

            # caches 
            if err_flag == false 
                x__tmp_numelem          = zeros(numtype,1)
                x__tmp_inputszs_vals    = Array{Int,1}(undef,0)
                x__tmp_inputszs_indxs   = Dict{Int,Int}() 
                x__tmp_pairdists_u      = Array{Array{numtype,2},1}(undef,0) 
                x__tmp_pairdists_cache  = LazyBufferCache() 
                x__tmp_rbfvals_u        = Array{Array{numtype,2},1}(undef,0) 
                x__tmp_rbfvals_cache    = LazyBufferCache() 
                x__tmp_polynomial_u     = Array{Array{numtype,2},1}(undef,0) 
                x__tmp_polynomial_cache = LazyBufferCache() 
                x__tmp_ptlvals_u        = Array{Array{numtype,2},1}(undef,0) 
                x__tmp_ptlvals_cache    = LazyBufferCache() 
                for i in 1:1 
                    x__tmp_inputsz = i
                    push!(x__tmp_inputszs_vals,x__tmp_inputsz)
                    x__tmp_inputszs_indxs[x__tmp_inputsz] = size(x__tmp_inputszs_vals,1)
                    push!(x__tmp_pairdists_u,zeros(numtype,x__tmp_inputsz,x__nodes_pts))
                    x__tmpary = x__tmp_pairdists_cache[zeros(numtype,(1,x__nodes_pts)),(1,x__nodes_pts)] 
                    push!(x__tmp_rbfvals_u,zeros(numtype,x__tmp_inputsz,x__nodes_pts))
                    x__tmpary = x__tmp_rbfvals_cache[zeros(numtype,(1,x__nodes_pts)),(1,x__nodes_pts)] 
                    push!(x__tmp_polynomial_u,zeros(numtype,x__tmp_inputsz,x__poly_binomialcnt))
                    x__tmpary = x__tmp_polynomial_cache[zeros(numtype,(1,x__poly_binomialcnt)),(1,x__poly_binomialcnt)] 
                    push!(x__tmp_ptlvals_u,zeros(numtype,x__tmp_inputsz,x__data_dims))
                    x__tmpary = x__tmp_ptlvals_cache[zeros(numtype,(1,x__data_dims)),(1,x__data_dims)]     
                end 
            end 

            # construct object 
            if err_flag == false 
                rs = ct__Temprun_Interpolator_Obj(
                            x__nodes, x__nodes_dims, x__nodes_pts, unq_indxs, unq_subindxs, x__nodes_srcnzdims, 
                            x__data, x__data_dims, x__data_pts, 
                            x__rbf_name, x__rbf_power, x__rbf_power_even, x__rbf_shapeparam, x__rbf_shapeparam_sq, x__rbf_weights, 
                            x__poly_include, x__poly_degree, x__poly_binomialcnt, x__poly_combos_tot, x__poly_combos_cnts, x__poly_combos_indxs, x__poly_lambda, 
                            x__tmp_numelem, x__tmp_inputszs_vals, x__tmp_inputszs_indxs, 
                            x__tmp_pairdists_u, x__tmp_pairdists_cache, 
                            x__tmp_rbfvals_u, x__tmp_rbfvals_cache, 
                            x__tmp_polynomial_u, x__tmp_polynomial_cache, 
                            x__tmp_ptlvals_u, x__tmp_ptlvals_cache
                        ) 
                unq_subindxs_srcnzdims = deepcopy(x__nodes_srcnzdims)
            end 
        end 

        return err_flag, err_msg, rs, unq_indxs, unq_subindxs, unq_subindxs_srcnzdims
    end 

    function Init__Temprun__Interpolation__Obj__Factorize(rbfvals, polynomial, data_t, rs, numtype::Type) 

        polynomial_t = polynomial'
        x__Af = factorize(rbfvals) 
        x__B = -polynomial_t * (x__Af \ polynomial) 
        x__E = x__B \ (polynomial_t * (x__Af \ data_t)) 
        rs.ary  = zeros(numtype,size(x__E))
        rs.ary .= x__E
    end 

    function Init__Temprun__Logging(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, run_temps, run_temps_index, run_temp, run_temp_K, run_folder, numtype::Type) 

        logging_flag = false 
        temprun_logging = ct__Temprun_Logging() 
        logging_filehandles = ct__Temprun_Logging_Handles()
        msgconfig_combined = ct__MessageConfigs() 
        msgconfig_run = ct__MessageConfigs() 
        if err_flag == false 

            # Initialize run logging 
            if err_flag == false 
                x__start_ts = now() 
                x__start_ts_txt = Dates.format(x__start_ts, "yyyy:mm:dd HH:MM:SS") 
                x__start_ts_txt = replace(replace(x__start_ts_txt, " " => "_"), ":" => "_") 
                x__log_file_name = "RunLog.txt" 
                x__subfolder_group_path = "" 
                x__subfolder_group_folder = "" 
                x__subfolder_run_path = "" 
                x__subfolder_log_file_path = "" 
                x__subfolder_log_file_name = "RunLog.txt" 
                x__run_name = (length(run_folder) > 0 ? run_folder : rxnrun.name) 
                if rxnrun.logging.folder_group_subparam == "timestamp"
                    if rxnrun.logging.folder_run_userunfolder == true 
                        x__path_run = joinpath(rxnrun.logging.path_group,string(x__run_name,(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",x__start_ts_txt) : "")))
                        x__path_run_folderonly = string(x__run_name,(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",x__start_ts_txt) : ""))
                    else
                        x__path_run = joinpath(rxnrun.logging.path_group,string("",(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",x__start_ts_txt) : "")))
                        x__path_run_folderonly = string("",(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",x__start_ts_txt) : ""))
                    end
                else
                    if rxnrun.logging.folder_run_userunfolder == true 
                        x__path_run = joinpath(rxnrun.logging.path_group,string(x__run_name,(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",run_temp) : "")))
                        x__path_run_folderonly = string(x__run_name,(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",replace(string(run_temp," ",run_temps.units),".0 "=>" ")) : ""))
                    else
                        x__path_run = joinpath(rxnrun.logging.path_group,string("",(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",run_temp) : "")))
                        x__path_run_folderonly = string("",(lowercase(strip(rxnrun.logging.folder_run_submode)) == "append" ? string("__",replace(string(run_temp," ",run_temps.units),".0 "=>" ")) : ""))
                    end
                end 
                x__log_file_path = joinpath(x__path_run,"RunLog.txt")
                if rxnrun.logging.folder_run_submode == "copy" && rxnrun.logging.folder_group_subfolder != "" && length(rxnrun.logging.folder_group_subfolder) > 0 
                    x__subfolder_group_path = joinpath(x__path_run,rxnrun.logging.folder_group_subfolder)
                    x__subfolder_group_folder = rxnrun.logging.folder_group_subfolder
                    if rxnrun.logging.folder_group_subparam == "timestamp"
                        x__subfolder_run_path = joinpath(x__subfolder_group_path,x__start_ts_txt)
                        x__subfolder_run_folder = x__start_ts_txt
                    else
                        x__run_temp = isinteger(run_temp) ? string(get_trunc(run_temp)) : string(run_temp)
                        x__subfolder_run_path = joinpath(x__subfolder_group_path,replace(string(x__run_temp," ",run_temps.units),".0 "=>" ")) 
                        x__subfolder_run_folder = replace(string(x__run_temp," ",run_temps.units),".0 "=>" ")
                    end
                    x__subfolder_log_file_path = joinpath(x__subfolder_run_path,"RunLog.txt")
                end
                temprun_logging = ct__Temprun_Logging(x__start_ts, x__start_ts_txt, x__path_run, x__path_run_folderonly, x__log_file_name, x__log_file_path, x__subfolder_group_path, x__subfolder_group_folder, x__subfolder_log_file_path, x__subfolder_log_file_name, x__subfolder_run_path, x__subfolder_run_folder)
            end 

            # Initialize directory for this calculation run
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("initializing run directories: ")) 
                mkpath(temprun_logging.path_run) 
                if lowercase(strip(rxnrun.logging.folder_run_submode)) == "copy" && rxnrun.logging.folder_group_subfolder != "" && length(rxnrun.logging.folder_group_subfolder) > 0 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  subfolder: ",replace(temprun_logging.subfolder_run_path, temprun_logging.path_run => ""))) 
                    mkpath(temprun_logging.subfolder_run_path) 
                end 
            end 

            # Initialize log file(s) for this calculation run 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("initializing log file(s)"))
                logging_flag = true 
                logging_filehandles.log_file_path = "" 
                logging_filehandles.log_file_openflag = false
                logging_filehandles.log_file_fsobj_indx = 0
                logging_filehandles.subfolder_log_file_path = "" 
                logging_filehandles.subfolder_log_file_openflag = false
                logging_filehandles.subfolder_log_file_fsobj_indx = 0   
                msgconfig_combined_cnt = 0 
                msgconfig_combined_indxs = Dict{String,Int}()
                msgconfig_combined_keys = Array{String,1}(undef,0)
                msgconfig_combined_vec = Array{ct__MessageConfig,1}(undef,0)
                msgconfig_combined_cnt = msgconfig_combined_cnt + 1 
                push!(msgconfig_combined_vec,msgoptions)
                msgconfig_run_cnt = 0 
                msgconfig_run_indxs = Dict{String,Int}()
                msgconfig_run_keys = Array{String,1}(undef,0)
                msgconfig_run_vec = Array{ct__MessageConfig,1}(undef,0)
                if rxnrun.logging.folder_group_submode == "subonly" 
                    if rxnrun.logging.folder_run_submode == "copy"
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  opening: ",replace(temprun_logging.subfolder_log_file_path, x__path_run => ""))) 
                        xfs = open(temprun_logging.subfolder_log_file_path,"w") 
                        close(xfs)
                        logging_filehandles.subfolder_log_file_path = temprun_logging.subfolder_log_file_path  
                        logging_filehandles.subfolder_log_file_openflag = true
                        logging_filehandles.subfolder_log_file_fsobj = open(temprun_logging.subfolder_log_file_path,"a")
                        x__run = ct__MessageConfig(temprun_logging.start_ts, temprun_logging.start_ts, rxnrun.logging.messages_show, rxnrun.logging.messages_log, msgoptions.log_file_sffx, temprun_logging.subfolder_run_path, temprun_logging.subfolder_log_file_path, logging_filehandles.subfolder_log_file_fsobj) 
                        msgconfig_combined_cnt = msgconfig_combined_cnt + 1 
                        push!(msgconfig_combined_vec,x__run) 
                        msgconfig_run_cnt = msgconfig_run_cnt + 1 
                        push!(msgconfig_run_vec,x__run) 
                        logging_filehandles.subfolder_log_file_fsobj_indx = msgconfig_run_cnt 
                    end
                else
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  opening: ",replace(temprun_logging.log_file_path, x__path_run => ""))) 
                    xfs = open(temprun_logging.log_file_path,"w")
                    close(xfs)
                    logging_filehandles.log_file_path = temprun_logging.log_file_path 
                    logging_filehandles.log_file_openflag = true
                    logging_filehandles.log_file_fsobj = open(temprun_logging.log_file_path,"a")
                    x__run = ct__MessageConfig(temprun_logging.start_ts, temprun_logging.start_ts, rxnrun.logging.messages_show, rxnrun.logging.messages_log, msgoptions.log_file_sffx, temprun_logging.path_run, temprun_logging.log_file_path, logging_filehandles.log_file_fsobj) 
                    msgconfig_combined_cnt = msgconfig_combined_cnt + 1 
                    push!(msgconfig_combined_vec,x__run)
                    msgconfig_run_cnt = msgconfig_run_cnt + 1 
                    push!(msgconfig_run_vec,x__run)
                    logging_filehandles.log_file_fsobj_indx = msgconfig_run_cnt
                    if rxnrun.logging.folder_run_submode == "copy"
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  opening: ",replace(temprun_logging.subfolder_log_file_path, x__path_run => ""))) 
                        xfs = open(temprun_logging.subfolder_log_file_path,"w")
                        close(xfs)
                        logging_filehandles.subfolder_log_file_path = temprun_logging.subfolder_log_file_path  
                        logging_filehandles.subfolder_log_file_openflag = true
                        logging_filehandles.subfolder_log_file_fsobj = open(temprun_logging.subfolder_log_file_path,"a")
                        x__run = ct__MessageConfig(temprun_logging.start_ts, temprun_logging.start_ts, rxnrun.logging.messages_show, rxnrun.logging.messages_log, msgoptions.log_file_sffx, temprun_logging.subfolder_run_path, temprun_logging.subfolder_log_file_path, logging_filehandles.subfolder_log_file_fsobj) 
                        msgconfig_combined_cnt = msgconfig_combined_cnt + 1 
                        push!(msgconfig_combined_vec,x__run)
                        msgconfig_run_cnt = msgconfig_run_cnt + 1 
                        push!(msgconfig_run_vec,x__run)
                        logging_filehandles.subfolder_log_file_fsobj_indx = msgconfig_run_cnt
                    end
                end 
                msgconfig_combined = ct__MessageConfigs(msgconfig_combined_cnt, deepcopy(msgconfig_combined_indxs), deepcopy(msgconfig_combined_keys), msgconfig_combined_vec) 
                msgconfig_run = ct__MessageConfigs(msgconfig_run_cnt, deepcopy(msgconfig_run_indxs), deepcopy(msgconfig_run_keys), msgconfig_run_vec) 
            end
        end 

        return err_flag, err_msg, logging_flag, temprun_logging, logging_filehandles, msgconfig_combined, msgconfig_run
    end 

    function Init__Temprun__ConstantParameters(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, run_temps, run_temps_index, run_temp, run_temp_K, numtype::Type) 
        
        # this precalculates and converts values to the Temprun number type to reduce number conversions in performance critical sections

        # Check error state 
        temprun_constparams = ct__TempRun_ConstParams(numtype) 
        if err_flag == false 

            # constants
            if err_flag == false 
                x__numelem             = zeros(numtype,1)
                x__run_temp            = convert(numtype, run_temp) 
                x__run_temp_units      = run_temps.units
                x__run_temp_K          = convert(numtype, run_temp_K) 
                x__cell_neighbordist_m = convert.(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.phases.neighbordists.value_si, rxnsystem.phases.neighbordists.units_si, "m")) 
                x__cell_b2_m2          = convert.(numtype, rxnsystem.phases.cellshapefactors .* (x__cell_neighbordist_m .* x__cell_neighbordist_m)) 
                x__wavenum_min_1_m     = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnrun.qfuncoptions.vib_minwavenum.value, rxnrun.qfuncoptions.vib_minwavenum.units, "1/m")) 
                x__wavenum_min_1_cm    = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnrun.qfuncoptions.vib_minwavenum.value, rxnrun.qfuncoptions.vib_minwavenum.units, "1/cm")) 
                x__wavenum_tol_1_m     = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, 1.0, "1/cm", "1/m")) 
                x__wavenum_tol_1_cm    = convert(numtype, 1.0) 
                x__nvs_kb_J_K          = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.k_b.value,    rxnsystem.physcnsts.k_b.units,     "J / K")) 
                x__nvs_kbt_eV          = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.k_b.value,    rxnsystem.physcnsts.k_b.units,    "eV / K") * conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, run_temps.value_si[run_temps_index], run_temps.units_si, "K")) 
                x__nvs_kbt_J           = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.k_b.value,    rxnsystem.physcnsts.k_b.units,     "J / K") * conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, run_temps.value_si[run_temps_index], run_temps.units_si, "K")) 
                x__nvs_kbt_hp_1_s      = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.k_b.value,    rxnsystem.physcnsts.k_b.units,     "J / K") * conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, run_temps.value_si[run_temps_index], run_temps.units_si, "K") / conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.h_p.value, rxnsystem.physcnsts.h_p.units, "J * s"))  
                x__nvs_hp_J_s          = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.h_p.value_si, rxnsystem.physcnsts.h_p.units_si,  "J * s")) 
                x__nvs_hpc_J_m         = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.h_p.value_si, rxnsystem.physcnsts.h_p.units_si,  "J * s") * conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.c_v.value_si, rxnsystem.physcnsts.c_v.units_si, "m / s")) 
                x__nvs_hpc_eV_m        = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.h_p.value_si, rxnsystem.physcnsts.h_p.units_si, "eV * s") * conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.c_v.value_si, rxnsystem.physcnsts.c_v.units_si, "m / s")) 
                x__nvs_Na_1_mol        = convert(numtype, conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.physcnsts.N_a.value,    rxnsystem.physcnsts.N_a.units,     "1/mol")) 
            end 

            # Construct object 
            if err_flag == false 
                temprun_constparams = ct__TempRun_ConstParams(
                                        x__numelem, 
                                        x__run_temp, x__run_temp_units, x__run_temp_K, 
                                        x__cell_neighbordist_m, x__cell_b2_m2, 
                                        x__wavenum_min_1_m, x__wavenum_min_1_cm, x__wavenum_tol_1_m, x__wavenum_tol_1_cm, 
                                        x__nvs_kb_J_K, x__nvs_kbt_eV, x__nvs_kbt_J, x__nvs_kbt_hp_1_s, x__nvs_hp_J_s, x__nvs_hpc_J_m, x__nvs_hpc_eV_m, x__nvs_Na_1_mol
                                    )
            end 
        end 

        return err_flag, err_msg, temprun_constparams 
    end 

    function Init__Temprun__ODEParameters(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, solv_num_fmt, solv_num_prec, numtype::Type) 
        
        # this precalculates and converts values to the Temprun number type to reduce number conversions in performance critical sections
        # this also prepares arrays that optimize looping calculations

        # Check error state 
        temprun_odeparams = ct__TempRun_ODEParams(numtype) 
        if err_flag == false 

            # Calculate values
            if err_flag == false 
                x__ode_cnt          = rxnsystem.odespecies.cnt
                x__ode_names        = deepcopy(rxnsystem.odespecies.names)
                x__ode_types        = deepcopy(rxnsystem.odespecies.types)
                x__ode_aflags       = fill(true,rxnsystem.odespecies.cnt,rxnsystem.reactions.cnt)
                x__ode_inifracs     = convert.(numtype,deepcopy(rxnrun.odefracs_ini))
                x__ode_gas_cnt      = rxnsystem.odespecies.indxs_gas_cnt
                x__ode_gas_indxs    = deepcopy(rxnsystem.odespecies.indxs_gas)
                x__ode_gas_momentum = zeros(numtype,rxnsystem.odespecies.indxs_gas_cnt)   # calculated in units of SI momentum (kg*m/s)
                for i in 1:rxnsystem.odespecies.indxs_gas_cnt 
                    err_flag = true 
                    x__molindex = rxnsystem.molecules.dindxs[rxnsystem.odespecies.compounds[rxnsystem.odespecies.indxs_gas[i]]] 
                    if x__molindex > 0 
                        err_flag = false 
                        x__ode_gas_momentum[i] = convert(numtype,(sqrt(2 * pi * conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnsystem.molecules.molwts.value_si[x__molindex], rxnsystem.molecules.molwts.units_si, "kg / mol") * temprun_constparams.nvs_kbt_J / temprun_constparams.nvs_Na_1_mol)))
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
                x__ode_nongas_cnt                = rxnsystem.odespecies.indxs_nongas_cnt 
                x__ode_nongas_indxs              = deepcopy(rxnsystem.odespecies.indxs_nongas) 
                x__ode_ads_cnt                   = rxnsystem.odespecies.indxs_ads_cnt 
                x__ode_ads_indxs                 = deepcopy(rxnsystem.odespecies.indxs_ads) 
                x__ode_coads_cnt                 = rxnsystem.odespecies.indxs_coads_cnt 
                x__ode_coads_indxs               = deepcopy(rxnsystem.odespecies.indxs_coads) 
                x__ode_site_cnt                  = rxnsystem.odespecies.indxs_site_cnt 
                x__ode_site_indxs                = deepcopy(rxnsystem.odespecies.indxs_site) 
                x__ode_adscoads_cnt              = rxnsystem.odespecies.indxs_adscoads_cnt 
                x__ode_adscoads_indxs            = deepcopy(rxnsystem.odespecies.indxs_adscoads) 
                x__ode_siteads_cnt               = rxnsystem.odespecies.indxs_siteads_cnt 
                x__ode_siteads_indxs             = deepcopy(rxnsystem.odespecies.indxs_siteads) 
                x__ode_siteads_adsindxs          = get_elemindex(rxnsystem.odespecies.indxs_siteads,rxnsystem.odespecies.indxs_ads,0) 
                x__ode_siteads_siteindxs         = get_elemindex(rxnsystem.odespecies.indxs_siteads,rxnsystem.odespecies.indxs_site,0) 
                x__ode_odeindex2nongasindex      = get_elemindex(rxnsystem.odespecies.indxs_nongas,collect(1:rxnsystem.odespecies.cnt),0) 
                x__ode_rxntypes                  = deepcopy(rxnsystem.reactions.rxntypes) 
                x__ode_adsorb_gas_odeindxs       = deepcopy(rxnsystem.reactions.adsorb_gas_odeindxs)
                x__ode_scaling_uscale_flag       = rxnrun.solveroptions.ode_scaling_uscale_flag 
                x__ode_scaling_uscale_unityflags = deepcopy(rxnrun.solveroptions.ode_scaling_uscale_unityflags) 
                x__ode_scaling_uscale_factors    = convert.(numtype,rxnrun.solveroptions.ode_scaling_uscale_factors) 
                if rxnrun.solveroptions.ode_include_spcs_n == true 
                    x__ode_scaling_uscale_unityflags = vcat(x__ode_scaling_uscale_unityflags,x__ode_scaling_uscale_unityflags)
                    x__ode_scaling_uscale_factors    = vcat(x__ode_scaling_uscale_factors,x__ode_scaling_uscale_factors)
                end 
                if rxnrun.solveroptions.ode_include_rxns_r == true 
                    x__ode_scaling_uscale_unityflags = vcat(x__ode_scaling_uscale_unityflags,fill(true,rxnsystem.reactions.cnt))
                    x__ode_scaling_uscale_factors    = vcat(x__ode_scaling_uscale_factors,ones(numtype,rxnsystem.reactions.cnt))
                end 
                x__ode_scaling_tflag            = rxnrun.solveroptions.ode_scaling_tflag 
                x__ode_scaling_tunityflag       = rxnrun.solveroptions.ode_scaling_tunityflag 
                x__ode_scaling_tfactor          = convert(numtype,rxnrun.solveroptions.ode_scaling_tfactor)
                x__ode_solpts_interp_flag       = rxnrun.solveroptions.ode_solpts_interp_flag 
                x__ode_solpts_interp_mag_min    = rxnrun.solveroptions.ode_solpts_interp_mag_min 
                x__ode_solpts_interp_mag_max    = rxnrun.solveroptions.ode_solpts_interp_mag_max 
                x__ode_solpts_interp_pts_min    = rxnrun.solveroptions.ode_solpts_interp_pts_min 
                x__ode_solpts_interp_pts_max    = rxnrun.solveroptions.ode_solpts_interp_pts_max 
                x__ode_include_spcs_g           = rxnrun.solveroptions.ode_include_spcs_g
                x__ode_include_spcs_n           = rxnrun.solveroptions.ode_include_spcs_n
                x__ode_include_rxns_r           = rxnrun.solveroptions.ode_include_rxns_r 
                x__ode_krate_gaspress_flag      = rxnrun.solveroptions.ode_krate_gaspress_flag 
                x__ode_rate_assigned_nopos      = fill(false,rxnsystem.odespecies.cnt) 
                x__ode_rate_assigned_noneg      = fill(false,rxnsystem.odespecies.cnt) 
                for i in 1:rxnsystem.odespecies.cnt 
                    if maximum(abs.(rxnsystem.reactions.coeffs_alpha[i,:])) > 0 
                        x__vrbl = false 
                        for j in 1:rxnsystem.reactions.cnt 
                            if rxnsystem.reactions.coeffs_alpha[i,j] != 0 
                                x__indx = get_elemindex(rxnsystem.reactions.kupdmodes_assigned,j,0) 
                                if x__indx <= 0 
                                    x__vrbl = true 
                                    break 
                                end 
                            end 
                        end 
                        if x__vrbl == false 
                            x__ode_rate_assigned_nopos[i] = true 
                            x__ode_rate_assigned_noneg[i] = true 
                            for j in 1:rxnsystem.reactions.cnt 
                                if rxnsystem.reactions.kfactors[j] > 0 
                                    if rxnsystem.reactions.coeffs_alpha[i,j] > 0  
                                        x__ode_rate_assigned_nopos[i] = false 
                                    end 
                                    if rxnsystem.reactions.coeffs_alpha[i,j] < 0  
                                        x__ode_rate_assigned_noneg[i] = false 
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
                x__ode_const_flags   = fill(false,rxnsystem.odespecies.cnt)
                x__ode_const_nzflags = fill(false,rxnsystem.odespecies.cnt)
                x__ode_const_vals    = zeros(numtype,rxnsystem.odespecies.cnt)
                x__ode_const_indxs   = Array{Int,1}(undef,0) 
                if size(rxnrun.odefracs_fixed,1) > 0 
                    for i in axes(rxnrun.odefracs_fixed,1)
                        x__ode_const_flags[rxnrun.odefracs_fixed[i]] = true 
                        x__ode_const_nzflags[rxnrun.odefracs_fixed[i]] = (rxnrun.odefracs_ini[rxnrun.odefracs_fixed[i]] != zero(rxnrun.odefracs_ini[rxnrun.odefracs_fixed[i]]))
                        x__ode_const_vals[rxnrun.odefracs_fixed[i]] = convert(numtype,rxnrun.odefracs_ini[rxnrun.odefracs_fixed[i]]) 
                        push!(x__ode_const_indxs,rxnrun.odefracs_fixed[i])
                    end 
                end 
                x__ode_refstates_nuflags = fill(false,rxnsystem.odespecies.cnt)
                x__ode_refstates_values  = zeros(numtype,rxnsystem.odespecies.cnt) 
                for i in axes(rxnsystem.odespecies.indxs_gas,1) 
                    if length(solv_num_fmt) > 0 
                        if lowercase(solv_num_fmt) == "bigfloat"
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_gas[i]] = BigFloat(string(rxnrun.solveroptions.ode_ref_pressure.value)) 
                        else 
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_gas[i]] = convert(numtype,rxnrun.solveroptions.ode_ref_pressure.value)
                        end 
                    else 
                        if rxnrun.solveroptions.ode_num_fmt_class == "bigfloat"
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_gas[i]] = BigFloat(string(rxnrun.solveroptions.ode_ref_pressure.value)) 
                        else 
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_gas[i]] = convert(numtype,rxnrun.solveroptions.ode_ref_pressure.value)
                        end 
                    end 
                    x__ode_refstates_nuflags[rxnsystem.odespecies.indxs_gas[i]] = (x__ode_refstates_values[rxnsystem.odespecies.indxs_gas[i]] != one(x__ode_refstates_values[rxnsystem.odespecies.indxs_gas[i]]))
                end 
                for i in axes(rxnsystem.odespecies.indxs_nongas,1) 
                    if length(solv_num_fmt) > 0 
                        if lowercase(solv_num_fmt) == "bigfloat"
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_nongas[i]] = BigFloat(string(rxnrun.solveroptions.ode_ref_coverage.value)) 
                        else 
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_nongas[i]] = convert(numtype,rxnrun.solveroptions.ode_ref_coverage.value)
                        end 
                    else 
                        if rxnrun.solveroptions.ode_num_fmt_class == "bigfloat"
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_nongas[i]] = BigFloat(string(rxnrun.solveroptions.ode_ref_coverage.value)) 
                        else 
                            x__ode_refstates_values[rxnsystem.odespecies.indxs_nongas[i]] = convert(numtype,rxnrun.solveroptions.ode_ref_coverage.value)
                        end 
                    end 
                    x__ode_refstates_nuflags[rxnsystem.odespecies.indxs_nongas[i]] = (x__ode_refstates_values[rxnsystem.odespecies.indxs_nongas[i]] != one(x__ode_refstates_values[rxnsystem.odespecies.indxs_nongas[i]]))
                end 
                x__ode_const_avals = zeros(numtype,rxnsystem.odespecies.cnt,rxnsystem.reactions.cnt)
                for i in 1:rxnsystem.odespecies.cnt
                    if x__ode_const_flags[i] == true 
                        for j in 1:rxnsystem.reactions.cnt 
                            if get_elemindex(x__ode_gas_indxs,i,0) > 0 && get_elemindex(rxnsystem.reactions.rxntypes_ads_hke,j,0) > 0 && rxnrun.solveroptions.ode_krate_gaspress_flag == true 
                                x__ode_aflags[i,j] = false
                            end 
                            if x__ode_refstates_nuflags[i] == true
                                x__ode_const_avals[i,j] = ((x__ode_const_vals[i] / x__ode_refstates_values[i]) ^ rxnsystem.reactions.coeffs_gamma[i,j]) 
                            else
                                x__ode_const_avals[i,j] = ((x__ode_const_vals[i]) ^ rxnsystem.reactions.coeffs_gamma[i,j]) 
                            end 
                        end 
                    end 
                end 
            end 

            # Construct object 
            if err_flag == false 
                temprun_odeparams = ct__TempRun_ODEParams(
                                            x__ode_cnt, x__ode_names, x__ode_types, x__ode_aflags, x__ode_inifracs, 
                                            x__ode_gas_cnt, x__ode_gas_indxs, x__ode_gas_momentum, 
                                            x__ode_nongas_cnt, x__ode_nongas_indxs, x__ode_ads_cnt, x__ode_ads_indxs, x__ode_coads_cnt, x__ode_coads_indxs, x__ode_site_cnt, x__ode_site_indxs, 
                                            x__ode_adscoads_cnt, x__ode_adscoads_indxs, x__ode_siteads_cnt, x__ode_siteads_indxs, x__ode_siteads_adsindxs, x__ode_siteads_siteindxs, 
                                            x__ode_odeindex2nongasindex, x__ode_rxntypes, x__ode_adsorb_gas_odeindxs, x__ode_scaling_uscale_flag, x__ode_scaling_uscale_unityflags, 
                                            x__ode_scaling_uscale_factors, x__ode_scaling_tflag, x__ode_scaling_tunityflag, x__ode_scaling_tfactor, x__ode_include_spcs_g, x__ode_include_spcs_n, x__ode_include_rxns_r, x__ode_rate_assigned_nopos, x__ode_rate_assigned_noneg, 
                                            x__ode_const_flags, x__ode_const_nzflags, x__ode_const_vals, x__ode_const_avals, x__ode_const_indxs, 
                                            x__ode_refstates_nuflags, x__ode_refstates_values, x__ode_krate_gaspress_flag, x__ode_solpts_interp_flag, 
                                            x__ode_solpts_interp_mag_min, x__ode_solpts_interp_mag_max, x__ode_solpts_interp_pts_min, x__ode_solpts_interp_pts_max
                                        )
            end 
        end 

        return err_flag, err_msg, temprun_odeparams 
    end 

    function Init__Temprun__ReactionParameters(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, numtype::Type) 
        
        # this precalculates and converts values to the Temprun number type to reduce number conversions in performance critical sections
        # this also prepares arrays that optimize looping calculations

        # Check error state 
        temprun_rxnparams = ct__TempRun_ReactionParams(numtype) 
        if err_flag == false 
              
            # Calculate values
            if err_flag == false 
                x__rxns_cnt         = rxnsystem.reactions.cnt 
                x__rxns_names       = deepcopy(rxnsystem.reactions.names)
                x__rxns_pairs_indxs = get_elemindex(rxnsystem.reactions.pairs_names,rxnsystem.reactions.pairnames,0) 
                x__rxns_gascnt      = 0 
                for i in 1:rxnsystem.configurations.states_indxs_gas_cnt
                    if sum(view(rxnsystem.reactions.coeffs_states,:,:,:,rxnsystem.configurations.states_indxs_gas[i])) > 0 
                        x__rxns_gascnt += 1
                    end 
                end 
                x__rxns_ratefactors          = convert.(numtype,deepcopy(rxnsystem.reactions.kratefactors)) 
                x__rxns_ratefactors_nzflags  = fill(false,rxnsystem.reactions.cnt) 
                x__rxns_ratefactors_nzuflags = fill(false,rxnsystem.reactions.cnt)
                x__rxns_tsrbalances          = convert.(numtype,deepcopy(rxnsystem.reactions.tsrbalances)) 
                x__rxns_tspbalances          = convert.(numtype,deepcopy(rxnsystem.reactions.tspbalances)) 
                x__rxns_pairs_tsrbalances    = convert.(numtype,deepcopy(rxnsystem.reactions.pairs_tsrbalances)) 
                x__rxns_pairs_tspbalances    = convert.(numtype,deepcopy(rxnsystem.reactions.pairs_tspbalances)) 
                x__rxns_adshkeflags          = fill(false,rxnsystem.reactions.cnt)
                x__rxns_adsrxnindxs          = deepcopy(rxnsystem.reactions.adsorb_adsrxnindxs) 
                x__rxns_adsfluxfactors       = zeros(numtype,rxnsystem.reactions.cnt)
                x__rxns_deskeqflags          = fill(false,rxnsystem.reactions.cnt)
                for i in 1:rxnsystem.reactions.cnt 
                    if x__rxns_ratefactors[i] != zero(x__rxns_ratefactors[i])
                        x__rxns_ratefactors_nzflags[i] = true 
                        if x__rxns_ratefactors[i] == one(x__rxns_ratefactors[i])
                            x__rxns_ratefactors_nzuflags[i] = true 
                        end 
                    end 
                    if get_elemindex(rxnsystem.reactions.rxntypes_ads_hke,i,0) > 0 
                        x__rxns_adshkeflags[i] = true
                        x__gasodeindx   = rxnsystem.reactions.adsorb_gas_odeindxs[i] 
                        x__adsphaseindx = rxnsystem.reactions.adsorb_ads_phaseindxs[i] 
                        if x__gasodeindx > 0 && x__adsphaseindx > 0 
                            x__gasodegasindx  = get_elemindex(rxnsystem.odespecies.indxs_gas,x__gasodeindx,0)
                            x__adssurfphsindx = get_elemindex(rxnsystem.phases.indxs_surfs,x__adsphaseindx,0)
                            if x__gasodegasindx > 0 && x__adssurfphsindx > 0 
                                x__n = abs(rxnsystem.reactions.coeffs_alpha[x__gasodeindx,i])
                                if rxnrun.solveroptions.ode_krate_gaspress_flag == true 
                                    x__u = convert(numtype,rxnrun.odefracs_ini[x__gasodeindx])
                                else
                                    x__u = one(numtype)
                                end 
                                x__rxns_adsfluxfactors[i] = convert(numtype, 
                                                                temprun_constparams.nvs_kbt_hp_1_s * 
                                                                (
                                                                    (
                                                                        (
                                                                            conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, x__u, rxnrun.solveroptions.ode_ref_pressure.units, "Pa") * 
                                                                            rxnsystem.phases.cellareas_m2[x__adssurfphsindx]
                                                                        ) / 
                                                                        (
                                                                            x__n * 
                                                                            temprun_odeparams.ode_gas_momentum[x__gasodegasindx] * 
                                                                            temprun_constparams.nvs_kbt_hp_1_s
                                                                        )
                                                                    ) ^ x__n
                                                                )
                                                            ) 
                            end 
                        end 
                    elseif get_elemindex(rxnsystem.reactions.rxntypes_des_keq,i,0) > 0 
                        x__rxns_deskeqflags[i] = true
                    end 
                end 
                x__coeffs_pairs             = convert.(numtype,rxnsystem.reactions.pairs_rxncoeffs)
                x__coeffs_alpha_t           = convert.(numtype,get_transpose(rxnsystem.reactions.coeffs_alpha))
                x__coeffs_alpha_t_nzflags   = fill(false,size(x__coeffs_alpha_t))
                x__coeffs_alpha_t_nzpuflags = fill(false,size(x__coeffs_alpha_t))
                x__coeffs_alpha_t_nznuflags = fill(false,size(x__coeffs_alpha_t))
                for i in axes(x__coeffs_alpha_t,1)
                    for j in axes(x__coeffs_alpha_t,2)
                        if abs(x__coeffs_alpha_t[i,j]) >= 0.0001 * one(x__coeffs_alpha_t[i,j])
                            x__coeffs_alpha_t_nzflags[i,j] = true
                            if x__coeffs_alpha_t[i,j] == one(x__coeffs_alpha_t[i,j])
                                x__coeffs_alpha_t_nzpuflags[i,j] = true
                            elseif x__coeffs_alpha_t[i,j] == -1 * one(x__coeffs_alpha_t[i,j])
                                x__coeffs_alpha_t_nznuflags[i,j] = true
                            end 
                        end 
                    end 
                end 
                x__coeffs_alphabeta_t           = convert.(numtype,get_transpose(rxnsystem.reactions.coeffs_alpha .* rxnsystem.reactions.coeffs_beta))
                x__coeffs_alphabeta_t_nzflags   = fill(false,size(x__coeffs_alphabeta_t))
                x__coeffs_alphabeta_t_nzpuflags = fill(false,size(x__coeffs_alphabeta_t))
                x__coeffs_alphabeta_t_nznuflags = fill(false,size(x__coeffs_alphabeta_t))
                for i in axes(x__coeffs_alphabeta_t,1)
                    for j in axes(x__coeffs_alphabeta_t,2)
                        if abs(x__coeffs_alphabeta_t[i,j]) >= 0.0001 * one(x__coeffs_alphabeta_t[i,j])
                            x__coeffs_alphabeta_t_nzflags[i,j] = true
                            if x__coeffs_alphabeta_t[i,j] == one(x__coeffs_alphabeta_t[i,j])
                                x__coeffs_alphabeta_t_nzpuflags[i,j] = true
                            elseif x__coeffs_alphabeta_t[i,j] == -1 * one(x__coeffs_alphabeta_t[i,j])
                                x__coeffs_alphabeta_t_nznuflags[i,j] = true
                            end 
                        end 
                    end 
                end 
                x__coeffs_gamma           = convert.(numtype,rxnsystem.reactions.coeffs_gamma)
                x__coeffs_gamma_nzflags   = fill(false,size(x__coeffs_gamma))
                x__coeffs_gamma_nzpuflags = fill(false,size(x__coeffs_gamma))
                x__coeffs_gamma_nznuflags = fill(false,size(x__coeffs_gamma))
                for i in axes(x__coeffs_gamma,1)
                    for j in axes(x__coeffs_gamma,2)
                        if abs(x__coeffs_gamma[i,j]) >= 0.0001 * one(x__coeffs_gamma[i,j])
                            x__coeffs_gamma_nzflags[i,j] = true
                            if x__coeffs_gamma[i,j] == one(x__coeffs_gamma[i,j])
                                x__coeffs_gamma_nzpuflags[i,j] = true
                            elseif x__coeffs_gamma[i,j] == -1 * one(x__coeffs_gamma[i,j])
                                x__coeffs_gamma_nznuflags[i,j] = true
                            end 
                        end 
                    end 
                end 
            end 

            # Construct object 
            if err_flag == false 
                temprun_rxnparams = ct__TempRun_ReactionParams(x__rxns_cnt, x__rxns_names, x__rxns_pairs_indxs, x__rxns_gascnt, x__rxns_ratefactors, x__rxns_ratefactors_nzflags, x__rxns_ratefactors_nzuflags, x__rxns_tsrbalances, x__rxns_tspbalances, x__rxns_pairs_tsrbalances, x__rxns_pairs_tspbalances, x__rxns_adshkeflags, x__rxns_adsrxnindxs, x__rxns_adsfluxfactors, x__rxns_deskeqflags, x__coeffs_pairs, x__coeffs_alpha_t, x__coeffs_alpha_t_nzflags, x__coeffs_alpha_t_nzpuflags, x__coeffs_alpha_t_nznuflags, x__coeffs_alphabeta_t, x__coeffs_alphabeta_t_nzflags, x__coeffs_alphabeta_t_nzpuflags, x__coeffs_alphabeta_t_nznuflags, x__coeffs_gamma, x__coeffs_gamma_nzflags, x__coeffs_gamma_nzpuflags, x__coeffs_gamma_nznuflags)
            end 
        end 

        return err_flag, err_msg, temprun_rxnparams 
    end 

    function Init__Temprun__FreeEnergyParameters(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, numtype::Type) 
        
        # this precalculates and converts values to the Temprun number type to reduce number conversions in performance critical sections
        # this also prepares arrays that optimize looping calculations

        # Check error state 
        temprun_relGparams = ct__TempRun_FreeEnergyParams(numtype) 
        if err_flag == false 
            if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0

                # Calculate values
                if err_flag == false 
                    x__ode_ads_names                        = get_view(view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_ads))
                    x__ode_adscoads_names                   = get_view(view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_adscoads))
                    x__states_adscoads_names                = get_view(view(rxnsystem.configurations.states_names,rxnsystem.configurations.states_indxs_adscoads)) 
                    x__configs_refadscoads_indxs            = unique(vcat(rxnsystem.configurations.indxs_ref,rxnsystem.configurations.uniquecovs_indxs_adscoads))
                    x__configs_refadscoads_subindxs_nocoads = Array{Int,1}(undef,0)
                    for i in axes(x__configs_refadscoads_indxs,1) 
                        if sum(rxnsystem.configurations.coeffs_states[x__configs_refadscoads_indxs[i],:,rxnsystem.configurations.states_indxs_coads]) <= 0 
                            push!(x__configs_refadscoads_subindxs_nocoads,i)
                        end 
                    end 
                    x__refinit_cfgs_xcovs_cfgindxs   = get_view(view(x__configs_refadscoads_indxs,x__configs_refadscoads_subindxs_nocoads))
                    x__interpcmpds_cnt               = size(rxnrun.solveroptions.interp_cmpds_stateindxs,1)
