                    x__aryG_kcalc_gindxs     = zeros(Int,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gtypes     = fill("",x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gmodes     = fill("",x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gsegindxs  = zeros(Int,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gflags     = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gnzpuflags = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gnznuflags = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_kcalc_gfactors   = zeros(numtype,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gmaxc      = 0 
                    x__aryG_updts_gindxs     = zeros(Int,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gtypes     = fill("",x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gmodes     = fill("",x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gsegindxs  = zeros(Int,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gflags     = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gnzpuflags = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gnznuflags = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_updts_gfactors   = zeros(numtype,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gmaxc      = 0 
                    x__aryG_rxndg_gindxs     = zeros(Int,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gtypes     = fill("",x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gmodes     = fill("",x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gsegindxs  = zeros(Int,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gflags     = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gnzpuflags = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gnznuflags = fill(false,x__kmax,rxnsystem.reactions.cnt) 
                    x__aryG_rxndg_gfactors   = zeros(numtype,x__kmax,rxnsystem.reactions.cnt) 
                    for i in 1:rxnsystem.reactions.cnt
                        x__kcalc_gmaxc = 0
                        x__updts_gmaxc = 0 
                        x__rxndg_gmaxc = 0 
                        for j in 1:rxnsystem.reactions.rxnsegs_cnt 
                            for k in 1:x__kcomps_gindxs_maxc 
                                x__gindex = x__kcomps_gindxs[i,j,k]
                                if x__gindex > 0
                                    x__gsubindx = 0 
                                    for l in axes(x__aryG_rxnindxs[x__gindex],1)
                                        if x__aryG_rxnindxs[x__gindex][l] == i && x__aryG_segindxs[x__gindex][l] == j 
                                            x__gsubindx = l 
                                            break 
                                        end 
                                    end 
                                    if x__gsubindx > 0 
                                        if x__aryG_kcalcflags[x__gindex][x__gsubindx] == true 
                                            x__kcalc_gmaxc += 1 
                                            x__aryG_kcalc_gindxs[x__kcalc_gmaxc,i]     = x__gindex
                                            x__aryG_kcalc_gtypes[x__kcalc_gmaxc,i]     = x__aryG_gtypes[x__gindex] 
                                            x__aryG_kcalc_gmodes[x__kcalc_gmaxc,i]     = x__aryG_gmodes[x__gindex] 
                                            x__aryG_kcalc_gsegindxs[x__kcalc_gmaxc,i]  = j 
                                            x__aryG_kcalc_gflags[x__kcalc_gmaxc,i]     = x__aryG_kcalcflags[x__gindex][x__gsubindx]
                                            x__aryG_kcalc_gnzpuflags[x__kcalc_gmaxc,i] = x__aryG_kcalcnzpuflags[x__gindex][x__gsubindx]
                                            x__aryG_kcalc_gnznuflags[x__kcalc_gmaxc,i] = x__aryG_kcalcnznuflags[x__gindex][x__gsubindx]
                                            x__aryG_kcalc_gfactors[x__kcalc_gmaxc,i]   = x__aryG_kcalcfactors[x__gindex][x__gsubindx]
                                        end
                                        if x__aryG_updtsflags[x__gindex][x__gsubindx] == true 
                                            x__updts_gmaxc += 1 
                                            x__aryG_updts_gindxs[x__updts_gmaxc,i]     = x__gindex
                                            x__aryG_updts_gtypes[x__updts_gmaxc,i]     = x__aryG_gtypes[x__gindex] 
                                            x__aryG_updts_gmodes[x__updts_gmaxc,i]     = x__aryG_gmodes[x__gindex] 
                                            x__aryG_updts_gsegindxs[x__updts_gmaxc,i]  = j 
                                            x__aryG_updts_gflags[x__updts_gmaxc,i]     = x__aryG_updtsflags[x__gindex][x__gsubindx]
                                            x__aryG_updts_gnzpuflags[x__updts_gmaxc,i] = x__aryG_updtsnzpuflags[x__gindex][x__gsubindx]
                                            x__aryG_updts_gnznuflags[x__updts_gmaxc,i] = x__aryG_updtsnznuflags[x__gindex][x__gsubindx]
                                            x__aryG_updts_gfactors[x__updts_gmaxc,i]   = x__aryG_updtsfactors[x__gindex][x__gsubindx]
                                        end
                                        if x__aryG_rxndgflags[x__gindex][x__gsubindx] == true 
                                            x__rxndg_gmaxc += 1 
                                            x__aryG_rxndg_gindxs[x__rxndg_gmaxc,i]     = x__gindex
                                            x__aryG_rxndg_gtypes[x__rxndg_gmaxc,i]     = x__aryG_gtypes[x__gindex] 
                                            x__aryG_rxndg_gmodes[x__rxndg_gmaxc,i]     = x__aryG_gmodes[x__gindex] 
                                            x__aryG_rxndg_gsegindxs[x__rxndg_gmaxc,i]  = j 
                                            x__aryG_rxndg_gflags[x__rxndg_gmaxc,i]     = x__aryG_rxndgflags[x__gindex][x__gsubindx]
                                            x__aryG_rxndg_gnzpuflags[x__rxndg_gmaxc,i] = x__aryG_rxndgnzpuflags[x__gindex][x__gsubindx]
                                            x__aryG_rxndg_gnznuflags[x__rxndg_gmaxc,i] = x__aryG_rxndgnznuflags[x__gindex][x__gsubindx]
                                            x__aryG_rxndg_gfactors[x__rxndg_gmaxc,i]   = x__aryG_rxndgfactors[x__gindex][x__gsubindx]
                                        end
                                    end 
                                end 
                            end
                        end
                        x__aryG_kcalc_gmaxc = max(x__aryG_kcalc_gmaxc,x__kcalc_gmaxc)
                        x__aryG_updts_gmaxc = max(x__aryG_updts_gmaxc,x__updts_gmaxc)
                        x__aryG_rxndg_gmaxc = max(x__aryG_rxndg_gmaxc,x__rxndg_gmaxc)
                    end 
                    if x__aryG_kcalc_gmaxc > 0 
                        x__aryG_kcalc_gindxs     = get_view(view(x__aryG_kcalc_gindxs,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gtypes     = get_view(view(x__aryG_kcalc_gtypes,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gmodes     = get_view(view(x__aryG_kcalc_gmodes,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gsegindxs  = get_view(view(x__aryG_kcalc_gsegindxs,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gflags     = get_view(view(x__aryG_kcalc_gflags,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gnzpuflags = get_view(view(x__aryG_kcalc_gnzpuflags,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gnznuflags = get_view(view(x__aryG_kcalc_gnznuflags,1:x__aryG_kcalc_gmaxc,:))
                        x__aryG_kcalc_gfactors   = get_view(view(x__aryG_kcalc_gfactors,1:x__aryG_kcalc_gmaxc,:))
                    end 
                    if x__aryG_updts_gmaxc > 0 
                        x__aryG_updts_gindxs     = get_view(view(x__aryG_updts_gindxs,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gtypes     = get_view(view(x__aryG_updts_gtypes,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gmodes     = get_view(view(x__aryG_updts_gmodes,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gsegindxs  = get_view(view(x__aryG_updts_gsegindxs,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gflags     = get_view(view(x__aryG_updts_gflags,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gnzpuflags = get_view(view(x__aryG_updts_gnzpuflags,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gnznuflags = get_view(view(x__aryG_updts_gnznuflags,1:x__aryG_updts_gmaxc,:))
                        x__aryG_updts_gfactors   = get_view(view(x__aryG_updts_gfactors,1:x__aryG_updts_gmaxc,:))
                    end 
                    if x__aryG_rxndg_gmaxc > 0 
                        x__aryG_rxndg_gindxs     = get_view(view(x__aryG_rxndg_gindxs,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gtypes     = get_view(view(x__aryG_rxndg_gtypes,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gmodes     = get_view(view(x__aryG_rxndg_gmodes,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gsegindxs  = get_view(view(x__aryG_rxndg_gsegindxs,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gflags     = get_view(view(x__aryG_rxndg_gflags,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gnzpuflags = get_view(view(x__aryG_rxndg_gnzpuflags,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gnznuflags = get_view(view(x__aryG_rxndg_gnznuflags,1:x__aryG_rxndg_gmaxc,:))
                        x__aryG_rxndg_gfactors   = get_view(view(x__aryG_rxndg_gfactors,1:x__aryG_rxndg_gmaxc,:))
                    end 
                    x__aryG_interp_cmpds_cnt      = rxnrun.solveroptions.interp_cmpds_cnt
                    x__aryG_interp_cmpds_names    = get_view(view(rxnsystem.configurations.states_names,rxnrun.solveroptions.interp_cmpds_stateindxs))
                    x__aryG_interp_cmpds_odeindxs = deepcopy(rxnrun.solveroptions.interp_cmpds_odeindxs) 
                    x__aryG_interp_cmpds_odesubindxs_nongas = get_elemindex(rxnsystem.odespecies.indxs_nongas,rxnrun.solveroptions.interp_cmpds_odeindxs,0) 
                    x__aryG_rxngindxs    = zeros(Int,rxnsystem.reactions.cnt,rxnsystem.reactions.rxnsegs_cnt) 
                    x__aryG_rxngsubindxs = zeros(Int,rxnsystem.reactions.cnt,rxnsystem.reactions.rxnsegs_cnt) 
                    for i in 1:rxnsystem.reactions.cnt 
                        for j in 1:rxnsystem.reactions.rxnsegs_cnt 
                            x__gtype = ""
                            x__gmode = "" 
                            for k in 1:x__aryG_cnt 
                                x__lflag = false
                                if x__aryG_gtypes[k] == "tst" 
                                    x__lflag = true 
                                else
                                    if x__aryG_gtypes[k] == "var" && x__aryG_gmodes[k] == "srf" 
                                        if x__gtype != "tst"
                                            x__lflag = true
                                        end 
                                    else
                                        if x__aryG_gtypes[k] == "ref" && x__aryG_gmodes[k] == "cfg" 
                                            if x__gtype != "tst" && x__gtype != "var"
                                                x__lflag = true 
                                            end 
                                        end 
                                    end
                                end 
                                if x__lflag == true 
                                    for l in axes(x__aryG_rxnindxs[k],1)
                                        if x__aryG_rxnindxs[k][l] == i && x__aryG_segindxs[k][l] == j 
                                            x__aryG_rxngindxs[i,j] = k 
                                            x__aryG_rxngsubindxs[i,j] = l 
                                            x__gtype = x__aryG_gtypes[k]
                                            x__gmode = x__aryG_gmodes[k]
                                            break 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                    x__aryG_rxngunqindxs      = zeros(Int,rxnsystem.reactions.cnt,rxnsystem.reactions.rxnsegs_cnt) 
                    x__aryG_rxngunqindxs_rcts = zeros(Int,rxnsystem.reactions.cnt) 
                    x__aryG_rxngunqindxs_prds = zeros(Int,rxnsystem.reactions.cnt) 
                    x__aryG_rxnuniquevar      = Array{Int,1}(undef,0)
                    x__aryG_rxnuniquevar_cnt  = 0
                    x__aryG_interp_rxnvecs = zeros(numtype,rxnsystem.reactions.cnt,rxnsystem.odespecies.indxs_ads_cnt)
                    for i in 1:rxnsystem.reactions.cnt 
                        for j in 1:rxnsystem.reactions.rxnsegs_cnt 
                            x__gindex = x__aryG_rxngindxs[i,j]
                            if x__gindex > 0 
                                if x__aryG_gtypes[x__gindex] == "var" && (j == rxnsystem.reactions.rxnsegs_dindxs["rcts"] || j == rxnsystem.reactions.rxnsegs_dindxs["prds"]) 
                                    x__indx = get_elemindex(x__aryG_rxnuniquevar,x__gindex,0)
                                    if x__indx <= 0 
                                        push!(x__aryG_rxnuniquevar,x__gindex)
                                        x__aryG_rxnuniquevar_cnt += 1
                                        x__indx = x__aryG_rxnuniquevar_cnt
                                    end 
                                    x__aryG_rxngunqindxs[i,j] = x__indx
                                    if j == rxnsystem.reactions.rxnsegs_dindxs["rcts"] 
                                        x__aryG_rxngunqindxs_rcts[i] = x__indx
                                    elseif j == rxnsystem.reactions.rxnsegs_dindxs["prds"] 
                                        x__aryG_rxngunqindxs_prds[i] = x__indx
                                    end 
                                end 
                            end 
                        end 
                        for j in 1:rxnsystem.odespecies.indxs_ads_cnt
                            r__indx = x__aryG_rxngunqindxs[i,rxnsystem.reactions.rxnsegs_dindxs["rcts"]]
                            p__indx = x__aryG_rxngunqindxs[i,rxnsystem.reactions.rxnsegs_dindxs["prds"]]
                            if r__indx > 0 && p__indx > 0 
                                ur__indx = x__aryG_rxnuniquevar[r__indx]
                                up__indx = x__aryG_rxnuniquevar[p__indx]
                                if up__indx > 0 && x__indxconvs_odeads2odeadscoads[j] > 0 
                                    x__aryG_interp_rxnvecs[i,j] = x__aryG_adjcovs[up__indx][x__indxconvs_odeads2odeadscoads[j]] - x__aryG_adjcovs[ur__indx][x__indxconvs_odeads2odeadscoads[j]]
                                end 
                            end 
                        end 
                    end 
                    x__aryG_interp_diffcovs_stepcnt = rxnrun.solveroptions.interp_diffcovs_stepcnt
                end 

                # Construct object
                if err_flag == false 
                    temprun_relGparams = ct__TempRun_FreeEnergyParams(           
                                                x__aryG_cnt, x__aryG_gindxs, x__aryG_gnames, x__aryG_gtitles, x__aryG_gtypes, x__aryG_gmodes, x__aryG_gpairs, x__aryG_extra_r, x__aryG_extra_s, x__aryG_extra_c, 
                                                x__aryG_rxnindxs, x__aryG_segindxs, x__aryG_rxngindxs_rgo, x__aryG_rxngindxs_rdg, x__aryG_adjcovs, x__aryG_adjcovs_titles, 
                                                x__aryG_ref_cnt, x__aryG_ref_gindxs, x__aryG_var_cnt, x__aryG_var_gindxs, x__aryG_tst_cnt, x__aryG_tst_gindxs, 
                                                x__aryG_kcalc_gmaxc, x__aryG_kcalc_gindxs, x__aryG_kcalc_gflags, x__aryG_kcalc_gnzpuflags, x__aryG_kcalc_gnznuflags, x__aryG_kcalc_gfactors, 
                                                x__aryG_updts_gmaxc, x__aryG_updts_gindxs, x__aryG_updts_gflags, x__aryG_updts_gnzpuflags, x__aryG_updts_gnznuflags, x__aryG_updts_gfactors, 
                                                x__aryG_rxndg_gmaxc, x__aryG_rxndg_gindxs, x__aryG_rxndg_gflags, x__aryG_rxndg_gnzpuflags, x__aryG_rxndg_gnznuflags, x__aryG_rxndg_gfactors, 
                                                x__aryG_interp_cmpds_cnt, x__aryG_interp_cmpds_names, x__aryG_interp_cmpds_odeindxs, x__aryG_interp_cmpds_odesubindxs_nongas, x__aryG_interp_rxnvecs, x__aryG_interp_diffcovs_stepcnt, 
                                                x__refinit_cfgs_unscaledcovs, x__refinit_cfgs_scaledcovs, x__refinit_cfgs_xcovs_cfgindxs, 
                                                x__refinit_adscoads_cnt, x__refinit_adscoads_indxs, x__refinit_adscoads_ncnt, x__refinit_adscoads_nindxs, 
                                                x__refinit_adscoads_covs, x__refinit_adscoads_cnts, x__refinit_adscoads_maxcnt, x__refinit_adscoads_maxcovs, 
                                                x__refinit_coads_cnts, x__refinit_coads_covs, x__refinit_coads_adscoadsindxs, 
                                                x__refinit_sites_cnts, x__refinit_sites_maxcnts, 
                                                x__refinit_interp_adscoads_byunscaledcovs_adscoadsscaledcovs, x__refinit_interp_adscoads_byscaledcovs_adscoadscnts, x__refinit_interp_adscoads_byscaledcovs_sitescnts
                                            )
                end 
            end
        end 

        return err_flag, err_msg, temprun_relGparams 
    end 

    function Init__Temprun__RateConstantParameters(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, numtype::Type) 
        
        # Check error state 
        temprun_kcnstparams = ct__TempRun_RateConstParams(numtype) 
        if err_flag == false 

            # assigned rate constants 
            if size(rxnsystem.reactions.kupdmodes_assigned,1) > 0 

                # Calculate values
                if err_flag == false 
                    x__kcnsts_assigned_cnt              = size(rxnsystem.reactions.kupdmodes_assigned,1)
                    x__kcnsts_assigned_indxs            = deepcopy(rxnsystem.reactions.kupdmodes_assigned) 
                    x__kcnsts_assigned_kvals            = convert.(numtype,rxnsystem.reactions.kfactors) 
                    x__kcnsts_assigned_stateflags_maxc  = 0 
                    x__kcnsts_assigned_stateflags_indxs = Array{Int,2}(undef,0,0) 
                    x__kcnsts_assigned_statefactors     = Array{numtype,2}(undef,0,0) 
                    if x__kcnsts_assigned_cnt > 0 
                        for i in 1:x__kcnsts_assigned_cnt 
                            x__cnt = 0 
                            for j in 1:rxnsystem.configurations.states_cnt 
                                if sum(rxnsystem.reactions.coeffs_states[x__kcnsts_assigned_indxs[i],rxnsystem.reactions.rxnsegs_indxs.rcts,:,j]) > 0 
                                    x__cnt += 1
                                elseif sum(rxnsystem.reactions.coeffs_states[x__kcnsts_assigned_indxs[i],rxnsystem.reactions.rxnsegs_indxs.tsts,:,j]) > 0 
                                    x__cnt += 1
                                end 
                            end 
                            x__kcnsts_assigned_stateflags_maxc = max(x__kcnsts_assigned_stateflags_maxc,x__cnt)
                        end 
                        if x__kcnsts_assigned_stateflags_maxc > 0 
                            x__kcnsts_assigned_stateflags_indxs = zeros(Int,x__kcnsts_assigned_stateflags_maxc,x__kcnsts_assigned_cnt)
                            x__kcnsts_assigned_statefactors     = zeros(numtype,x__kcnsts_assigned_stateflags_maxc,x__kcnsts_assigned_cnt)
                            for i in 1:x__kcnsts_assigned_cnt 
                                x__cnt = 0 
                                for j in 1:rxnsystem.configurations.states_cnt 
                                    if sum(rxnsystem.reactions.coeffs_states[x__kcnsts_assigned_indxs[i],rxnsystem.reactions.rxnsegs_indxs.rcts,:,j]) > 0 
                                        x__cnt += 1
                                        x__kcnsts_assigned_stateflags_indxs[x__cnt,i] = j
                                        x__kcnsts_assigned_statefactors[x__cnt,i] = -1 * sum(rxnsystem.reactions.coeffs_states[x__kcnsts_assigned_indxs[i],rxnsystem.reactions.rxnsegs_indxs.rcts,:,j])
                                    elseif sum(rxnsystem.reactions.coeffs_states[x__kcnsts_assigned_indxs[i],rxnsystem.reactions.rxnsegs_indxs.tsts,:,j]) > 0 
                                        x__cnt += 1
                                        x__kcnsts_assigned_stateflags_indxs[x__cnt,i] = j
                                        x__kcnsts_assigned_statefactors[x__cnt,i] = +1 * sum(rxnsystem.reactions.coeffs_states[x__kcnsts_assigned_indxs[i],rxnsystem.reactions.rxnsegs_indxs.tsts,:,j])
                                    end 
                                end 
                            end 
                        end
                    end 
                end 

                # Update object 
                if err_flag == false 
                    temprun_kcnstparams.kcnsts_assigned_cnt              = x__kcnsts_assigned_cnt 
                    temprun_kcnstparams.kcnsts_assigned_indxs            = deepcopy(x__kcnsts_assigned_indxs) 
                    temprun_kcnstparams.kcnsts_assigned_kvals            = deepcopy(x__kcnsts_assigned_kvals) 
                    temprun_kcnstparams.kcnsts_assigned_stateflags_maxc  = x__kcnsts_assigned_stateflags_maxc 
                    temprun_kcnstparams.kcnsts_assigned_stateflags_indxs = deepcopy(x__kcnsts_assigned_stateflags_indxs) 
                    temprun_kcnstparams.kcnsts_assigned_statefactors     = deepcopy(x__kcnsts_assigned_statefactors) 
                end 
            end 

            # Non-assigned rate constants 
            if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0
        
                # Calculate values
                if err_flag == false 
                    x__kcnsts_nonassigned_cnt   = size(rxnsystem.reactions.kupdmodes_nonassigned,1)
                    x__kcnsts_nonassigned_indxs = deepcopy(rxnsystem.reactions.kupdmodes_nonassigned)
                    x__kcnsts_calc_cnt          = size(rxnsystem.reactions.kupdmodes_nonassigned,1) 
                    x__kcnsts_calc_indxs        = deepcopy(rxnsystem.reactions.kupdmodes_nonassigned) 
                    x__kcnsts_calc_varbl_cnt    = 0 
                    x__kcnsts_calc_varbl_indxs  = Array{Int,1}(undef,0)
                    x__kcnsts_calc_variesflags  = fill(false,rxnsystem.reactions.cnt) 
                    for i in 1:rxnsystem.reactions.cnt 
                        if get_elemindex(rxnsystem.reactions.rxntypes_ads_hke_varbl,i,0) > 0 || get_elemindex(rxnsystem.reactions.rxntypes_des_keq_varbl,i,0) > 0 || get_elemindex(rxnsystem.reactions.rxntypes_tst_act_varbl,i,0) > 0 
                            x__kcnsts_calc_varbl_cnt += 1
                            push!(x__kcnsts_calc_varbl_indxs,i)
                            x__kcnsts_calc_variesflags[i] = true 
                        end 
                    end 
                    x__kcnsts_calc_ads_hke_cnt          = size(rxnsystem.reactions.rxntypes_ads_hke,1)
                    x__kcnsts_calc_ads_hke_indxs        = deepcopy(rxnsystem.reactions.rxntypes_ads_hke)
                    x__kcnsts_calc_ads_hke_cindxs       = get_elemindex(rxnsystem.reactions.kupdmodes_nonassigned,x__kcnsts_calc_ads_hke_indxs,0) 
                    x__kcnsts_calc_ads_hke_varbl_cnt    = size(rxnsystem.reactions.rxntypes_ads_hke_varbl,1)
                    x__kcnsts_calc_ads_hke_varbl_indxs  = deepcopy(rxnsystem.reactions.rxntypes_ads_hke_varbl)
                    x__kcnsts_calc_ads_hke_varbl_cindxs = get_elemindex(rxnsystem.reactions.kupdmodes_nonassigned,x__kcnsts_calc_ads_hke_varbl_indxs,0) 
                    x__kcnsts_calc_des_keq_cnt          = size(rxnsystem.reactions.rxntypes_des_keq,1)
                    x__kcnsts_calc_des_keq_indxs        = deepcopy(rxnsystem.reactions.rxntypes_des_keq)
                    x__kcnsts_calc_des_keq_cindxs       = get_elemindex(rxnsystem.reactions.kupdmodes_nonassigned,x__kcnsts_calc_des_keq_indxs,0) 
                    x__kcnsts_calc_des_keq_varbl_cnt    = size(rxnsystem.reactions.rxntypes_des_keq_varbl,1)
                    x__kcnsts_calc_des_keq_varbl_indxs  = deepcopy(rxnsystem.reactions.rxntypes_des_keq_varbl)
                    x__kcnsts_calc_des_keq_varbl_cindxs = get_elemindex(rxnsystem.reactions.kupdmodes_nonassigned,x__kcnsts_calc_des_keq_varbl_indxs,0) 
                    x__kcnsts_calc_tst_act_cnt          = size(rxnsystem.reactions.rxntypes_tst_act,1)
                    x__kcnsts_calc_tst_act_indxs        = deepcopy(rxnsystem.reactions.rxntypes_tst_act)
                    x__kcnsts_calc_tst_act_cindxs       = get_elemindex(rxnsystem.reactions.kupdmodes_nonassigned,x__kcnsts_calc_tst_act_indxs,0) 
                    x__kcnsts_calc_tst_act_varbl_cnt    = size(rxnsystem.reactions.rxntypes_tst_act_varbl,1)
                    x__kcnsts_calc_tst_act_varbl_indxs  = deepcopy(rxnsystem.reactions.rxntypes_tst_act_varbl)
                    x__kcnsts_calc_tst_act_varbl_cindxs = get_elemindex(rxnsystem.reactions.kupdmodes_nonassigned,x__kcnsts_calc_tst_act_varbl_indxs,0) 
                end 

                # Update object 
                if err_flag == false 
                    temprun_kcnstparams.kcnsts_nonassigned_cnt           = x__kcnsts_nonassigned_cnt 
                    temprun_kcnstparams.kcnsts_nonassigned_indxs         = deepcopy(x__kcnsts_nonassigned_indxs) 
                    temprun_kcnstparams.kcnsts_calc_cnt                  = x__kcnsts_calc_cnt 
                    temprun_kcnstparams.kcnsts_calc_indxs                = deepcopy(x__kcnsts_calc_indxs) 
                    temprun_kcnstparams.kcnsts_calc_varbl_cnt            = x__kcnsts_calc_varbl_cnt 
                    temprun_kcnstparams.kcnsts_calc_varbl_indxs          = deepcopy(x__kcnsts_calc_varbl_indxs)
                    temprun_kcnstparams.kcnsts_calc_variesflags          = deepcopy(x__kcnsts_calc_variesflags) 
                    temprun_kcnstparams.kcnsts_calc_ads_hke_cnt          = x__kcnsts_calc_ads_hke_cnt 
                    temprun_kcnstparams.kcnsts_calc_ads_hke_indxs        = deepcopy(x__kcnsts_calc_ads_hke_indxs) 
                    temprun_kcnstparams.kcnsts_calc_ads_hke_cindxs       = deepcopy(x__kcnsts_calc_ads_hke_cindxs) 
                    temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cnt    = x__kcnsts_calc_ads_hke_varbl_cnt 
                    temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_indxs  = deepcopy(x__kcnsts_calc_ads_hke_varbl_indxs) 
                    temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cindxs = deepcopy(x__kcnsts_calc_ads_hke_varbl_cindxs) 
                    temprun_kcnstparams.kcnsts_calc_des_keq_cnt          = x__kcnsts_calc_des_keq_cnt 
                    temprun_kcnstparams.kcnsts_calc_des_keq_indxs        = deepcopy(x__kcnsts_calc_des_keq_indxs) 
                    temprun_kcnstparams.kcnsts_calc_des_keq_cindxs       = deepcopy(x__kcnsts_calc_des_keq_cindxs) 
                    temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cnt    = x__kcnsts_calc_des_keq_varbl_cnt 
                    temprun_kcnstparams.kcnsts_calc_des_keq_varbl_indxs  = deepcopy(x__kcnsts_calc_des_keq_varbl_indxs) 
                    temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cindxs = deepcopy(x__kcnsts_calc_des_keq_varbl_cindxs) 
                    temprun_kcnstparams.kcnsts_calc_tst_act_cnt          = x__kcnsts_calc_tst_act_cnt 
                    temprun_kcnstparams.kcnsts_calc_tst_act_indxs        = deepcopy(x__kcnsts_calc_tst_act_indxs) 
                    temprun_kcnstparams.kcnsts_calc_tst_act_cindxs       = deepcopy(x__kcnsts_calc_tst_act_cindxs) 
                    temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cnt    = x__kcnsts_calc_tst_act_varbl_cnt 
                    temprun_kcnstparams.kcnsts_calc_tst_act_varbl_indxs  = deepcopy(x__kcnsts_calc_tst_act_varbl_indxs) 
                    temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cindxs = deepcopy(x__kcnsts_calc_tst_act_varbl_cindxs) 
                end 
            end 
        end 

        return err_flag, err_msg, temprun_kcnstparams 
    end 

    function Init__Temprun__ConfigsEnergies(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols) 

        cfg_G_ref             = zeros(eltype(temprun_constparams.numelem[1]),1,1)
        cfg_G_ref_gaststs     = zeros(eltype(temprun_constparams.numelem[1]),1,1)
        cfg_evalflags         = fill(false,1) 
        cfg_evalflags_gaststs = fill(false,1) 
        if err_flag == false 
            if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0 
                cfg_G_ref             = zeros(eltype(temprun_constparams.numelem[1]),(rxnsystem.configurations.cnt,cfg_G_refcols.cnt)) 
                cfg_G_ref_gaststs     = zeros(eltype(temprun_constparams.numelem[1]),(rxnsystem.configurations.indxs_gas_cnt,cfg_G_refcols.cnt)) 
                cfg_evalflags         = fill(false,rxnsystem.configurations.cnt) 
                cfg_evalflags_gaststs = fill(false,rxnsystem.configurations.indxs_gas_cnt) 
                err_flag, err_msg     = Init__Temprun__ConfigsEnergies__Reference(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs) 
            end 
        end 

        return err_flag, err_msg, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs  
    end 

    function Init__Temprun__ConfigsEnergies__Columns(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg) 

        rs = cfg_G_refcols = ct__Temprun_Configs_G_Refcols()
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("reference columns"))
            x__names = ["H_U", "H_pV", "H_zpe", "H_vib", "H_trs", "H_rot", "H_tot", "TS_elec", "TS_vib", "TS_trs", "TS_rot", "TS_tot", "G_tot", "G_ref", "G_rel", "active_H_trs", "active_H_rot", "active_TS_trs", "active_TS_rot", "active_G_trs", "active_G_rot"]     
            x__dindxs = Dict{String,Int}() 
            for i in axes(x__names,1)
                x__dindxs[x__names[i]] = i 
            end 
            x__cnt = size(x__names,1) 
            x__colindx_H_U           = x__dindxs["H_U"]
            x__colindx_H_pV          = x__dindxs["H_pV"]
            x__colindx_H_zpe         = x__dindxs["H_zpe"]
            x__colindx_H_vib         = x__dindxs["H_vib"]
            x__colindx_H_trs         = x__dindxs["H_trs"]
            x__colindx_H_rot         = x__dindxs["H_rot"]
            x__colindx_H_tot         = x__dindxs["H_tot"]
            x__colindx_TS_elec       = x__dindxs["TS_elec"] 
            x__colindx_TS_vib        = x__dindxs["TS_vib"]
            x__colindx_TS_trs        = x__dindxs["TS_trs"]
            x__colindx_TS_rot        = x__dindxs["TS_rot"]
            x__colindx_TS_tot        = x__dindxs["TS_tot"]
            x__colindx_G_tot         = x__dindxs["G_tot"]
            x__colindx_G_ref         = x__dindxs["G_ref"]
            x__colindx_G_rel         = x__dindxs["G_rel"]
            x__colindx_active_H_trs  = x__dindxs["active_H_trs"]
            x__colindx_active_H_rot  = x__dindxs["active_H_rot"]
            x__colindx_active_TS_trs = x__dindxs["active_TS_trs"] 
            x__colindx_active_TS_rot = x__dindxs["active_TS_rot"] 
            x__colindx_active_G_trs  = x__dindxs["active_G_trs"] 
            x__colindx_active_G_rot  = x__dindxs["active_G_rot"] 
            rs = ct__Temprun_Configs_G_Refcols(
                    x__cnt, x__names, x__dindxs, 
                    x__colindx_H_U, x__colindx_H_pV, x__colindx_H_zpe, x__colindx_H_vib, x__colindx_H_trs, x__colindx_H_rot, x__colindx_H_tot, 
                    x__colindx_TS_elec, x__colindx_TS_vib, x__colindx_TS_trs, x__colindx_TS_rot, x__colindx_TS_tot, 
                    x__colindx_G_tot, x__colindx_G_ref, x__colindx_G_rel, 
                    x__colindx_active_H_trs, x__colindx_active_H_rot, x__colindx_active_TS_trs, x__colindx_active_TS_rot, x__colindx_active_G_trs, x__colindx_active_G_rot
                )
        end 

        return err_flag, err_msg, rs 
    end 

    function Init__Temprun__ConfigsEnergies__Reference(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs) 

        # This function calculates a set of configurations energies that are associated with known compositions, e.g. from DFT relaxations

        # Check error state
        if err_flag == false 
            err_flag = false 
            err_msg = ""

            # calculate configuration energies - reference lattices
            if err_flag == false 
                err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, "reflats") 
            end 
            
            # calculate configuration energies - bulk phase gases
            if err_flag == false 
                err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, "gasbulk") 
            end

            # calculate configuration energies - gas transition states
            if err_flag == false 
                err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, "gaststs") 
            end

            # calculate configuration energies - surface adsorbates/coadsorbates
            if err_flag == false 
                err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, "surfads") 
            end

            # calculate configuration energies - surface transition states
            if err_flag == false 
                err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, "surftst") 
            end
        end

        return err_flag, err_msg
    end 

    function Init__Temprun__ConfigsEnergies__Category(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, cfg_category) 

        # This function calculates the Gibbs free energies of the specified configurations 
        # G = U + pV + ZPE - TS 

        # Check parameters 
        if err_flag == false 
            if cfg_category == "gasbulk" 
                cfg_gsrcindxs = rxnsystem.configurations.indxs_gas
                cfg_calcindxs = rxnsystem.configurations.indxs_gas
            elseif cfg_category == "gaststs" 
                cfg_gsrcindxs = rxnsystem.configurations.indxs_gas
                cfg_calcindxs = collect(1:rxnsystem.configurations.indxs_gas_cnt)
            elseif cfg_category == "reflats" 
                cfg_gsrcindxs = rxnsystem.configurations.indxs_ref
                cfg_calcindxs = rxnsystem.configurations.indxs_ref
            elseif cfg_category == "surfads" 
                cfg_gsrcindxs = rxnsystem.configurations.indxs_ads
                cfg_calcindxs = rxnsystem.configurations.indxs_ads
            elseif cfg_category == "surftst" 
                cfg_gsrcindxs = rxnsystem.configurations.indxs_tst
                cfg_calcindxs = rxnsystem.configurations.indxs_tst
            else 
                cfg_calcindxs = Array{Int,1}(undef,0) 
                err_flag = true 
            end 
        end 

        # Check error state
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Calculate configurations energies 
            if size(cfg_calcindxs,1) > 0 

                # Initialize working variables 
                if err_flag == false 
                    if rxnrun.qfuncoptions.rot_include == true && (((cfg_category == "gasbulk" || cfg_category == "gaststs") && rxnrun.qfuncoptions.rot_gasmode == "gas") || ((cfg_category == "surfads" || cfg_category == "surftst") && rxnrun.qfuncoptions.rot_adsmode == "hindered"))
                        x__rotbarriers_J     = convert.(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.rotbarriers_J) 
                        x__rotpeaks          = convert.(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.rotpeaks) 
                        x__rotinertias_kg_m2 = convert.(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.rotinertias_kg_m2) 
                    else 
                        x__rotbarriers_J     = zeros(eltype(temprun_constparams.numelem[1]),1)
                        x__rotpeaks          = zeros(eltype(temprun_constparams.numelem[1]),1)
                        x__rotinertias_kg_m2 = zeros(eltype(temprun_constparams.numelem[1]),1)
                    end 
                    trot3 = zeros(eltype(temprun_constparams.numelem[1]),3) 
                end 

                # Calculate molecular rotational energies 
                if err_flag == false 
                    hrot_vals = zeros(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.cnt) 
                    srot_vals = zeros(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.cnt) 
                    err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category__Rotation(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, cfg_category, x__rotbarriers_J, x__rotpeaks, x__rotinertias_kg_m2, trot3, hrot_vals, srot_vals)
                end 

                # Calculate absolute energies 
                if err_flag == false 
                    if cfg_category == "gaststs" 
                        cfg_evalflags_gaststs[cfg_calcindxs] .= false 
                    else 
                        cfg_evalflags[cfg_calcindxs] .= false 
                    end 
                    x__loop_flag = true 
                    x__loop_cnt = 0 
                    x__loop_max = 20 
                    while err_flag == false && x__loop_flag == true && x__loop_cnt < x__loop_max
                        x__loop_flag = false 
                        x__loop_cnt = x__loop_cnt + 1
                        for i in axes(cfg_calcindxs,1) 
                            cfg_gsrcindex = cfg_gsrcindxs[i] 
                            cfg_calcindex = cfg_calcindxs[i] 
                            if cfg_category == "gaststs" 
                                eval_flag = cfg_evalflags_gaststs[cfg_calcindex] 
                            else 
                                eval_flag = cfg_evalflags[cfg_calcindex] 
                            end 
                            if eval_flag == false
                                err_flag, err_msg = Init__Temprun__ConfigsEnergies__Category__EvalConfig(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, cfg_category, cfg_gsrcindex, cfg_calcindex, trot3, hrot_vals, srot_vals) 
                            end 
                            if err_flag == true 
                                break
                            end
                        end
                        if x__loop_flag == true && x__loop_cnt >= x__loop_max 
                            err_flag = true
                        end
                    end
                end 
                
                # Calculate relative energies 
                if err_flag == false 
                    x__refcolindx = cfg_G_refcols.dindxs["G_tot"] 
                    if x__refcolindx > 0 
                        if cfg_category == "reflats"
                            cfg_G_ref[cfg_calcindxs,cfg_G_refcols.G_ref] .= view(cfg_G_ref,cfg_calcindxs,x__refcolindx)
                        else 
                            x__vals = view(rxnsystem.configurations.refGcoeffs,:,cfg_calcindxs) 
                            if cfg_category == "gaststs" 
                                cfg_G_ref_gaststs[cfg_calcindxs,cfg_G_refcols.G_ref] .= vec(sum(view(cfg_G_ref,rxnsystem.configurations.refGcfgindxs,x__refcolindx) .* x__vals,dims=1))
                                cfg_G_ref_gaststs[cfg_calcindxs,cfg_G_refcols.G_rel] .= view(cfg_G_ref_gaststs,cfg_calcindxs,cfg_G_refcols.G_tot) .- view(cfg_G_ref_gaststs,cfg_calcindxs,cfg_G_refcols.G_ref)
                            else 
                                cfg_G_ref[cfg_calcindxs,cfg_G_refcols.G_ref] .= vec(sum(view(cfg_G_ref,rxnsystem.configurations.refGcfgindxs,x__refcolindx) .* x__vals,dims=1))
                                cfg_G_ref[cfg_calcindxs,cfg_G_refcols.G_rel] .= view(cfg_G_ref,cfg_calcindxs,cfg_G_refcols.G_tot) .- view(cfg_G_ref,cfg_calcindxs,cfg_G_refcols.G_ref)
                            end 
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 

    function Init__Temprun__ConfigsEnergies__Category__Rotation(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, cfg_category, rotbarriers_J, rotpeaks, rotinertias_kg_m2, trot3, hrot_vals, srot_vals) 

        if err_flag == false && rxnrun.qfuncoptions.rot_include == true 
            if ((cfg_category == "gasbulk" || cfg_category == "gaststs") && rxnrun.qfuncoptions.rot_gasmode == "gas") || ((cfg_category == "surfads" || cfg_category == "surftst") && rxnrun.qfuncoptions.rot_adsmode == "hindered") 
                mode_factor = 1 
                hrot_vals .= zero(temprun_constparams.numelem[1])
                srot_vals .= zero(temprun_constparams.numelem[1]) 
                for i in 1:rxnsystem.molecules.cnt 
                    if rxnsystem.molecules.phases[i] == "gas" 
                        if rxnrun.qfuncoptions.rot_gasmode == "gas" 
                            if rxnsystem.molecules.rotsymfactors[i] > 0 && ((rxnsystem.molecules.rotconstants.value[i,1] > 0 && minimum(view(rxnsystem.molecules.rotconstants.value,i,2:3)) <= 0) || minimum(view(rxnsystem.molecules.rotconstants.value,i,:)) > 0)
                                if rxnsystem.molecules.rotconstants.value[i,1] > 0 && minimum(view(rxnsystem.molecules.rotconstants.value,i,2:3)) <= 0 
                                    # diatomic or linear
                                    trot1 = ((temprun_constparams.nvs_hp_J_s * temprun_constparams.nvs_hp_J_s) / (8 * (pi * pi) * temprun_constparams.nvs_kb_J_K)) / rxnsystem.molecules.rotconstants_kg_m2[i,1]
                                    hrot_vals[i] += temprun_constparams.nvs_kbt_eV * (2/2)
                                    srot_vals[i] += temprun_constparams.nvs_kbt_eV * (2/2 + log((1 / rxnsystem.molecules.rotsymfactors[i]) * (temprun_constparams.run_temp_K / trot1)))
                                elseif minimum(view(rxnsystem.molecules.rotconstants.value,i,:)) > 0 
                                    # nonlinear
                                    trot3 .= ((temprun_constparams.nvs_hp_J_s * temprun_constparams.nvs_hp_J_s) / (8 * (pi * pi) * temprun_constparams.nvs_kb_J_K)) ./ vec(view(rxnsystem.molecules.rotconstants_kg_m2,i,:))
                                    hrot_vals[i] += temprun_constparams.nvs_kbt_eV * (3/2)
                                    srot_vals[i] += temprun_constparams.nvs_kbt_eV * (3/2 + log((1 / rxnsystem.molecules.rotsymfactors[i]) * sqrt(pi * (temprun_constparams.run_temp_K / trot3[1]) * (temprun_constparams.run_temp_K / trot3[2]) * (temprun_constparams.run_temp_K / trot3[3])))) 
                                end 
                            end
                        end 
                    elseif rxnsystem.molecules.phases[i] == "ads" || rxnsystem.molecules.phases[i] == "coads" 
                        if rxnrun.qfuncoptions.rot_adsmode == "hindered" 
                            if rxnsystem.molecules.rotsymfactors[i] > 0 && rxnsystem.molecules.rotinertias.value[i] > 0
                                W_r = rotbarriers_J[i]                                               # J 
                                n_r = rotpeaks[i]                                                    # unitless
                                I_r = rotinertias_kg_m2[i]                                           # kg-m^2
                                v_r = (1 / (2 * pi)) * sqrt( (n_r ^ 2) * W_r / (2 * I_r) )           # 1/sec
                                r_r = W_r / (temprun_constparams.nvs_hp_J_s * v_r)                        # unitless
                                T_r = temprun_constparams.nvs_kbt_J / (temprun_constparams.nvs_hp_J_s * v_r)   # unitless 
                                u_r = r_r / T_r                                                      # unitless
                                x__bx = convert(Float64, 0.5 * u_r)                                  # unitless
                                x__b0 = Bessels.besseli(0, x__bx)
                                x__b1 = Bessels.besseli(1, x__bx) 
                                
                                # HO contribution
                                hrot_vals[i] += mode_factor * temprun_constparams.nvs_kbt_eV * ((1 / T_r) / (exp(1 / T_r) - 1.0))
                                srot_vals[i] += mode_factor * temprun_constparams.nvs_kbt_eV * ((1 / T_r) / (exp(1 / T_r) - 1.0)) - mode_factor * temprun_constparams.nvs_kbt_eV * log(1.0 - exp(-1 * (1 / T_r)))
                                
                                # HR contribution 
                                hrot_vals[i] += mode_factor * temprun_constparams.nvs_kbt_eV * (0.5 / T_r - 0.5 - 0.5 * (1 / ((1 + 8 * r_r) * T_r)) + 0.5 * u_r * (1 - (x__b1 / x__b0)))
                                srot_vals[i] += mode_factor * temprun_constparams.nvs_kbt_eV * (-0.5 - log(rxnsystem.molecules.rotsymfactors[i]) - 0.5 * u_r * (x__b1 / x__b0) + log(sqrt(pi * u_r) * x__b0))
                            end
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 
    
    function Init__Temprun__ConfigsEnergies__Category__EvalConfig(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, cfg_evalflags, cfg_evalflags_gaststs, cfg_category, cfg_gsrcindex, cfg_calcindex, trot3, hrot_vals, srot_vals) 

        # states number
        if err_flag == false 
            stnum = sum(rxnsystem.configurations.coeffs_states[cfg_gsrcindex,:,:]) 
        end 

        # internal energy 
        vals_H_U = zero(temprun_constparams.numelem[1])
        if err_flag == false && rxnrun.qfuncoptions.u_include == true 
            vals_H_U += convert(eltype(temprun_constparams.numelem[1]),rxnsystem.configurations.enthalpies_eV[cfg_gsrcindex])
        end 

        # pressure-volume work 
        vals_H_pV = zero(temprun_constparams.numelem[1])
        if err_flag == false && rxnrun.qfuncoptions.pv_include == true && stnum > 0 
            if cfg_category == "gasbulk" 
                for j in 1:rxnsystem.phases.indxs_gases_cnt 
                    for k in axes(rxnsystem.configurations.states_indxs_gas,1)
                        if rxnsystem.configurations.coeffs_states[cfg_gsrcindex,rxnsystem.phases.indxs_gases[j],rxnsystem.configurations.states_indxs_gas[k]] > 0 
                            vals_H_pV += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,rxnsystem.phases.indxs_gases[j],rxnsystem.configurations.states_indxs_gas[k]] * temprun_constparams.nvs_kbt_eV
                        end 
                    end 
                end 
            end 
        end 

        # electronic motion 
        vals_TS_elec = zero(temprun_constparams.numelem[1])
        if err_flag == false && rxnrun.qfuncoptions.elec_include == true && stnum > 0 
            if cfg_category != "reflats"
                for j in 1:rxnsystem.phases.phases_cnt 
                    for k in 1:rxnsystem.configurations.states_cnt
                        if haskey(rxnsystem.molecules.dindxs,rxnsystem.configurations.states_compounds[k]) 
                            if rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] > 0 && rxnsystem.molecules.spinmultiplicities[rxnsystem.molecules.dindxs[rxnsystem.configurations.states_compounds[k]]] > 0 
                                vals_TS_elec += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * temprun_constparams.nvs_kbt_eV * log(rxnsystem.molecules.spinmultiplicities[rxnsystem.molecules.dindxs[rxnsystem.configurations.states_compounds[k]]])
                            end 
                        end 
                    end 
                end 
            end 
        end

        # Vibrational motion 
        vals_H_zpe  = zero(temprun_constparams.numelem[1])
        vals_H_vib  = zero(temprun_constparams.numelem[1])
        vals_TS_vib = zero(temprun_constparams.numelem[1])
        if err_flag == false && rxnrun.qfuncoptions.vib_include == true && stnum > 0 
            if rxnrun.qfuncoptions.vib_freqmethod == 1 && cfg_category != "reflats"
                for i in 1:rxnsystem.configurations.states_cnt 
                    xcfgcnt = sum(rxnsystem.configurations.coeffs_states[cfg_gsrcindex,:,i])
                    if xcfgcnt > 0 
                        xcfgname = ""
                        xcfgindx = 0
                        xmolindx = 0
                        for j in 1:rxnsystem.configurations.cnt
                            if sum(rxnsystem.configurations.coeffs_states[j,:,i]) == 1 && sum(rxnsystem.configurations.coeffs_states[j,:,:]) == 1
                                xcfgname = rxnsystem.configurations.names[j]
                                xcfgindx = j 
                                break 
                            end 
                        end 
                        if xcfgindx <= 0 
                            for j in 1:rxnsystem.configurations.cnt
                                if sum(rxnsystem.configurations.coeffs_states[j,:,i]) == xcfgcnt && sum(rxnsystem.configurations.coeffs_states[j,:,:]) == xcfgcnt
                                    xcfgname = rxnsystem.configurations.names[j]
                                    xcfgindx = j 
                                    xcfgcnt = 1
                                    break 
                                end 
                            end 
                        end 
                        xmolindx = get_elemindex(rxnsystem.molecules.names,xcfgname,0)
                        if xcfgindx > 0 
                            xfreqcnt = 0 
                            for j in axes(rxnsystem.configurations.vibfreqs_1_m,2) 
                                if rxnsystem.configurations.vibfreqs_1_m[xcfgindx,j] != 0 
                                    xfreqcnt += 1
                                else 
                                    break 
                                end 
                            end 
                            xrotsym = 0 
                            if xmolindx > 0 
                                xrotsym = rxnsystem.molecules.rotsymfactors[xmolindx]
                            end 
                            if xfreqcnt > 0 
                                xfreqary = get_view(vec(view(rxnsystem.configurations.vibfreqs_1_m,xcfgindx,1:xfreqcnt)))
                                xcfgisgas = false
                                x__vib_hflag = false 
                                x__vib_tsflag = false
                                if get_elemindex(rxnsystem.configurations.states_indxs_gas,i,0) > 0 
                                    xcfgisgas = true
                                    x__vib_hflag  = rxnrun.qfuncoptions.vib_gashflag 
                                    x__vib_tsflag = rxnrun.qfuncoptions.vib_gastsflag
                                else 
                                    x__vib_hflag  = rxnrun.qfuncoptions.vib_adshflag 
                                    x__vib_tsflag = rxnrun.qfuncoptions.vib_adstsflag
                                end 
                                x__H_zpe  = zero(temprun_constparams.numelem[1])
                                x__H_vib  = zero(temprun_constparams.numelem[1])
                                x__TS_vib = zero(temprun_constparams.numelem[1])
                                for j in 1:xfreqcnt 
                                    x__wavenum = 0
                                    if xcfgisgas == true 
                                        if rxnrun.qfuncoptions.vib_gasmode == "raw"
                                            x__wavenum = xfreqary[j]
                                        elseif rxnrun.qfuncoptions.vib_gasmode == "applymin"
                                            x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                        end
                                    else 
                                        if rxnrun.qfuncoptions.vib_adsmode == "raw"
                                            x__wavenum = xfreqary[j]
                                        elseif rxnrun.qfuncoptions.vib_adsmode == "applymin"
                                            x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                        elseif rxnrun.qfuncoptions.vib_adsmode == "removelowest"
                                            if cfg_category == "surftst"
                                                x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                            else
                                                if j <= xfreqcnt - 3 
                                                    x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                                end 
                                            end 
                                        end
                                    end 
                                    if x__wavenum > 0 
                                        hvkt = temprun_constparams.nvs_hpc_eV_m * x__wavenum / temprun_constparams.nvs_kbt_eV
                                        if rxnrun.qfuncoptions.vib_zpeflag == true 
                                            x__H_zpe += hvkt / 2
                                        end
                                        if x__vib_hflag == true 
                                            x__H_vib += hvkt / (exp(hvkt) - 1)
                                        end 
                                        if x__vib_tsflag == true 
                                            x__TS_vib += hvkt / (exp(hvkt) - 1) - log(1 - exp(-1 * hvkt))
                                        end 
                                    end 
                                end 
                                vals_H_zpe  += xcfgcnt * temprun_constparams.nvs_kbt_eV * x__H_zpe
                                vals_H_vib  += xcfgcnt * temprun_constparams.nvs_kbt_eV * x__H_vib
                                vals_TS_vib += xcfgcnt * temprun_constparams.nvs_kbt_eV * x__TS_vib
                            end 
                        end 
                    end
                end 
            elseif rxnrun.qfuncoptions.vib_freqmethod == 2 || cfg_category == "reflats"
                xcfgname = rxnsystem.configurations.names[cfg_gsrcindex] 
                xcfgindx = cfg_gsrcindex
                xcfgcnt = 1 
                xmolindx = get_elemindex(rxnsystem.molecules.names,xcfgname,0)
                xrotsym = 0 
                x__rotinertia = 0
                if xmolindx > 0 
                    xrotsym = rxnsystem.molecules.rotsymfactors[xmolindx]
                    x__rotinertia = rxnsystem.molecules.rotinertias.value[xmolindx]
                end 
                if xcfgindx > 0 
                    xfreqcnt = 0 
                    for j in axes(rxnsystem.configurations.vibfreqs_1_m,2) 
                        if rxnsystem.configurations.vibfreqs_1_m[xcfgindx,j] != 0 
                            xfreqcnt += 1
                        else 
                            break 
                        end 
                    end 
                    if xfreqcnt > 0 
                        xfreqary = get_view(vec(view(rxnsystem.configurations.vibfreqs_1_m,xcfgindx,1:xfreqcnt)))
                        xcfgisgas = false
                        x__vib_hflag = false 
                        x__vib_tsflag = false
                        if get_elemindex(rxnsystem.configurations.states_names[rxnsystem.configurations.states_indxs_gas],xcfgname,0) > 0 || get_elemindex(rxnsystem.configurations.states_names[rxnsystem.configurations.states_indxs_gas],string("<gas> ",xcfgname),0) > 0  
                            xcfgisgas = true
                            x__vib_hflag  = rxnrun.qfuncoptions.vib_gashflag 
                            x__vib_tsflag = rxnrun.qfuncoptions.vib_gastsflag
                        else 
                            x__vib_hflag  = rxnrun.qfuncoptions.vib_adshflag 
                            x__vib_tsflag = rxnrun.qfuncoptions.vib_adstsflag
                        end 
                        x__H_zpe  = zero(temprun_constparams.numelem[1])
                        x__H_vib  = zero(temprun_constparams.numelem[1])
                        x__TS_vib = zero(temprun_constparams.numelem[1])
                        for j in 1:xfreqcnt 
                            x__wavenum = 0
                            if xcfgisgas == true 
                                if rxnrun.qfuncoptions.vib_gasmode == "raw"
                                    x__wavenum = xfreqary[j]
                                elseif rxnrun.qfuncoptions.vib_gasmode == "applymin"
                                    x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                end
                            else 
                                if rxnrun.qfuncoptions.vib_adsmode == "raw"
                                    x__wavenum = xfreqary[j]
                                elseif rxnrun.qfuncoptions.vib_adsmode == "applymin"
                                    x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                elseif rxnrun.qfuncoptions.vib_adsmode == "removelowest"
                                    if cfg_category == "surftst"
                                        x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                    else
                                        if j <= xfreqcnt - 3 
                                            x__wavenum = max(xfreqary[j],temprun_constparams.wavenum_min_1_m)
                                        end 
                                    end 
                                end
                            end 
                            if x__wavenum > 0 
                                hvkt = temprun_constparams.nvs_hpc_eV_m * x__wavenum / temprun_constparams.nvs_kbt_eV
                                if rxnrun.qfuncoptions.vib_zpeflag == true 
                                    x__H_zpe += hvkt / 2
                                end
                                if x__vib_hflag == true 
                                    x__H_vib += hvkt / (exp(hvkt) - 1)
                                end 
                                if x__vib_tsflag == true 
                                    x__TS_vib += hvkt / (exp(hvkt) - 1) - log(1 - exp(-1 * hvkt))
                                end 
                            end 
                        end 
                        vals_H_zpe  += xcfgcnt * temprun_constparams.nvs_kbt_eV * x__H_zpe
                        vals_H_vib  += xcfgcnt * temprun_constparams.nvs_kbt_eV * x__H_vib
                        vals_TS_vib += xcfgcnt * temprun_constparams.nvs_kbt_eV * x__TS_vib
                    end 
                end 
            end
        end 

        # translational motion 
        vals_H_trs  = zero(temprun_constparams.numelem[1])
        vals_TS_trs = zero(temprun_constparams.numelem[1])
        if err_flag == false && rxnrun.qfuncoptions.trs_include == true && stnum > 0 
            if ((cfg_category == "gasbulk" || cfg_category == "gaststs") && rxnrun.qfuncoptions.trs_gasmode == "gas") || ((cfg_category == "surfads" || cfg_category == "surftst") && rxnrun.qfuncoptions.trs_adsmode == "hindered") 
                mode_factor = 2 
                for j in 1:rxnsystem.phases.phases_cnt            
                    for k in 1:rxnsystem.configurations.states_cnt
                        if haskey(rxnsystem.molecules.dindxs,rxnsystem.configurations.states_compounds[k]) 
                            molecule_index = rxnsystem.molecules.dindxs[rxnsystem.configurations.states_compounds[k]] 
                            if rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] > 0 
                                x__htrs = zero(temprun_constparams.numelem[1])
                                x__strs = zero(temprun_constparams.numelem[1])
                                if rxnsystem.molecules.phases[molecule_index] == "gas" && get_elemindex(rxnsystem.phases.indxs_gases,j,0) > 0 
                                    if rxnrun.qfuncoptions.trs_gasmode == "gas" 
                                        err_flag = true
                                        ode__indx = 0 
                                        if haskey(rxnsystem.odespecies.dindxs,rxnsystem.configurations.states_names[k])
                                            ode__indx = rxnsystem.odespecies.dindxs[rxnsystem.configurations.states_names[k]]
                                        end 
                                        gas__indx = get_elemindex(view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_gas),rxnsystem.configurations.states_names[k],0) 
                                        if ode__indx > 0 && gas__indx > 0 
                                            err_flag = false 
                                            x__momentum = temprun_odeparams.ode_gas_momentum[gas__indx] 
                                            adsorb_molcnt = 1
                                            if cfg_category == "gaststs"
                                                x__htrs += temprun_constparams.nvs_kbt_eV
                                                x__strs += temprun_constparams.nvs_kbt_eV * (4/2 + log((rxnsystem.phases.cellareas_m2[j] / adsorb_molcnt) * (x__momentum / temprun_constparams.nvs_hp_J_s) * (x__momentum / temprun_constparams.nvs_hp_J_s)))
                                            else 
                                                x__htrs += temprun_constparams.nvs_kbt_eV * (3/2)
                                                x__strs += temprun_constparams.nvs_kbt_eV * (5/2 + log((temprun_constparams.nvs_kbt_J / (rxnrun.odefracs_ini[ode__indx] > zero(eltype(rxnrun.odefracs_ini)) ? conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, rxnrun.odefracs_ini[ode__indx], rxnrun.solveroptions.ode_ref_pressure.units, "Pa") : rxnrun.solveroptions.ode_abstol)) * (x__momentum / temprun_constparams.nvs_hp_J_s) * (x__momentum / temprun_constparams.nvs_hp_J_s) * (x__momentum / temprun_constparams.nvs_hp_J_s))) 
                                            end 
                                        end 
                                    end 
                                elseif (rxnsystem.molecules.phases[molecule_index] == "ads" || rxnsystem.molecules.phases[molecule_index] == "coads") && get_elemindex(rxnsystem.phases.indxs_surfs,j,0) > 0 
                                    if rxnrun.qfuncoptions.trs_adsmode == "hindered" 
                                        if rxnsystem.molecules.trsbarriers.value[molecule_index] > 0 && rxnsystem.molecules.trspeaks[molecule_index] > 0 && rxnsystem.phases.surfs_indexes[j] > 0 
                                            if rxnsystem.configurations.states_maxcounts[cfg_gsrcindex,rxnsystem.phases.surfs_indexes[j],k] > 0 
                                                W_t = convert(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.trsbarriers_J[molecule_index])    # J 
                                                m_t = convert(eltype(temprun_constparams.numelem[1]),rxnsystem.molecules.molwt_kg_mol[molecule_index])     # kg / mol 
                                                m_t = m_t / temprun_constparams.nvs_Na_1_mol                                                               # kg 
                                                v_t = sqrt(W_t / (2 * m_t * temprun_constparams.cell_b2_m2[j]))                                            # 1 / sec 
                                                if v_t > 0
                                                    r_t = W_t / (temprun_constparams.nvs_hp_J_s * v_t)                                                     # unitless 
                                                    T_t = temprun_constparams.nvs_kbt_J / (temprun_constparams.nvs_hp_J_s * v_t)                           # unitless 
                                                    u_t = r_t / T_t                                                                                        # unitless 
                                                    if rxnsystem.configurations.refstatescovs_unscaled[cfg_gsrcindex,k] / rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] >= 1.0 / rxnsystem.phases.cellcounts[j] + 0.0001
                                                        xmodefactor = 1
                                                    else 
                                                        xmodefactor = 2
                                                    end 

                                                    # HO contribution
                                                    x__htrs += xmodefactor * temprun_constparams.nvs_kbt_eV * ((1 / T_t) / (exp(1 / T_t) - 1.0))
                                                    x__strs += xmodefactor * temprun_constparams.nvs_kbt_eV * ((1 / T_t) / (exp(1 / T_t) - 1.0)) - mode_factor * temprun_constparams.nvs_kbt_eV * log(1.0 - exp(-1 * (1 / T_t)))

                                                    # HT contribution 
                                                    x__bx = convert(Float64,0.5 * u_t)
                                                    x__htrs += xmodefactor * temprun_constparams.nvs_kbt_eV * (0.5 / T_t - 0.5 - 0.5 * (1 / ((1 + 8 * r_t) * T_t)) + 0.5 * u_t * (1.0 - (Bessels.besseli(1, x__bx) / Bessels.besseli(0, x__bx))))
                                                    x__strs += xmodefactor * temprun_constparams.nvs_kbt_eV * (-0.5 - 0.5 * u_t * (Bessels.besseli(1, x__bx) / Bessels.besseli(0, x__bx)) + log(sqrt(pi * u_t) * Bessels.besseli(0, x__bx)) - 0.5 * (log(rxnsystem.configurations.refstatescovs_unscaled[cfg_gsrcindex,k] / rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k]) - 1.0))
                                                end
                                            end 
                                        end
                                    end
                                end 
                                if err_flag == false 
                                    if rxnsystem.molecules.phases[molecule_index] == "gas" && get_elemindex(rxnsystem.phases.indxs_gases,j,0) > 0 && rxnrun.qfuncoptions.trs_gasmode != "none" 
                                        if rxnrun.qfuncoptions.trs_gashflag == true 
                                            vals_H_trs  += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * x__htrs
                                        end 
                                        if rxnrun.qfuncoptions.trs_gastsflag == true 
                                            vals_TS_trs += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * x__strs
                                        end 
                                    end
                                    if (rxnsystem.molecules.phases[molecule_index] == "ads" || rxnsystem.molecules.phases[molecule_index] == "coads") && get_elemindex(rxnsystem.phases.indxs_surfs,j,0) > 0 && rxnrun.qfuncoptions.trs_adsmode != "none" 
                                        if rxnrun.qfuncoptions.trs_adshflag == true 
                                            vals_H_trs  += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * x__htrs
                                        end 
                                        if rxnrun.qfuncoptions.trs_adstsflag == true 
                                            vals_TS_trs += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * x__strs
                                        end 
                                    end 
                                end 
                            end 
                        end 
                        if err_flag == true 
                            break 
                        end 
                    end 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 
        end 

        # rotational motion 
        vals_H_rot  = zero(temprun_constparams.numelem[1])
        vals_TS_rot = zero(temprun_constparams.numelem[1])
        if err_flag == false && rxnrun.qfuncoptions.rot_include == true && stnum > 0 
            if ((cfg_category == "gasbulk" || cfg_category == "gaststs") && rxnrun.qfuncoptions.rot_gasmode == "gas") || ((cfg_category == "surfads" || cfg_category == "surftst") && rxnrun.qfuncoptions.rot_adsmode == "hindered") 
                mode_factor = 1 
                for j in 1:rxnsystem.phases.phases_cnt            
                    for k in 1:rxnsystem.configurations.states_cnt
                        if haskey(rxnsystem.molecules.dindxs,rxnsystem.configurations.states_compounds[k]) 
                            molecule_index = rxnsystem.molecules.dindxs[rxnsystem.configurations.states_compounds[k]] 
                            if rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] > 0 && molecule_index > 0 
                                if (cfg_category == "gasbulk" || cfg_category == "gaststs") && rxnrun.qfuncoptions.rot_gasmode != "none" 
                                    if rxnrun.qfuncoptions.rot_gashflag == true 
                                        vals_H_rot  += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * hrot_vals[molecule_index]
                                    end 
                                    if rxnrun.qfuncoptions.rot_gastsflag == true 
                                        vals_TS_rot += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * srot_vals[molecule_index]
                                    end 
                                end
                                if (cfg_category == "surfads" || cfg_category == "surftst") && rxnrun.qfuncoptions.rot_adsmode != "none"
                                    if rxnrun.qfuncoptions.rot_adshflag == true 
                                        vals_H_rot  += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * hrot_vals[molecule_index]
                                    end 
                                    if rxnrun.qfuncoptions.rot_adstsflag == true 
                                        vals_TS_rot += rxnsystem.configurations.coeffs_states[cfg_gsrcindex,j,k] * srot_vals[molecule_index]
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 
            end 
        end

        # total energies
        if err_flag == false 
            vals_H_tot  = vals_H_U + vals_H_pV + vals_H_zpe + vals_H_vib + vals_H_trs + vals_H_rot
            vals_TS_tot = vals_TS_elec + vals_TS_vib + vals_TS_trs + vals_TS_rot
            vals_G_tot  = vals_H_tot - vals_TS_tot
            if cfg_category == "gaststs" 
                cfg_evalflags_gaststs[cfg_calcindex] = true 
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_U]     = vals_H_U
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_pV]    = vals_H_pV
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_zpe]   = vals_H_zpe
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_vib]   = vals_H_vib
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_trs]   = vals_H_trs
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_rot]   = vals_H_rot
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.H_tot]   = vals_H_tot
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.TS_elec] = vals_TS_elec
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.TS_vib]  = vals_TS_vib
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.TS_trs]  = vals_TS_trs
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.TS_rot]  = vals_TS_rot
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.TS_tot]  = vals_TS_tot
                cfg_G_ref_gaststs[cfg_calcindex,cfg_G_refcols.G_tot]   = vals_G_tot
            else 
                cfg_evalflags[cfg_calcindex] = true 
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_U]     = vals_H_U
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_pV]    = vals_H_pV
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_zpe]   = vals_H_zpe
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_vib]   = vals_H_vib
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_trs]   = vals_H_trs
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_rot]   = vals_H_rot
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.H_tot]   = vals_H_tot
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.TS_elec] = vals_TS_elec
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.TS_vib]  = vals_TS_vib
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.TS_trs]  = vals_TS_trs
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.TS_rot]  = vals_TS_rot
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.TS_tot]  = vals_TS_tot
                cfg_G_ref[cfg_calcindex,cfg_G_refcols.G_tot]   = vals_G_tot
            end 
        end 

        return err_flag, err_msg
    end 

    function Init__Temprun__EnergyInterpObjects(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, rxnrun_numtype, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, u_numtype) 

        # Construct energy interpolation objects 
        interp_itpobj_sitecaledcovs_byunscaled     = ct__Temprun_Interpolator_Obj(u_numtype)
        interp_itpobj_adscoadscaledcovs_byunscaled = ct__Temprun_Interpolator_Obj(u_numtype)
        interp_itpobj_relG_full_unscaled           = ct__Temprun_Interpolator_Obj(u_numtype)
        interp_itpobj_relG_full_scaled             = ct__Temprun_Interpolator_Obj(u_numtype)
        interp_itpobj_relG_itpcmpds_scaled         = ct__Temprun_Interpolator_Obj(u_numtype)
        if err_flag == false 
            if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0
                nodes_data      = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refstatescovs_unscaled,:,rxnsystem.configurations.states_indxs_adscoads)))
                nodes_rowsindxs = collect(1:rxnsystem.configurations.states_indxs_adscoads_cnt) 
                nodes_colsindxs = unique(vcat(rxnsystem.configurations.indxs_ref,rxnsystem.configurations.uniquecovs_indxs_adscoads))
                data            = convert.(u_numtype,get_view(reshape(view(cfg_G_ref,nodes_colsindxs,cfg_G_refcols.G_rel),1,size(nodes_colsindxs,1))))
                output_pts      = Array{Int,1}(undef,0)
                err_flag, err_msg, interp_itpobj_relG_full_unscaled, unq_indxs, unq_subindxs, unq_subindxs_srcnzdims = Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, u_numtype, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, rxnrun.solveroptions.ode_multi_threaded, rxnrun.solveroptions.interp_rbf_includepolynomial) 
                nodes_data      = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refstatescovs_scaled,:,rxnsystem.configurations.states_indxs_adscoads)))
                nodes_rowsindxs = collect(1:rxnsystem.configurations.states_indxs_adscoads_cnt) 
                nodes_colsindxs = unique(vcat(rxnsystem.configurations.indxs_ref,rxnsystem.configurations.uniquecovs_indxs_adscoads))
                data            = convert.(u_numtype,get_view(reshape(view(cfg_G_ref,nodes_colsindxs,cfg_G_refcols.G_rel),1,size(nodes_colsindxs,1))))
                output_pts      = Array{Int,1}(undef,0)
                err_flag, err_msg, interp_itpobj_relG_full_scaled, unq_indxs, unq_subindxs, unq_subindxs_srcnzdims = Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, u_numtype, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, rxnrun.solveroptions.ode_multi_threaded, rxnrun.solveroptions.interp_rbf_includepolynomial) 
                nodes_data      = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refstatescovs_unscaled,:,rxnsystem.configurations.states_indxs_adscoads)))
                nodes_rowsindxs = collect(1:rxnsystem.configurations.states_indxs_adscoads_cnt) 
                nodes_colsindxs = rxnsystem.configurations.indxs_adsref
                data            = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refsitescovs_scaled,nodes_colsindxs,:)))
                output_pts      = Array{Int,1}(undef,0)
                err_flag, err_msg, interp_itpobj_sitecaledcovs_byunscaled, unq_indxs, unq_subindxs, unq_subindxs_srcnzdims = Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, u_numtype, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, rxnrun.solveroptions.ode_multi_threaded, rxnrun.solveroptions.interp_rbf_includepolynomial) 
                nodes_data      = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refstatescovs_unscaled,:,rxnsystem.configurations.states_indxs_adscoads)))
                nodes_rowsindxs = collect(1:rxnsystem.configurations.states_indxs_adscoads_cnt) 
                nodes_colsindxs = rxnsystem.configurations.indxs_adsref
                data            = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refstatescovs_scaled,nodes_colsindxs,rxnsystem.configurations.states_indxs_adscoads)))
                output_pts      = Array{Int,1}(undef,0)
                err_flag, err_msg, interp_itpobj_adscoadscaledcovs_byunscaled, unq_indxs, unq_subindxs, unq_subindxs_srcnzdims = Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, u_numtype, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, rxnrun.solveroptions.ode_multi_threaded, rxnrun.solveroptions.interp_rbf_includepolynomial)     
            end 
        end
        if err_flag == false 
            if temprun_relGparams.aryG_var_cnt > 0 
                x__ode_adscoads_names = get_view(view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_adscoads))
                x__states_adscoads_names = get_view(view(rxnsystem.configurations.states_names,rxnsystem.configurations.states_indxs_adscoads)) 
                x__indxconvs_ode2odeadscoads = get_elemindex(x__ode_adscoads_names,rxnsystem.odespecies.names,0)
                x__indxconvs_interpcmpds2ode = Array{Int,1}(undef,0)
                x__indxconvs_interpcmpds2odeadscoads_subindxs = Array{Int,1}(undef,0)
                x__indxconvs_interpcmpds2state_subindxs = Array{Int,1}(undef,0)
                x__indxconvs_interpcmpds2stateadscoads_subindxs = Array{Int,1}(undef,0)
                if size(rxnrun.solveroptions.interp_cmpds_stateindxs,1) > 0 
                    x__indxconvs_interpcmpds2ode = get_elemindex(rxnsystem.odespecies.names,temprun_relGparams.aryG_interp_cmpds_names,0)
                    x__indxconvs_interpcmpds2odeadscoads_subindxs = get_elemindex(x__ode_adscoads_names, temprun_relGparams.aryG_interp_cmpds_names, 0) 
                    x__indxconvs_interpcmpds2state_subindxs = get_elemindex(rxnsystem.configurations.states_names, temprun_relGparams.aryG_interp_cmpds_names, 0) 
                    x__indxconvs_interpcmpds2stateadscoads_subindxs = get_elemindex(x__states_adscoads_names, temprun_relGparams.aryG_interp_cmpds_names, 0) 
                end 
                x__interp_method = 1
                if x__interp_method == 1 
                    x__cfgcnt   = size(rxnsystem.configurations.indxs_ref,1) 
                    x__cfgindxs = deepcopy(rxnsystem.configurations.indxs_ref) 
                    for i in axes(rxnsystem.configurations.indxs_ads,1)
                        x__itpflag = false 
                        x__ntpflag = false
                        for j in axes(rxnsystem.configurations.states_indxs_ads,1)
                            if sum(rxnsystem.configurations.coeffs_states[rxnsystem.configurations.indxs_ads[i],:,rxnsystem.configurations.states_indxs_ads[j]]) >= 0.001 
                                if get_elemindex(rxnrun.solveroptions.interp_cmpds_stateindxs,rxnsystem.configurations.states_indxs_ads[j],0) > 0 
                                    x__itpflag = true 
                                else
                                    x__ntpflag = true 
                                    break
                                end 
                            end 
                        end 
                        for j in axes(rxnsystem.configurations.states_indxs_coads,1)
                            if sum(rxnsystem.configurations.coeffs_states[rxnsystem.configurations.indxs_ads[i],:,rxnsystem.configurations.states_indxs_coads[j]]) >= 0.001
                                if get_elemindex(rxnrun.solveroptions.interp_cmpds_stateindxs,rxnsystem.configurations.states_indxs_coads[j],0) > 0 
                                    x__itpflag = true 
                                else
                                    x__ntpflag = true 
                                    break
                                end 
                            end 
                        end 
                        if x__itpflag == true && x__ntpflag == false
                            x__cfgcnt += 1 
                            push!(x__cfgindxs,rxnsystem.configurations.indxs_ads[i])
                        end 
                    end 
                    if x__cfgcnt > 0 
                        x__aryG_itp_interpcovs = zeros(u_numtype,x__cfgcnt,temprun_relGparams.aryG_interp_cmpds_cnt)
                        for i in axes(x__cfgindxs,1) 
                            for j in 1:temprun_relGparams.aryG_interp_cmpds_cnt
                                if sum(rxnsystem.configurations.coeffs_states[x__cfgindxs[i],:,x__indxconvs_interpcmpds2state_subindxs[j]]) > 0.0001 
                                    x__aryG_itp_interpcovs[i,j] = rxnsystem.configurations.refstatescovs_unscaled[x__cfgindxs[i],x__indxconvs_interpcmpds2state_subindxs[j]] 
                                end 
                            end 
                        end 
                        x__aryG_itp_interpGvals = zeros(u_numtype,x__cfgcnt,temprun_relGparams.aryG_var_cnt) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, false, 1, 1, string("interp covs")) 
                        for i in 1:temprun_relGparams.aryG_var_cnt 
                            x__itpcovs = zeros(u_numtype,x__cfgcnt,rxnsystem.odespecies.indxs_adscoads_cnt) 
                            for j in axes(x__cfgindxs,1)
                                for k in axes(x__indxconvs_interpcmpds2odeadscoads_subindxs,1)
                                    x__itpcovs[j,x__indxconvs_interpcmpds2odeadscoads_subindxs[k]] = x__aryG_itp_interpcovs[j,k]
                                end 
                                for k in 1:rxnsystem.odespecies.indxs_coads_cnt 
                                    x__itpcovs[j,x__indxconvs_ode2odeadscoads[rxnsystem.odespecies.indxs_coads[k]]] = temprun_relGparams.refinit_coads_covs[k]
                                end 
                                for k in 1:rxnsystem.odespecies.indxs_adscoads_cnt
                                    x__itpcovs[j,k] += temprun_relGparams.aryG_adjcovs[temprun_relGparams.aryG_var_gindxs[i]][k] * (1.0 - sum(temprun_relGparams.refinit_coads_covs))
                                end 
                            end 
                            x__itprelG = zeros(u_numtype,x__cfgcnt,1)
                            err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_full_unscaled, get_transpose(x__itpcovs), x__itprelG, false, false, nothing, nothing, nothing, nothing)
                            x__aryG_itp_interpGvals[:,i] .= x__itprelG
                        end 
                    else 
                        err_flag = true 
                    end 
                elseif x__interp_method == 2 
                    x__itrflag = true 
                    x__itrcnts = zeros(Int,temprun_relGparams.aryG_interp_cmpds_cnt) 
                    x__itrcnts[temprun_relGparams.aryG_interp_cmpds_cnt] = -1 
                    x__itrcnts_ary = Array{Array{Int,1},1}(undef,0)
                    while x__itrflag == true 
                        x__itrcnts[temprun_relGparams.aryG_interp_cmpds_cnt] += 1 
                        for i in 1:temprun_relGparams.aryG_interp_cmpds_cnt
                            if x__itrcnts[temprun_relGparams.aryG_interp_cmpds_cnt-i+1] > temprun_relGparams.refinit_adscoads_maxcnt 
                                if i < temprun_relGparams.aryG_interp_cmpds_cnt 
                                    x__itrcnts[temprun_relGparams.aryG_interp_cmpds_cnt-i+0] += 1
                                    x__itrcnts[temprun_relGparams.aryG_interp_cmpds_cnt-i+1]  = 0  
                                else
                                    x__itrflag = false 
                                end 
                            else 
                                break 
                            end 
                        end
                        if x__itrflag == true && sum(x__itrcnts) <= temprun_relGparams.refinit_adscoads_maxcnt && maximum((1/temprun_relGparams.refinit_adscoads_maxcnt) .* x__itrcnts .- view(temprun_relGparams.refinit_adscoads_maxcovs,x__indxconvs_interpcmpds2stateadscoads_subindxs)) < 0.0001
                            push!(x__itrcnts_ary,deepcopy(x__itrcnts))
                        end 
                    end 
                    x__aryG_itp_interpcnts = zeros(u_numtype,size(x__itrcnts_ary,1),temprun_relGparams.aryG_interp_cmpds_cnt)
                    x__aryG_itp_interpcovs = zeros(u_numtype,size(x__itrcnts_ary,1),temprun_relGparams.aryG_interp_cmpds_cnt)
                    for i in axes(x__itrcnts_ary,1) 
                        for j in axes(x__itrcnts_ary[i],1)
                            x__aryG_itp_interpcnts[i,j] = x__itrcnts_ary[i][j]
                            x__aryG_itp_interpcovs[i,j] = x__itrcnts_ary[i][j] / temprun_relGparams.refinit_adscoads_maxcnt
                        end 
                    end 
                    x__aryG_itp_interpGvals = zeros(u_numtype,size(x__itrcnts_ary,1),temprun_relGparams.aryG_var_cnt) 
                    for i in 1:temprun_relGparams.aryG_var_cnt 
                        x__itpcovs = zeros(u_numtype,size(x__itrcnts_ary,1),rxnsystem.odespecies.indxs_adscoads_cnt) 
                        for j in axes(x__itrcnts_ary,1)
                            for k in axes(x__indxconvs_interpcmpds2odeadscoads_subindxs,1)
                                x__itpcovs[j,x__indxconvs_interpcmpds2odeadscoads_subindxs[k]] = x__aryG_itp_interpcovs[j,k]
                            end 
                            for k in 1:rxnsystem.odespecies.indxs_coads_cnt 
                                x__itpcovs[j,x__indxconvs_ode2odeadscoads[rxnsystem.odespecies.indxs_coads[k]]] = temprun_relGparams.refinit_coads_covs[k]
                            end 
                            for k in 1:rxnsystem.odespecies.indxs_adscoads_cnt
                                x__itpcovs[j,k] += temprun_relGparams.aryG_adjcovs[temprun_relGparams.aryG_var_gindxs[i]][k]
                            end 
                        end 
                        x__itprelG = zeros(u_numtype,size(x__itrcnts_ary,1),1)
                        err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_full_scaled, get_transpose(x__itpcovs), x__itprelG, false, false, nothing, nothing, nothing, nothing)
                        x__aryG_itp_interpGvals[:,i] .= x__itprelG
                    end 
                else 
                    err_flag = true 
                end
                if err_flag == false 
                    nodes_data      = convert.(u_numtype,get_transpose(x__aryG_itp_interpcovs)) 
                    nodes_rowsindxs = collect(1:size(x__aryG_itp_interpcovs,2)) 
                    nodes_colsindxs = collect(1:size(x__aryG_itp_interpcovs,1)) 
                    data            = get_transpose(x__aryG_itp_interpGvals)
                    output_pts      = Array{Int,1}(undef,0)
                    err_flag, err_msg, interp_itpobj_relG_itpcmpds_scaled, x__aryG_itp_interpunq_indxs, x__aryG_itp_interpunq_subindxs, x__aryG_itp_interpunq_subindxs_srcnzdims = Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, u_numtype, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, rxnrun.solveroptions.ode_multi_threaded, rxnrun.solveroptions.interp_rbf_includepolynomial)     
                end 
            end 
        end 

        return err_flag, err_msg, interp_itpobj_sitecaledcovs_byunscaled, interp_itpobj_adscoadscaledcovs_byunscaled, interp_itpobj_relG_full_unscaled, interp_itpobj_relG_full_scaled, interp_itpobj_relG_itpcmpds_scaled 
    end 

    function Init__Temprun__EnergyArrays(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, rxnrun_numtype, u_o, cfg_G_refcols, cfg_G_ref, cfg_G_ref_gaststs, interp_itpobj_relG_full_unscaled, interp_itpobj_relG_full_scaled, interp_itpobj_relG_itpcmpds_scaled) 

        # Construct energy arrays
        u_numtype = eltype(u_o[1])
        aryG_gvals = zeros(u_numtype,temprun_relGparams.aryG_cnt)
        aryG_calcd = zeros(Int,temprun_relGparams.aryG_cnt)
        if err_flag == false 
            if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0

                # reference configurations 
                # must be adjusted with perturbation factors, as needed
                if err_flag == false 
                    if size(temprun_relGparams.aryG_ref_gindxs,1) > 0
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("reference configurations energies")) 
                        x__ode_adscoads_names = get_view(view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_adscoads))
                        x__indxconvs_ode2odeadscoads = get_elemindex(x__ode_adscoads_names,rxnsystem.odespecies.names,0)
                        for i in 1:temprun_relGparams.aryG_ref_cnt 
                            x__gindex = temprun_relGparams.aryG_ref_gindxs[i] 
                            if x__gindex > 0 
                                x__cfgname = temprun_relGparams.aryG_extra_c[x__gindex]     
                                if length(x__cfgname) > 0 
                                    x__cfgindex = get_elemindex(rxnsystem.configurations.names,x__cfgname,0) 
                                    x__isgas = false
                                    if x__cfgindex > 0 
                                        x__isgas = (get_elemindex(rxnsystem.configurations.indxs_gas,x__cfgindex,0) > 0)
                                    end
                                    if temprun_relGparams.aryG_gmodes[x__gindex] == "gas" || x__isgas == true
                                        if x__cfgindex > 0 
                                            aryG_gvals[x__gindex] = cfg_G_ref[x__cfgindex,cfg_G_refcols.G_rel]
                                            aryG_calcd[x__gindex] += 1
                                        end 
                                    elseif temprun_relGparams.aryG_gmodes[x__gindex] == "gts" 
                                        x__cfgindex = get_elemindex(view(rxnsystem.configurations.names,rxnsystem.configurations.indxs_gas),x__cfgname,0) 
                                        if x__cfgindex > 0 
                                            aryG_gvals[x__gindex] = cfg_G_ref_gaststs[rxnsystem.configurations.dindxs[x__cfgname],cfg_G_refcols.G_rel]
                                            aryG_calcd[x__gindex] += 1
                                        end 
                                    elseif temprun_relGparams.aryG_gmodes[x__gindex] == "cfg" 
                                        if x__cfgindex > 0 
                                            x__itpcovs = zeros(u_numtype,rxnsystem.odespecies.indxs_adscoads_cnt,1) 
                                            for j in 1:rxnsystem.odespecies.indxs_adscoads_cnt 
                                                x__stateindex = get_elemindex(rxnsystem.configurations.states_names,rxnsystem.odespecies.names[rxnsystem.odespecies.indxs_adscoads[j]],0)
                                                if x__stateindex > 0 
                                                    x__itpcovs[j] = rxnsystem.configurations.refstatescovs_unscaled[x__cfgindex,x__stateindex]
                                                end 
                                            end 
                                            for j in 1:rxnsystem.odespecies.indxs_coads_cnt 
                                                x__itpcovs[x__indxconvs_ode2odeadscoads[rxnsystem.odespecies.indxs_coads[j]]] = temprun_relGparams.refinit_coads_covs[j]
                                            end 
                                            x__itprelG = zeros(u_numtype,1,1)
                                            err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_full_unscaled, x__itpcovs, x__itprelG, false, false, nothing, nothing, nothing, nothing)
                                            if err_flag == false 
                                                aryG_gvals[x__gindex] = x__itprelG[1]
                                                aryG_calcd[x__gindex] += 1
                                            end 
                                        else 
                                            err_flag = true 
                                        end   
                                    end 
                                end      
                            end 
                            if err_flag == true 
                                break 
                            end 
                        end 
                    end 
                end 

                # variable energies 
                if err_flag == false 
                    if temprun_relGparams.aryG_var_cnt > 0 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("variable configurations energies")) 
                        x__indxconvs_interpcmpds2ode = Array{Int,1}(undef,0)
                        if size(rxnrun.solveroptions.interp_cmpds_stateindxs,1) > 0 
                            x__indxconvs_interpcmpds2ode = get_elemindex(rxnsystem.odespecies.names,temprun_relGparams.aryG_interp_cmpds_names,0)
                        end 
                        x__xvals = get_view(view(u_o,x__indxconvs_interpcmpds2ode))
                        x__gvals = zeros(u_numtype,1,temprun_relGparams.aryG_var_cnt)
                        err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_itpcmpds_scaled, x__xvals, x__gvals, false, false, nothing, nothing, nothing, nothing)
                        if err_flag == false 
                            for i in axes(temprun_relGparams.aryG_var_gindxs,1)
                                x__gindex = temprun_relGparams.aryG_var_gindxs[i] 
                                aryG_gvals[x__gindex] = x__gvals[i]
                                aryG_calcd[x__gindex] += 1 
                                if length(temprun_relGparams.aryG_gpairs[x__gindex]) > 0 
                                    for j in 1:temprun_relGparams.aryG_cnt 
                                        if temprun_relGparams.aryG_gpairs[x__gindex] == temprun_relGparams.aryG_gnames[j] 
                                            aryG_gvals[j] = x__gvals[i] 
                                            aryG_calcd[j] += 1 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                end 

                # transition states 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("transition states energies")) 
                    x__aryG_tst_rxn_cnt    = 0
                    x__aryG_tst_rxn_indxs  = Array{Int,1}(undef,0) 
                    x__aryG_tst_rxn_dindxs = Dict{Int,Int}()    
                    for h in 1:2 
                        if h == 1 
                            x__indxs = Array{Int,1}(undef,0)
                            for i in axes(temprun_relGparams.aryG_gtitles,1)
                                if startswith(temprun_relGparams.aryG_gtitles[i], "ref::cfg|cfg::") && length(temprun_relGparams.aryG_gtitles[i]) > length("ref::cfg|cfg::")
                                    xcfg = join(SubString(temprun_relGparams.aryG_gtitles[i],(length("ref::cfg|cfg::")+1):length(temprun_relGparams.aryG_gtitles[i])), "")
                                    if get_substrindex(xcfg,"::","first") <= 0 && get_substrindex(xcfg,"--","first") > 0 
                                        push!(x__indxs,i)
                                    end 
                                end 
                            end 
                        else 
                            x__indxs = temprun_relGparams.aryG_tst_gindxs
                        end 
                        if size(x__indxs,1) > 0 
                            for i in axes(x__indxs,1)
                                x__gindex = x__indxs[i] 
                                if x__gindex > 0 
                                    x__cfgname = str_trim(str_cut(str_trim(str_cut(temprun_relGparams.aryG_gtitles[x__gindex], "right", "{", "delete")), "left", "}", "delete")) 
                                    if length(x__cfgname) > 0 && (h == 1 || (h == 2 && (temprun_relGparams.aryG_gmodes[x__gindex] == "gts" || temprun_relGparams.aryG_gmodes[x__gindex] == "sts")))
                                        if temprun_relGparams.aryG_gmodes[x__gindex] == "gts" 
                                            x__cfgindex = get_elemindex(view(rxnsystem.configurations.names,rxnsystem.configurations.indxs_gas),x__cfgname,0) 
                                        else
                                            x__cfgindex = get_elemindex(view(rxnsystem.configurations.names,rxnsystem.configurations.indxs_tst),x__cfgname,0)
                                        end  
                                        if x__cfgindex > 0 
                                            x__gvoindex = 0 
                                            if h == 1 
                                                x__gvoindex = x__gindex 
                                            else 
                                                if length(temprun_relGparams.aryG_gpairs[x__gindex]) > 0 
                                                    for j in 1:temprun_relGparams.aryG_cnt 
                                                        if temprun_relGparams.aryG_gpairs[x__gindex] == temprun_relGparams.aryG_gnames[j] 
                                                            x__gvoindex = j
                                                            break 
                                                        end 
                                                    end 
                                                end
                                            end 
                                            if x__gvoindex > 0 
                                                if temprun_relGparams.aryG_gmodes[x__gindex] == "gts" 
                                                    aryG_gvals[x__gvoindex] = cfg_G_ref_gaststs[x__cfgindex,cfg_G_refcols.G_rel] 
                                                    aryG_calcd[x__gvoindex] += 1 
                                                else 
                                                    x__stindxs = Array{Int,1}(undef,0)
                                                    for j in 1:rxnsystem.configurations.states_indxs_tsts_cnt
                                                        if sum(rxnsystem.configurations.coeffs_states[rxnsystem.configurations.indxs_tst[x__cfgindex],:,rxnsystem.configurations.states_indxs_tsts[j]]) > 0 
                                                            push!(x__stindxs,rxnsystem.configurations.states_indxs_tsts[j])
                                                        end 
                                                    end 
                                                    if size(x__stindxs,1) > 0 
                                                        x__cfindxs = Array{Int,1}(undef,0)
                                                        for j in 1:rxnsystem.configurations.indxs_tst_cnt
                                                            if sum(view(rxnsystem.configurations.coeffs_states,rxnsystem.configurations.indxs_tst[j],:,x__stindxs)) > 0 
                                                                push!(x__cfindxs,rxnsystem.configurations.indxs_tst[j]) 
                                                            end 
                                                        end 
                                                        if size(x__cfindxs,1) > 1 
                                                            nodes_data      = convert.(u_numtype,get_transpose(view(rxnsystem.configurations.refstatescovs_scaled,x__cfindxs,rxnsystem.configurations.states_indxs_adscoads))) 
                                                            nodes_rowsindxs = collect(1:rxnsystem.configurations.states_indxs_adscoads_cnt) 
                                                            nodes_colsindxs = collect(1:size(x__cfindxs,1)) 
                                                            data            = convert.(u_numtype,get_view(reshape(view(cfg_G_ref,x__cfindxs,cfg_G_refcols.G_rel),1,size(x__cfindxs,1))))
                                                            output_pts      = Array{Int,1}(undef,0) 
                                                            err_flag, err_msg, x__interpobj, x__interpunq_indxs, x__interpunq_subindxs, x__interpunq_srcnzdims = Init__Temprun__Interpolation__Obj(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, u_numtype, nodes_data, nodes_rowsindxs, nodes_colsindxs, data, output_pts, rxnrun.solveroptions.ode_multi_threaded, rxnrun.solveroptions.interp_rbf_includepolynomial) 
                                                            x__xvals = get_view(view(u_o,rxnsystem.odespecies.indxs_adscoads))
                                                            x__gvals = zeros(u_numtype,1,1)
                                                            err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, x__interpobj, x__xvals, x__gvals, false, false, nothing, nothing, nothing, nothing)
                                                            if err_flag == false 
                                                                aryG_gvals[x__gvoindex] = x__gvals[1]
                                                                aryG_calcd[x__gvoindex] += 1 
                                                            end 
                                                        elseif size(x__cfindxs,1) == 1 
                                                            aryG_gvals[x__gvoindex] = cfg_G_ref[x__cfindxs[1],cfg_G_refcols.G_rel] 
                                                            aryG_calcd[x__gvoindex] += 1 
                                                        end 
                                                    else
                                                        err_flag = true 
                                                        break 
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                    if h == 2 
                                        for j in axes(temprun_relGparams.aryG_rxnindxs[x__gindex],1)
                                            x__rxnindex = temprun_relGparams.aryG_rxnindxs[x__gindex][j]
                                            if haskey(x__aryG_tst_rxn_dindxs,x__rxnindex) == false 
                                                x__aryG_tst_rxn_cnt += 1
                                                push!(x__aryG_tst_rxn_indxs,x__rxnindex)
                                                x__aryG_tst_rxn_dindxs[x__rxnindex] = x__gindex
                                            end 
                                        end 
                                        x__rxnindx = temprun_relGparams.aryG_rxnindxs[x__gindex][1]
                                        x__segindx = temprun_relGparams.aryG_segindxs[x__gindex][1]
                                        if x__rxnindx > 0 && x__segindx > 0 
                                            for j in 1:temprun_relGparams.aryG_updts_gmaxc 
                                                x__gsubindex = temprun_relGparams.aryG_updts_gindxs[j,x__rxnindx]
                                                x__gsubfactor = temprun_relGparams.aryG_updts_gfactors[j,x__rxnindx]
                                                if x__gsubindex > 0 && x__gsubfactor != 0 
                                                    aryG_gvals[x__gindex] += x__gsubfactor * aryG_gvals[x__gsubindex]
                                                else 
                                                    break 
                                                end
                                            end
                                            aryG_calcd[x__gindex] += 1 
                                        end 
                                    end 
                                else 
                                    err_flag = true 
                                    break 
                                end 
                            end 
                        end 
                    end 
                end 

                # activation energies
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("activation energies")) 
                    x__aryG_tst_actG_o = zeros(u_numtype,x__aryG_tst_rxn_cnt)
                    x__aryG_tst_rxnG_o = zeros(u_numtype,x__aryG_tst_rxn_cnt)
                    for i in axes(x__aryG_tst_rxn_indxs,1)
                        x__rxnindx = x__aryG_tst_rxn_indxs[i]
                        for j in 1:temprun_relGparams.aryG_kcalc_gmaxc 
                            x__gsubindex = temprun_relGparams.aryG_kcalc_gindxs[j,x__rxnindx]
                            if x__gsubindex > 0 
                                x__gsubfactor = temprun_relGparams.aryG_kcalc_gfactors[j,x__rxnindx]
                                if x__gsubfactor != 0
                                    x__aryG_tst_actG_o[i] += x__gsubfactor * aryG_gvals[x__gsubindex]
                                end
                            else
                                break
                            end
                        end
                        x__aryG_tst_actG_o[i] = max(x__aryG_tst_actG_o[i],zero(u_numtype))
                        for j in 1:temprun_relGparams.aryG_rxndg_gmaxc 
                            x__gsubindex = temprun_relGparams.aryG_rxndg_gindxs[j,x__rxnindx]
                            if x__gsubindex > 0 
                                x__gsubfactor = temprun_relGparams.aryG_rxndg_gfactors[j,x__rxnindx]
                                if x__gsubfactor != 0
                                    x__aryG_tst_rxnG_o[i] += x__gsubfactor * aryG_gvals[x__gsubindex]
                                end
                            else
                                break
                            end
                        end
                    end 
                end 

                # reaction energies 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("reaction energies")) 
                    for i in 1:rxnsystem.reactions.cnt
                        x__rdgindx = temprun_relGparams.aryG_rxngindxs_rdg[i]
                        if x__rdgindx > 0 
                            x__gsum = zero(u_numtype)
                            for j in 1:temprun_relGparams.aryG_rxndg_gmaxc 
                                x__gsubindex = temprun_relGparams.aryG_rxndg_gindxs[j,i]
                                if x__gsubindex > 0 
                                    x__gsubfactor = temprun_relGparams.aryG_rxndg_gfactors[j,i]
                                    if x__gsubfactor != 0
                                        x__gsum += x__gsubfactor * aryG_gvals[x__gsubindex]
                                    end
                                else
                                    break
                                end
                            end
                            aryG_gvals[x__rdgindx] = x__gsum
                            aryG_calcd[x__rdgindx] += 1 
                            x__rgoindx = temprun_relGparams.aryG_rxngindxs_rgo[i]
                            if x__rgoindx > 0 
                                aryG_gvals[x__rgoindx] = x__gsum
                                aryG_calcd[x__rgoindx] += 1 
                            end 
                        end 
                    end 
                end 
                
                # trim values 
                if err_flag == false 
                    for i in axes(aryG_gvals,1)
                        if abs(aryG_gvals[i]) < 1e-10 && aryG_calcd[i] > 0
                            aryG_gvals[i] = zero(u_numtype)
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg, aryG_gvals, aryG_calcd
    end



    # Calculation functions 

    function Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_obj, input_vals, output_vals, output_transposeflag, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 

        # this selects the temporary arrays which are expected to be more performant, then calls the interpolation values code

        if err_flag == false 
            nodes_pts  = interp_obj.nodes_pts 
            data_dims  = interp_obj.data_dims 
            input_pts  = size(input_vals,2) 
            if eltype(input_vals) <: eltype(interp_obj.tmp_numelem) 
                tmpindx = 0 
                tmptype = eltype(interp_obj.tmp_numelem)
                if haskey(interp_obj.tmp_inputszs_indxs,input_pts) == false
                    push!(interp_obj.tmp_inputszs_vals,input_pts)
                    interp_obj.tmp_inputszs_indxs[input_pts] = size(interp_obj.tmp_inputszs_vals,1)
                    push!(interp_obj.tmp_pairdists_u,zeros(tmptype,input_pts,nodes_pts))
                    push!(interp_obj.tmp_rbfvals_u,zeros(tmptype,input_pts,nodes_pts))
                    push!(interp_obj.tmp_polynomial_u,zeros(tmptype,input_pts,interp_obj.poly_binomialcnt))
                    push!(interp_obj.tmp_ptlvals_u,zeros(tmptype,input_pts,data_dims))
                end
                tmpindx    = interp_obj.tmp_inputszs_indxs[input_pts] 
                pair_dists = interp_obj.tmp_pairdists_u[tmpindx] 
                rbf_vals   = interp_obj.tmp_rbfvals_u[tmpindx]
                polynomial = interp_obj.tmp_polynomial_u[tmpindx]
                ptl_vals   = interp_obj.tmp_ptlvals_u[tmpindx]
            else 
                if use_tmpcaches == true 
                    pair_dists = tmpcache_pairdists[input_vals,(input_pts,nodes_pts)] 
                    rbf_vals   = tmpcache_rbfvals[input_vals,(input_pts,nodes_pts)] 
                    polynomial = tmpcache_polynomial[input_vals,(input_pts,interp_obj.poly_binomialcnt)] 
                    ptl_vals   = tmpcache_ptlvals[output_vals,(input_pts,data_dims)] 
                else
                    pair_dists = interp_obj.tmp_pairdists_cache[input_vals,(input_pts,nodes_pts)] 
                    rbf_vals   = interp_obj.tmp_rbfvals_cache[input_vals,(input_pts,nodes_pts)]
                    polynomial = interp_obj.tmp_polynomial_cache[input_vals,(input_pts,interp_obj.poly_binomialcnt)]
                    ptl_vals   = interp_obj.tmp_ptlvals_cache[output_vals,(input_pts,data_dims)]
                end 
            end 
            err_flag, err_msg = Rxn__Calc__InterpolatedValues__VAL(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_obj, input_vals, output_vals, output_transposeflag, pair_dists, rbf_vals, polynomial, ptl_vals) 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__Calc__InterpolatedValues__VAL(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_obj, input_vals, output_vals, output_transposeflag, pair_dists, rbf_vals, polynomial, ptl_vals) 

        # this interpolation is based on polyharmonic splines

        if err_flag == false 

            # Initialize variables
            x__nodes_pts    = interp_obj.nodes_pts 
            x__nodes_dims   = interp_obj.nodes_dims
            x__data_dims    = interp_obj.data_dims 
            x__input_isdual = (eltype(input_vals) <: ForwardDiff.Dual)
            x__input_pts    = size(input_vals,2) 
            x__input_zero   = zero(input_vals[1]) 
            x__input_posone = one(input_vals[1]) 
            x__input_negone = -1 * one(input_vals[1]) 

            # Calculate pairwise distances 
            if x__nodes_pts >= x__input_pts 
                @inbounds for i in axes(interp_obj.nodes,2)
                    v__nodes = view(interp_obj.nodes,:,i)
                    for j in axes(input_vals,2)
                        pair_dists[j,i] = get_pairdists_dist(view(input_vals,interp_obj.nodes_srcnzdims,j), v__nodes, x__nodes_dims, true, x__input_zero, x__input_posone, x__input_negone, x__input_isdual) 
                    end 
                end 
            else 
                @inbounds for i in axes(input_vals,2)
                    v__input = view(input_vals,interp_obj.nodes_srcnzdims,i)
                    for j in axes(interp_obj.nodes,2)
                        pair_dists[i,j] = get_pairdists_dist(v__input, view(interp_obj.nodes,:,j), x__nodes_dims, true, x__input_zero, x__input_posone, x__input_negone, x__input_isdual) 
                    end 
                end 
            end

            # Calculate radial basis function (RBF) values 
            rbf_name          = interp_obj.rbf_name 
            rbf_power         = interp_obj.rbf_power 
            rbf_power_even    = interp_obj.rbf_power_even 
            rbf_shapeparam_sq = interp_obj.rbf_shapeparam_sq
            if x__nodes_pts >= x__input_pts 
                @inbounds for i in axes(interp_obj.nodes,2)
                    for j in axes(input_vals,2)
                        rbf_vals[j,i] = Rxn__Calc__InterpolatedValues__RBF(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, pair_dists[j,i], rbf_name, rbf_power, rbf_power_even, rbf_shapeparam_sq, x__input_zero, x__input_posone, x__input_negone, x__input_isdual)
                    end 
                end 
            else
                @inbounds for i in axes(input_vals,2)
                    for j in axes(interp_obj.nodes,2)
                        rbf_vals[i,j] = Rxn__Calc__InterpolatedValues__RBF(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, pair_dists[i,j], rbf_name, rbf_power, rbf_power_even, rbf_shapeparam_sq, x__input_zero, x__input_posone, x__input_negone, x__input_isdual)
                    end 
                end 
            end
            
            # Calculate weights 
            if output_transposeflag == true 
                @inbounds for i in axes(rbf_vals,1) 
                    for j in axes(interp_obj.rbf_weights,2) 
                        xf = false 
                        for k in axes(rbf_vals,2) 
                            if xf == true 
                                output_vals[j,i] += rbf_vals[i,k] * interp_obj.rbf_weights[k,j]
                            else 
                                output_vals[j,i]  = rbf_vals[i,k] * interp_obj.rbf_weights[k,j]
                                xf = true 
                            end 
                        end
                    end 
                end 
            else 
                mul!(output_vals, rbf_vals, interp_obj.rbf_weights) 
            end
            
            # Add interpolation polynomial, as needed
            if interp_obj.poly_include == true && interp_obj.poly_degree > 0 
                polynomial .= x__input_posone 
                row = 0 
                i = 0
                while i < interp_obj.poly_degree 
                    i += 1 
                    j = 0
                    while j < interp_obj.poly_combos_cnts[i]
                        j += 1
                        x__jindex = row + j + 1
                        k = 0 
                        while k < i 
                            k += 1 
                            x__kindex = interp_obj.nodes_srcnzdims[interp_obj.poly_combos_indxs[row + j, k]]
                            @inbounds for l in axes(input_vals,2)
                                if x__input_isdual == true 
                                    polynomial[l, x__jindex] *= input_vals[x__kindex, l]
                                else
                                    if polynomial[l, x__jindex] != x__input_zero 
                                        if input_vals[x__kindex, l] == x__input_zero
                                            polynomial[l, x__jindex] = x__input_zero
                                        else 
                                            if input_vals[x__kindex, l] != x__input_posone
                                                if polynomial[l, x__jindex] != x__input_posone 
                                                    polynomial[l, x__jindex] *= input_vals[x__kindex, l]
                                                else 
                                                    polynomial[l, x__jindex]  = input_vals[x__kindex, l]
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                            end 
                        end 
                    end 
                    row += interp_obj.poly_combos_cnts[i]
                end 
                mul!(ptl_vals, polynomial, interp_obj.poly_lambda) 
                if output_transposeflag == true 
                    @inbounds for i in axes(ptl_vals,1) 
                        for j in axes(ptl_vals,2) 
                            output_vals[j,i] += ptl_vals[i,j]
                        end 
                    end 
                else
                    output_vals .+= ptl_vals 
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__Calc__InterpolatedValues__RBF(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, pair_dist, rbf_name, rbf_power, rbf_power_even, rbf_shapeparam_sq, x__zero, x__posone, x__negone, x__isdual)
        
        rs = x__zero 
        if rbf_name == "polyharmonic"
            if rbf_power_even == true 
                if rbf_power > x__zero
                    if x__isdual == true 
                        rs = (pair_dist ^ rbf_power) * log(pair_dist) 
                    else 
                        if pair_dist > x__zero && pair_dist != x__posone
                            rs = (pair_dist ^ rbf_power) * log(pair_dist) 
                        else 
                            rs = x__zero
                        end
                    end
                else
                    if x__isdual == true 
                        rs = log(pair_dist) 
                    else 
                        if pair_dist > x__zero && pair_dist != x__posone 
                            rs = log(pair_dist) 
                        else 
                            rs = x__zero
                        end
                    end
                end
            else
                if x__isdual == true 
                    rs = pair_dist ^ rbf_power
                else 
                    if pair_dist > x__zero 
                        if rbf_power > x__posone && pair_dist != x__posone  
                            rs = pair_dist ^ rbf_power
                        else
                            rs = pair_dist
                        end
                    else 
                        rs = x__zero
                    end
                end
            end
        elseif rbf_name == "inversemultiquadric"
            if rbf_shapeparam == x__posone
                if x__isdual == true 
                    rs = 1 / sqrt(1 + pair_dist * pair_dist)
                else 
                    if pair_dist == x__zero 
                        rs = x__posone 
                    elseif pair_dist == x__posone 
                        rs = 1 / sqrt(2 * x__posone)
                    else
                        rs = 1 / sqrt(1 + pair_dist * pair_dist)
                    end
                end
            elseif rbf_shapeparam > x__zero
                if x__isdual == true 
                    rs = 1 / sqrt(1 + rbf_shapeparam_sq * pair_dist * pair_dist)
                else 
                    if pair_dist == x__zero 
                        rs = x__posone 
                    elseif pair_dist == x__posone 
                        rs = 1 / sqrt(1 + rbf_shapeparam_sq)
                    else
                        rs = 1 / sqrt(1 + rbf_shapeparam_sq * pair_dist * pair_dist)
                    end
                end
            else
                rs = x__posone 
            end 
        end

        return rs 
    end 

    function Rxn__Calc__SurfaceEnergies(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_odeparams, temprun_relGparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 

        if err_flag == false 

            # variable surface energies
            if err_flag == false 
                if temprun_relGparams.aryG_var_cnt > 0 
                    err_flag, err_msg = Rxn__Calc__SurfaceEnergies__srfG(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_odeparams, temprun_relGparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                end 
            end

            # transition state energies 
            if err_flag == false 
                if temprun_relGparams.aryG_tst_cnt > 0 
                    err_flag, err_msg = Rxn__Calc__SurfaceEnergies__tstG(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_relGparams, G) 
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__Calc__SurfaceEnergies__srfG(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_odeparams, temprun_relGparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 

        if err_flag == false 
            if temprun_relGparams.aryG_var_cnt > 0 
                flag__u = true 
                if eltype(interp_gvals_tmp[1]) <: eltype(G[1]) && length(interp_gvals_tmp) == temprun_relGparams.aryG_var_cnt 
                    if u_copy == true 
                        if eltype(u[1]) <: eltype(interp_xvals_tmp[1]) && length(interp_xvals_tmp) == temprun_relGparams.aryG_interp_cmpds_cnt 
                            if length(u) == temprun_relGparams.aryG_interp_cmpds_cnt 
                                if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                    interp_xvals_tmp .= u .* temprun_odeparams.ode_scaling_uscale_factors
                                else
                                    interp_xvals_tmp .= u 
                                end
                            else 
                                if ode_include_spcs_g == true 
                                    interp_xvals_tmp .= view(u,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                                else 
                                    interp_xvals_tmp .= view(u,temprun_relGparams.aryG_interp_cmpds_odesubindxs_nongas) 
                                end 
                                if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                    interp_xvals_tmp .= interp_xvals_tmp .* view(temprun_odeparams.ode_scaling_uscale_factors,temprun_relGparams.aryG_interp_cmpds_odeindxs)
                                end
                            end 
                        else 
                            flag__u = false 
                        end 
                    end 
                    if flag__u == true 
                        err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_gvals_tmp, false, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                    else 
                        x__xvals = interp_xvals_cache[u,(temprun_relGparams.aryG_interp_cmpds_cnt,1)] 
                        if length(u) == temprun_relGparams.aryG_interp_cmpds_cnt 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                x__xvals .= u .* temprun_odeparams.ode_scaling_uscale_factors
                            else
                                x__xvals .= u 
                            end
                        else 
                            if ode_include_spcs_g == true 
                                x__xvals .= view(u,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                            else 
                                x__xvals .= view(u,temprun_relGparams.aryG_interp_cmpds_odesubindxs_nongas) 
                            end 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                x__xvals .= x__xvals .* view(temprun_odeparams.ode_scaling_uscale_factors,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                            end
                        end 
                        err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_itpcmpds_scaled, x__xvals, interp_gvals_tmp, false, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                    end 
                    if err_flag == false 
                        G[temprun_relGparams.aryG_var_gindxs] .= view(interp_gvals_tmp,1,:) 
                    end 
                else 
                    x__gvals = interp_gvals_cache[G,(1,temprun_relGparams.aryG_var_cnt)] 
                    if u_copy == true 
                        if eltype(u[1]) <: eltype(interp_xvals_tmp[1]) && length(interp_xvals_tmp) == temprun_relGparams.aryG_interp_cmpds_cnt 
                            if length(u) == temprun_relGparams.aryG_interp_cmpds_cnt 
                                if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                    interp_xvals_tmp .= u .* temprun_odeparams.ode_scaling_uscale_factors 
                                else
                                    interp_xvals_tmp .= u 
                                end
                            else 
                                if ode_include_spcs_g == true 
                                    interp_xvals_tmp .= view(u,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                                else 
                                    interp_xvals_tmp .= view(u,temprun_relGparams.aryG_interp_cmpds_odesubindxs_nongas) 
                                end 
                                if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                    interp_xvals_tmp .= interp_xvals_tmp .* view(temprun_odeparams.ode_scaling_uscale_factors,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                                end
                            end 
                        else 
                            flag__u = false 
                        end 
                    end 
                    if flag__u == true 
                        err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, x__gvals, false, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                    else 
                        x__xvals = interp_xvals_cache[u,(temprun_relGparams.aryG_interp_cmpds_cnt,1)] 
                        if length(u) == temprun_relGparams.aryG_interp_cmpds_cnt 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                x__xvals .= u .* temprun_odeparams.ode_scaling_uscale_factors 
                            else
                                x__xvals .= u 
                            end
                        else 
                            if ode_include_spcs_g == true 
                                x__xvals .= view(u,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                            else 
                                x__xvals .= view(u,temprun_relGparams.aryG_interp_cmpds_odesubindxs_nongas) 
                            end 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true 
                                x__xvals .= x__xvals .* view(temprun_odeparams.ode_scaling_uscale_factors,temprun_relGparams.aryG_interp_cmpds_odeindxs) 
                            end
                        end 
                        err_flag, err_msg = Rxn__Calc__InterpolatedValues(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, interp_itpobj_relG_itpcmpds_scaled, x__xvals, x__gvals, false, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                    end 
                    if err_flag == false 
                        G[temprun_relGparams.aryG_var_gindxs] .= view(x__gvals,1,:) 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__Calc__SurfaceEnergies__tstG(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_relGparams, G) 

        # transition state energies 
        if err_flag == false 
            if temprun_relGparams.aryG_tst_cnt > 0 
                x__gzero = zero(G[1]) 
                x__szero = zero(temprun_relGparams.aryG_updts_gfactors[1]) 
                @inbounds for i in 1:temprun_relGparams.aryG_tst_cnt 
                    x__gindex = temprun_relGparams.aryG_tst_gindxs[i]      
                    if x__gindex > 0 
                        x__gflag = false 
                        x__rxnindx = temprun_relGparams.aryG_rxnindxs[x__gindex][1]
                        if x__rxnindx > 0 
                            for j in 1:temprun_relGparams.aryG_updts_gmaxc 
                                x__gsubindex = temprun_relGparams.aryG_updts_gindxs[j,x__rxnindx]
                                if x__gsubindex > 0 
                                    x__gsubfactor = temprun_relGparams.aryG_updts_gfactors[j,x__rxnindx]
                                    if x__gsubfactor != x__szero && G[x__gsubindex] != x__gzero 
                                        if x__gflag == true 
                                            G[x__gindex] += x__gsubfactor * G[x__gsubindex]
                                        else 
                                            G[x__gindex]  = x__gsubfactor * G[x__gsubindex]
                                            x__gflag = true 
                                        end 
                                    end
                                else
                                    break
                                end
                            end
                        end 
                        if x__gflag == false 
                            G[x__gindex] = x__gzero
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__Calc__RateConstants(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 

        if err_flag == false 
            if initial_flag == true || temprun_relGparams.aryG_var_cnt > 0

                # Update surface energies
                if err_flag == false 
                    if temprun_kcnstparams.kcnsts_nonassigned_cnt > 0
                        if initial_flag == true || temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cnt > 0 || temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cnt > 0 || temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__SurfaceEnergies(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_odeparams, temprun_relGparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                        end 
                    end 
                end

                # Update reaction energies 
                if err_flag == false 
                    if temprun_kcnstparams.kcnsts_nonassigned_cnt > 0
                        x__gzero = zero(G[1])
                        x__szero = zero(temprun_relGparams.aryG_rxndg_gfactors[1]) 
                        @inbounds for i in 1:temprun_rxnparams.rxns_cnt 
                            if initial_flag == true || temprun_kcnstparams.kcnsts_calc_variesflags[i] == true
                                x__rdgindx = temprun_relGparams.aryG_rxngindxs_rdg[i]
                                if x__rdgindx > 0 
                                    x__gsumflag = false 
                                    for j in 1:temprun_relGparams.aryG_rxndg_gmaxc 
                                        x__gsubindex = temprun_relGparams.aryG_rxndg_gindxs[j,i]
                                        if x__gsubindex > 0 
                                            if temprun_relGparams.aryG_rxndg_gflags[j,i] == true 
                                                if x__gsumflag == true 
                                                    x__gsum += temprun_relGparams.aryG_rxndg_gfactors[j,i] * G[x__gsubindex]
                                                else 
                                                    x__gsum  = temprun_relGparams.aryG_rxndg_gfactors[j,i] * G[x__gsubindex]
                                                    x__gsumflag = true 
                                                end 
                                            end
                                        else
                                            break
                                        end
                                    end
                                    if x__gsumflag == false 
                                        x__gsum = x__gzero 
                                    end 
                                    G[x__rdgindx] = x__gsum
                                    if initial_flag == true 
                                        x__rgoindx = temprun_relGparams.aryG_rxngindxs_rgo[i]
                                        if x__rgoindx > 0 
                                            G[x__rgoindx] = x__gsum
                                        end 
                                    end 
                                end 
                            end
                        end 
                    end 
                end 

                # Calculate rate constants
                if err_flag == false 
                    if initial_flag == true 

                        # assigned 
                        if err_flag == false && temprun_kcnstparams.kcnsts_assigned_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__Assigned(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_assigned_cnt, temprun_kcnstparams.kcnsts_assigned_indxs)
                        end 

                        # Adsorption 
                        if err_flag == false && temprun_kcnstparams.kcnsts_calc_ads_hke_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__ADSORB__ADS_HKE(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_calc_ads_hke_cnt, temprun_kcnstparams.kcnsts_calc_ads_hke_indxs, temprun_kcnstparams.kcnsts_calc_ads_hke_cindxs, rxns_adsfluxfactors)
                        end 

                        # Surface - transition state activation
                        if err_flag == false && temprun_kcnstparams.kcnsts_calc_tst_act_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__GENERAL__TST_ACT(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_calc_tst_act_cnt, temprun_kcnstparams.kcnsts_calc_tst_act_indxs, temprun_kcnstparams.kcnsts_calc_tst_act_cindxs)
                        end 

                        # Desorption - quasi-equilibriated 
                        if err_flag == false && temprun_kcnstparams.kcnsts_calc_des_keq_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__DESORB__DES_KEQ(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_calc_des_keq_cnt, temprun_kcnstparams.kcnsts_calc_des_keq_indxs, temprun_kcnstparams.kcnsts_calc_des_keq_cindxs)
                        end 
                    else 

                        # Adsorption - Hertz-Knudsen 
                        if err_flag == false && temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__ADSORB__ADS_HKE(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cnt, temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_indxs, temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cindxs, rxns_adsfluxfactors)
                        end 

                        # Surface - transition state activation
                        if err_flag == false && temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__GENERAL__TST_ACT(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cnt, temprun_kcnstparams.kcnsts_calc_tst_act_varbl_indxs, temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cindxs)
                        end 

                        # Desorption - quasi-equilibriated 
                        if err_flag == false && temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cnt > 0 
                            err_flag, err_msg = Rxn__Calc__RateConstants__DESORB__DES_KEQ(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cnt, temprun_kcnstparams.kcnsts_calc_des_keq_varbl_indxs, temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cindxs)
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 
    
    function Rxn__Calc__RateConstants__Assigned(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, rxncnt, rxnindxs) 
        
        if err_flag == false 
            for i in axes(rxnindxs,1)
                x__rxnindx = rxnindxs[i] 
                if x__rxnindx > 0 
                    k[x__rxnindx] = temprun_kcnstparams.kcnsts_assigned_kvals[x__rxnindx] 
                    if initial_flag == true 
                        k_o[x__rxnindx] = k[x__rxnindx] 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 

    function Rxn__Calc__RateConstants__ADSORB__ADS_HKE(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, rxncnt, rxnindxs, rxncindxs, rxns_adsfluxfactors) 

        if err_flag == false 
            @inbounds for i in axes(rxnindxs,1)
                x__rxnindx = rxnindxs[i]
                if x__rxnindx > 0 
                    if initial_flag == true || temprun_kcnstparams.kcnsts_calc_variesflags[x__rxnindx] == true
                        if temprun_rxnparams.rxns_adshkeflags[x__rxnindx] == true 
                            x__kval = rxns_adsfluxfactors[x__rxnindx] 
                            if initial_flag == false && temprun_kcnstparams.kcnsts_calc_variesflags[x__rxnindx] == true
                                x__rdgindx = temprun_relGparams.aryG_rxngindxs_rdg[x__rxnindx]
                                x__rgoindx = temprun_relGparams.aryG_rxngindxs_rgo[x__rxnindx]
                                if x__rdgindx > 0 && x__rgoindx > 0 
                                    x__kval *= exp(temprun_rxnparams.rxns_tspbalances[x__rxnindx] * (G[x__rgoindx] - G[x__rdgindx]) / temprun_constparams.nvs_kbt_eV)
                                end 
                            end
                        else 
                            x__kval = zero(eltype(k))
                        end 
                    else
                        x__kval = k_o[x__rxnindx] 
                    end 
                    k[x__rxnindx] = x__kval
                    if initial_flag == true 
                        k_o[x__rxnindx] = x__kval 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 

    function Rxn__Calc__RateConstants__DESORB__DES_KEQ(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, rxncnt, rxnindxs, rxncindxs) 
        
        if err_flag == false 
            x__kzero = zero(eltype(k))
            @inbounds for i in axes(rxnindxs,1)
                x__rxnindx = rxnindxs[i]
                if x__rxnindx > 0 
                    if initial_flag == true || temprun_kcnstparams.kcnsts_calc_variesflags[x__rxnindx] == true
                        x__kval = x__kzero 
                        if temprun_rxnparams.rxns_deskeqflags[x__rxnindx] == true 
                            x__rdgindx = temprun_relGparams.aryG_rxngindxs_rdg[x__rxnindx]
                            x__adsrxnindx = temprun_rxnparams.rxns_adsrxnindxs[x__rxnindx]
                            if x__rdgindx > 0 && x__adsrxnindx > 0 
                                x__kval = k[x__adsrxnindx] / exp(G[x__rdgindx] / temprun_constparams.nvs_kbt_eV)
                            end 
                        end 
                    else
                        x__kval = k_o[x__rxnindx] 
                    end 
                    k[x__rxnindx] = x__kval
                    if initial_flag == true 
                        k_o[x__rxnindx] = x__kval 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 

    function Rxn__Calc__RateConstants__GENERAL__TST_ACT(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, G, k, k_o, initial_flag, initial_gasflag, rxncnt, rxnindxs, rxncindxs) 
        
        if err_flag == false 
            x__gzero = zero(G[1])
            x__gsum = x__gzero 
            @inbounds for i in axes(rxnindxs,1)
                x__rxnindx = rxnindxs[i]
                if x__rxnindx > 0 
                    if initial_flag == true || temprun_kcnstparams.kcnsts_calc_variesflags[x__rxnindx] == true
                        x__gsumflag = false 
                        for j in 1:temprun_relGparams.aryG_kcalc_gmaxc 
                            x__gsubindex = temprun_relGparams.aryG_kcalc_gindxs[j,x__rxnindx]
                            if x__gsubindex > 0 
                                if temprun_relGparams.aryG_kcalc_gflags[j,x__rxnindx] == true 
                                    if x__gsumflag == true 
                                        x__gsum += temprun_relGparams.aryG_kcalc_gfactors[j,x__rxnindx] * G[x__gsubindex]
                                    else 
                                        x__gsum  = temprun_relGparams.aryG_kcalc_gfactors[j,x__rxnindx] * G[x__gsubindex]
                                        x__gsumflag = true
                                    end 
                                end
                            else
                                break
                            end
                        end 
                        if x__gsumflag == false 
                            x__gsum = x__gzero 
                        end 
                        x__rdgindx = temprun_relGparams.aryG_rxngindxs_rdg[x__rxnindx]
                        if x__rdgindx > 0 
                            if x__gsum < G[x__rdgindx]
                                x__gsum = G[x__rdgindx] 
                            end 
                        end 
                        if x__gsum > x__gzero 
                            x__kval = temprun_constparams.nvs_kbt_hp_1_s / exp(x__gsum / temprun_constparams.nvs_kbt_eV) 
                        else 
                            x__kval = temprun_constparams.nvs_kbt_hp_1_s / exp(x__gzero) 
                        end 
                    else 
                        x__kval = k_o[x__rxnindx] 
                    end 
                    k[x__rxnindx] = x__kval
                    if initial_flag == true 
                        k_o[x__rxnindx] = x__kval 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg
    end 



    # Reaction system modeling functions 

    function Rxn__ModelSystem(core_path, datafile_path, cl_dir, runs_dir, run_folder, dbgprfx, partofset, setindex, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_taskjobid, run_taskarrayid, run_parallelworkers, run_cache_method, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, solv_num_fmt, solv_num_prec, drcs_analyze, calc_optss) 
        
        # Initialize error checking 
        err_flag = false 
        err_msg = "" 

        # Designate module information 
        module_name = "Microkinetics__Core.jl" 
        module_ver = "A001" 
        sim_started = false 
        log_started = false 
        
        # Initialize logging options
        if err_flag == false 
            x__log_file_sffx = "" 
            if run_temperature_value !== nothing && run_temperature_value != "" 
                x__log_file_sffx = string(x__log_file_sffx,"__",run_temperature_value,"_",run_temperature_units)
            end 
            if run_taskjobid !== nothing && run_taskjobid != ""  
                x__log_file_sffx = string(x__log_file_sffx,"__",run_taskjobid)
            end 
            if run_taskarrayid !== nothing && run_taskarrayid != ""  
                x__log_file_sffx = string(x__log_file_sffx,"__",run_taskarrayid)
            end 
            if partofset == true 
                x__log_file_sffx = string(x__log_file_sffx,"__",setindex)
            end
            x__log_file_path = joinpath(dirname(datafile_path),"Logs")
            if isdir(x__log_file_path) == false 
                mkdir(x__log_file_path)
            end 
            x__log_file_path = joinpath(x__log_file_path,string("RunLog__RxnSystem",x__log_file_sffx,".txt"))
            x__log_file_fsobj = open(x__log_file_path,"w")
            close(x__log_file_fsobj)
            x__log_file_fsobj = open(x__log_file_path,"a")
            msgconfig_master = ct__MessageConfig(now(), now(), true, true, x__log_file_sffx, dirname(datafile_path), x__log_file_path, x__log_file_fsobj)
            msgtxtprfx = dbgprfx 
            msgrslts = ct__MessageResults()
            msgrslts.err_flag = false 
            msgrslts.err_msg = "" 
            msgrslts.rtn_msg = "" 
            msgrslts.item_cnt = 0 
            msgrslts.item_size = 0 
            msgrslts.cols_cnt = 6 
            msgrslts.cols_start_ts = 1
            msgrslts.cols_seg_ts = 2
            msgrslts.cols_log_msg = 3
            msgrslts.cols_log_open = 4
            msgrslts.cols_log_fsobj = 5
            msgrslts.cols_dbg_prfx = 6
            msgrslts.ary_sizes = fill(0,(msgrslts.cols_cnt)) 
            msgrslts.ts_prfx = fill("",0) 
            msgrslts.dbg_prfx = fill("",0) 
            msgrslts.tot_prfx = fill("",0) 
            msgrslts.msg_txt = fill("",0) 
            msgrslts.tmp_start_ts = fill(now(),0) 
            msgrslts.tmp_seg_ts = fill(now(),0) 
            msgrslts.tmp_log_msg = fill(false,0) 
            msgrslts.tmp_log_open = fill(false,0) 
            msgrslts.tmp_dbg_prfx = fill("",0) 
            msgrslts.tmp_msg_txtf = fill("",0) 
            log_started = true 
        end 

        # Log start of simulation
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true , true, 1, 1, string("Simulation started"))
            if err_flag == false 
                sim_started = true 
            end 
        end 

        # Retrieve XML content from data file 
        if err_flag == false 
            xfs = open(datafile_path,"r") 
            datafile_str = read(xfs, String) 
            xml_str = xml_dict(datafile_str) 
            close(xfs) 
            config_data = Dict{String,Array{ct__ConfigRecord,1}}() 
            get_configdata(config_data, "", xml_str, "") 
        end 

        # Initialize reaction system
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Reaction system initializing..."))
            err_flag, err_msg, rxnsystem = Init__RxnSystem(msgrslts, msgconfig_master, string(msgtxtprfx,"  "), err_flag, err_msg, config_data, run_cache_method)
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Reaction system initialized..."))
                err_flag, err_msg = log_rxnsystem(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, rxnsystem)
            else 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Reaction system initialization failed..."))
            end 
        end 
        
        # Initialize simulation runs 
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Reaction runs initializing..."))
            err_flag, err_msg, rxnruns = Init__RxnRuns(msgrslts, msgconfig_master, string(msgtxtprfx,"  "), err_flag, err_msg, config_data, cl_dir, runs_dir, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, rxnsystem)
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Reaction runs initialized..."))
            else 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Reaction runs initialization failed..."))
            end 
        end

        # Initialize configuration energies objects
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing configuration energies objects..."))
            err_flag, err_msg, cfg_G_refcols = Init__Temprun__ConfigsEnergies__Columns(msgrslts, msgconfig_master, string(msgtxtprfx,"  "), err_flag, err_msg) 
        end 

        # Iterate through simulation runs array
        if err_flag == false 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Iterating through simulation runs array..."))
            for i in 1:rxnruns.cnt
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  Run ",i))
                rxnrun = rxnruns.vec[i]
                if length(solv_num_fmt) > 0 
                    rxnrun_numtype = rxnrun.solveroptions.ode_num_fmt_types[solv_num_fmt] 
                else
                    rxnrun_numtype = rxnrun.solveroptions.ode_num_fmt_types[rxnrun.solveroptions.ode_num_fmt_str] 
                end 
                err_flag, err_msg = Rxn__ModelSystem__Rxnrun(msgrslts, msgconfig_master, string(msgtxtprfx,"    "), err_flag, err_msg, rxnsystem, rxnrun, rxnrun_numtype, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, cfg_G_refcols, module_ver, core_path, datafile_path, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, solv_num_fmt, solv_num_prec, drcs_analyze, calc_optss) 
                if err_flag == true 
                    break 
                end 
            end 
        end 

        # Log finished simulation
        if sim_started == true 
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgconfig_master, msgtxtprfx, err_flag, err_msg, true , true, 1, 1, string("Simulation finished"))
        end 

        # Display error 
        if err_flag == true 
            println("ERROR OCCURRED: ",err_msg)
        end 

        # Close logging file
        if log_started == true 
            close(msgconfig_master.log_file_fsobj)
        end 
    end 

    function Rxn__ModelSystem__Rxnrun(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, rxnrun_numtype, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, cfg_G_refcols, module_ver, core_path, datafile_path, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, solv_num_fmt, solv_num_prec, drcs_analyze, calc_optss) 

        if err_flag == false 

            # Reset number precision 
            if length(solv_num_fmt) > 0 
                if lowercase(solv_num_fmt) == "bigfloat" 
                    if solv_num_prec > 0 
                        setprecision(BigFloat,solv_num_prec)
                    else 
                        setprecision(BigFloat,256)
                    end
                end 
            else 
                if lowercase(rxnrun.solveroptions.ode_num_fmt_str) == "bigfloat" 
                    if rxnrun.solveroptions.ode_num_prec > 0 
                        setprecision(BigFloat,rxnrun.solveroptions.ode_num_prec)
                    else 
                        setprecision(BigFloat,256)
                    end
                end 
            end 
    
            # Construct temperatures array 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Constructing temperatures array"))
                err_flag, err_msg, run_temps = Init__RxnRun__Temperatures(msgrslts, msgoptions, string(msgtxtprfx,"      "), err_flag, err_msg, rxnsystem, rxnrun, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units) 
            end 
            
            # Iterate through temperatures array 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Iterating through temperatures array"))
                for j in 1:run_temps.cnt 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true , true, 1, 1, string("  Temperature [",j,"]: ",run_temps.value[j]," ",((run_temps.units_absent == false) ? run_temps.units : "")))
                    err_flag, err_msg = Rxn__ModelSystem__Temprun(
                                                msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, 
                                                rxnsystem, rxnrun, rxnrun_numtype, run_folder, run_temperature_value, run_temperature_units, 
                                                run_timespan_value, run_timespan_units, run_temps, j, cfg_G_refcols, module_ver, core_path, datafile_path, 
                                                solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, solv_num_fmt, solv_num_prec, drcs_analyze, calc_optss
                                            ) 
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Reset number precision 
            if length(solv_num_fmt) > 0 
                if lowercase(solv_num_fmt) == "bigfloat" 
                    setprecision(BigFloat,256)
                end 
            else 
                if lowercase(rxnrun.solveroptions.ode_num_fmt_str) == "bigfloat" 
                    setprecision(BigFloat,256)
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__ModelSystem__Temprun(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, rxnrun_numtype, run_folder, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, cfg_G_refcols, module_ver, core_path, datafile_path, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, solv_num_fmt, solv_num_prec, drcs_analyze, calc_optss) 

        if err_flag == false 

            # Retrieve temperature value
            if err_flag == false 
                run_temp = run_temps.value[run_temps_index] 
                run_temp_K = conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, run_temp, run_temps.units, "K") 
            end 

            # Initialize run logging 
            logging_flag = false 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("initializing run logging")) 
                err_flag, err_msg, logging_flag, temprun_logging, logging_filehandles, msgoptions_combined, msgoptions_run = Init__Temprun__Logging(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, run_temps, run_temps_index, run_temp, run_temp_K, run_folder, rxnrun_numtype)
            end 

            # Log start of temperature run
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_run, msgtxtprfx, err_flag, err_msg, true, false, 1, 1, string(" "))
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_run, msgtxtprfx, err_flag, err_msg, true, false, 1, 1, string("Simulating of reaction system"))
                if msgoptions_run !== nothing 
                    err_flag, err_msg = log_rxnsystem(msgrslts, msgoptions_run, "  ", err_flag, err_msg, rxnsystem) 
                    if err_flag == false 
                        cp(core_path, joinpath(msgoptions_run.vec[1].log_file_folderpath,basename(core_path)), force=true)
                        cp(datafile_path, joinpath(msgoptions_run.vec[1].log_file_folderpath,basename(datafile_path)), force=true)
                    end 
                end 
                err_flag, err_msg = log_rxnrun(msgrslts, msgoptions_combined, "  ", err_flag, err_msg, rxnsystem, rxnrun, run_temps, run_temps_index) 
            end 

            # Initialize constant parameters 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing constant parameters"))
                err_flag, err_msg, temprun_constparams = Init__Temprun__ConstantParameters(msgrslts, msgoptions_combined, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, run_temps, run_temps_index, run_temp, run_temp_K, rxnrun_numtype) 
            end 

            # Initialize ODE parameters 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing ODE parameters"))
                err_flag, err_msg, temprun_odeparams = Init__Temprun__ODEParameters(msgrslts, msgoptions_combined, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, solv_num_fmt, solv_num_prec, rxnrun_numtype) 
            end 

            # Initialize reaction parameters 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing reaction parameters"))
                err_flag, err_msg, temprun_rxnparams = Init__Temprun__ReactionParameters(msgrslts, msgoptions_combined, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, rxnrun_numtype) 
            end 

            # Initialize free energy parameters 
            if err_flag == false 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("Initializing free energy parameters"))
                err_flag, err_msg, temprun_relGparams = Init__Temprun__FreeEnergyParameters(msgrslts, msgoptions_combined, string(msgtxtprfx,"  "), err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, rxnrun_numtype) 
            end 

            # Initialize rate constant parameters 
            if err_flag == false 
