                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species rates integrals"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_RatesIntegrals", wkscnt, "Species Rates Integrals", "A1", [], vcat(["time"], rxnsystem.odespecies.names), hcat(solver_rs.rs_t_dat,(one(rxnrun_numtype) - x__coads_unscaled_sum) .* solver_rs.rs_spcs_ri_dat), true)
                    end
                end 

                # Species - rates compare [Species_RatesCompare]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_spcs_rc == true && solver_rs.output_calced.spcs_rc_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species rates comparison"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_RatesCompare", wkscnt, "Species Rates Compare", "A1", [], vcat(["time"; "maxabsrate"], rxnsystem.odespecies.names), hcat(solver_rs.rs_t_dat,solver_rs.rs_spcs_rc_dat), true)
                    end
                end 

                # Species - rates selectivities [Species_Selectivities]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_spcs_rs == true && solver_rs.output_calced.spcs_rs_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species rates selectivities"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_RatesSelectivities", wkscnt, "Species Selectivities", "A1", [], ["time"; spcs_snames], hcat(solver_rs.rs_t_dat,solver_rs.rs_spcs_rs_dat), true)
                    end
                end 

                # Species - molar rates [Species_MolarRates]
                if err_flag == false  
                    if rxnrun.outputoptions.flags_spcs_n == true && solver_rs.output_calced.spcs_n_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species molar rates"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_MolarRates", wkscnt, "Species Molar Rates", "A1", [], ["time"; rxnsystem.odespecies.names], hcat(solver_rs.rs_t_dat,(one(rxnrun_numtype) - x__coads_unscaled_sum) .* solver_rs.rs_spcs_n_dat), true)
                    end 
                end 

                # Species - molar rates integrals [Species_MolarRatesIntegrals]
                if err_flag == false  
                    if rxnrun.outputoptions.flags_spcs_ni == true && solver_rs.output_calced.spcs_ni_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species molar rates integrals"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_MolarRatesIntegrals", wkscnt, "Species Molar Rates Integrals", "A1", [], vcat(["time"], rxnsystem.odespecies.names), hcat(solver_rs.rs_t_dat,(one(rxnrun_numtype) - x__coads_unscaled_sum) .* solver_rs.rs_spcs_ni_dat), true)
                    end
                end 

                # Species - molar rates compare [Species_MolarRatesCompare]
                if err_flag == false  
                    if rxnrun.outputoptions.flags_spcs_nc == true && solver_rs.output_calced.spcs_nc_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species molar rates comparison"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_MolarRatesCompare", wkscnt, "Species Molar Rates Compare", "A1", [], vcat(["time"; "maxabsrate"], rxnsystem.odespecies.names), hcat(solver_rs.rs_t_dat,solver_rs.rs_spcs_nc_dat), true)
                    end
                end 

                # Species - rates molar selectivities [Species_MolarSelectivities]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_spcs_ns == true && solver_rs.output_calced.spcs_ns_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species molar rates selectivities"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_MolarRatesSelectivities", wkscnt, "Species Molar Selectivities", "A1", [], ["time"; spcs_snames], hcat(solver_rs.rs_t_dat,solver_rs.rs_spcs_ns_dat), true)
                    end
                end 

                # Species - molar rates integrals [Species_MolarRatesTOFs]
                if err_flag == false  
                    if rxnrun_outputoptions_flags_spcs_nt == true && solver_rs_output_calced_spcs_nt_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species molar rates TOFs"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_MolarRatesTOFs", wkscnt, "Species Molar Rates TOFs", "A1", [], ["time"; rxnsystem.odespecies.names], hcat(solver_rs.rs_t_dat,(one(rxnrun_numtype) - x__coads_unscaled_sum) .* solver_rs_rs_spcs_nt_dat), true)
                    end
                end 

                # Species - surface energies [Species_Energies]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_spcs_G == true && solver_rs.output_calced.spcs_G_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  species - energies"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Species_Energies", wkscnt, "Species Energies", "A1", [], ["time"; temprun_relGparams.aryG_gtitles], hcat(solver_rs.rs_t_dat,solver_rs.rs_spcs_G_dat), true) 
                    end 
                end 

                # Configurations reference energies [Configs_RefEnergies]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_cfg_G == true && solver_rs.output_calced.cfg_G_refs_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  configurations reference energies"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Configs_RefEnergies", wkscnt, "Config Ref Energies", "A1", cfg_G_refs_names, cfg_G_refcols.names, solver_rs.rs_cfg_G_refs_dat, true)
                    end
                end 

                # Reactions - rate constants - all [Reactions_RateConstants_All]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rxn_k == true && solver_rs.output_calced.rxn_k_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - rate constants"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_RateConstants_All", wkscnt, "Reactions Rate Constants All", "A1", [], ["time"; rxnsystem.reactions.names], hcat(solver_rs.rs_t_dat,solver_rs.rs_rxn_k_dat), true)
                    end 
                end 

                # Reactions - rates [Reactions_Rates]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rxn_r == true && solver_rs.output_calced.rxn_r_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - rates"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_Rates", wkscnt, "Reactions Rates", "A1", [], ["time"; rxnsystem.reactions.names], hcat(solver_rs.rs_t_dat,(one(rxnrun_numtype) - x__coads_unscaled_sum) .* solver_rs.rs_rxn_r_dat), true)
                    end 
                end 

                # Reactions - rates compare [Reactions_RatesCompare]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rxn_rc == true && solver_rs.output_calced.rxn_rc_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - rates comparison"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_RatesCompare", wkscnt, "Reactions Rates Compare", "A1", [], vcat(["time"; "maxabsrate"], rxnsystem.reactions.names), hcat(solver_rs.rs_t_dat,solver_rs.rs_rxn_rc_dat), true)
                    end 
                end 

                # Reactions - reaction energies [Reactions_Energies]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rxn_G == true && solver_rs.output_calced.rxn_G_calced == true 
                        x__rxntitles = rxnsystem.reactions.names
                        for i in 1:rxnsystem.reactions.cnt 
                            x__rxntitles[i] = string("<",rxnsystem.reactions.rxndirs[i],"> ",rxnsystem.reactions.pairnames[i])
                        end 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - energies"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_Energies", wkscnt, "Reactions Energies", "A1", [], ["time"; x__rxntitles], hcat(solver_rs.rs_t_dat,solver_rs.rs_rxn_G_dat), true) 
                    end 
                end 

                # Reactions - pair rates [Reactions_PairRates]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rpn_r == true && solver_rs.output_calced.rpn_r_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - pair rates"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_PairRates", wkscnt, "Reactions Pair Rates", "A1", [], ["time"; rxnsystem.reactions.pairs_names], hcat(solver_rs.rs_t_dat,(one(rxnrun_numtype) - x__coads_unscaled_sum) .* solver_rs.rs_rpn_r_dat), true)
                    end 
                end 

                # Reactions - pair rates compare [Reactions_PairRatesCompare]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rpn_rc == true && solver_rs.output_calced.rpn_rc_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - pair rates comparison"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_PairRatesCompare", wkscnt, "Reactions Pair Rates Compare", "A1", [], vcat(["time"; "maxabsrate"], rxnsystem.reactions.pairs_names), hcat(solver_rs.rs_t_dat,solver_rs.rs_rpn_rc_dat), true)
                    end 
                end 

                # Reactions - pair reaction energies [Reactions_PairEnergies]
                if err_flag == false 
                    if rxnrun.outputoptions.flags_rpn_G == true && solver_rs.output_calced.rpn_G_calced == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  reactions - pair energies"))
                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                        "Reactions_PairEnergies", wkscnt, "Reactions Pair Energies", "A1", [], ["time"; rxnsystem.reactions.pairs_names], hcat(solver_rs.rs_t_dat,solver_rs.rs_rpn_G_dat), true) 
                    end 
                end 
                            
                # Sensitivity Analysis [JAC_, DRC_, DSC_]
                if err_flag == false 
                    if rxnrun.snsoptions.analyze == true && solver_rs.rs_sns_cnt > 0 && (rxnrun.outputoptions.flags_sns_jac == true || rxnrun.outputoptions.flags_sns_drc == true || rxnrun.outputoptions.flags_sns_dsc == true)
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  sensitivity analysis"))
                        
                        # Rate Sensitivities [JAC_]
                        if err_flag == false 
                            if rxnrun.outputoptions.flags_sns_jac == true && solver_rs.output_calced.sns_jac_calced == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    rate sensitivities"))
                                for i in axes(rxnrun.snsoptions.drc_species,1)
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      ",rxnrun.snsoptions.drc_species[i]))
                                    err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                                        string("JAC_",rxnrun.snsoptions.drc_species[i]), 
                                                                        wkscnt, 
                                                                        string("JAC - ",rxnrun.snsoptions.drc_species[i]), 
                                                                        "A1", 
                                                                        [], 
                                                                        vcat(["time"],solver_rs.rs_sns_names), 
                                                                        hcat(
                                                                            solver_rs.rs_t_dat,
                                                                            reshape(view(solver_rs.rs_sns_jac_dat,:,i,:), solver_rs.rs_t_cnt, solver_rs.rs_sns_cnt)
                                                                        ), 
                                                                        true
                                                                    ) 
                                end 
                            end 
                        end 

                        # Degrees of Rate Control [DRC_]
                        if err_flag == false 
                            if rxnrun.outputoptions.flags_sns_drc == true && solver_rs.output_calced.sns_drc_calced == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    degrees of rate control"))
                                for i in axes(rxnrun.snsoptions.drc_species,1)
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      ",rxnrun.snsoptions.drc_species[i]))
                                    if solver_rs.rs_sns_tst_cnt > 0 
                                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                                            string("DRC_",rxnrun.snsoptions.drc_species[i]), 
                                                                            wkscnt, 
                                                                            string("DRC - ",rxnrun.snsoptions.drc_species[i]), 
                                                                            "A1", 
                                                                            [], 
                                                                            vcat(["time"; "sum(tsts)"],solver_rs.rs_sns_names), 
                                                                            hcat( 
                                                                                solver_rs.rs_t_dat,
                                                                                sum(
                                                                                    view(
                                                                                        reshape(
                                                                                            view(solver_rs.rs_sns_drc_dat,:,i,solver_rs.rs_sns_fractions_cnt+1:solver_rs.rs_sns_cnt), 
                                                                                            solver_rs.rs_t_cnt, 
                                                                                            solver_rs.rs_sns_energies_cnt
                                                                                        ),
                                                                                        :,
                                                                                        solver_rs.rs_sns_tst_indxs
                                                                                    ),
                                                                                    dims=2
                                                                                ),
                                                                                reshape(view(solver_rs.rs_sns_drc_dat,:,i,:), solver_rs.rs_t_cnt, solver_rs.rs_sns_cnt)
                                                                            ), 
                                                                            true 
                                                                        ) 
                                                                                # sum(
                                                                                    # view(
                                                                                        # reshape(
                                                                                            # view(solver_rs.rs_sns_drc_dat,:,i,solver_rs.rs_sns_fractions_cnt+1:solver_rs.rs_sns_cnt), 
                                                                                            # solver_rs.rs_t_cnt, 
                                                                                            # solver_rs.rs_sns_energies_cnt
                                                                                        # ),
                                                                                        # :,
                                                                                        # solver_rs.rs_sns_tst_indxs
                                                                                    # ) ./ 
                                                                                    # reshape(solver_rs.rs_sns_pairs_alpha,1,solver_rs.rs_sns_tst_cnt),
                                                                                    # dims=2
                                                                                # ),
                                    else 
                                        err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                                            string("DRC_",rxnrun.snsoptions.drc_species[i]), 
                                                                            wkscnt, 
                                                                            string("DRC - ",rxnrun.snsoptions.drc_species[i]), 
                                                                            "A1", 
                                                                            [], 
                                                                            vcat(["time"],solver_rs.rs_sns_names), 
                                                                            hcat(
                                                                                solver_rs.rs_t_dat,
                                                                                reshape(view(solver_rs.rs_sns_drc_dat,:,i,:), solver_rs.rs_t_cnt, solver_rs.rs_sns_cnt)
                                                                            ), 
                                                                            true
                                                                        )
                                    end 
                                end 
                            end 
                        end

                        # Degrees of Selectivity Control [DSC_]
                        if err_flag == false 
                            if rxnrun.outputoptions.flags_sns_dsc == true && solver_rs.output_calced.sns_dsc_calced == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    degrees of selectivity control"))
                                for i in axes(solver_rs.rs_sns_dsc_pairs_odeindxs,1)
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions_combined, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      ",rxnsystem.odespecies.names[solver_rs.rs_sns_dsc_pairs_odeindxs[i,1]]," | ",rxnsystem.odespecies.names[solver_rs.rs_sns_dsc_pairs_odeindxs[i,2]]))
                                    err_flag, err_msg, wkscnt = Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions_run, "", err_flag, err_msg, rxnrun, temprun_logging, false, 
                                                                        string("DSC_",rxnsystem.odespecies.names[solver_rs.rs_sns_dsc_pairs_odeindxs[i,1]],"_",rxnsystem.odespecies.names[solver_rs.rs_sns_dsc_pairs_odeindxs[i,2]]), 
                                                                        wkscnt, 
                                                                        string("DSC - ",rxnsystem.odespecies.names[solver_rs.rs_sns_dsc_pairs_odeindxs[i,1]]," - ",rxnsystem.odespecies.names[solver_rs.rs_sns_dsc_pairs_odeindxs[i,2]]), 
                                                                        "A1", 
                                                                        [], 
                                                                        ["time"; solver_rs.rs_sns_names], 
                                                                        hcat(
                                                                            solver_rs.rs_t_dat, 
                                                                            reshape(view(solver_rs.rs_sns_dsc_dat,:,i,:), solver_rs.rs_t_cnt, solver_rs.rs_sns_cnt)
                                                                        ), 
                                                                        true
                                                                    )
                                end 
                            end 
                        end 
                    end 
                end 

                # Save copy of XLSX workbook to alternate folder 
                if err_flag == false 
                    if (rxnrun.outputoptions.files_format == "XLSX" || rxnrun.outputoptions.files_format == "XLSX_TXT") && temprun_logging.subfolder_run_path != "" 
                        cp(joinpath(temprun_logging.path_run,"RunData__OUTPUT.xlsx"), joinpath(temprun_logging.subfolder_run_path,"RunData__OUTPUT.xlsx"), force=true)
                    end
                end 
            end 

            # Close log file for this calculation run 
            if logging_flag == true 
                if logging_filehandles.log_file_openflag == true || logging_filehandles.subfolder_log_file_openflag == true 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, false, true, 1, 1, string(" "))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("closing log file(s)..."))
                    if logging_filehandles.log_file_openflag == true 
                        close(logging_filehandles.log_file_fsobj)
                    end
                    if logging_filehandles.subfolder_log_file_openflag == true 
                        close(logging_filehandles.subfolder_log_file_fsobj) 
                    end
                end 
            end 
        end 

        return err_flag, err_msg 
    end 

    function Rxn__ModelSystem__Temprun__Solver(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, aryG_gvals, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_cache, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, drcs_analyze, calc_optss) 
        
        # unsteady solution 
