            err_flag, err_msg, use_scaling_tfactor, use_scaling_tunityflag = Rxn__ModelSystem__Temprun__Solver__ODES(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, aryG_gvals, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_cache, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, drcs_analyze, calc_optss) 
            solver_rs.loop_params.loop_exitflag = true 
            if solver_rs.loop_params.loop_exitflag == true && rxnrun.sbsoptions.analyze == true && solver_rs.loop_params.sbs_checked == true 
                if solver_rs.loop_params.sbs_onsetflag == false || solver_rs.loop_params.sbs_onsetindex <= 0 
                    if ((rxnrun.sbsoptions.timespan_extend == true && solv_sbs_extend == "") || solv_sbs_extend == "true") && solver_rs.loop_params.loop_t_curr < solver_rs.loop_params.loop_t_max 
                        solver_rs.loop_params.loop_exitflag = false 
                    end 
                end 
            end 
            if solver_rs.loop_params.loop_exitflag == true && rxnrun.stsoptions.analyze == true && solver_rs.loop_params.sts_checked == true 
                if solver_rs.loop_params.sts_onsetflag == false || solver_rs.loop_params.sts_onsetindex <= 0 
                    if ((rxnrun.stsoptions.timespan_extend == true && solv_sts_extend == "") || solv_sts_extend == "true") && solver_rs.loop_params.loop_t_curr < solver_rs.loop_params.loop_t_max 
                        solver_rs.loop_params.loop_exitflag = false 
                    end 
                end 
            end 
            if solver_rs.loop_params.loop_exitflag == true 
                err_flag, err_msg, use_scaling_tfactor, use_scaling_tunityflag = Rxn__ModelSystem__Temprun__Solver__DRCS(msgrslts, msgoptions, string(msgtxtprfx,"  "), err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, aryG_gvals, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_cache, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, solv_sbs_extend, solv_sts_extend, solv_sps_extend, drcs_analyze, calc_optss) 
                if solver_rs.loop_params.loop_exitflag == true && rxnrun.spsoptions.analyze == true && solver_rs.loop_params.sps_checked == true 
                    if solver_rs.loop_params.sps_onsetflag == false || solver_rs.loop_params.sps_onsetindex <= 0 
                        if ((rxnrun.spsoptions.timespan_extend == true && solv_sps_extend == "") || solv_sps_extend == "true") && solver_rs.loop_params.loop_t_curr < solver_rs.loop_params.loop_t_max 
                            solver_rs.loop_params.loop_exitflag = false 
                            solver_rs.loop_params.loop_t_curr = min(rxnrun.spsoptions.timespan_extend_factor * solver_rs.loop_params.loop_t_curr,solver_rs.loop_params.loop_t_max)
                            if use_scaling_tflag == true && use_scaling_tunityflag == false 
                                use_scaling_tfactor = solver_rs.loop_params.loop_t_curr 
