                                solver_ode_params = (
                                            solver_ode_params[1], solver_ode_params[2], solver_ode_params[3], solver_ode_params[4], solver_ode_params[5], solver_ode_params[6], solver_ode_params[7], 
                                            solver_ode_params[8], solver_ode_params[9], solver_ode_params[10], solver_ode_params[11], solver_ode_params[12], solver_ode_params[13], solver_ode_params[14], 
                                            solver_ode_params[15], solver_ode_params[16], solver_ode_params[17], 
                                            use_scaling_tfactor, use_scaling_tunityflag, 
                                            solver_ode_params[20], solver_ode_params[21], solver_ode_params[22], solver_ode_params[23], solver_ode_params[24], solver_ode_params[25], solver_ode_params[26], 
                                            solver_ode_params[27], solver_ode_params[28], solver_ode_params[29], solver_ode_params[30], solver_ode_params[31], solver_ode_params[32], solver_ode_params[33], 
                                            solver_ode_params[34], solver_ode_params[35], solver_ode_params[36], solver_ode_params[37], solver_ode_params[38], solver_ode_params[39], solver_ode_params[40], 
                                            solver_ode_params[41], solver_ode_params[42], solver_ode_params[43], solver_ode_params[44], solver_ode_params[45], solver_ode_params[46], solver_ode_params[47]
                                        )
                            end 
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg, use_scaling_tfactor, use_scaling_tunityflag
    end 

    function Rxn__ModelSystem__Temprun__Solver__ODES(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, aryG_gvals, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_cache, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, solv_sbs_extend, solv_sts_extend, solv_sps_extend, solv_scaling_tflag, solv_scaling_tfactor, drcs_analyze, calc_optss) 
        
        if err_flag == false 
            x__runtimeunits = solver_rs.rs_t_units 
            if (lowercase(x__runtimeunits) == "s" && x__runtimeunits != "s") || (lowercase(x__runtimeunits) == "sec" && x__runtimeunits != "sec") 
                x__runtimeunits = lowercase(x__runtimeunits)
            end 
            x__loop_flag = true 
            while x__loop_flag == true 
                x__loop_flag = false 

                # Display loop information 
                x__runtime = string(replace(string(solver_rs.loop_params.loop_t_curr),".0e"=>"e")," ",((x__runtimeunits == "s" || x__runtimeunits == "sec") ? "seconds" : x__runtimeunits)) 
                if x__runtimeunits != "s" && x__runtimeunits != "sec" 
                    x__runtime = string(x__runtime," (",conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, solver_rs.loop_params.loop_t_curr, x__runtimeunits, "s")," seconds)") 
                end 
                x__runtime = replace(x__runtime,".0 "=>" ")
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("ODE loop: ")) 
                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  timespan                      : ",x__runtime)) 
                if rxnrun.sbsoptions.analyze == true 
                    x__sbsmintime = string(replace(string(solver_rs.loop_params.sbs_tmin),".0e"=>"e")," ",((x__runtimeunits == "s" || x__runtimeunits == "sec") ? "seconds" : x__runtimeunits)) 
                    if x__runtimeunits != "s" && x__runtimeunits != "sec" 
                        x__sbsmintime = string(x__sbsmintime," (",conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, solver_rs.loop_params.sbs_tmin, x__runtimeunits, "s")," seconds)") 
                    end 
                    x__sbsmintime = replace(x__sbsmintime,".0 "=>" ")
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  min stable state time         : ",x__sbsmintime)) 
                end 
                if rxnrun.stsoptions.analyze == true 
                    x__stsmintime = string(replace(string(solver_rs.loop_params.sts_tmin),".0e"=>"e")," ",((x__runtimeunits == "s" || x__runtimeunits == "sec") ? "seconds" : x__runtimeunits)) 
                    if x__runtimeunits != "s" && x__runtimeunits != "sec" 
                        x__stsmintime = string(x__stsmintime," (",conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, solver_rs.loop_params.sts_tmin, x__runtimeunits, "s")," seconds)") 
                    end 
                    x__stsmintime = replace(x__stsmintime,".0 "=>" ")
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  min steady state time         : ",x__stsmintime)) 
                end 
                if rxnrun.spsoptions.analyze == true 
                    x__spsmintime = string(replace(string(solver_rs.loop_params.sps_tmin),".0e"=>"e")," ",((x__runtimeunits == "s" || x__runtimeunits == "sec") ? "seconds" : x__runtimeunits)) 
                    if x__runtimeunits != "s" && x__runtimeunits != "sec" 
                        x__spsmintime = string(x__spsmintime," (",conv_value(rxnsystem.physcnsts, rxnsystem.physconvs, solver_rs.loop_params.sps_tmin, x__runtimeunits, "s")," seconds)") 
                    end 
                    x__spsmintime = replace(x__spsmintime,".0 "=>" ")
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  min single pathway state time : ",x__spsmintime)) 
                end 

                # Reset outputs 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  resetting outputs")) 
                    solver_rs.output_calced.spcs_x_calced = false 
                    solver_rs.output_calced.spcs_r_calced = false 
                    solver_rs.output_calced.spcs_ri_calced = false 
                    solver_rs.output_calced.spcs_rc_calced = false 
                    solver_rs.output_calced.spcs_rs_calced = false 
                    solver_rs.output_calced.spcs_n_calced = false 
                    solver_rs.output_calced.spcs_ni_calced = false 
                    solver_rs.output_calced.spcs_nc_calced = false 
                    solver_rs.output_calced.spcs_ns_calced = false 
                    solver_rs.output_calced.sites_x_calced = false 
                    solver_rs.output_calced.sites_r_calced = false 
                    solver_rs.output_calced.sites_tof_calced = false 
                    solver_rs.output_calced.cfg_G_refs_calced = false 
                    solver_rs.output_calced.rxn_info_calced = false 
                    solver_rs.output_calced.spcs_G_calced = false 
                    solver_rs.output_calced.rxn_k_calced = false 
                    solver_rs.output_calced.rxn_r_calced = false 
                    solver_rs.output_calced.rxn_rc_calced = false 
                    solver_rs.output_calced.rpn_r_calced = false 
                    solver_rs.output_calced.rpn_rc_calced = false 
                    solver_rs.output_calced.sns_jac_calced = false 
                    solver_rs.output_calced.sns_drc_calced = false 
                    solver_rs.output_calced.sns_dsc_calced = false 
                    solver_rs.solver_iterations = 0 
                end 

                # Solve system over specified timespan
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  running solver")) 

                    # Construct time stops
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    constructing time stops")) 
                        tadjs = Array{rxnrun_numtype,1}(undef,0) 
                        tadjs_flag = false 
                        if temprun_odeparams.ode_solpts_interp_flag == true 
                            if temprun_odeparams.ode_solpts_interp_mag_min != "" 
                                err_flag, err_msg, x__parsed_flag, x__parsed_val = try_parse(err_flag, err_msg, temprun_odeparams.ode_solpts_interp_mag_min, 0)
                                if x__parsed_flag == true 
                                    if x__parsed_val >= -20
                                    tmagmin = x__parsed_val 
                                    tadjs_flag = true
                                    end
                                else
                                    err_flag = true 
                                end 
                            end 
                        end 
                        if err_flag == false 
                            if tadjs_flag == false 
                                tmagmin = -10
                            end 
                            tmag = get_floor(log10(solver_rs.loop_params.loop_t_curr)) 
                            if tmag >= tmagmin 
                                for i in tmagmin:tmag 
                                    if 1 * ((10.0) ^ i) <= solver_rs.loop_params.loop_t_curr
                                        push!(tadjs,1 * ((10.0) ^ i)) 
                                    else
                                        break 
                                    end 
                                end 
                            end 
                            if size(rxnrun.solveroptions.timepoints,1) > 0 
                                for i in axes(rxnrun.solveroptions.timepoints,1)
                                    if rxnrun.solveroptions.timepoints[i] <= solver_rs.loop_params.loop_t_curr 
                                        push!(tadjs,rxnrun.solveroptions.timepoints[i])
                                    end 
                                end
                            end
                            if rxnrun.sbsoptions.analyze == true 
                                if rxnrun.sbsoptions.mintime_beforeonset_interval.value > 0
                                    if rxnrun.sbsoptions.mintime_beforeonset_interval.value <= solver_rs.loop_params.loop_t_curr
                                        push!(tadjs,rxnrun.sbsoptions.mintime_beforeonset_interval.value)
                                    end 
                                end 
                                if size(solver_rs.loop_params.sbs_tminvals,1) > 0 
                                    for i in axes(solver_rs.loop_params.sbs_tminvals,1)
                                        if solver_rs.loop_params.sbs_tminvals[i] > 0
                                            if solver_rs.loop_params.sbs_tminvals[i] <= solver_rs.loop_params.loop_t_curr 
                                                push!(tadjs,solver_rs.loop_params.sbs_tminvals[i])
                                            end 
                                        end 
                                    end
                                end 
                                if rxnrun.sbsoptions.mintime_afteronset_interval_min.value > 0
                                    if solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_min.value >= 0
                                        push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_min.value)
                                    end 
                                end 
                                if rxnrun.sbsoptions.mintime_afteronset_interval_suf.value > 0
                                    if solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_suf.value >= 0
                                        push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_suf.value)
                                    end 
                                end 
                                push!(tadjs,solver_rs.loop_params.sbs_tmax)
                            end 
                            if rxnrun.stsoptions.analyze == true 
                                if rxnrun.stsoptions.mintime_beforeonset_interval.value > 0
                                    if rxnrun.stsoptions.mintime_beforeonset_interval.value <= solver_rs.loop_params.loop_t_curr
                                        push!(tadjs,rxnrun.stsoptions.mintime_beforeonset_interval.value)
                                    end 
                                end 
                                if size(solver_rs.loop_params.sts_tminvals,1) > 0 
                                    for i in axes(solver_rs.loop_params.sts_tminvals,1)
                                        if solver_rs.loop_params.sts_tminvals[i] > 0
                                            if solver_rs.loop_params.sts_tminvals[i] <= solver_rs.loop_params.loop_t_curr 
                                                push!(tadjs,solver_rs.loop_params.sts_tminvals[i])
                                            end 
                                        end 
                                    end
                                end 
                                if rxnrun.stsoptions.mintime_afteronset_interval_min.value > 0
                                    if solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_min.value >= 0
                                        push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_min.value)
                                    end 
                                end 
                                if rxnrun.stsoptions.mintime_afteronset_interval_suf.value > 0
                                    if solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_suf.value >= 0
                                        push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_suf.value)
                                    end 
                                end 
                                push!(tadjs,solver_rs.loop_params.sts_tmax)
                            end 
                            if rxnrun.spsoptions.analyze == true 
                                if rxnrun.spsoptions.mintime_beforeonset_interval.value > 0
                                    if rxnrun.spsoptions.mintime_beforeonset_interval.value <= solver_rs.loop_params.loop_t_curr 
                                        push!(tadjs,rxnrun.spsoptions.mintime_beforeonset_interval.value)
                                    end 
                                end 
                                if size(solver_rs.loop_params.sps_tminvals,1) > 0 
                                    for i in axes(solver_rs.loop_params.sps_tminvals,1)
                                        if solver_rs.loop_params.sps_tminvals[i] > 0
                                            if solver_rs.loop_params.sps_tminvals[i] <= solver_rs.loop_params.loop_t_curr 
                                                push!(tadjs,solver_rs.loop_params.sps_tminvals[i])
                                            end 
                                        end 
                                    end
                                end 
                                if rxnrun.spsoptions.mintime_afteronset_interval_min.value > 0
                                    if solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_min.value >= 0
                                        push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_min.value)
                                    end 
                                end 
                                if rxnrun.spsoptions.mintime_afteronset_interval_suf.value > 0
                                    if solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_suf.value >= 0
                                        push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_suf.value)
                                    end 
                                end 
                                push!(tadjs,solver_rs.loop_params.sps_tmax)
                            end 
                            for i in axes(solver_rs.loop_params.loop_t_pts,1)
                                if solver_rs.loop_params.loop_t_pts[i] <= solver_rs.loop_params.loop_t_curr
                                    push!(tadjs,solver_rs.loop_params.loop_t_pts[i])
                                end 
                            end 
                            push!(tadjs,solver_rs.loop_params.loop_t_curr)
                            if size(tadjs,1) > 1 
                                tadjs = unique(tadjs)
                                sort!(tadjs) 
                            end 
                            solver_rs.rs_t_pts = deepcopy(tadjs)
                        end
                    end 

                    # Construct initial values 
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    constructing initial values")) 
                        if ode_include_spcs_g == true 
                            x__names = string.("spcs_u: ",rxnsystem.odespecies.names) 
                            x__u = convert.(rxnrun_numtype,u_o)
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true
                                x__u .= x__u ./ get_view(view(temprun_odeparams.ode_scaling_uscale_factors,collect(1:rxnsystem.odespecies.cnt)))
                            end 
                        else 
                            x__names = string.("spcs_u: ",view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_nongas)) 
                            x__u = convert.(rxnrun_numtype,view(u_o,rxnsystem.odespecies.indxs_nongas))
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true
                                x__u .= x__u ./ get_view(view(get_view(view(temprun_odeparams.ode_scaling_uscale_factors,collect(1:rxnsystem.odespecies.cnt))),rxnsystem.odespecies.indxs_nongas)) 
                            end 
                        end 
                        if ode_include_spcs_n == true 
                            x__names = vcat(x__names,string.("spcs_n: ",rxnsystem.odespecies.names))
                            x__u = vcat(x__u,zeros(rxnrun_numtype,rxnsystem.odespecies.cnt))
                        end 
                        if ode_include_rxns_r == true 
                            x__names = vcat(x__names,string.("rxns_r: ",rxnsystem.reactions.names))
                            x__u = vcat(x__u,zeros(rxnrun_numtype,rxnsystem.reactions.cnt))
                        end 
                        x__du = zeros(rxnrun_numtype,size(x__u))
                        Rxn__ModelSystem__Temprun__Solver__SpeciesRates(x__du, x__u, solver_ode_params, zero(rxnrun_numtype)) 
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            x__du ./= use_scaling_tfactor 
                        end 

                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("{init_rates}: ")) 
                        err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                    [
                                                        string.("[",collect(1:size(x__names,1)),"]"), 
                                                        x__names
                                                    ], 
                                                    ["u","du"], 
                                                    hcat(
                                                        str_precfloat_m(x__u,4,true), 
                                                        str_precfloat_m(x__du,4,true)
                                                    ), 
                                                    0, false, true, true
                                                )
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                        
                    end 

                    # Initialize ODE problem  
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    initializing ODE problem...")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      constructing integrator...")) 
                        ode_uary    = deepcopy(x__u)
                        ode_algo    = getfield(Main, Symbol(rxnrun.solveroptions.ode_solver))
                        ode_tpts    = zeros(rxnrun_numtype,2) 
                        ode_tpts[2] = convert(rxnrun_numtype,1e-20) 
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            ode_tpts[2] /= use_scaling_tfactor
                        end 
                        ode_prob = ODEProblem{true,SciMLBase.FullSpecialize}(Rxn__ModelSystem__Temprun__Solver__SpeciesRates, ode_uary, (ode_tpts[1], ode_tpts[2]), solver_ode_params) 
                        global gbl_ode_solver_ctr = 0
                        global gbl_ode_solver_t_magnitude = -100.0
                        global gbl_ode_solver_t_flagcnt = 0 
                        ode_intg = init(ode_prob, ode_algo(), alias_u0=false, abstol=rxnrun.solveroptions.ode_abstol, reltol=rxnrun.solveroptions.ode_reltol, maxiters=rxnrun.solveroptions.ode_maxiters)
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      solving...")) 
                        # if rxnrun.solveroptions.ode_showtiming_solver == true 
                            # @btime solve!($ode_intg)
                        # end 
                        global gbl_ode_solver_ctr = 0
                        global gbl_ode_solver_t_magnitude = -100.0
                        global gbl_ode_solver_t_flagcnt = 0 
                        solve!(ode_intg)
                        ode_solv = ode_intg.sol
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      stats: ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        iterations    : ",ode_solv.destats.nnonliniter)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        accepted steps: ",ode_solv.destats.naccept)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        rejected steps: ",ode_solv.destats.nreject)) 
                    end 

                    # Solve ODE problem  
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    solving ODE problem...")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      constructing integrator...")) 
                        ode_uary    = deepcopy(x__u)
                        ode_algo    = getfield(Main, Symbol(rxnrun.solveroptions.ode_solver))
                        ode_tpts    = zeros(rxnrun_numtype,2) 
                        ode_tpts[2] = convert(rxnrun_numtype,solver_rs.loop_params.loop_t_curr) 
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            ode_tpts[2] /= use_scaling_tfactor
                        end 
                        ode_prob = ODEProblem{true,SciMLBase.FullSpecialize}(Rxn__ModelSystem__Temprun__Solver__SpeciesRates, ode_uary, (ode_tpts[1], ode_tpts[2]), solver_ode_params) 
                        global gbl_ode_solver_ctr = 0
                        global gbl_ode_solver_t_magnitude = -100.0
                        global gbl_ode_solver_t_flagcnt = 0 
                        ode_intg = init(ode_prob, ode_algo(), alias_u0=false, abstol=rxnrun.solveroptions.ode_abstol, reltol=rxnrun.solveroptions.ode_reltol, maxiters=rxnrun.solveroptions.ode_maxiters, tstops=tadjs)
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      solving...")) 
                        # if rxnrun.solveroptions.ode_showtiming_solver == true 
                            # @btime solve!($ode_intg)
                        # end 
                        global gbl_ode_solver_ctr = 0
                        global gbl_ode_solver_t_magnitude = -100.0
                        global gbl_ode_solver_t_flagcnt = 0 
                        solve!(ode_intg)
                        ode_solv = ode_intg.sol
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      stats: ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        iterations    : ",ode_solv.destats.nnonliniter)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        accepted steps: ",ode_solv.destats.naccept)) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        rejected steps: ",ode_solv.destats.nreject)) 
                    end 
                end

                # Retrieve results 
                if err_flag == false 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  retrieving results...")) 

                    # time vector [rs_t_dat] 
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    time vector")) 
                        tary = get_realvalue(ode_solv.t) 
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            tary .= tary .* use_scaling_tfactor
                        end 
                        tadjs = copy(vec(tary)) 
                        push!(tadjs,solver_rs.loop_params.loop_t_curr) 
                        tadjs_flag = false 
                        if temprun_odeparams.ode_solpts_interp_flag == true 
                            if temprun_odeparams.ode_solpts_interp_mag_min != "" 
                                err_flag, err_msg, x__parsed_flag, x__parsed_val = try_parse(err_flag, err_msg, temprun_odeparams.ode_solpts_interp_mag_min, 0)
                                if x__parsed_flag == true 
                                    if x__parsed_val >= -20
                                        tmagmin = x__parsed_val 
                                        tadjs_flag = true
                                    end
                                else
                                    err_flag = true 
                                end 
                            end 
                        end 
                        if err_flag == false 
                            if tadjs_flag == false 
                                tmagmin = -10
                            end 
                            tmag = get_floor(log10(solver_rs.loop_params.loop_t_curr)) 
                            if tmag >= tmagmin 
                                for i in tmagmin:tmag 
                                    if 1 * ((10.0) ^ i) <= solver_rs.loop_params.loop_t_curr
                                        push!(tadjs,1 * ((10.0) ^ i)) 
                                    else
                                        break
                                    end
                                end 
                            end 
                        end
                        tadjs = unique(tadjs)
                        sort!(tadjs) 
                        if temprun_odeparams.ode_solpts_interp_flag == true 
                            tmagmax = tmag
                            tptsmin = 0
                            tptsmax = 0
                            if temprun_odeparams.ode_solpts_interp_mag_max != "" 
                                err_flag, err_msg, x__parsed_magmax_flag, x__parsed_magmax_val = try_parse(err_flag, err_msg, temprun_odeparams.ode_solpts_interp_mag_max, 0)
                                if x__parsed_magmax_flag == true 
                                    if x__parsed_magmax_val >= tmagmin
                                        tmagmax = x__parsed_magmax_val 
                                    end
                                else
                                    err_flag = true 
                                end 
                            end 
                            if temprun_odeparams.ode_solpts_interp_pts_min != "" 
                                err_flag, err_msg, x__parsed_ptsmin_flag, x__parsed_ptsmin_val = try_parse(err_flag, err_msg, temprun_odeparams.ode_solpts_interp_pts_min, 0)
                                if x__parsed_ptsmin_flag == true 
                                    tptsmin = x__parsed_ptsmin_val 
                                else
                                    err_flag = true 
                                end 
                            end 
                            if temprun_odeparams.ode_solpts_interp_pts_max != "" 
                                err_flag, err_msg, x__parsed_ptsmax_flag, x__parsed_ptsmax_val = try_parse(err_flag, err_msg, temprun_odeparams.ode_solpts_interp_pts_max, 0)
                                if x__parsed_ptsmax_flag == true 
                                    if x__parsed_ptsmax_val >= tptsmin 
                                        tptsmax = x__parsed_ptsmax_val 
                                    end
                                else
                                    err_flag = true 
                                end 
                            end 
                            if tptsmin > 0 || tptsmax > 0 
                                tadjs = [t for t in tadjs if t >= 0]
                                tadjs = unique(tadjs)
                                sort!(tadjs)  
                                tindx = 0 
                                for i in tmagmin:min(tmagmax,tmag)
                                    tindx += 1
                                    x__lpcnt = 0
                                    x__lpmax = 100
                                    x__lpflag = true 
                                    while x__lpflag == true && x__lpcnt < x__lpmax 
                                        x__lpflag = false 
                                        x__index = 1
                                        x__sindex = size(tadjs,1) 
                                        x__tot = size(tadjs,1) 
                                        x__cnt = 0
                                        x__cntflag = false
                                        for j in x__index:x__tot 
                                            if ((10.0) ^ i) <= tadjs[j] && tadjs[j] < ((10.0) ^ (i + 1))
                                                if x__cntflag == false 
                                                    x__index = j 
                                                    x__cntflag = true
                                                end
                                                x__cnt += 1
                                            elseif tadjs[j] >= ((10.0) ^ (i + 1))
                                                x__sindex = j
                                                break 
                                            end 
                                        end
                                        x__sindex = max(x__index,x__sindex)
                                        if tadjs[x__index] < solver_rs.loop_params.loop_t_curr && x__index < x__sindex 
                                            if x__cnt < tptsmin 
                                                if x__cnt > 0 
                                                    x__lpflag = true 
                                                    x__nmax = tptsmin - x__cnt 
                                                    for j in x__index:(x__sindex-1)
                                                        if x__index < x__tot 
                                                            push!(tadjs,(tadjs[j] + tadjs[j+1]) / 2) 
                                                        end 
                                                    end 
                                                else
                                                    if x__index < x__tot 
                                                        push!(tadjs,(tadjs[x__index] + tadjs[x__index+1]) / 2) 
                                                    end 
                                                end 
                                            elseif x__cnt > tptsmax 
                                                x__nflag = false 
                                                x__ncnt = 0 
                                                for j in 1:x__cnt 
                                                    if x__nflag == true 
                                                        x__lpflag = true 
                                                        tadjs[x__index + j - 1] = -1 
                                                        x__nflag = false 
                                                        x__ncnt += 1 
                                                    else 
                                                        x__nflag = true 
                                                    end 
                                                    if x__ncnt >= x__cnt - tptsmax 
                                                        break 
                                                    end 
                                                end 
                                            end 
                                            tadjs = [t for t in tadjs if t >= 0] 
                                            tadjs = unique(tadjs) 
                                            sort!(tadjs) 
                                            x__index = 1
                                            x__sindex = size(tadjs,1) 
                                            x__tot = size(tadjs,1) 
                                            x__cnt = 0
                                            x__cntflag = false
                                            for j in x__index:x__tot 
                                                if ((10.0) ^ i) <= tadjs[j] && tadjs[j] < ((10.0) ^ (i + 1))
                                                    if x__cntflag == false 
                                                        x__index = j 
                                                        x__cntflag = true
                                                    end
                                                    x__cnt += 1
                                                elseif tadjs[j] >= ((10.0) ^ (i + 1))
                                                    x__sindex = j
                                                    break 
                                                end 
                                            end
                                        end 
                                        x__cnt = 0 
                                        for j in x__index:x__tot 
                                            if ((10.0) ^ i) <= tadjs[j] && tadjs[j] < ((10.0) ^ (i + 1))
                                                x__cnt += 1
                                            elseif tadjs[j] >= ((10.0) ^ (i + 1))
                                                break 
                                            end 
                                        end
                                        x__lpcnt += 1
                                    end 
                                end 
                            end
                        end 
                        if size(rxnrun.solveroptions.timepoints,1) > 0 
                            for i in axes(rxnrun.solveroptions.timepoints,1)
                                if rxnrun.solveroptions.timepoints[i] <= solver_rs.loop_params.loop_t_curr 
                                    push!(tadjs,rxnrun.solveroptions.timepoints[i])
                                end 
                            end
                        end
                        if rxnrun.sbsoptions.analyze == true 
                            if rxnrun.sbsoptions.mintime_beforeonset_interval.value > 0
                                if rxnrun.sbsoptions.mintime_beforeonset_interval.value <= solver_rs.loop_params.loop_t_curr
                                    push!(tadjs,rxnrun.sbsoptions.mintime_beforeonset_interval.value)
                                end 
                            end 
                            if size(solver_rs.loop_params.sbs_tminvals,1) > 0 
                                for i in axes(solver_rs.loop_params.sbs_tminvals,1)
                                    if solver_rs.loop_params.sbs_tminvals[i] > 0
                                        if solver_rs.loop_params.sbs_tminvals[i] <= solver_rs.loop_params.loop_t_curr
                                            push!(tadjs,solver_rs.loop_params.sbs_tminvals[i])
                                        end 
                                    end 
                                end
                            end 
                            if rxnrun.sbsoptions.mintime_afteronset_interval_min.value > 0
                                if solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_min.value >= 0
                                    push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_min.value)
                                end 
                            end 
                            if rxnrun.sbsoptions.mintime_afteronset_interval_suf.value > 0
                                if solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_suf.value >= 0
                                    push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.sbsoptions.mintime_afteronset_interval_suf.value)
                                end 
                            end 
                            if solver_rs.loop_params.sbs_tmax <= solver_rs.loop_params.loop_t_curr 
                                push!(tadjs,solver_rs.loop_params.sbs_tmax)
                            end 
                        end 
                        if rxnrun.stsoptions.analyze == true 
                            if rxnrun.stsoptions.mintime_beforeonset_interval.value > 0
                                if rxnrun.stsoptions.mintime_beforeonset_interval.value <= solver_rs.loop_params.loop_t_curr
                                    push!(tadjs,rxnrun.stsoptions.mintime_beforeonset_interval.value)
                                end 
                            end 
                            if size(solver_rs.loop_params.sts_tminvals,1) > 0 
                                for i in axes(solver_rs.loop_params.sts_tminvals,1)
                                    if solver_rs.loop_params.sts_tminvals[i] > 0
                                        if solver_rs.loop_params.sts_tminvals[i] <= solver_rs.loop_params.loop_t_curr
                                            push!(tadjs,solver_rs.loop_params.sts_tminvals[i])
                                        end 
                                    end 
                                end
                            end 
                            if rxnrun.stsoptions.mintime_afteronset_interval_min.value > 0
                                if solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_min.value >= 0
                                    push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_min.value)
                                end 
                            end 
                            if rxnrun.stsoptions.mintime_afteronset_interval_suf.value > 0
                                if solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_suf.value >= 0
                                    push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.stsoptions.mintime_afteronset_interval_suf.value)
                                end 
                            end 
                            if solver_rs.loop_params.sts_tmax <= solver_rs.loop_params.loop_t_curr 
                                push!(tadjs,solver_rs.loop_params.sts_tmax)
                            end 
                        end 
                        if rxnrun.spsoptions.analyze == true 
                            if rxnrun.spsoptions.mintime_beforeonset_interval.value > 0
                                if rxnrun.spsoptions.mintime_beforeonset_interval.value <= solver_rs.loop_params.loop_t_curr
                                    push!(tadjs,rxnrun.spsoptions.mintime_beforeonset_interval.value)
                                end 
                            end 
                            if size(solver_rs.loop_params.sps_tminvals,1) > 0 
                                for i in axes(solver_rs.loop_params.sps_tminvals,1)
                                    if solver_rs.loop_params.sps_tminvals[i] > 0
                                        if solver_rs.loop_params.sps_tminvals[i] <= solver_rs.loop_params.loop_t_curr
                                            push!(tadjs,solver_rs.loop_params.sps_tminvals[i])
                                        end 
                                    end 
                                end
                            end 
                            if rxnrun.spsoptions.mintime_afteronset_interval_min.value > 0
                                if solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_min.value >= 0
                                    push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_min.value)
                                end 
                            end 
                            if rxnrun.spsoptions.mintime_afteronset_interval_suf.value > 0
                                if solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_suf.value >= 0
                                    push!(tadjs,solver_rs.loop_params.loop_t_curr - rxnrun.spsoptions.mintime_afteronset_interval_suf.value)
                                end 
                            end 
                            if solver_rs.loop_params.sps_tmax <= solver_rs.loop_params.loop_t_curr 
                                push!(tadjs,solver_rs.loop_params.sps_tmax)
                            end 
                        end 
                        for i in axes(solver_rs.loop_params.loop_t_pts,1)
                            if solver_rs.loop_params.loop_t_pts[i] <= solver_rs.loop_params.loop_t_curr
                                push!(tadjs,solver_rs.loop_params.loop_t_pts[i])
                            end 
                        end 
                        if size(tadjs,1) > 1 
                            tadjs = unique(tadjs)
                            sort!(tadjs) 
                        end 
                        # solver_rs.rs_t_pts = deepcopy(tadjs)
                        x__int = 1
                        x__rs_t_dat = zeros(rxnrun_numtype,(1 + x__int * (size(tadjs,1) - 1),1))
                        for i in 2:size(tadjs,1)
                            for j in 1:x__int
                                x__rs_t_dat[(1 + x__int * (i - 2) + j)] = tadjs[i] - ((x__int - j) / x__int) * (tadjs[i] - tadjs[i - 1])
                            end
                        end 
                        solver_rs.rs_t_dat = unique(x__rs_t_dat)
                        sort!(solver_rs.rs_t_dat) 
                        solver_rs.rs_t_cnt = size(solver_rs.rs_t_dat,1)
                    end 

                    # species fractions [rs_spcs_x_dat]
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    species fractions")) 
                        x__xdat = zeros(rxnrun_numtype,(size(ode_uary,1),solver_rs.rs_t_cnt))
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            x__xtmp = ode_solv(solver_rs.rs_t_dat ./ use_scaling_tfactor)
                        else
                            x__xtmp = ode_solv(solver_rs.rs_t_dat)
                        end
                        for i in 1:solver_rs.rs_t_cnt
                            x__xdat[:,i] .= get_realvalue(x__xtmp[i])
                        end
                        if ode_include_spcs_g == true 
                            solver_rs.rs_spcs_x_dat = get_transpose(view(x__xdat,1:temprun_odeparams.ode_cnt,:))
                        else 
                            solver_rs.rs_spcs_x_dat = zeros(rxnrun_numtype,solver_rs.rs_t_cnt,size(ode_uary,1))
                            solver_rs.rs_spcs_x_dat[:,rxnsystem.odespecies.indxs_nongas] .= get_transpose(view(x__xdat,1:temprun_odeparams.ode_nongas_cnt,:))
                        end 
                        for i in 1:temprun_odeparams.ode_cnt 
                            if temprun_odeparams.ode_const_flags[i] == true 
                                solver_rs.rs_spcs_x_dat[:,i] .= convert(rxnrun_numtype,temprun_odeparams.ode_const_vals[i])
                            end 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true
                                solver_rs.rs_spcs_x_dat[:,i] .= solver_rs.rs_spcs_x_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[i]
                            end 
                        end 
                        solver_rs.output_calced.spcs_x_calced = true
                    end 
                    
                    # species rates [rs_spcs_r_dat]
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    species rates")) 
                        x__rdat = zeros(rxnrun_numtype,(size(ode_uary,1),solver_rs.rs_t_cnt))
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            x__rtmp = ode_solv(solver_rs.rs_t_dat ./ use_scaling_tfactor,Val{1})
                        else 
                            x__rtmp = ode_solv(solver_rs.rs_t_dat,Val{1})
                        end
                        for i in 1:solver_rs.rs_t_cnt 
                            x__rdat[:,i] .= get_realvalue(x__rtmp[i])
                        end
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            x__rdat ./= use_scaling_tfactor 
                        end
                        if ode_include_spcs_g == true 
                            solver_rs.rs_spcs_r_dat = get_transpose(view(x__rdat,1:temprun_odeparams.ode_cnt,:))
                        else 
                            solver_rs.rs_spcs_r_dat = zeros(rxnrun_numtype,solver_rs.rs_t_cnt,size(ode_uary,1))
                            solver_rs.rs_spcs_r_dat[:,rxnsystem.odespecies.indxs_nongas] .= get_transpose(view(x__rdat,1:temprun_odeparams.ode_nongas_cnt,:))
                        end 
                        for i in 1:temprun_odeparams.ode_cnt 
                            if temprun_odeparams.ode_types[i] == "gas" && ode_include_spcs_g == false && ode_include_spcs_n == true 
                                solver_rs.rs_spcs_r_dat[:,i] .= get_transpose(view(x__rdat,temprun_odeparams.ode_nongas_cnt + i,:))
                            end 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true
                                solver_rs.rs_spcs_r_dat[:,i] .= solver_rs.rs_spcs_r_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[i]
                            end 
                        end 
                        solver_rs.output_calced.spcs_r_calced = true 
                        if ode_include_spcs_n == true 
                            if ode_include_spcs_g == true 
                                solver_rs.rs_spcs_n_dat = get_transpose(view(x__rdat,temprun_odeparams.ode_cnt+1:temprun_odeparams.ode_cnt+temprun_odeparams.ode_cnt,:)) 
                            else 
                                solver_rs.rs_spcs_n_dat = get_transpose(view(x__rdat,temprun_odeparams.ode_nongas_cnt+1:temprun_odeparams.ode_nongas_cnt+temprun_odeparams.ode_cnt,:)) 
                            end 
                            for i in 1:temprun_odeparams.ode_cnt 
                                if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true
                                    if ode_include_spcs_g == true 
                                        solver_rs.rs_spcs_n_dat[:,i] .= solver_rs.rs_spcs_n_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_cnt + i]
                                    else 
                                        solver_rs.rs_spcs_n_dat[:,i] .= solver_rs.rs_spcs_n_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_nongas_cnt + i]
                                    end 
                                end 
                            end 
                            solver_rs.output_calced.spcs_n_calced = true 
                        end 
                        if ode_include_rxns_r == true 
                            if ode_include_spcs_n == true 
                                if ode_include_spcs_g == true 
                                    solver_rs.rs_rxn_r_dat = get_transpose(view(x__rdat,temprun_odeparams.ode_cnt+temprun_odeparams.ode_cnt+1:temprun_odeparams.ode_cnt+temprun_odeparams.ode_cnt+rxnsystem.reactions.cnt,:)) 
                                else 
                                    solver_rs.rs_rxn_r_dat = get_transpose(view(x__rdat,temprun_odeparams.ode_nongas_cnt+temprun_odeparams.ode_cnt+1:temprun_odeparams.ode_nongas_cnt+temprun_odeparams.ode_cnt+rxnsystem.reactions.cnt,:)) 
                                end 
                            else 
                                if ode_include_spcs_g == true 
                                    solver_rs.rs_rxn_r_dat = get_transpose(view(x__rdat,temprun_odeparams.ode_cnt+1:temprun_odeparams.ode_cnt+rxnsystem.reactions.cnt,:)) 
                                else 
                                    solver_rs.rs_rxn_r_dat = get_transpose(view(x__rdat,temprun_odeparams.ode_nongas_cnt+1:temprun_odeparams.ode_nongas_cnt+rxnsystem.reactions.cnt,:)) 
                                end 
                            end 
                            for i in 1:rxnsystem.reactions.cnt
                                if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true
                                    if ode_include_spcs_n == true 
                                        if ode_include_spcs_g == true 
                                            solver_rs.rs_rxn_r_dat[:,i] .= solver_rs.rs_rxn_r_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_cnt + temprun_odeparams.ode_cnt + i]
                                        else 
                                            solver_rs.rs_rxn_r_dat[:,i] .= solver_rs.rs_rxn_r_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_nongas_cnt + temprun_odeparams.ode_cnt + i]
                                        end 
                                    else 
                                        if ode_include_spcs_g == true 
                                            solver_rs.rs_rxn_r_dat[:,i] .= solver_rs.rs_rxn_r_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_cnt + i]
                                        else 
                                            solver_rs.rs_rxn_r_dat[:,i] .= solver_rs.rs_rxn_r_dat[:,i] .* temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_nongas_cnt + i]
                                        end 
                                    end 
                                end 
                            end 
                            solver_rs.output_calced.rxn_r_calced = true 
                        end 
                    end 

                    # special fields 
                    if err_flag == false 
                        solver_rs.solver_iterations = ode_solv.destats.nnonliniter 
                    end 
                end 
                
                # Detect stable state conditions
                if err_flag == false 
                    if x__loop_flag == false && rxnrun.sbsoptions.analyze == true
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  detecting stable-state conditions...")) 
                        sns_pairs_alpha = ones(rxnrun_numtype,rxnsystem.reactions.pairs_cnt) 
                        err_flag, err_msg = Rxn__ModelSystem__Temprun__Solver__DetectStableState(msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, false, "fracs|rates", "", sns_pairs_alpha, x__rs_t_dat) 
                        if err_flag == false 
                            if (solver_rs.loop_params.sbs_onsetflag == false || solver_rs.loop_params.sbs_onsetindex <= 0) && ((rxnrun.sbsoptions.timespan_extend == true && solv_sbs_extend == "") || solv_sbs_extend == "true") && rxnrun.sbsoptions.timespan_extend_factor > 1 && solver_rs.loop_params.loop_t_curr < solver_rs.loop_params.loop_t_max 
                                x__loop_flag = true 
                                if solver_rs.loop_params.sbs_textend == true 
                                    solver_rs.loop_params.loop_t_curr = max(solver_rs.loop_params.sbs_tmin,min(rxnrun.sbsoptions.timespan_extend_factor * solver_rs.loop_params.loop_t_curr,solver_rs.loop_params.loop_t_max)) 
                                    if use_scaling_tflag == true && use_scaling_tunityflag == false 
                                        use_scaling_tfactor = solver_rs.loop_params.loop_t_curr 
                                        use_scaling_tunityflag = (use_scaling_tfactor == one(use_scaling_tfactor)) 
                                        solver_ode_params = (
                                                    solver_ode_params[1], solver_ode_params[2], solver_ode_params[3], solver_ode_params[4], solver_ode_params[5], solver_ode_params[6], solver_ode_params[7], 
                                                    solver_ode_params[8], solver_ode_params[9], solver_ode_params[10], solver_ode_params[11], solver_ode_params[12], solver_ode_params[13], solver_ode_params[14], 
                                                    solver_ode_params[15], solver_ode_params[16], solver_ode_params[17], 
                                                    use_scaling_tfactor, use_scaling_tunityflag, 
                                                    solver_ode_params[20], solver_ode_params[21], solver_ode_params[22], solver_ode_params[23], solver_ode_params[24], solver_ode_params[25], solver_ode_params[26], 
                                                    solver_ode_params[27], solver_ode_params[28], solver_ode_params[29], solver_ode_params[30], solver_ode_params[31], solver_ode_params[32], solver_ode_params[33], 
                                                    solver_ode_params[34], solver_ode_params[35], solver_ode_params[36], solver_ode_params[37], solver_ode_params[38], solver_ode_params[39], solver_ode_params[40], 
                                                    solver_ode_params[41], solver_ode_params[42], solver_ode_params[43], solver_ode_params[44], solver_ode_params[45], solver_ode_params[46], solver_ode_params[47]
                                                )
                                    end 
                                end 
                                solver_rs.loop_params.sbs_textend = true 
                            end 
                        end 
                    end 
                end 
                
                # Detect steady state conditions
                if err_flag == false 
                    if x__loop_flag == false && rxnrun.stsoptions.analyze == true
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  detecting steady-state conditions...")) 
                        sns_pairs_alpha = ones(rxnrun_numtype,rxnsystem.reactions.pairs_cnt) 
                        err_flag, err_msg = Rxn__ModelSystem__Temprun__Solver__DetectSteadyState(msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, false, "fracs|rates", "", sns_pairs_alpha, x__rs_t_dat) 
                        if err_flag == false 
                            if (solver_rs.loop_params.sts_onsetflag == false || solver_rs.loop_params.sts_onsetindex <= 0) && ((rxnrun.stsoptions.timespan_extend == true && solv_sts_extend == "") || solv_sts_extend == "true") && rxnrun.stsoptions.timespan_extend_factor > 1 && solver_rs.loop_params.loop_t_curr < solver_rs.loop_params.loop_t_max 
                                x__loop_flag = true 
                                if solver_rs.loop_params.sts_textend == true 
                                    solver_rs.loop_params.loop_t_curr = max(solver_rs.loop_params.sts_tmin,min(rxnrun.stsoptions.timespan_extend_factor * solver_rs.loop_params.loop_t_curr,solver_rs.loop_params.loop_t_max)) 
                                    if use_scaling_tflag == true && use_scaling_tunityflag == false 
                                        use_scaling_tfactor = solver_rs.loop_params.loop_t_curr 
                                        use_scaling_tunityflag = (use_scaling_tfactor == one(use_scaling_tfactor)) 
                                        solver_ode_params = (
                                                    solver_ode_params[1], solver_ode_params[2], solver_ode_params[3], solver_ode_params[4], solver_ode_params[5], solver_ode_params[6], solver_ode_params[7], 
                                                    solver_ode_params[8], solver_ode_params[9], solver_ode_params[10], solver_ode_params[11], solver_ode_params[12], solver_ode_params[13], solver_ode_params[14], 
                                                    solver_ode_params[15], solver_ode_params[16], solver_ode_params[17], 
                                                    use_scaling_tfactor, use_scaling_tunityflag, 
                                                    solver_ode_params[20], solver_ode_params[21], solver_ode_params[22], solver_ode_params[23], solver_ode_params[24], solver_ode_params[25], solver_ode_params[26], 
                                                    solver_ode_params[27], solver_ode_params[28], solver_ode_params[29], solver_ode_params[30], solver_ode_params[31], solver_ode_params[32], solver_ode_params[33], 
                                                    solver_ode_params[34], solver_ode_params[35], solver_ode_params[36], solver_ode_params[37], solver_ode_params[38], solver_ode_params[39], solver_ode_params[40], 
                                                    solver_ode_params[41], solver_ode_params[42], solver_ode_params[43], solver_ode_params[44], solver_ode_params[45], solver_ode_params[46], solver_ode_params[47]
                                                )
                                    end 
                                end 
                                solver_rs.loop_params.sts_textend = true 
                            end 
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg, use_scaling_tfactor, use_scaling_tunityflag 
    end 

    function Rxn__ModelSystem__Temprun__Solver__DRCS(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, aryG_gvals, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_cache, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, solv_sbs_extend, solv_sts_extend, solv_sps_extend, drcs_analyze, calc_optss) 
        
        if err_flag == false 

            # Retrieve solver results - Sensitivity Analysis 
            if err_flag == false 
                if ((rxnrun.snsoptions.analyze == true && drcs_analyze == "") || drcs_analyze == "true") && ((rxnrun.snsoptions.drc_fractions == true && rxnrun.snsoptions.drc_fractions_cnt > 0) || (rxnrun.snsoptions.drc_energies == true && rxnrun.snsoptions.drc_energies_cnt > 0)) && (rxnrun.outputoptions.flags_sns_jac == true || rxnrun.outputoptions.flags_sns_drc == true || rxnrun.outputoptions.flags_sns_dsc == true) 
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("performing sensitivity analysis")) 

                    # Calculate rate sensitivities
                    if err_flag == false 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  calculating rate sensitivites")) 
                        log_actions = true 
                        solv_tspan  = solver_rs.rs_t_dat[length(solver_rs.rs_t_dat)] 
                        solv_tcnt   = size(solver_rs.rs_t_dat,1)
                        solv_tdat   = deepcopy(solver_rs.rs_t_dat)
                        solv_tpts   = deepcopy(solver_rs.rs_t_pts)
                        sns_apply   = true 
                        sns_names   = Array{String,1}(undef,0)
                        sns_pairs_alpha = ones(rxnrun_numtype,rxnsystem.reactions.pairs_cnt) 
                        sns_ode_include_spcs_g = rxnrun.snsoptions.ode_include_spcs_g 
                        sns_ode_include_spcs_n = rxnrun.snsoptions.ode_include_spcs_n 
                        sns_ode_include_rxns_r = rxnrun.snsoptions.ode_include_rxns_r 
                        if sns_ode_include_spcs_g == true 
                            sns_src_idxs  = collect(1:rxnsystem.odespecies.cnt)
                            sns_view_idxs = collect(1:rxnsystem.odespecies.cnt)
                        else 
                            sns_src_idxs  = collect(1:rxnsystem.odespecies.indxs_nongas_cnt)
                            sns_view_idxs = deepcopy(rxnsystem.odespecies.indxs_nongas) 
                        end 
                        sns_cache_odesolv = LazyBufferCache()
                        sns_cache_odeview = LazyBufferCache()
                        solver_rs.rs_sns_fractions_cnt      = 0 
                        solver_rs.rs_sns_fractions_srcindxs = Array{Int,1}(undef,0)
                        solver_rs.rs_sns_energies_cnt       = 0 
                        solver_rs.rs_sns_energies_srcindxs  = Array{Int,1}(undef,0)
                        solver_rs.rs_sns_tst_cnt   = 0 
                        solver_rs.rs_sns_tst_indxs = Array{Int,1}(undef,0) 
                        solver_rs.rs_sns_jac_dat   = Array{rxnrun_numtype,3}(undef,0,0,0) 
                        x__sns_jac_cnt = Array{Array{Int,1},1}(undef,0)
                        x__sns_jac_val = Array{Array{Array{rxnrun_numtype,2},1},1}(undef,0)
                        x__calc_cnt = 0 
                        for i in 1:2 
                            x__sns_apply        = false 
                            x__sns_cnt          = 0 
                            x__sns_setsize      = 0
                            x__sns_chunksize    = 0
                            x__sns_srctypes     = Array{String,1}(undef,0) 
                            x__sns_srcindxs     = Array{Int,1}(undef,0)
                            x__sns_names        = Array{String,1}(undef,0) 
                            x__sns_pairs_alpha  = ones(rxnrun_numtype,rxnsystem.reactions.pairs_cnt) 
                            x__sns_pf_flags     = Array{Bool,2}(undef,0,0) 
                            x__sns_pf_nzpuflags = Array{Bool,2}(undef,0,0) 
                            x__sns_pf_nznuflags = Array{Bool,2}(undef,0,0) 
                            x__sns_pf_factors   = Array{rxnrun_numtype,2}(undef,0,0) 
                            if i == 1 && rxnrun.snsoptions.drc_fractions == true && ((rxnrun.snsoptions.drc_fractions_gas == true && rxnsystem.odespecies.indxs_gas_cnt > 0) || (rxnrun.snsoptions.drc_fractions_ads == true && rxnsystem.odespecies.indxs_ads_cnt > 0) || (rxnrun.snsoptions.drc_fractions_coads == true && rxnsystem.odespecies.indxs_coads_cnt > 0)) 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    perturbing initial pressures and coverages")) 
                                x__sns_apply = true 
                                x__sns_mode = "fractions"
                                if rxnrun.snsoptions.drc_fractions_gas == true && rxnsystem.odespecies.indxs_gas_cnt > 0 
                                    x__sns_cnt      += rxnsystem.odespecies.indxs_gas_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("gas_pressure",rxnsystem.odespecies.indxs_gas_cnt)) 
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, rxnsystem.odespecies.indxs_gas)
                                    x__sns_names     = vcat(x__sns_names, string.("P::",view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_gas)))
                                end 
                                if rxnrun.snsoptions.drc_fractions_ads == true && rxnsystem.odespecies.indxs_ads_cnt > 0 
                                    x__sns_cnt      += rxnsystem.odespecies.indxs_ads_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("ads_coverage",rxnsystem.odespecies.indxs_ads_cnt))
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, rxnsystem.odespecies.indxs_ads)
                                    x__sns_names     = vcat(x__sns_names,string.("X::",view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_ads)))
                                end 
                                if rxnrun.snsoptions.drc_fractions_coads == true && rxnsystem.odespecies.indxs_coads_cnt > 0 
                                    x__sns_cnt      += rxnsystem.odespecies.indxs_coads_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("coads_coverage",rxnsystem.odespecies.indxs_coads_cnt))
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, rxnsystem.odespecies.indxs_coads)
                                    x__sns_names     = vcat(x__sns_names,string.("X::",view(rxnsystem.odespecies.names,rxnsystem.odespecies.indxs_coads)))
                                end 
                                x__sns_setsize   = min((rxnrun.snsoptions.drc_fractions_setsize   > 0 ? rxnrun.snsoptions.drc_fractions_setsize   : 10), x__sns_cnt)
                                x__sns_chunksize = min((rxnrun.snsoptions.drc_fractions_chunksize > 0 ? rxnrun.snsoptions.drc_fractions_chunksize : 10), x__sns_cnt)
                                sns_names = vcat(sns_names,x__sns_names)
                                solver_rs.rs_sns_fractions_cnt = size(x__sns_names,1) 
                                solver_rs.rs_sns_fractions_srcindxs = deepcopy(x__sns_srcindxs)
                                x__sns_pf_flags     = fill(false,rxnsystem.reactions.cnt,x__sns_cnt)
                                x__sns_pf_nzpuflags = fill(false,rxnsystem.reactions.cnt,x__sns_cnt)
                                x__sns_pf_nznuflags = fill(false,rxnsystem.reactions.cnt,x__sns_cnt)
                                x__sns_pf_factors   = zeros(rxnrun_numtype,rxnsystem.reactions.cnt,x__sns_cnt)
                            elseif i == 2 && rxnrun.snsoptions.drc_energies == true && ((rxnrun.snsoptions.drc_energies_gas == true && rxnsystem.configurations.states_indxs_gas_cnt > 0) || (rxnrun.snsoptions.drc_energies_ads == true && rxnsystem.configurations.states_indxs_ads_cnt > 0) || (rxnrun.snsoptions.drc_energies_coads == true && rxnsystem.configurations.states_indxs_coads_cnt > 0) || (rxnrun.snsoptions.drc_energies_tst == true && rxnsystem.reactions.pairs_cnt > 0)) 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    perturbing state energies")) 
                                x__sns_apply = true 
                                x__sns_mode = "energies"
                                if rxnrun.snsoptions.drc_energies_gas == true && rxnsystem.configurations.states_indxs_gas_cnt > 0
                                    x__sns_cnt      += rxnsystem.configurations.states_indxs_gas_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("gas_energy",rxnsystem.configurations.states_indxs_gas_cnt))
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, rxnsystem.configurations.states_indxs_gas)
                                    x__sns_names     = vcat(x__sns_names, string.("G::",view(rxnsystem.configurations.states_names,rxnsystem.configurations.states_indxs_gas)))
                                    x__sz = rxnsystem.configurations.states_indxs_gas_cnt 
                                    if x__sns_cnt > x__sz
                                        x__sns_pf_flags     = hcat(x__sns_pf_flags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nzpuflags = hcat(x__sns_pf_nzpuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nznuflags = hcat(x__sns_pf_nznuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_factors   = hcat(x__sns_pf_factors,fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz))
                                    else 
                                        x__sns_pf_flags     = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nzpuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nznuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_factors   = fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz) 
                                    end 
                                    for j in 1:x__sz 
                                        x__odeindx = get_elemindex(rxnsystem.odespecies.names,rxnsystem.configurations.states_names[rxnsystem.configurations.states_indxs_gas[j]],0) 
                                        if x__odeindx > 0 
                                            for k in 1:rxnsystem.reactions.cnt 
                                                if rxnsystem.reactions.coeffs_alpha[x__odeindx,k] < zero(rxnsystem.reactions.coeffs_alpha[x__odeindx,k]) || get_elemindex(rxnsystem.reactions.rxntypes_des,k,0) > 0 
                                                    x__sns_pf_factors[k,x__sns_cnt-x__sz+j] = convert(rxnrun_numtype,rxnsystem.reactions.coeffs_alpha[x__odeindx,k])
                                                    x__pairindex = temprun_rxnparams.rxns_pairs_indxs[k]
                                                    if x__pairindex > 0 
                                                        x__sns_pairs_alpha[x__pairindex] = max(x__sns_pairs_alpha[x__pairindex],abs(x__sns_pf_factors[k,x__sns_cnt-x__sz+j]))
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                                if rxnrun.snsoptions.drc_energies_ads == true && rxnsystem.configurations.states_indxs_ads_cnt > 0
                                    x__sns_cnt      += rxnsystem.configurations.states_indxs_ads_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("ads_energy",rxnsystem.configurations.states_indxs_ads_cnt))
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, rxnsystem.configurations.states_indxs_ads)
                                    x__sns_names     = vcat(x__sns_names, string.("G::",view(rxnsystem.configurations.states_names,rxnsystem.configurations.states_indxs_ads)))
                                    x__sz = rxnsystem.configurations.states_indxs_ads_cnt 
                                    if x__sns_cnt > x__sz
                                        x__sns_pf_flags     = hcat(x__sns_pf_flags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nzpuflags = hcat(x__sns_pf_nzpuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nznuflags = hcat(x__sns_pf_nznuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_factors   = hcat(x__sns_pf_factors,fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz))
                                    else 
                                        x__sns_pf_flags     = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nzpuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nznuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_factors   = fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz) 
                                    end 
                                    for j in 1:x__sz 
                                        x__odeindx = get_elemindex(rxnsystem.odespecies.names,rxnsystem.configurations.states_names[rxnsystem.configurations.states_indxs_ads[j]],0) 
                                        if x__odeindx > 0 
                                            for k in 1:rxnsystem.reactions.cnt 
                                                if rxnsystem.reactions.coeffs_alpha[x__odeindx,k] < zero(rxnsystem.reactions.coeffs_alpha[x__odeindx,k])
                                                    x__sns_pf_factors[k,x__sns_cnt-x__sz+j] = convert(rxnrun_numtype,rxnsystem.reactions.coeffs_alpha[x__odeindx,k])
                                                    x__pairindex = temprun_rxnparams.rxns_pairs_indxs[k]
                                                    if x__pairindex > 0 
                                                        x__sns_pairs_alpha[x__pairindex] = max(x__sns_pairs_alpha[x__pairindex],abs(x__sns_pf_factors[k,x__sns_cnt-x__sz+j]))
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                                if rxnrun.snsoptions.drc_energies_coads == true && rxnsystem.configurations.states_indxs_coads_cnt > 0
                                    x__sns_cnt      += rxnsystem.configurations.states_indxs_coads_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("coads_energy",rxnsystem.configurations.states_indxs_coads_cnt))
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, rxnsystem.configurations.states_indxs_coads)
                                    x__sns_names     = vcat(x__sns_names, string.("G::",view(rxnsystem.configurations.states_names,rxnsystem.configurations.states_indxs_coads)))
                                    x__sz = rxnsystem.configurations.states_indxs_coads_cnt 
                                    if x__sns_cnt > x__sz
                                        x__sns_pf_flags     = hcat(x__sns_pf_flags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nzpuflags = hcat(x__sns_pf_nzpuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nznuflags = hcat(x__sns_pf_nznuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_factors   = hcat(x__sns_pf_factors,fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz))
                                    else 
                                        x__sns_pf_flags     = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nzpuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nznuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_factors   = fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz) 
                                    end 
                                    for j in 1:x__sz 
                                        x__odeindx = get_elemindex(rxnsystem.odespecies.names,rxnsystem.configurations.states_names[rxnsystem.configurations.states_indxs_coads[j]],0) 
                                        if x__odeindx > 0 
                                            for k in 1:rxnsystem.reactions.cnt 
                                                if rxnsystem.reactions.coeffs_alpha[x__odeindx,k] < zero(rxnsystem.reactions.coeffs_alpha[x__odeindx,k])
                                                    x__sns_pf_factors[k,x__sns_cnt-x__sz+j] = convert(rxnrun_numtype,rxnsystem.reactions.coeffs_alpha[x__odeindx,k])
                                                    x__pairindex = temprun_rxnparams.rxns_pairs_indxs[k]
                                                    if x__pairindex > 0 
                                                        x__sns_pairs_alpha[x__pairindex] = max(x__sns_pairs_alpha[x__pairindex],abs(x__sns_pf_factors[k,x__sns_cnt-x__sz+j]))
                                                    end 
                                                end 
                                            end 
                                        end 
                                    end 
                                end 
                                if rxnrun.snsoptions.drc_energies_tst == true && rxnsystem.reactions.pairs_cnt > 0 
                                    x__sns_cnt      += rxnsystem.reactions.pairs_cnt
                                    x__sns_srctypes  = vcat(x__sns_srctypes, fill("tst_energy",rxnsystem.reactions.pairs_cnt))
                                    x__sns_srcindxs  = vcat(x__sns_srcindxs, collect(1:rxnsystem.reactions.pairs_cnt))
                                    x__sns_names     = vcat(x__sns_names, string.("G::TST::",rxnsystem.reactions.pairs_names))
                                    x__sz = rxnsystem.reactions.pairs_cnt 
                                    if x__sns_cnt > x__sz
                                        x__sns_pf_flags     = hcat(x__sns_pf_flags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nzpuflags = hcat(x__sns_pf_nzpuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_nznuflags = hcat(x__sns_pf_nznuflags,fill(false,rxnsystem.reactions.cnt,x__sz))
                                        x__sns_pf_factors   = hcat(x__sns_pf_factors,fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz))
                                    else 
                                        x__sns_pf_flags     = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nzpuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_nznuflags = fill(false,rxnsystem.reactions.cnt,x__sz)
                                        x__sns_pf_factors   = fill(zero(rxnrun_numtype),rxnsystem.reactions.cnt,x__sz) 
                                    end 
                                    for j in 1:rxnsystem.reactions.cnt 
                                        x__pair_index = temprun_rxnparams.rxns_pairs_indxs[j] 
                                        if x__pair_index > 0 
                                            x__sns_pf_factors[j,x__sns_cnt-x__sz+x__pair_index] = one(rxnrun_numtype)
                                        end 
                                    end 
                                    solver_rs.rs_sns_tst_cnt   = rxnsystem.reactions.pairs_cnt
                                    solver_rs.rs_sns_tst_indxs = collect(x__sns_cnt-rxnsystem.reactions.pairs_cnt+1:x__sns_cnt)
                                end 
                                dtol = 1e-6
                                for j in axes(x__sns_pf_flags,1)
                                    for k in axes(x__sns_pf_flags,2)
                                        if abs(x__sns_pf_factors[j,k]) >= dtol 
                                            x__sns_pf_flags[j,k] = true 
                                            if abs(x__sns_pf_factors[j,k] - one(x__sns_pf_factors[j,k])) < dtol 
                                                x__sns_pf_nzpuflags[j,k] = true 
                                            elseif x__sns_pf_factors[j,k] < zero(x__sns_pf_factors[j,k]) && abs(abs(x__sns_pf_factors[j,k]) - one(x__sns_pf_factors[j,k])) < dtol 
                                                x__sns_pf_nznuflags[j,k] = true 
                                            end 
                                        end 
                                    end 
                                end 
                                x__sns_setsize   = min((rxnrun.snsoptions.drc_energies_setsize   > 0 ? rxnrun.snsoptions.drc_energies_setsize   : 10), x__sns_cnt)
                                x__sns_chunksize = min((rxnrun.snsoptions.drc_energies_chunksize > 0 ? rxnrun.snsoptions.drc_energies_chunksize : 10), x__sns_cnt)
                                solver_rs.rs_sns_energies_cnt      = size(x__sns_names,1) 
                                solver_rs.rs_sns_energies_srcindxs = deepcopy(x__sns_srcindxs)
                                sns_names = vcat(sns_names,x__sns_names)
                                sns_pairs_alpha = deepcopy(x__sns_pairs_alpha)
                            end 
                            x__sns_apply = (x__sns_apply && (x__sns_cnt == size(x__sns_srcindxs,1)) && (x__sns_cnt == size(x__sns_names,1)) && (x__sns_setsize > 0 && x__sns_chunksize > 0))
                            push!(x__sns_jac_cnt,Array{Int,1}(undef,0))
                            push!(x__sns_jac_val,Array{Array{rxnrun_numtype,2},1}(undef,0)) 
                            if x__sns_apply == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("    ",(i == 1 ? "fractions" : "energies")," perturbations")) 
                                x__sns_setcnt  = ceil(Int, x__sns_cnt / x__sns_setsize) 
                                x__set_snssize = min(x__sns_cnt,x__sns_setsize)
                                for j in 1:x__sns_setcnt 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("      set ",j," of ",x__sns_setcnt," : factors ",(x__set_snssize * (j-1) + 1)," to ",min((x__set_snssize * j),x__sns_cnt)," of ",x__sns_cnt)) 
                                    global gbl_sns_chunk_ctr = 0 
                                    x__set_snscnt    = min((x__set_snssize * j),x__sns_cnt) - x__set_snssize * (j-1)
                                    x__set_snsindxs  = collect((x__set_snssize * (j-1) + 1):min((x__set_snssize * j),x__sns_cnt))
                                    x__set_chunksize = min(min(x__set_snssize, x__sns_chunksize),size(x__set_snsindxs,1))
                                    x__set_chunkcnt  = ceil(Int, x__set_snscnt / x__set_chunksize) 
                                    x__set_prob      = ct__Sensitivity_Problem(
                                                            msgrslts, msgoptions, string(msgtxtprfx,"        "), log_actions, rxnsystem, rxnrun, 
                                                            temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, 
                                                            use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, sns_ode_include_spcs_g, sns_ode_include_spcs_n, sns_ode_include_rxns_r, 
                                                            u_o, aryG_gvals, solv_tspan, solv_tcnt, solv_tdat, solv_tpts, 
                                                            x__sns_apply, x__sns_mode, x__set_snssize, x__sns_setcnt, j, x__set_chunksize, x__set_chunkcnt, x__sns_cnt, x__set_snscnt, 
                                                            get_view(view(x__sns_srctypes,x__set_snsindxs)), 
                                                            get_view(view(x__sns_srcindxs,x__set_snsindxs)), 
                                                            get_view(view(x__sns_names,x__set_snsindxs)), 
                                                            x__sns_pairs_alpha, 
                                                            get_view(view(x__sns_pf_flags,:,x__set_snsindxs)), 
                                                            get_view(view(x__sns_pf_nzpuflags,:,x__set_snsindxs)), 
                                                            get_view(view(x__sns_pf_nznuflags,:,x__set_snsindxs)), 
                                                            get_view(view(x__sns_pf_factors,:,x__set_snsindxs)), 
                                                            sns_src_idxs, sns_view_idxs, sns_cache_odesolv, sns_cache_odeview, 
                                                            cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, 
                                                            interp_itpobj_relG_itpcmpds_scaled, interp_xvals_cache, interp_gvals_cache, 
                                                            use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals
                                                        ) 
                                    x__sns_f_x      = zeros(rxnrun_numtype, x__set_snscnt) 
                                    x__sns_f_y      = zeros(rxnrun_numtype, solver_rs.rs_t_cnt * rxnsystem.odespecies.cnt) 
                                    x__sns_jac_cfg  = ForwardDiff.JacobianConfig(x__set_prob, x__sns_f_y, x__sns_f_x, ForwardDiff.Chunk{x__set_chunksize}())
                                    push!(x__sns_jac_cnt[i],size(x__set_snsindxs,1))
                                    push!(x__sns_jac_val[i],zeros(rxnrun_numtype, (solver_rs.rs_t_cnt * rxnsystem.odespecies.cnt, size(x__set_snsindxs,1))))
                                    ForwardDiff.jacobian!(x__sns_jac_val[i][j], x__set_prob, x__sns_f_y, x__sns_f_x, x__sns_jac_cfg)
                                end 
                                x__calc_cnt += 1 
                            end 
                        end 
                        solver_rs.rs_sns_cnt   = size(sns_names,1)
                        solver_rs.rs_sns_names = deepcopy(sns_names) 
                        solver_rs.rs_sns_pairs_alpha = deepcopy(sns_pairs_alpha)
                        if rxnrun.outputoptions.flags_sns_jac == true 
                            solver_rs.rs_sns_jac_dat = zeros(rxnrun_numtype,solver_rs.rs_t_cnt,size(solver_rs.rs_sns_drc_species_odeindxs,1),solver_rs.rs_sns_cnt)
                            x__cnt = 0 
                            for i in 1:2 
                                for j in 1:size(x__sns_jac_cnt[i],1)
                                    if x__sns_jac_cnt[i][j] > 0 
                                        for k in 1:solver_rs.rs_t_cnt 
                                            for l in axes(solver_rs.rs_sns_drc_species_odeindxs,1)
                                                solver_rs.rs_sns_jac_dat[k,l,x__cnt+1:x__cnt+x__sns_jac_cnt[i][j]] .= view(x__sns_jac_val[i][j],solver_rs.rs_t_cnt*(solver_rs.rs_sns_drc_species_odeindxs[l]-1)+k,:)
                                            end 
                                        end 
                                    end 
                                    x__cnt += x__sns_jac_cnt[i][j] 
                                end 
                            end 
                            solver_rs.output_calced.sns_jac_calced = true 
                        end 
                    end 

                    # Calculate degrees of rate control 
                    if err_flag == false 
                        if (rxnrun.outputoptions.flags_sns_drc == true || rxnrun.outputoptions.flags_sns_dsc == true) && x__calc_cnt > 0 && solver_rs.output_calced.spcs_r_calced == true 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  calculating degrees of rate control")) 
                            solver_rs.rs_sns_drc_dat = zeros(rxnrun_numtype,solver_rs.rs_t_cnt,size(solver_rs.rs_sns_drc_species_odeindxs,1),solver_rs.rs_sns_cnt)
                            x__cnt = 0 
                            for i in 1:2 
                                for j in 1:size(x__sns_jac_cnt[i],1)
                                    if x__sns_jac_cnt[i][j] > 0 
                                        for k in 1:solver_rs.rs_t_cnt 
                                            for l in axes(solver_rs.rs_sns_drc_species_odeindxs,1)
                                                xs = view(x__sns_jac_val[i][j],solver_rs.rs_t_cnt*(solver_rs.rs_sns_drc_species_odeindxs[l]-1)+k,:) ./ solver_rs.rs_spcs_r_dat[k,solver_rs.rs_sns_drc_species_odeindxs[l]] 
                                                solver_rs.rs_sns_drc_dat[k,l,x__cnt+1:x__cnt+x__sns_jac_cnt[i][j]] .= map(x -> (isnan(x) ? zero(x) : x), xs)
                                            end 
                                        end 
                                    end 
                                    x__cnt += x__sns_jac_cnt[i][j]
                                end 
                            end 
                            solver_rs.output_calced.sns_drc_calced = true 
                        end 
                    end 

                    # Calculate degrees of selectivity control 
                    if err_flag == false 
                        if rxnrun.outputoptions.flags_sns_dsc == true && solver_rs.output_calced.sns_drc_calced == true 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  calculating degrees of selectivity control")) 
                            solver_rs.rs_sns_dsc_dat = zeros(rxnrun_numtype,solver_rs.rs_t_cnt,size(solver_rs.rs_sns_dsc_pairs_odeindxs,1),solver_rs.rs_sns_cnt)
                            for i in 1:solver_rs.rs_t_cnt 
                                for j in axes(solver_rs.rs_sns_dsc_pairs_odeindxs,1)
                                    x__cnt = 0 
                                    for k in 1:2 
                                        for l in 1:size(x__sns_jac_cnt[k],1)
                                            if x__sns_jac_cnt[k][l] > 0 
                                                solver_rs.rs_sns_dsc_dat[i,j,x__cnt+1:x__cnt+x__sns_jac_cnt[k][l]] .= view(x__sns_jac_val[k][l],solver_rs.rs_t_cnt*(solver_rs.rs_sns_dsc_pairs_odeindxs[j,1]-1)+i,:) ./ solver_rs.rs_spcs_r_dat[i,solver_rs.rs_sns_dsc_pairs_odeindxs[j,1]] 
                                                solver_rs.rs_sns_dsc_dat[i,j,x__cnt+1:x__cnt+x__sns_jac_cnt[k][l]] .-= view(x__sns_jac_val[k][l],solver_rs.rs_t_cnt*(solver_rs.rs_sns_dsc_pairs_odeindxs[j,2]-1)+i,:) ./ solver_rs.rs_spcs_r_dat[i,solver_rs.rs_sns_dsc_pairs_odeindxs[j,2]] 
                                                solver_rs.rs_sns_dsc_dat[i,j,x__cnt+1:x__cnt+x__sns_jac_cnt[k][l]] .= map(x -> (isnan(x) ? zero(x) : x), solver_rs.rs_sns_dsc_dat[i,j,x__cnt+1:x__cnt+x__sns_jac_cnt[k][l]])
                                            end 
                                            x__cnt += x__sns_jac_cnt[k][l]
                                        end 
                                    end 
                                end 
                            end 
                            solver_rs.output_calced.sns_dsc_calced = true
                        end 
                    end 
                    
                    # Detect single pathway state conditions
                    if err_flag == false 
                        if rxnrun.snsoptions.analyze == true && solver_rs.output_calced.sns_drc_calced == true 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("  detecting single pathway state conditions..."))
                            err_flag, err_msg = Rxn__ModelSystem__Temprun__Solver__DetectSinglePathwayState(msgrslts, msgoptions, string(msgtxtprfx,"    "), err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, false, "sens", "", sns_pairs_alpha, solver_rs.rs_t_dat) 
                        end 
                    end 
                end 
            end 
        end 

        return err_flag, err_msg, use_scaling_tfactor, use_scaling_tunityflag
    end 

    function Rxn__ModelSystem__Temprun__Solver__SpeciesRates(du, u, (msgrslts, msgoptions, msgtxtprfx, u_o, du_cache, G_o, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_const_vals, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, sns_apply, sns_pf_pkfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, tmp_gvals, tmp_kvals, tmp_kvals_o, tmp_rvals, tmp_uvals_p, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, show_updates, show_updates_vals), t) 
             
        # Initialize error checking 
        err_flag = false 
        err_msg = "" 

        # Retrieve rates
        if err_flag == false 
            err_flag, err_msg = Rxn__ModelSystem__Temprun__Solver__SpeciesRates__calc(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, u_o, G_o, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_const_vals, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, sns_apply, sns_pf_pkfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, tmp_gvals, tmp_kvals, tmp_kvals_o, tmp_rvals, tmp_uvals_p, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, show_updates, show_updates_vals, du, u, t) 
        end 

        # Return default, as needed 
        if err_flag == true 
            du .= zero(eltype(u[1]))
        end 

        return nothing 
    end 

    function Rxn__ModelSystem__Temprun__Solver__SpeciesRates__RS(u, (msgrslts, msgoptions, msgtxtprfx, u_o, du_cache, G_o, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_const_vals, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, sns_apply, sns_pf_pkfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, tmp_gvals, tmp_kvals, tmp_kvals_o, tmp_rvals, tmp_uvals_p, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, show_updates, show_updates_vals), t) 
             
        # Initialize error checking 
        err_flag = false 
        err_msg = "" 
        du = du_cache[u,size(u)]

        # Retrieve rates
        if err_flag == false 
            err_flag, err_msg = Rxn__ModelSystem__Temprun__Solver__SpeciesRates__calc(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, u_o, G_o, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_const_vals, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, sns_apply, sns_pf_pkfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, tmp_gvals, tmp_kvals, tmp_kvals_o, tmp_rvals, tmp_uvals_p, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, show_updates, show_updates_vals, du, u, t) 
        end 

        # Return default, as needed 
        if err_flag == true 
            du .= zero(eltype(u[1]))
        end 

        return du 
    end 

    function Rxn__ModelSystem__Temprun__Solver__SpeciesRates__calc(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, u_o, G_o, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_const_vals, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, sns_apply, sns_pf_pkfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, tmp_gvals, tmp_kvals, tmp_kvals_o, tmp_rvals, tmp_uvals_p, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, show_updates, show_updates_vals, du, u, t) 
        
        # This function calculates the rates of the ODE species 

        #   DIMENSIONS
        #     xc               = Ss 
        #     ref              = Ss 
        #     xc ./ ref        = Ss 
        #     gamma            = Ss x Rr 
        #     ... .^ gamma     = Ss x Rr 
        #     prod(...,1)      =  1 x Rr 
        #     kc               =  1 x Rr 
        #     kc .* ...        =  1 x Rr 
        #     alphabeta        = Ss x Rr 
        #     alphabeta .* ... = Ss x Rr 
        #     sum(...,2)       = Ss 
        # 

        # Initialize arrays 
        if err_flag == false 
            initial_flag = false 
            initial_gasflag = false 
            u_copy = true 
            u_numtype = eltype(u[1])
            x__kvals_flag = false 
            if u_numtype <: eltype(u_o[1]) 
                x__kvals = tmp_kvals 
                x__rvals = tmp_rvals 
            else 
                x__kvals = cache_kvals[u,(temprun_rxnparams.rxns_cnt)] 
                if isassigned(x__kvals, 1) == false 
                    x__kvals .= convert.(u_numtype,tmp_kvals) 
                    x__kvals_flag = true 
                end 
                x__rvals = cache_rvals[u,(temprun_rxnparams.rxns_cnt)] 
                if isassigned(x__rvals, 1) == false 
                    x__rvals .= zero(u_numtype) 
                end 
            end 
            x__kvals_o_flag = false 
            x__gvals_flag = false 
            if temprun_kcnstparams.kcnsts_calc_varbl_cnt > 0 
                if u_numtype <: eltype(u_o[1]) 
                    x__kvals_o = tmp_kvals_o 
                    x__gvals = tmp_gvals 
                else 
                    x__kvals_o = cache_kvals_o[u,(temprun_rxnparams.rxns_cnt)] 
                    if isassigned(x__kvals_o, 1) == false
                        x__kvals_o .= convert.(u_numtype,tmp_kvals_o)
                        x__kvals_o_flag = true 
                    end 
                    x__gvals = cache_gvals[u,(temprun_relGparams.aryG_cnt)] 
                    if isassigned(x__gvals, 1) == false 
                        x__gvals .= convert.(u_numtype,tmp_gvals) 
                        x__gvals_flag = true 
                    end 
                end 
            end 
            x__init = cache_initflags[u,(1,1)] 
            if isassigned(x__init, 1) == false
                x__init[1] = one(u_numtype)
            end 
            if !(u_numtype <: eltype(u_o[1]))
                newcache_flag = false 
                if u_numtype <: ForwardDiff.Dual 
                    if x__init[1].value < 10 * one(u_numtype)
                        newcache_flag = true 
                    end
                else 
                    if x__init[1] < 10 * one(u_numtype)
                        newcache_flag = true 
                    end
                end 
                if newcache_flag == true 
                    x__init[1] = 10 * one(u_numtype) 
                    if x__kvals_flag == false 
                        x__kvals .= convert.(u_numtype,tmp_kvals) 
                    end 
                    if temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cnt > 0 || temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cnt > 0 || temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cnt > 0
                        if x__kvals_o_flag == false 
                            x__kvals_o .= convert.(u_numtype,tmp_kvals_o)
                        end 
                        if x__gvals_flag == false 
                            x__gvals .= convert.(u_numtype,tmp_gvals) 
                        end 
                    end 
                end 
            end
        end 

        # Calculate rate constants 
        if err_flag == false 
            if temprun_kcnstparams.kcnsts_calc_varbl_cnt > 0 
                err_flag, err_msg = Rxn__Calc__RateConstants(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, u, u_o, t, x__gvals, x__kvals, x__kvals_o, initial_flag, initial_gasflag, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                if sns_apply == true 
                    x__kvals[temprun_kcnstparams.kcnsts_calc_varbl_indxs] .= view(x__kvals,temprun_kcnstparams.kcnsts_calc_varbl_indxs) .* view(sns_pf_pkfactors,temprun_kcnstparams.kcnsts_calc_varbl_indxs) 
                end 
            end 
        end 

        # Calculate reaction rates 
        if err_flag == false 
            u__zero   = zero(u_numtype)
            u__posone = one(u_numtype)
            r__zero   = zero(eltype(x__rvals[1]))
            r__posone = one(eltype(x__rvals[1]))
            @inbounds for i in 1:temprun_rxnparams.rxns_cnt
                if temprun_rxnparams.rxns_ratefactors_nzflags[i] == true && x__kvals[i] > zero(x__kvals[i])
                    x__rvals[i] = r__posone 
                    for j in 1:temprun_odeparams.ode_cnt 
                        if temprun_rxnparams.coeffs_gamma_nzflags[j,i] == true && temprun_odeparams.ode_aflags[j,i] == true 
                            if temprun_odeparams.ode_const_flags[j] == true 
                                if temprun_odeparams.ode_types[j] == "gas" && temprun_odeparams.ode_krate_gaspress_flag == true 
                                    x__u = u__posone
                                else 
                                    x__u = ode_const_vals[j] 
                                end 
                            else 
                                if ode_include_spcs_g == true 
                                    x__u = u[j]
                                else 
                                    if temprun_odeparams.ode_types[j] == "gas" 
                                        if temprun_odeparams.ode_krate_gaspress_flag == true  
                                            x__u = u__posone
                                        else 
                                            x__u = u_o[j] 
                                        end 
                                    else 
                                        x__u = u[temprun_odeparams.ode_odeindex2nongasindex[j]] 
                                    end 
                                end 
                            end 
                            if temprun_odeparams.ode_refstates_nuflags[j] == true
                                x__u /= temprun_odeparams.ode_refstates_values[j]
                            end 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true && temprun_odeparams.ode_scaling_uscale_unityflags[j] == false 
                                x__u *= temprun_odeparams.ode_scaling_uscale_factors[j] 
                            end 
                            if x__u != u__zero 
                                if x__u != u__posone 
                                    if temprun_rxnparams.coeffs_gamma_nzpuflags[j,i] == true 
                                        if x__rvals[i] != r__posone
                                            x__rvals[i] *= x__u 
                                        else
                                            x__rvals[i]  = x__u 
                                        end
                                    elseif temprun_rxnparams.coeffs_gamma_nznuflags[j,i] == true 
                                        x__rvals[i] /= x__u
                                    else 
                                        if x__rvals[i] != r__posone
                                            x__rvals[i] *= x__u ^ temprun_rxnparams.coeffs_gamma[j,i]
                                        else 
                                            x__rvals[i]  = x__u ^ temprun_rxnparams.coeffs_gamma[j,i]
                                        end
                                    end
                                end
                            else 
                                x__rvals[i] = r__zero
                                break 
                            end 
                        end 
                    end 
                    if x__rvals[i] != r__zero 
                        if x__rvals[i] != r__posone 
                            x__rvals[i] *= x__kvals[i]
                        else 
                            x__rvals[i]  = x__kvals[i]
                        end 
                        if temprun_rxnparams.rxns_ratefactors_nzuflags[i] == false
                            x__rvals[i] *= temprun_rxnparams.rxns_ratefactors[i]
                        end 
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            x__rvals[i] *= use_scaling_tfactor 
                        end 
                    end 
                else 
                    x__rvals[i] = r__zero
                end 
                if ode_include_rxns_r == true 
                    if ode_include_spcs_n == true 
                        if ode_include_spcs_g == true 
                            du[temprun_odeparams.ode_cnt + temprun_odeparams.ode_cnt + i] = x__rvals[i] 
                        else 
                            du[temprun_odeparams.ode_nongas_cnt + temprun_odeparams.ode_cnt + i] = x__rvals[i] 
                        end 
                    else
                        if ode_include_spcs_g == true 
                            du[temprun_odeparams.ode_cnt + i] = x__rvals[i] 
                        else 
                            du[temprun_odeparams.ode_nongas_cnt + i] = x__rvals[i] 
                        end 
                    end 
                end 
            end 
        end 

        # Calculate species rates 
        if err_flag == false 
            @inbounds for i in 1:temprun_odeparams.ode_cnt 
                x__du_flag = false 
                if ode_include_spcs_g == true 
                    x__du_indx = i 
                else 
                    if temprun_odeparams.ode_types[i] == "gas" 
                        x__du_indx = 0 
                    else 
                        x__du_indx = temprun_odeparams.ode_odeindex2nongasindex[i] 
                    end 
                end 
                x__dun_flag = false 
                if ode_include_spcs_n == true 
                    if ode_include_spcs_g == true 
                        x__dun_indx = temprun_odeparams.ode_cnt + i  
                    else 
                        x__dun_indx = temprun_odeparams.ode_nongas_cnt + i 
                    end 
                else 
                    x__dun_indx = 0
                end 
                for j in 1:temprun_rxnparams.rxns_cnt 
                    if x__du_indx > 0 && temprun_rxnparams.coeffs_alphabeta_t_nzflags[j,i] == true 
                        if temprun_rxnparams.coeffs_alphabeta_t_nzpuflags[j,i] == true
                            if x__du_flag == true 
                                du[x__du_indx] += x__rvals[j]
                            else 
                                du[x__du_indx]  = x__rvals[j]
                                x__du_flag = true 
                            end 
                        elseif temprun_rxnparams.coeffs_alphabeta_t_nznuflags[j,i] == true
                            if x__du_flag == true 
                                du[x__du_indx] -= x__rvals[j]
                            else 
                                du[x__du_indx]  = u__zero - x__rvals[j]
                                x__du_flag = true 
                            end 
                        else 
                            if x__du_flag == true 
                                du[x__du_indx] += x__rvals[j] * temprun_rxnparams.coeffs_alphabeta_t[j,i] 
                            else 
                                du[x__du_indx]  = x__rvals[j] * temprun_rxnparams.coeffs_alphabeta_t[j,i] 
                                x__du_flag = true 
                            end 
                        end
                    end 
                    if x__dun_indx > 0 && temprun_rxnparams.coeffs_alpha_t_nzflags[j,i] == true 
                        if temprun_rxnparams.coeffs_alpha_t_nzpuflags[j,i] == true 
                            if x__dun_flag == true 
                                du[x__dun_indx] += x__rvals[j] 
                            else 
                                du[x__dun_indx]  = x__rvals[j] 
                                x__dun_flag = true 
                            end 
                        elseif temprun_rxnparams.coeffs_alpha_t_nznuflags[j,i] == true 
                            if x__dun_flag == true 
                                du[x__dun_indx] -= x__rvals[j] 
                            else 
                                du[x__dun_indx]  = u__zero - x__rvals[j] 
                                x__dun_flag = true 
                            end 
                        else 
                            if x__dun_flag == true 
                                du[x__dun_indx] += x__rvals[j] * temprun_rxnparams.coeffs_alpha_t[j,i] 
                            else 
                                du[x__dun_indx]  = x__rvals[j] * temprun_rxnparams.coeffs_alpha_t[j,i] 
                                x__dun_flag = true 
                            end 
                        end 
                    end 
                end 
                if x__du_indx > 0 
                    if x__du_flag == true 
                        if temprun_odeparams.ode_types[i] != "gas" && u[x__du_indx] < u__zero && du[x__du_indx] < u__zero 
                            du[x__du_indx] = u__zero 
                            if x__dun_indx > 0 
                                du[x__dun_indx] = u__zero 
                            end 
                        else 
                            if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true && temprun_odeparams.ode_scaling_uscale_unityflags[i] == false 
                                du[x__du_indx] /= temprun_odeparams.ode_scaling_uscale_factors[i] 
                            end 
                        end 
                    else 
                        du[x__du_indx] = u__zero 
                    end 
                end 
                if x__dun_indx > 0 
                    if x__dun_flag == true 
                        if use_scaling_uscale == true && temprun_odeparams.ode_scaling_uscale_flag == true && temprun_odeparams.ode_scaling_uscale_unityflags[temprun_odeparams.ode_cnt + i] == false
                            du[x__dun_indx] /= temprun_odeparams.ode_scaling_uscale_factors[temprun_odeparams.ode_cnt + i]   
                        end 
                    else 
                        du[x__dun_indx] = u__zero 
                    end 
                end 
            end 
        end 

        # Return default, as needed 
        if err_flag == true 
            du .= zero(u[1])
        end 

        # Check prograss
        if err_flag == false 
            if show_updates == true 
                tx = t 
                if use_scaling_tflag == true && use_scaling_tunityflag == false 
                    tx *= use_scaling_tfactor
                end 
                if gbl_ode_solver_t_magnitude < get_floor(log10(tx)) 
                    global gbl_ode_solver_t_magnitude = get_floor(log10(tx))
                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("        ",(sns_apply == true ? "" : "  "),"time point: ",str_precfloat_m((10^gbl_ode_solver_t_magnitude),8,true)," ",str_precfloat_m(t,8,true))) 
                    if show_updates_vals == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("{u_calc}: ",str_precfloat_m(t,8,true))) 
                        if use_scaling_tflag == true && use_scaling_tunityflag == false 
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                        [
                                                            string.("[",collect(1:temprun_odeparams.ode_cnt),"]"),
                                                            temprun_odeparams.ode_names
                                                        ], 
                                                        ["u_o","u","d_u","d_u*"], 
                                                        hcat(
                                                            str_precfloat_m(view(u_o,1:temprun_odeparams.ode_cnt),8,true),
                                                            str_precfloat_m(view(u,1:temprun_odeparams.ode_cnt),8,true),
                                                            str_precfloat_m(view(du,1:temprun_odeparams.ode_cnt),8,true),
                                                            str_precfloat_m(view(du,1:temprun_odeparams.ode_cnt) ./ use_scaling_tfactor,8,true)
                                                        ), 
                                                        0, false, true, true
                                                    )
                        else
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                        [
                                                            string.("[",collect(1:temprun_odeparams.ode_cnt),"]"),
                                                            temprun_odeparams.ode_names
                                                        ], 
                                                        ["u_o","u","d_u"], 
                                                        hcat(
                                                            str_precfloat_m(view(u_o,1:temprun_odeparams.ode_cnt),8,true),
                                                            str_precfloat_m(view(u,1:temprun_odeparams.ode_cnt),8,true),
                                                            str_precfloat_m(view(du,1:temprun_odeparams.ode_cnt),8,true)
                                                        ), 
                                                        0, false, true, true
                                                    )
                        end 
                        if temprun_kcnstparams.kcnsts_calc_ads_hke_varbl_cnt > 0 || temprun_kcnstparams.kcnsts_calc_des_keq_varbl_cnt > 0 || temprun_kcnstparams.kcnsts_calc_tst_act_varbl_cnt > 0
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("{g_calc}: ",str_precfloat_m(t,8,true))) 
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                        [
                                                            string.("[",collect(1:temprun_relGparams.aryG_cnt),"]"), 
                                                            string.("[",temprun_relGparams.aryG_gindxs,"]"),
                                                            view(temprun_relGparams.aryG_gtitles,temprun_relGparams.aryG_gindxs) 
                                                        ], 
                                                        ["G_o","G"], 
                                                        hcat(
                                                            str_precfloat_m(view(G_o,temprun_relGparams.aryG_gindxs),8,true), 
                                                            str_precfloat_m(view(x__gvals,temprun_relGparams.aryG_gindxs),8,true)
                                                        ),
                                                        0, false, true, true
                                                    )
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("{k_calc}: ",str_precfloat_m(t,8,true))) 
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                        [
                                                            string.("[",collect(1:temprun_rxnparams.rxns_cnt),"]"), 
                                                            temprun_rxnparams.rxns_names
                                                        ], 
                                                        ["k","k_o"], 
                                                        hcat(
                                                            str_precfloat_m(x__kvals,8,true), 
                                                            str_precfloat_m(x__kvals_o,8,true)
                                                        ),
                                                        0, false, true, true
                                                    )
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                        else 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("{k_calc}: ",str_precfloat_m(t,8,true))) 
                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                        [
                                                            string.("[",collect(1:temprun_rxnparams.rxns_cnt),"]"), 
                                                            temprun_rxnparams.rxns_names
                                                        ], 
                                                        ["k"], 
                                                        str_precfloat_m(x__kvals,8,true),
                                                        0, false, true, true
                                                    )
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                        end 
                    end 
                end 
            end
        end 

        return err_flag, err_msg
    end 

    function Rxn__ModelSystem__Temprun__Solver__SpeciesRates__outofdomain(u, (msgrslts, msgoptions, msgtxtprfx, u_o, du_cache, G_o, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_const_vals, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, sns_apply, sns_pf_pkfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, tmp_gvals, tmp_kvals, tmp_kvals_o, tmp_rvals, tmp_uvals_p, cache_initflags, cache_gvals, cache_kvals, cache_kvals_o, cache_rvals, cache_uvals_p, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, show_updates, show_updates_vals), t) 
        
        rs = false 
        if temprun_odeparams.ode_adscoads_cnt > 0 
            for i in axes(temprun_odeparams.ode_adscoads_indxs,1)
                if u[temprun_odeparams.ode_adscoads_indxs[i]] < 0 || u[temprun_odeparams.ode_adscoads_indxs[i]] > 1 
                    rs = true 
                    break 
                end 
            end 
        end 

        return rs
    end 

    function Rxn__ModelSystem__Temprun__Solver__DetectStableState(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, show_initialmsg, sbs_detect_mode, sbs_loop_mode, sns_pairs_alpha, t) 

        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Checking stable-state conditions, as needed
            if rxnrun.sbsoptions.analyze == true 

                # Show initial message, as needed 
                if err_flag == false 
                    show_prfx = ""
                    if show_initialmsg == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("checking stable-state conditions...")) 
                        show_prfx = "  "
                    end 
                end 

                # Reset stable-state indicators 
                if err_flag == false 
                    solver_rs.loop_params.sbs_checked = true 
                    solver_rs.loop_params.sbs_onsetflag = true 
                    solver_rs.loop_params.sbs_onsetindex = 1 
                end 

                # Initialize working variables 
                if err_flag == false 
                    x__odespecies_molindxs = get_elemindex(rxnsystem.molecules.names,rxnsystem.odespecies.compounds,0)
                end 

                # Check fractions and rates criteria 
                if err_flag == false 
                    x__sbsindx = 0
                    if sbs_detect_mode == "fracs|rates" || sbs_detect_mode == "fracs|rates|sens"
                        for i in 1:2 
                            x__sbsflag = true 
                            x__sbsindx = 0
                            if i == 1 
                                x__abstol_curr = rxnrun.sbsoptions.covs_abstol_curr 
                                x__abstol_rmdr = rxnrun.sbsoptions.covs_abstol_rmdr 
                                x__fractol_curr = rxnrun.sbsoptions.covs_fractol_curr 
                                x__fractol_rmdr = rxnrun.sbsoptions.covs_fractol_rmdr 
                                if x__abstol_curr > 0 || x__abstol_rmdr > 0 || x__fractol_curr > 0 || x__fractol_rmdr > 0 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"adsorbates coverages..."))
                                    if solver_rs.rs_spcs_x_dat !== nothing 
                                        x__adscovs = view(solver_rs.rs_spcs_x_dat,:,rxnsystem.odespecies.indxs_adscoads) 
                                        if x__sbsflag == true && x__abstol_curr > 0 
                                            x__adscovs_diff = view(x__adscovs,2:size(x__adscovs,1),:) .- view(x__adscovs,1:(size(x__adscovs,1)-1),:)
                                            x__adscovs_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__adscovs_diff)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__adscovs_diff_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__abstol_curr, x__adscovs_diff_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0 
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__adscovs_diff_nx,x__indxs))) 
                                                x__fail_fin = abs(x__adscovs_diff_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__sbsindx = max(x__sbsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)   # the ' + x__dindxs' term to account for difference array positions being shifted by one compared to the solver_rs.rs_t_dat 
                                                else 
                                                    x__sbsflag = false 
                                                    x__sbsindx = 0
                                                end
                                            else 
                                                x__sbsindx = max(x__sbsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__sbsindx && x__sbsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change at current time point...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sbs t: [",x__sbsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__sbsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_curr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__adscovs_diff_nx,(x__sbsindx - x__dindxs),:))))))
                                            else
                                                x__sbsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change at current time point...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_curr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                        if x__sbsflag == true && x__abstol_rmdr > 0 
                                            x__adscovs_diff = view(x__adscovs,1:(size(x__adscovs,1)-1),:) .- reshape(view(x__adscovs,size(x__adscovs,1),:),(1,size(x__adscovs,2)))
                                            x__adscovs_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__adscovs_diff)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__adscovs_diff_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__abstol_rmdr, x__adscovs_diff_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__adscovs_diff_nx,x__indxs))) 
                                                x__fail_fin = abs(x__adscovs_diff_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__sbsindx = max(x__sbsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)
                                                else 
                                                    x__sbsflag = false 
                                                    x__sbsindx = 0
                                                end
                                            else 
                                                x__sbsindx = max(x__sbsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__sbsindx && x__sbsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change over remainder of time span...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sbs t: [",x__sbsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__sbsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_rmdr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__adscovs_diff_nx,(x__sbsindx - x__dindxs),:))))))
                                            else
                                                x__sbsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change over remainder of time span...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",x__abstol_rmdr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                        if x__sbsflag == true && x__fractol_curr > 0 
                                            x__adscovs_diff = (view(x__adscovs,2:size(x__adscovs,1),:) .- view(x__adscovs,1:(size(x__adscovs,1)-1),:)) ./ view(x__adscovs,1:(size(x__adscovs,1)-1),:)
                                            x__adscovs_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__adscovs_diff)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__adscovs_diff_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__fractol_curr, x__adscovs_diff_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__adscovs_diff_nx,x__indxs))) 
                                                x__fail_fin = abs(x__adscovs_diff_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__sbsindx = max(x__sbsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)   # the ' + x__dindxs' term to account for difference array positions being shifted by one compared to the solver_rs.rs_t_dat 
                                                else 
                                                    x__sbsflag = false 
                                                    x__sbsindx = 0
                                                end
                                            else 
                                                x__sbsindx = max(x__sbsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__sbsindx && x__sbsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional change at current time point...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sbs t: [",x__sbsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__sbsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_curr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__adscovs_diff_nx,(x__sbsindx - x__dindxs),:))))))
                                            else
                                                x__sbsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional change at current time point...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_curr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                        if x__sbsflag == true && x__fractol_rmdr > 0 
                                            x__adscovs_frac = similar(x__adscovs)
                                            x__adscovs_frac .= zero(x__adscovs[1])
                                            for j = axes(x__adscovs,1)
                                                for k = axes(x__adscovs,2)
                                                    x__adscovs_frac[j,k] = max(abs(x__adscovs[j,k] - maximum(view(x__adscovs,j:size(x__adscovs,1),k))),abs(x__adscovs[j,k] - minimum(view(x__adscovs,j:size(x__adscovs,1),k)))) / abs(x__adscovs[j,k])
                                                end
                                            end 
                                            x__adscovs_frac_nx = map(x -> (isnan(x) ? zero(x) : x),x__adscovs_frac)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__adscovs_frac_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__fractol_rmdr, x__adscovs_frac_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__adscovs_frac_nx,x__indxs))) 
                                                x__fail_fin = abs(x__adscovs_frac_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__sbsindx = max(x__sbsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)
                                                else 
