                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sbs t: [",x__sbsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__sbsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_rmdr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__adscovs_frac_nx,(x__sbsindx - x__dindxs),:))))))
                                            else
                                                x__sbsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional change over remainder of time span...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_rmdr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                    else
                                        x__sbsflag = false
                                    end 
                                end 
                            elseif i == 2 
                                x__abstol_curr = rxnrun.sbsoptions.rate_abstol_curr 
                                x__abstol_rmdr = rxnrun.sbsoptions.rate_abstol_rmdr 
                                x__fractol_curr = rxnrun.sbsoptions.rate_fractol_curr 
                                x__fractol_rmdr = rxnrun.sbsoptions.rate_fractol_rmdr 
                                if x__abstol_curr > 0 || x__abstol_rmdr > 0 || x__fractol_curr > 0 || x__fractol_rmdr > 0 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"rates..."))
                                    if solver_rs.rs_spcs_r_dat !== nothing 
                                        x__rates = solver_rs.rs_spcs_r_dat
                                        if x__sbsflag == true && x__abstol_curr > 0 
                                            x__rates_diff = view(x__rates,2:size(x__rates,1),:) .- view(x__rates,1:(size(x__rates,1)-1),:)
                                            x__rates_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__rates_diff)
