                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sbs t: [",x__sbsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__sbsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_rmdr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__rates_frac_nx,(x__sbsindx - x__dindxs),:))))))
                                            else
