                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"pre-onset time check...absolute time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"pre-onset time check...absolute time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.sbsoptions.mintime_beforeonset_interval.value))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sbs t: ",x__sbstime))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg  : ",x__chg))
                        end 
                        if solver_rs.loop_params.sbs_onsetflag == true 
                            solver_rs.loop_params.sbs_onsetindex = x__onset 
                        end 
                        if solver_rs.loop_params.sbs_onsetflag == true && rxnrun.sbsoptions.mintime_afteronset_interval_min.value > 0 
                            if rxnrun.sbsoptions.mintime_afteronset_interval_min.value <= (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])
                                solver_rs.loop_params.sbs_onsetflag = ((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]) >= rxnrun.sbsoptions.mintime_afteronset_interval_min.value)
                            else 
                                solver_rs.loop_params.sbs_onsetflag = false 
                            end 
                            if solver_rs.loop_params.sbs_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...absolute minimum time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...absolute minimum time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sbs t: [",solver_rs.loop_params.sbs_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.sbsoptions.mintime_afteronset_interval_min.value))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex])))
                        end 
                        if solver_rs.loop_params.sbs_onsetflag == true && rxnrun.sbsoptions.mintime_afteronset_fracofmax > 0 && rxnrun.sbsoptions.mintime_afteronset_fracofmax <= 1
                            solver_rs.loop_params.sbs_onsetflag = ((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) >= rxnrun.sbsoptions.mintime_afteronset_fracofmax)
                            if solver_rs.loop_params.sbs_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...fractional time...passed"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sbs t: [",solver_rs.loop_params.sbs_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.sbsoptions.mintime_afteronset_fracofmax))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tot t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]))))
                            else
                                if 0 < rxnrun.sbsoptions.mintime_afteronset_interval_suf.value && rxnrun.sbsoptions.mintime_afteronset_interval_suf.value <= (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex])
                                    solver_rs.loop_params.sbs_onsetflag = true 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...absolute sufficient time...passed"))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sbs t: [",solver_rs.loop_params.sbs_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.sbsoptions.mintime_afteronset_interval_suf.value))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex])))
                                else 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...fractional time...failed"))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sbs t: [",solver_rs.loop_params.sbs_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.sbsoptions.mintime_afteronset_fracofmax))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tot t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]))))
                                end
                            end 
                        end 
                    end 
                end 

                # Set onset index to default, as needed
                if err_flag == false 
                    if solver_rs.loop_params.sbs_onsetflag == true && solver_rs.loop_params.sbs_onsetindex <= 0 
                        solver_rs.loop_params.sbs_onsetindex = 1
                    end 
                end 
    
                # Check max change criteria 
                if err_flag == false 
                    if solver_rs.loop_params.sbs_onsetflag == true && solver_rs.loop_params.sbs_onsetindex > 0 
                        if solver_rs.loop_params.sbs_onsetindex > 1 
                            if solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex] <= rxnrun.sbsoptions.timespan_extend_maxchg * solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex - 1] 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"stable-state onset detected at timestep ",solver_rs.loop_params.sbs_onsetindex," (",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]," seconds)"))
                            else 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"stable state onset time step is too large"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  relative size of ",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex - 1]," -> ",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]," is greater than ",log_value(err_flag, err_msg, 100 * (rxnrun.sbsoptions.timespan_extend_maxchg - 1.0), 1, true, false, false),"%"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  updating minimum stable state onset to ",(rxnrun.sbsoptions.timespan_extend_maxchg * solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex - 1])," seconds"))
                                solver_rs.loop_params.sbs_tmin = solver_rs.loop_params.loop_t_max
                                solver_rs.loop_params.sbs_textend = false 
                                solver_rs.loop_params.sbs_onsetflag = true
                                solver_rs.loop_params.sbs_onsetindex = 0 
                            end 
                        else 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"stable-state onset detected at timestep ",solver_rs.loop_params.sbs_onsetindex," (",solver_rs.rs_t_dat[solver_rs.loop_params.sbs_onsetindex]," seconds)"))
                        end 
                    else 
                        solver_rs.loop_params.sbs_onsetflag = true
                        solver_rs.loop_params.sbs_onsetindex = 0 
                    end 
                end 

                # Show error message, as needed
                if err_flag == false 
                    if solver_rs.loop_params.sbs_onsetflag == false || solver_rs.loop_params.sbs_onsetindex <= 0 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"stable state not detected"))
                        solver_rs.loop_params.sbs_onsetflag = true
                        solver_rs.loop_params.sbs_onsetindex = 0 
                    end 
                end 
            end 
        end 
        
        return err_flag, err_msg
    end 

    function Rxn__ModelSystem__Temprun__Solver__DetectSteadyState(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, show_initialmsg, sts_detect_mode, sts_loop_mode, sns_pairs_alpha, t) 

        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Checking steady-state conditions, as needed
            if rxnrun.stsoptions.analyze == true 

                # Show initial message, as needed 
                if err_flag == false 
                    show_prfx = ""
                    if show_initialmsg == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("checking steady-state conditions...")) 
                        show_prfx = "  "
                    end 
                end 

                # Reset steady-state indicators 
                if err_flag == false 
                    solver_rs.loop_params.sts_checked = true 
                    solver_rs.loop_params.sts_onsetflag = true 
                    solver_rs.loop_params.sts_onsetindex = 1 
                end 

                # Initialize working variables 
                if err_flag == false 
                    x__odespecies_molindxs = get_elemindex(rxnsystem.molecules.names,rxnsystem.odespecies.compounds,0)
                end 

                # Check fractions and rates criteria 
                if err_flag == false 
                    x__stsindx = 0
                    if sts_detect_mode == "fracs|rates" || sts_detect_mode == "fracs|rates|sens"
                        for i in 1:1 
                            x__stsflag = true 
                            x__stsindx = 0
                            if i == 1 
                                x__abstol_curr = rxnrun.stsoptions.gasatoms_abstol_curr 
                                x__abstol_rmdr = rxnrun.stsoptions.gasatoms_abstol_rmdr 
                                x__fractol_curr = rxnrun.stsoptions.gasatoms_fractol_curr 
                                x__fractol_rmdr = rxnrun.stsoptions.gasatoms_fractol_rmdr 
                                if x__abstol_curr > 0 || x__abstol_rmdr > 0 || x__fractol_curr > 0 || x__fractol_rmdr > 0 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"gas atom rates..."))
                                    if solver_rs.rs_spcs_r_dat !== nothing 
                                        x__gasrates = view(solver_rs.rs_spcs_r_dat,:,rxnsystem.odespecies.indxs_gas) 
                                        x__gascoefs = reshape(view(rxnsystem.molecules.atomcoeffs,view(x__odespecies_molindxs,rxnsystem.odespecies.indxs_gas),:),(1,size(rxnsystem.odespecies.indxs_gas,1),size(rxnsystem.molecules.atomcoeffs,2))) 
                                        if x__stsflag == true && x__abstol_curr > 0 
                                            x__atomrates = dropdims(sum(x__gasrates .* x__gascoefs, dims=2), dims=2)
                                            x__atomrates_nx = map(x -> (isnan(x) ? zero(x) : x),x__atomrates)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__atomrates_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__abstol_curr, x__atomrates_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__atomrates_nx,x__indxs))) 
                                                x__fail_fin = abs(x__atomrates_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__stsindx = max(x__stsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)
                                                else 
                                                    x__stsflag = false 
                                                    x__stsindx = 0
                                                end
                                            else 
                                                x__stsindx = max(x__stsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__stsindx && x__stsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change at current time point...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sts t: [",x__stsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__stsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_curr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__atomrates_nx,(x__stsindx - x__dindxs),:))))))
                                            else 
                                                x__stsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change at current time point...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_curr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                        if x__stsflag == true && x__abstol_rmdr > 0 
                                            x__atomrates = dropdims(sum(x__gasrates .* x__gascoefs, dims=2), dims=2)
                                            x__atomrates_diff = view(x__atomrates,axes(x__atomrates,1),:) .- reshape(view(x__atomrates,size(x__atomrates,1),:),(1,size(x__atomrates,2)))
                                            x__atomrates_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__atomrates_diff)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__atomrates_diff_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__abstol_rmdr, x__atomrates_diff_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__atomrates_diff_nx,x__indxs))) 
                                                x__fail_fin = abs(x__atomrates_diff_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__stsindx = max(x__stsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)
                                                else 
                                                    x__stsflag = false 
                                                    x__stsindx = 0
                                                end
                                            else 
                                                x__stsindx = max(x__stsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__stsindx && x__stsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change over remainder of time span...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sts t: [",x__stsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__stsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_rmdr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__atomrates_diff_nx,(x__stsindx - x__dindxs),:))))))
                                            else 
                                                x__stsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  absolute change over remainder of time span...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__abstol_rmdr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                        if x__stsflag == true && x__fractol_curr > 0 && temprun_rxnparams.rxns_gascnt > 1
                                            x__gasrates_pos_nx = map(x -> (isnan(x) ? zero(x) : x),x__gasrates)
                                            x__gasrates_pos_nx[findall(x -> x < 0, x__gasrates_pos_nx)] .= 0.0 
                                            x__atomrates_pos = dropdims(sum(x__gasrates_pos_nx .* x__gascoefs, dims=2), dims=2)
                                            x__gasrates_neg_nx = map(x -> (isnan(x) ? zero(x) : x),x__gasrates)
                                            x__gasrates_neg_nx[findall(x -> x > 0, x__gasrates_neg_nx)] .= 0.0 
                                            x__atomrates_neg = dropdims(sum(x__gasrates_neg_nx .* x__gascoefs, dims=2), dims=2)
                                            x__atomrates_sum = x__atomrates_pos .+ x__atomrates_neg 
                                            x__atomrates_sum_nx = map(x -> (isnan(x) ? zero(x) : x),x__atomrates_sum)
                                            x__atomrates_sum_diff = similar(x__atomrates_sum_nx)
                                            x__atomrates_sum_diff .= zero(x__atomrates_sum_nx[1])
                                            for j = axes(x__atomrates_sum_nx,1) 
                                                for k = axes(x__atomrates_sum_nx,2)
                                                    if abs(x__atomrates_sum_nx[j,k]) >= rxnrun.solveroptions.ode_abstol
                                                        x__atomrates_sum_diff[j,k] = x__atomrates_sum_nx[j,k] / max(abs(x__atomrates_pos[j,k]),abs(x__atomrates_neg[j,k]))
                                                    end 
                                                end
                                            end 
                                            x__atomrates_sum_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__atomrates_sum_diff)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__atomrates_sum_diff_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__fractol_curr, x__atomrates_sum_diff_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__atomrates_sum_diff_nx,x__indxs))) 
                                                # x__fail_fin = abs(x__atomrates_sum_diff_nx[x__indxs[size(x__indxs,1)]])
                                                x__fail_fin = maximum(abs.(x__atomrates_sum_diff_nx[solver_rs.rs_t_cnt])) 
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__stsindx = max(x__stsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)
                                                else 
                                                    x__stsflag = false 
                                                    x__stsindx = 0
                                                end
                                            else 
                                                x__stsindx = max(x__stsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__stsindx && x__stsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional remainder at current time point...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sts t: [",x__stsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__stsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_curr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__atomrates_sum_diff_nx,(x__stsindx - x__dindxs),:))))))
                                            else 
                                                x__stsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional remainder at current time point...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_curr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 

                                            x__gasratesmax = maximum(abs.(x__gasrates), dims=2) 
                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("gasrates: ")) 
                                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                                        [], 
                                                                        rxnsystem.odespecies.names[rxnsystem.odespecies.indxs_gas], 
                                                                        vcat(
                                                                            reshape(x__gasrates[solver_rs.rs_t_cnt,:],1,size(rxnsystem.odespecies.indxs_gas,1)) ./ x__gasratesmax[solver_rs.rs_t_cnt], 
                                                                            reshape(x__gasrates_pos_nx[solver_rs.rs_t_cnt,:],1,size(rxnsystem.odespecies.indxs_gas,1)) ./ x__gasratesmax[solver_rs.rs_t_cnt], 
                                                                            reshape(x__gasrates_neg_nx[solver_rs.rs_t_cnt,:],1,size(rxnsystem.odespecies.indxs_gas,1)) ./ x__gasratesmax[solver_rs.rs_t_cnt]
                                                                        ), 
                                                                        0, false, true, true
                                                                    )
                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 

                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 
                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("atomrates: ")) 
                                            err_flag, err_msg = log_table_msgopts(msgrslts, msgoptions, "    ", err_flag, err_msg, false, false, 1, 1, 
                                                                        [], 
                                                                        rxnsystem.atoms.atoms_names, 
                                                                        vcat(
                                                                            reshape(x__atomrates_pos[solver_rs.rs_t_cnt,:],1,size(rxnsystem.molecules.atomcoeffs,2)) ./ x__gasratesmax[solver_rs.rs_t_cnt], 
                                                                            reshape(x__atomrates_neg[solver_rs.rs_t_cnt,:],1,size(rxnsystem.molecules.atomcoeffs,2)) ./ x__gasratesmax[solver_rs.rs_t_cnt], 
                                                                            reshape(x__atomrates_sum_nx[solver_rs.rs_t_cnt,:],1,size(rxnsystem.molecules.atomcoeffs,2)) ./ x__gasratesmax[solver_rs.rs_t_cnt], 
                                                                            reshape(x__atomrates_sum_diff_nx[solver_rs.rs_t_cnt,:],1,size(rxnsystem.molecules.atomcoeffs,2)) 
                                                                        ), 
                                                                        0, false, true, true
                                                                    )
                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, "  ", err_flag, err_msg, false, false, 1, 1, string("  ")) 

                                        end 
                                        if x__stsflag == true && x__fractol_rmdr > 0 && temprun_rxnparams.rxns_gascnt > 1 
                                            x__gasrates_pos_nx = map(x -> (isnan(x) ? zero(x) : x),x__gasrates)
                                            x__gasrates_pos_nx[findall(x -> x < 0, x__gasrates_pos_nx)] .= 0.0 
                                            x__atomrates_pos = dropdims(sum(x__gasrates_pos_nx .* x__gascoefs, dims=2), dims=2)
                                            x__gasrates_neg_nx = map(x -> (isnan(x) ? zero(x) : x),x__gasrates)
                                            x__gasrates_neg_nx[findall(x -> x > 0, x__gasrates_neg_nx)] .= 0.0 
                                            x__atomrates_neg = dropdims(sum(x__gasrates_neg_nx .* x__gascoefs, dims=2), dims=2)
                                            x__atomrates_sum = x__atomrates_pos .+ x__atomrates_neg 
                                            x__atomrates_sum_nx = map(x -> (isnan(x) ? zero(x) : x),x__atomrates_sum)
                                            x__atomrates_frac = similar(x__atomrates_sum_nx)
                                            x__atomrates_frac .= zero(x__atomrates_sum_nx[1])
                                            for j = axes(x__atomrates_sum_nx,1)
                                                for k = axes(x__atomrates_sum_nx,2)
                                                    if maximum(abs.(view(x__atomrates_sum_nx,j:size(x__atomrates_pos,1),k))) >= rxnrun.solveroptions.ode_abstol
                                                        x__atomrates_frac[j,k] = maximum(abs.(view(x__atomrates_sum_nx,j:size(x__atomrates_pos,1),k))) / max(maximum(abs.(view(x__atomrates_pos,j:size(x__atomrates_pos,1),k))), maximum(abs.(view(x__atomrates_neg,j:size(x__atomrates_neg,1),k))))   
                                                    end
                                                end
                                            end 
                                            x__atomrates_frac_nx = map(x -> (isnan(x) ? zero(x) : x),x__atomrates_frac)
                                            x__dindxs = solver_rs.rs_t_cnt - size(x__atomrates_frac_nx,1)
                                            x__indxs = findall(x -> abs(x) >= x__fractol_rmdr, x__atomrates_frac_nx) 
                                            x__fail_min = 0 
                                            x__fail_fin = 0
                                            if size(x__indxs,1) > 0 
                                                x__fail_min = minimum(abs.(view(x__atomrates_frac_nx,x__indxs))) 
                                                x__fail_fin = abs(x__atomrates_frac_nx[x__indxs[size(x__indxs,1)]])
                                                if maximum([x[1] for x in x__indxs]) < solver_rs.rs_t_cnt
                                                    x__stsindx = max(x__stsindx,maximum([x[1] for x in x__indxs]) + 1 + x__dindxs)
                                                else 
                                                    x__stsflag = false 
                                                    x__stsindx = 0
                                                end
                                            else 
                                                x__stsindx = max(x__stsindx,1 + x__dindxs)
                                            end 
                                            if x__dindxs < x__stsindx && x__stsindx <= solver_rs.rs_t_cnt
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional remainder over remainder of time span...passed"))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    sts t: [",x__stsindx,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[x__stsindx]))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_rmdr))
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |chg|: ",maximum(vec(abs.(view(x__atomrates_frac_nx,(x__stsindx - x__dindxs),:))))))
                                            else
                                                x__stsflag = false 
                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fractional remainder over remainder of time span...failed"))
                                                if x__fail_min > 0 && x__fail_fin > 0 
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    tol  : ",x__fractol_rmdr))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |min|: ",x__fail_min))
                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    |fin|: ",x__fail_fin))
                                                end 
                                            end 
                                        end 
                                    else
                                        x__stsflag = false
                                    end 
                                end 
                            end 
                            if x__stsflag == true && x__stsindx > 0 
                                solver_rs.loop_params.sts_onsetindex = max(solver_rs.loop_params.sts_onsetindex,x__stsindx)
                            end 
                            if x__stsflag == false 
                                solver_rs.loop_params.sts_onsetflag = false 
                                break 
                            end 
                        end 
                    end
                end 

                # Check onset offset criteria 
                if err_flag == false 
                    if solver_rs.loop_params.sts_onsetflag == true && solver_rs.loop_params.sts_onsetindex > 0 
                        x__onset = solver_rs.loop_params.sts_onsetindex 
                        if solver_rs.loop_params.sts_onsetflag == true && rxnrun.stsoptions.onsetoffset_fracofmax > 0 && rxnrun.stsoptions.onsetoffset_fracofmax <= 1
                            x__chg = (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) 
                            x__ststime = solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]
                            solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) >= rxnrun.stsoptions.onsetoffset_fracofmax)
                            if solver_rs.loop_params.sts_onsetflag == true 
                                for i in solver_rs.loop_params.sts_onsetindex:solver_rs.rs_t_cnt
                                    if solver_rs.rs_t_dat[i] == solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] + rxnrun.stsoptions.onsetoffset_fracofmax * (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) 
                                        x__onset = max(i,x__onset) 
                                        break 
                                    else 
                                        if i == solver_rs.rs_t_cnt 
                                            push!(solver_rs.loop_params.loop_t_pts, (solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] + rxnrun.stsoptions.onsetoffset_fracofmax * (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                                            solver_rs.loop_params.sts_onsetflag = false 
                                            solver_rs.loop_params.sts_onsetindex = 0 
                                        end 
                                    end 
                                end 
                            end 
                            if solver_rs.loop_params.sts_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"onset offset check...fractional time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"onset offset check...fractional time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",x__ststime))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.onsetoffset_fracofmax))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tot t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg  : ",x__chg))
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true && rxnrun.stsoptions.onsetoffset_interval.value > 0 
                            x__chg = (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex])
                            x__ststime = solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]
                            if rxnrun.stsoptions.onsetoffset_interval.value <= solver_rs.rs_t_dat[solver_rs.rs_t_cnt]
                                solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) >= rxnrun.stsoptions.onsetoffset_interval.value)
                                if solver_rs.loop_params.sts_onsetflag == true 
                                    for i in solver_rs.loop_params.sts_onsetindex:solver_rs.rs_t_cnt
                                        if solver_rs.rs_t_dat[i] == solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] + rxnrun.stsoptions.onsetoffset_interval.value 
                                            x__onset = max(i,x__onset)
                                            break 
                                        else 
                                            if i == solver_rs.rs_t_cnt 
                                                push!(solver_rs.loop_params.loop_t_pts, (solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] + rxnrun.stsoptions.onsetoffset_interval.value))
                                                solver_rs.loop_params.sts_onsetflag = false 
                                                solver_rs.loop_params.sts_onsetindex = 0 
                                            end 
                                        end
                                    end
                                end 
                            else 
                                solver_rs.loop_params.sts_onsetflag = false 
                            end 
                            if solver_rs.loop_params.sts_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"onset offset check...absolute time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"onset offset check...absolute time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",x__ststime))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.onsetoffset_interval.value))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg  : ",x__chg))
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true 
                            solver_rs.loop_params.sts_onsetindex = x__onset 
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true && rxnrun.stsoptions.mintime_beforeonset_fracofmax > 0 && rxnrun.stsoptions.mintime_beforeonset_fracofmax <= 1
                            x__chg = (solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] - solver_rs.rs_t_dat[1]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])
                            x__ststime = solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]
                            solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] - solver_rs.rs_t_dat[1]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) >= rxnrun.stsoptions.mintime_beforeonset_fracofmax)
                            if solver_rs.loop_params.sts_onsetflag == false && solver_rs.loop_params.sts_onsetindex < solver_rs.rs_t_cnt
                                x__val = solver_rs.loop_params.sts_onsetindex
                                for i = 1:solver_rs.rs_t_cnt
                                    x__val = x__val + 1
                                    x__onset = max(x__val,x__onset)
                                    solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[x__onset] - solver_rs.rs_t_dat[1]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) >= rxnrun.stsoptions.mintime_beforeonset_fracofmax)
                                    if solver_rs.loop_params.sts_onsetflag == true 
                                        break
                                    end 
                                end 
                            end 
                            if solver_rs.loop_params.sts_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"pre-onset time check...fractional time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"pre-onset time check...fractional time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",x__ststime))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.mintime_beforeonset_fracofmax))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tot t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg  : ",x__chg))
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true && rxnrun.stsoptions.mintime_beforeonset_interval.value > 0 
                            x__chg = (solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] - solver_rs.rs_t_dat[1])
                            x__ststime = solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]
                            if rxnrun.stsoptions.mintime_beforeonset_interval.value <= (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])
                                solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] - solver_rs.rs_t_dat[1]) >= rxnrun.stsoptions.mintime_beforeonset_interval.value)
                                if solver_rs.loop_params.sts_onsetflag == false && solver_rs.loop_params.sts_onsetindex < solver_rs.rs_t_cnt
                                    x__val = solver_rs.loop_params.sts_onsetindex
                                    for i = 1:solver_rs.rs_t_cnt
                                        x__val = x__val + 1
                                        x__onset = max(x__val,x__onset)
                                        solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[x__val] - solver_rs.rs_t_dat[1]) >= rxnrun.stsoptions.mintime_beforeonset_interval.value)
                                        if solver_rs.loop_params.sts_onsetflag == true 
                                            break
                                        end 
                                    end 
                                end 
                            else 
                                solver_rs.loop_params.sts_onsetflag = false 
                            end 
                            if solver_rs.loop_params.sts_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"pre-onset time check...absolute time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"pre-onset time check...absolute time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.mintime_beforeonset_interval.value))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: ",x__ststime))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg  : ",x__chg))
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true 
                            solver_rs.loop_params.sts_onsetindex = x__onset 
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true && rxnrun.stsoptions.mintime_afteronset_interval_min.value > 0 
                            if rxnrun.stsoptions.mintime_afteronset_interval_min.value <= (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])
                                solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) >= rxnrun.stsoptions.mintime_afteronset_interval_min.value)
                            else 
                                solver_rs.loop_params.sts_onsetflag = false 
                            end 
                            if solver_rs.loop_params.sts_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...absolute minimum time...passed"))
                            else
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...absolute minimum time...failed"))
                            end 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.mintime_afteronset_interval_min.value))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex])))
                        end 
                        if solver_rs.loop_params.sts_onsetflag == true && rxnrun.stsoptions.mintime_afteronset_fracofmax > 0 && rxnrun.stsoptions.mintime_afteronset_fracofmax <= 1
                            solver_rs.loop_params.sts_onsetflag = ((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]) >= rxnrun.stsoptions.mintime_afteronset_fracofmax)
                            if solver_rs.loop_params.sts_onsetflag == true 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...fractional time...passed"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.mintime_afteronset_fracofmax))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tot t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]))))
                            else
                                if 0 < rxnrun.stsoptions.mintime_afteronset_interval_suf.value && rxnrun.stsoptions.mintime_afteronset_interval_suf.value <= (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex])
                                    solver_rs.loop_params.sts_onsetflag = true 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...absolute sufficient time...passed"))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.mintime_afteronset_interval_suf.value))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  fin t: ",solver_rs.rs_t_dat[solver_rs.rs_t_cnt]))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex])))
                                else 
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"post-onset time check...fractional time...failed"))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  sts t: [",solver_rs.loop_params.sts_onsetindex,"/",solver_rs.rs_t_cnt,"] ",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tol  : ",rxnrun.stsoptions.mintime_afteronset_fracofmax))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  tot t: ",(solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1])))
                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  chg t: ",((solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]) / (solver_rs.rs_t_dat[solver_rs.rs_t_cnt] - solver_rs.rs_t_dat[1]))))
                                end
                            end 
                        end 
                    end 
                end 

                # Set onset index to default, as needed
                if err_flag == false 
                    if solver_rs.loop_params.sts_onsetflag == true && solver_rs.loop_params.sts_onsetindex <= 0 
                        solver_rs.loop_params.sts_onsetindex = 1
                    end 
                end 
    
                # Check max change criteria 
                if err_flag == false 
                    if solver_rs.loop_params.sts_onsetflag == true && solver_rs.loop_params.sts_onsetindex > 0 
                        if solver_rs.loop_params.sts_onsetindex > 1 
                            if solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex] <= rxnrun.stsoptions.timespan_extend_maxchg * solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex - 1] 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"steady-state onset detected at timestep ",solver_rs.loop_params.sts_onsetindex," (",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]," seconds)"))
                            else 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"steady state onset time step is too large"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  relative size of ",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex - 1]," -> ",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]," is greater than ",log_value(err_flag, err_msg, 100 * (rxnrun.stsoptions.timespan_extend_maxchg - 1.0), 1, true, false, false),"%"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  updating minimum steady state onset to ",(rxnrun.stsoptions.timespan_extend_maxchg * solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex - 1])," seconds"))
                                solver_rs.loop_params.sts_tmin = solver_rs.loop_params.loop_t_max
                                solver_rs.loop_params.sts_textend = false 
                                solver_rs.loop_params.sts_onsetflag = true
                                solver_rs.loop_params.sts_onsetindex = 0 
                            end 
                        else 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"steady-state onset detected at timestep ",solver_rs.loop_params.sts_onsetindex," (",solver_rs.rs_t_dat[solver_rs.loop_params.sts_onsetindex]," seconds)"))
                        end 
                    else 
                        solver_rs.loop_params.sts_onsetflag = true
                        solver_rs.loop_params.sts_onsetindex = 0 
                    end 
                end 

                # Show error message, as needed
                if err_flag == false 
                    if solver_rs.loop_params.sts_onsetflag == false || solver_rs.loop_params.sts_onsetindex <= 0 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"steady-state not detected"))
                        solver_rs.loop_params.sts_onsetflag = true
                        solver_rs.loop_params.sts_onsetindex = 0 
                    end 
                end 
            end 
        end 
        
        return err_flag, err_msg
    end 

    function Rxn__ModelSystem__Temprun__Solver__DetectSinglePathwayState(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, module_ver, rxnsystem, rxnrun, rxnrun_numtype, run_temperature_value, run_temperature_units, run_timespan_value, run_timespan_units, run_temps, run_temps_index, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, cfg_G_refcols, solver_rs, solver_ode_params, u_o, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, show_initialmsg, sps_detect_mode, sps_loop_mode, sns_pairs_alpha, t) 
                        
        if err_flag == false 
            err_flag = false 
            err_msg = "" 

            # Checking single pathway state conditions, as needed
            if rxnrun.spsoptions.analyze == true 

                # Show initial message, as needed 
                if err_flag == false 
                    show_prfx = ""
                    if show_initialmsg == true 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("checking single pathway state conditions...")) 
                        show_prfx = "  "
                    end 
                end 

                # Reset single pathway state indicators 
                if err_flag == false 
                    solver_rs.loop_params.sps_checked = true 
                    solver_rs.loop_params.sps_onsetflag = true 
                    solver_rs.loop_params.sps_onsetindex = 1 
                end 

                # Initialize working variables 
                if err_flag == false 
                    x__odespecies_molindxs = get_elemindex(rxnsystem.molecules.names,rxnsystem.odespecies.compounds,0)
                end 

                # Check sensitivities criteria 
                if err_flag == false 
                    if sps_detect_mode == "sens" || sps_detect_mode == "fracs|rates|sens"
                        x__abstol_curr = rxnrun.spsoptions.drcs_abstol_curr 
                        x__abstol_rmdr = rxnrun.spsoptions.drcs_abstol_rmdr 
                        x__fractol_curr = rxnrun.spsoptions.drcs_fractol_curr 
                        x__fractol_rmdr = rxnrun.spsoptions.drcs_fractol_rmdr 
                        x__kineticsumerr_curr = rxnrun.spsoptions.drcs_kineticsumerr_curr
                        x__kineticsumerr_rmdr = rxnrun.spsoptions.drcs_kineticsumerr_rmdr
                        if x__abstol_curr > 0 || x__abstol_rmdr > 0 || x__fractol_curr > 0 || x__fractol_rmdr > 0 || x__kineticsumerr_curr > 0 || x__kineticsumerr_rmdr > 0 
                            for i in 1:2 
                                if i == 1 
                                    jtype = "fractions"
                                elseif i == 2 
                                    jtype = "energies"
                                end 
                                if (i == 1 && rxnrun.snsoptions.drc_fractions_cnt > 0) || (i == 2 && rxnrun.snsoptions.drc_energies_cnt > 0) 
                                    kflag = false
                                    for k = 1:6
                                        ktype = ""
                                        ktol = 0
                                        if k == 1         # absolute - current time point 
                                            ktype = "absolute - current time point"
                                            ktol = x__abstol_curr 
                                        elseif k == 2     # absolute - remainder of time span
                                            ktype = "absolute - remainder of time span"
                                            ktol = x__abstol_rmdr 
                                        elseif k == 3     # fractional - current time point 
                                            ktype = "fractional - current time point"
                                            ktol = x__fractol_curr 
                                        elseif k == 4     # fractional - remainder of time span
                                            ktype = "fractional - remainder of time span"
                                            ktol = x__fractol_rmdr 
                                        elseif k == 5 && i == 2 && rxnrun.snsoptions.drc_energies_tst == true && solver_rs.rs_sns_tst_cnt > 0     # kinetic sum error - current time point 
                                            ktype = "kinetic sum error - current time point"
                                            ktol = x__kineticsumerr_curr 
                                        elseif k == 6 && i == 2 && rxnrun.snsoptions.drc_energies_tst == true && solver_rs.rs_sns_tst_cnt > 0     # kinetic sum error - remainder of time span 
                                            ktype = "kinetic sum error - remainder of time span"
                                            ktol = x__kineticsumerr_rmdr 
                                        end 
                                        if ktol > 0 
                                            lflag = false
                                            for l in axes(rxnrun.snsoptions.drc_species,1) 
                                                if haskey(rxnsystem.odespecies.dindxs,rxnrun.snsoptions.drc_species[l])
                                                    x__indx = rxnsystem.odespecies.dindxs[rxnrun.snsoptions.drc_species[l]]
                                                    if x__indx > 0 
                                                        if lflag == false 
                                                            if kflag == false 
                                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"",jtype," perturbations..."))
                                                            end 
                                                            kflag = true 
                                                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  ",ktype,"...tolerance: ",ktol))
                                                        end 
                                                        lflag = true
                                                        x__spsindx = 0 
                                                        x__drcs_flag = false 
                                                        x__indxoffset = 0
                                                        if i == 1 
                                                            if solver_rs.rs_sns_drc_dat !== nothing 
                                                                x__drcs = get_view(reshape(view(solver_rs.rs_sns_drc_dat,:,l,solver_rs.rs_sns_fractions_srcindxs),(solver_rs.rs_t_cnt,solver_rs.rs_sns_fractions_cnt)) )
                                                                x__drcs_flag = true 
                                                            end
                                                        elseif i == 2 
                                                            if solver_rs.rs_sns_drc_dat !== nothing
                                                                x__drcs = get_view(reshape(view(solver_rs.rs_sns_drc_dat,:,l,collect(solver_rs.rs_sns_fractions_cnt+1:solver_rs.rs_sns_cnt)),(solver_rs.rs_t_cnt,solver_rs.rs_sns_energies_cnt)) )
                                                                x__drcs_flag = true 
                                                            end 
                                                        end
                                                        if x__drcs_flag == true 
                                                            if k == 1         # absolute - current time point 
                                                                x__drcs_diff = (view(x__drcs,2:size(x__drcs,1),:) .- view(x__drcs,1:(size(x__drcs,1)-1),:)) 
                                                                x__indxoffset = 1
                                                            elseif k == 2     # absolute - remainder of time span 
                                                                x__drcs_diff = (view(x__drcs,axes(x__drcs,1),:) .- reshape(view(x__drcs,size(x__drcs,1),:),(1,size(x__drcs,2)))) 
                                                            elseif k == 3     # fractional - current time point 
                                                                x__drcs_diff = (view(x__drcs,2:size(x__drcs,1),:) .- view(x__drcs,1:(size(x__drcs,1)-1),:)) ./ view(x__drcs,1:(size(x__drcs,1)-1),:) 
                                                                x__indxoffset = 1
                                                            elseif k == 4     # fractional - remainder of time span 
                                                                x__drcs_diff = similar(x__drcs)
                                                                x__drcs_diff .= zero(x__drcs[1])
                                                                for m = axes(x__drcs,1)
                                                                    for n = axes(x__drcs,2) 
                                                                        x__drcs_diff[m,n] = max(abs(x__drcs[m,n] - maximum(view(x__drcs,m:size(x__drcs,1),n))),abs(x__drcs[m,n] - minimum(view(x__drcs,m:size(x__drcs,1),n)))) / abs(x__drcs[m,n])
                                                                    end
                                                                end 
                                                            elseif k == 5 && i == 2 && rxnrun.snsoptions.drc_energies_tst == true && solver_rs.rs_sns_tst_cnt > 0         # kinetic sum error - current time point 
                                                                # assumes kinetic sum of surface reactions is unity at single pathway state
                                                                x__subindxs = get_elemindex(collect(1:solver_rs.rs_sns_energies_cnt),solver_rs.rs_sns_tst_indxs,0)
                                                                # x__drcs_diff = vec(sum(view(x__drcs,:,x__subindxs) ./ reshape(sns_pairs_alpha,1,solver_rs.rs_sns_tst_cnt),dims=2)) .- one(x__drcs[1])     
                                                                x__drcs_diff = vec(sum(view(x__drcs,:,x__subindxs),dims=2)) .- one(x__drcs[1])                                                              
                                                            elseif k == 6 && i == 2 && rxnrun.snsoptions.drc_energies_tst == true && solver_rs.rs_sns_tst_cnt > 0         # kinetic sum error - remainder of time span 
                                                                # assumes kinetic sum of surface reactions is unity at single pathway state
                                                                x__subindxs = get_elemindex(collect(1:solver_rs.rs_sns_energies_cnt),solver_rs.rs_sns_tst_indxs,0)
                                                                # x__drcs_ksum = vec(sum(view(x__drcs,:,x__subindxs) ./ reshape(sns_pairs_alpha,1,solver_rs.rs_sns_tst_cnt),dims=2)) .- one(x__drcs[1])     
                                                                x__drcs_ksum = vec(sum(view(x__drcs,:,x__subindxs),dims=2)) .- one(x__drcs[1])                                                              
                                                                x__drcs_diff = similar(x__drcs_ksum)
                                                                x__drcs_diff .= zero(x__drcs_ksum[1])
                                                                for m = axes(x__drcs_ksum,1)
                                                                    x__drcs_diff[m] = maximum(abs.(view(x__drcs_ksum,m:size(x__drcs_ksum,1))))
                                                                end 
                                                            end 
                                                            x__drcs_diff_nx = map(x -> (isnan(x) ? zero(x) : x),x__drcs_diff)
                                                            x__indxs = findall(x -> abs(x) >= ktol, x__drcs_diff_nx) 
                                                            if size(x__indxs,1) > 0 
                                                                x__spsindx = maximum([x[1] for x in x__indxs]) + x__indxoffset + 1     # ' + 1' term is to indicate single pathway state starts at the next index after the last index that fails the tolerance check
                                                                if x__spsindx > solver_rs.loop_params.sps_onsetindex 
                                                                    if x__spsindx > solver_rs.rs_t_cnt 
                                                                        x__spsindx = -1 
                                                                    end 
                                                                else 
                                                                    x__spsindx = 0 
                                                                end 
                                                            else 
                                                                x__spsindx = 1 + x__indxoffset 
                                                                if x__spsindx <= solver_rs.loop_params.sps_onsetindex 
                                                                    x__spsindx = 0 
                                                                end
                                                            end 
                                                            if x__spsindx < 0 
                                                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    ",rxnrun.snsoptions.drc_species[l],"...failed...max |fin|: ",maximum(abs.(view(x__drcs_diff_nx,size(x__drcs_diff_nx,1),:)))))
                                                                solver_rs.loop_params.sps_onsetflag = false 
                                                                solver_rs.loop_params.sps_onsetindex = -1
                                                            else 
                                                                if 0 < (x__spsindx-x__indxoffset) && (x__spsindx-x__indxoffset) <= size(x__drcs_diff_nx,1) 
                                                                    err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"    ",rxnrun.snsoptions.drc_species[l],"...passed...max |sps|: ",maximum(abs.(view(x__drcs_diff_nx,(x__spsindx-x__indxoffset):size(x__drcs_diff_nx,1),:))))) 
                                                                else 
