                if err_flag == false 
                    if solver_rs.loop_params.sps_onsetflag == true && solver_rs.loop_params.sps_onsetindex > 0 
                        if solver_rs.loop_params.sps_onsetindex > 1 
                            if solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex] <= rxnrun.spsoptions.timespan_extend_maxchg * solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex - 1] 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"single pathway state onset detected at timestep ",solver_rs.loop_params.sps_onsetindex," (",solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex]," seconds)"))
                            else 
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"single pathway state onset time step is too large"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  relative size of ",solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex - 1]," -> ",solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex]," is greater than ",log_value(err_flag, err_msg, 100 * (rxnrun.spsoptions.timespan_extend_maxchg - 1.0), 1, true, false, false),"%"))
                                err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"  updating minimum single pathway state onset to ",(rxnrun.spsoptions.timespan_extend_maxchg * solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex - 1])," seconds"))
                                solver_rs.loop_params.sps_tmin = solver_rs.loop_params.loop_t_max
                                solver_rs.loop_params.sps_textend = false 
                                solver_rs.loop_params.sps_onsetflag = true
                                solver_rs.loop_params.sps_onsetindex = 0 
                            end 
                        else 
                            err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"single pathway state onset detected at timestep ",solver_rs.loop_params.sps_onsetindex," (",solver_rs.rs_t_dat[solver_rs.loop_params.sps_onsetindex]," seconds)"))
                        end 
                    else 
                        solver_rs.loop_params.sps_onsetflag = true
                        solver_rs.loop_params.sps_onsetindex = 0 
                    end 
                end 

                # Show error message, as needed
                if err_flag == false 
                    if solver_rs.loop_params.sps_onsetflag == false || solver_rs.loop_params.sps_onsetindex <= 0 
                        err_flag, err_msg = log_messageAB_msgopts(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string(show_prfx,"single pathway state not detected"))
                        solver_rs.loop_params.sps_onsetflag = true
                        solver_rs.loop_params.sps_onsetindex = 0 
                    end 
                end 
            end 
        end 
        
        return err_flag, err_msg
    end 

    function Rxn__ModelSystem__Temprun__ReactionsRates(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnsystem, rxnrun, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, solv_num_fmt, solv_num_prec, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals, du, u, u_o, t, G, G_o, k, k_o, un, rn, rp) 

        # This function calculates the rates of the ODE species 
        #   PARAMETERS 
        #     du : species rates           : t x S 
        #     u  : species fractions       : t x S 
        #     p  : parameters                
        #     t  : elapsed time            : t 
        #     G  : reaction energies       : t x G 
        #     k  : reaction rate constants : t x R 
        #     un : species molar rates     : t x S 
        #     rn : reaction rates          : t x R 
        #     rp : reaction pair rates     : t x P 

        if err_flag == false 

            # Initialize error checking 
            err_flag = false 
            err_msg = "" 

            # Initialize output arrays
            if err_flag == false 
                du .= zero(eltype(du[1])) 
                if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0
                    G .= zero(eltype(G[1])) 
                end 
                k  .= zero(eltype(k[1])) 
                un .= zero(eltype(un[1]))
                rn .= zero(eltype(rn[1])) 
                rp .= zero(eltype(rp[1])) 
            end 

            # Iterate through time array 
            if err_flag == false 
                x__u      = zeros(eltype(u[1]),temprun_odeparams.ode_cnt) 
                x__u_zero = zero(eltype(u[1]))
                x__u_one  =  one(eltype(u[1]))
                if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0 
                    x__G = zeros(eltype(G[1]),temprun_relGparams.aryG_cnt) 
                else 
                    x__G = deepcopy(G)
                end 
                x__k      = zeros(eltype(k[1]),temprun_rxnparams.rxns_cnt) 
                x__r      = zeros(eltype(rn[1]),temprun_rxnparams.rxns_cnt) 
                x__r_zero = zero(eltype(rn[1]))
                x__r_one  =  one(eltype(rn[1]))
                u_copy              = true
                use_scaling_uscale  = false 
                use_scaling_tflag   = false 
                use_scaling_tfactor = one(eltype(u[1]))
                use_scaling_tunityflag = true 
                use_num_fmt         = rxnrun.solveroptions.ode_num_fmt_str 
                use_num_prec        = rxnrun.solveroptions.ode_num_prec 
                if length(solv_num_fmt) > 0 
                    use_num_fmt = solv_num_fmt 
                    use_num_prec = solv_num_prec 
                end 
                rxns_adsfluxfactors = convert.(eltype(u[1]),temprun_rxnparams.rxns_adsfluxfactors)
                initial_flag        = true 
                initial_gasflag     = true 
                for i in axes(t,1) 

                    # Initialize temporary variables
                    x__u .= view(u,i,:)
                    if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0
                        x__G .= convert.(eltype(G[1]),G_o)
                    end 
                    x__k .= convert.(eltype(k[1]),k_o) 
                    x__r .= x__r_zero

                    # Enforce constant fractions
                    if err_flag == false 
                        for j in 1:temprun_odeparams.ode_cnt 
                            if temprun_odeparams.ode_const_flags[j] == true 
                                x__u[j] = convert(eltype(u[1]),temprun_odeparams.ode_const_vals[j])
                            end 
                        end 
                    end 

                    # Calculate rate constants 
                    if err_flag == false 
                        err_flag, err_msg = Rxn__Calc__RateConstants(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, temprun_constparams, temprun_odeparams, temprun_rxnparams, temprun_relGparams, temprun_kcnstparams, ode_include_spcs_g, ode_include_spcs_n, ode_include_rxns_r, x__u, u_o, t[i], x__G, x__k, k_o, initial_flag, initial_gasflag, u_copy, use_scaling_uscale, use_scaling_tflag, use_scaling_tfactor, use_scaling_tunityflag, use_num_fmt, use_num_prec, rxns_adsfluxfactors, interp_itpobj_relG_itpcmpds_scaled, interp_xvals_tmp, interp_xvals_cache, interp_gvals_tmp, interp_gvals_cache, use_tmpcaches, tmpcache_pairdists, tmpcache_rbfvals, tmpcache_polynomial, tmpcache_ptlvals) 
                        if size(rxnsystem.reactions.kupdmodes_nonassigned,1) > 0
                            G[i,:] .= x__G
                        end 
                        k[i,:] .= x__k
                    end 
                    
                    # Calculate reaction rates 
                    if err_flag == false 
                        for j in 1:temprun_rxnparams.rxns_cnt
                            if temprun_rxnparams.rxns_ratefactors_nzflags[j] == true
                                x__r[j] = x__r_one
                                for k in 1:temprun_odeparams.ode_cnt 
                                    if temprun_rxnparams.coeffs_gamma_nzflags[k,j] == true
                                        if temprun_odeparams.ode_const_flags[k] == true 
                                            x__ur = temprun_odeparams.ode_const_vals[k]
                                        else 
                                            x__ur = x__u[k]
                                        end 
                                        if x__ur != x__u_zero
                                            if temprun_odeparams.ode_refstates_nuflags[k] == true
                                                x__ur /= temprun_odeparams.ode_refstates_values[k]
                                            end
                                            if x__ur != x__u_one 
                                                if temprun_rxnparams.coeffs_gamma_nzpuflags[k,j] == true 
                                                    if x__r[j] != x__r_one 
                                                        x__r[j] *= x__ur 
                                                    else 
                                                        x__r[j]  = x__ur 
                                                    end 
                                                elseif temprun_rxnparams.coeffs_gamma_nznuflags[k,j] == true 
                                                    x__r[j] /= x__ur 
                                                else 
                                                    if x__r[j] != x__r_one 
                                                        x__r[j] *= x__ur ^ temprun_rxnparams.coeffs_gamma[k,j] 
                                                    else 
                                                        x__r[j]  = x__ur ^ temprun_rxnparams.coeffs_gamma[k,j] 
                                                    end 
                                                end 
                                            end 
                                        else 
                                            x__r[j] = x__r_zero
                                            break 
                                        end 
                                    end 
                                end 
                                if x__r[j] != x__r_zero
                                    if temprun_rxnparams.rxns_ratefactors_nzuflags[j] == false
                                        x__r[j] *= temprun_rxnparams.rxns_ratefactors[j] 
                                    end 
                                    if x__r[j] != x__r_one
                                        x__r[j] *= x__k[j] 
                                    else 
                                        x__r[j]  = x__k[j] 
                                    end 
                                end 
                            else
                                x__r[j] = x__r_zero
                            end 
                            rn[i,j] = x__r[j]
                        end 
                        rp[i,:] .= sum(reshape(x__r,1,temprun_rxnparams.rxns_cnt) .* temprun_rxnparams.coeffs_pairs, dims=2) 
                    end 

                    # Calculate species rates 
                    if err_flag == false 
                        for j in 1:temprun_odeparams.ode_cnt 
                            du[i,j] = x__u_zero
                            un[i,j] = x__u_zero
                            for k in 1:temprun_rxnparams.rxns_cnt 
                                if x__r[k] != x__r_zero
                                    if temprun_rxnparams.coeffs_alpha_t_nzflags[k,j] == true
                                        if temprun_rxnparams.coeffs_alpha_t_nzpuflags[k,j] == true
                                            un[i,j] += x__r[k]
                                        elseif temprun_rxnparams.coeffs_alpha_t_nznuflags[k,j] == true 
                                            un[i,j] -= x__r[k]
                                        else
                                            un[i,j] += temprun_rxnparams.coeffs_alpha_t[k,j] * x__r[k]
                                        end
                                    end
                                    if temprun_rxnparams.coeffs_alphabeta_t_nzflags[k,j] == true
                                        if temprun_rxnparams.coeffs_alphabeta_t_nzpuflags[k,j] == true 
                                            du[i,j] += x__r[k]
                                        elseif temprun_rxnparams.coeffs_alphabeta_t_nznuflags[k,j] == true
                                            du[i,j] -= x__r[k]
                                        else
                                            du[i,j] += temprun_rxnparams.coeffs_alphabeta_t[k,j] * x__r[k]
                                        end
                                    end
                                end 
                            end 
                        end 
                    end 

                    # Check error state
                    if err_flag == true 
                        break 
                    end 
                end 
            end 

            # Remove outliers from array data
            if err_flag == false  
                Rxn__ModelSystem__Temprun__ReactionsRates__RemoveOutliers(t, un) 
                Rxn__ModelSystem__Temprun__ReactionsRates__RemoveOutliers(t, rn) 
                Rxn__ModelSystem__Temprun__ReactionsRates__RemoveOutliers(t, rp) 
            end 
        end 

        return err_flag, err_msg
    end 

    function Rxn__ModelSystem__Temprun__ReactionsRates__RemoveOutliers(t, ary) 
        
        # Perform array outlier checking
        xzero = zero(eltype(ary)) 
        stol  = 0.5 
        rtol  = 10
        for i in axes(ary,2)
            for h in 1:2 
                dtol = (h == 2 ? 5 : 100) 
                xpos = 1
                for j in 1:size(ary,1)-5
                    if j >= xpos
                        slope_1 = (ary[j+1,i] - ary[j+0,i]) / (t[j+1] - t[j+0]) 
                        slope_2 = (ary[j+2,i] - ary[j+1,i]) / (t[j+2] - t[j+1]) 
                        slope_3 = (ary[j+4,i] - ary[j+3,i]) / (t[j+4] - t[j+3]) 
                        slope_4 = (ary[j+5,i] - ary[j+4,i]) / (t[j+5] - t[j+4]) 
                        xsum1 = ary[j+0,i] + ary[j+1,i] + ary[j+4,i] + ary[j+5,i]
                        xavg1 = xsum1 / 4 
                        xmin1 = min(ary[j+0,i],ary[j+1,i],ary[j+4,i],ary[j+5,i]) 
                        xmax1 = max(ary[j+0,i],ary[j+1,i],ary[j+4,i],ary[j+5,i]) 
                        xrng1 = max(xmax1 - xavg1, xavg1 - xmin1)
                        xdev1 = xrng1 / abs(xavg1)
                        xsum2 = ary[j+0,i] + ary[j+1,i] + ary[j+3,i] + ary[j+4,i] + ary[j+5,i]
                        xavg2 = xsum2 / 5 
                        xmin2 = min(ary[j+0,i],ary[j+1,i],ary[j+3,i],ary[j+4,i],ary[j+5,i]) 
                        xmax2 = max(ary[j+0,i],ary[j+1,i],ary[j+3,i],ary[j+4,i],ary[j+5,i]) 
                        xrng2 = max(xmax2 - xavg2, xavg2 - xmin2)
                        xdev2 = xrng2 / abs(xavg2)
                        xsum3 = ary[j+0,i] + ary[j+1,i] + ary[j+2,i] + ary[j+3,i] + ary[j+4,i] + ary[j+5,i]
                        xavg3 = xsum3 / 6 
                        xmin3 = min(ary[j+0,i],ary[j+1,i],ary[j+2,i],ary[j+3,i],ary[j+4,i],ary[j+5,i]) 
                        xmax3 = max(ary[j+0,i],ary[j+1,i],ary[j+2,i],ary[j+3,i],ary[j+4,i],ary[j+5,i]) 
                        xrng3 = max(xmax3 - xavg3, xavg3 - xmin3)
                        xdev3 = xrng3 / abs(xavg3)
                        if xrng2 > dtol * xrng1 && xrng3 > dtol * xrng1 
                            ary[j+2,i] = (ary[j+1,i] + ary[j+4,i]) / 2 
                            ary[j+3,i] = (ary[j+1,i] + ary[j+4,i]) / 2 
                            j = j+3
                            xpos = j+1 
                        elseif xrng2 <= dtol * xrng1 && xrng3 > dtol * xrng1 
                            ary[j+2,i] = (ary[j+1,i] + ary[j+3,i]) / 2 
                            j = j+2
                            xpos = j+1 
                        elseif (sign(slope_1) != sign(slope_2) || abs(slope_2) < (1 - stol) * abs(slope_1) || abs(slope_2) > (1 + stol) * abs(slope_1)) && (sign(slope_4) != sign(slope_2) || abs(slope_2) < (1 - stol) * abs(slope_4) || abs(slope_2) > (1 + stol) * abs(slope_4))
                            if sign(slope_1) == sign(slope_3) && (1 - stol) * abs(slope_1) <= abs(slope_3) && abs(slope_3) <= (1 + stol) * abs(slope_1)
                                ary[j+2,i] = (ary[j,i] + ary[j+1,i] + ary[j+3,i] + ary[j+4,i]) / 4 
                                j = j+2
                                xpos = j+1
                            elseif sign(slope_1) == sign(slope_4) && (1 - stol) * abs(slope_1) <= abs(slope_4) && abs(slope_4) <= (1 + stol) * abs(slope_1)
                                if sign(slope_1) != sign(slope_3) || abs(slope_3) < (1 - stol) * abs(slope_1) || abs(slope_3) > (1 + stol) * abs(slope_1)
                                    ary[j+2,i] = (ary[j,i] + ary[j+1,i] + ary[j+4,i] + ary[j+5,i]) / 4 
                                    ary[j+3,i] = (ary[j,i] + ary[j+1,i] + ary[j+4,i] + ary[j+5,i]) / 4 
                                    j = j+3
                                    xpos = j+1
                                end 
                            end 
                        end
                    end
                end 
            end 
        end 
    end 

    function Rxn__ModelSystem__Temprun__DataOutput(msgrslts, msgoptions, msgtxtprfx, err_flag, err_msg, rxnrun, temprun_logging, initflag, filesffx, wkscnt, wksname, wksinicell, rownames, colnames, tbldata, msgconfig_isrunonly)

        # Check error state 
        if err_flag == false 

            # Initialize error checking 
            err_flag = false 
            err_msg = "" 

            # Check dimensions - rows
            if err_flag == false 
                if size(rownames,1) > 0 && size(rownames,1) != size(tbldata,1)
                    err_flag = true 
                end 
            end 

            # Check dimensions - columns
            if err_flag == false 
                if size(colnames,1) <= 0 || size(colnames,1) != size(tbldata,2)
                    err_flag = true 
                end 
            end 

            # Output to Excel, as needed 
            if err_flag == false 
                if rxnrun.outputoptions.files_format == "XLSX" || rxnrun.outputoptions.files_format == "XLSX_TXT" || rxnrun.outputoptions.files_format == "TXT_XLSX"
                    if initflag == true 
                        XLSX.openxlsx(joinpath(temprun_logging.path_run,"RunData__OUTPUT.xlsx"), mode="w") do xf
                            wkscnt = wkscnt + 1
                            s = xf[wkscnt]
                            XLSX.rename!(s, "General")
                            if size(rownames,1) > 0 
                                xl__wksdat = hcat(vcat([""],rownames),vcat(conv_Vec2Row(colnames),tbldata))
                            else
                                xl__wksdat = vcat(conv_Vec2Row(colnames),tbldata)
                            end 
                            XLSX.setdata!(s, XLSX.CellRef(wksinicell), xl__wksdat)
                        end
                    else 
                        swksname = wksname 
                        if length(swksname) > 31 
                            swksname = join(SubString(swksname,1,31), "")
                        end 
                        XLSX.openxlsx(joinpath(temprun_logging.path_run,"RunData__OUTPUT.xlsx"), mode="rw") do xf
                            XLSX.addsheet!(xf, swksname)
                            wkscnt = wkscnt + 1
                            s = xf[wkscnt]
                            if size(rownames,1) > 0 
                                xl__wksdat = hcat(vcat([""],rownames),vcat(conv_Vec2Row(colnames),tbldata))
                            else
                                xl__wksdat = vcat(conv_Vec2Row(colnames),tbldata)
                            end 
                            XLSX.setdata!(s, XLSX.CellRef(wksinicell), xl__wksdat)
                        end
                    end 
                end 
            end 

            # Output to text, as needed 
            if err_flag == false 
                if rxnrun.outputoptions.files_format == "TXT" || rxnrun.outputoptions.files_format == "XLSX_TXT" || rxnrun.outputoptions.files_format == "TXT_XLSX"
                    if msgconfig_isrunonly == true 
                        if isa(msgoptions,ct__MessageConfigs) == true
                            xpath = msgoptions.vec[1].log_file_folderpath 
                        else 
                            xpath = msgoptions.log_file_folderpath
                        end 
                    else 
                        xpath = rxnrun.logging.rxnrun.logging.path_cl 
                    end 
                    if xpath != "" 
                        x__ts = now() 
                        x__path = joinpath(xpath,string("RunData__OUTPUT__",replace(replace(filesffx,"<" => "("),">" => ")"),".txt"))
                        x__fsobj = open(x__path,"w")
                        close(x__fsobj)
                        x__fsobj = open(x__path,"a")
                        x__outputconfigs = ct__MessageConfig(x__ts, x__ts, false, true, "", xpath, joinpath(xpath,string("RunData__OUTPUT__",replace(replace(filesffx,"<" => "("),">" => ")"),".txt")), x__fsobj) 
                        log_table_msgopts(msgrslts, x__outputconfigs, "", err_flag, err_msg, false, false, 1, 1, rownames, colnames, tbldata, rxnrun.output_num_prec, true, true, true)
                        close(x__fsobj)
                        if msgconfig_isrunonly == false && rxnrun.logging.subfolder_run_path != "" 
                            cp(joinpath(xpath,string("RunData__OUTPUT__",replace(replace(filesffx,"<" => "("),">" => ")"),".txt")), joinpath(joinpath(xpath,rxnrun.logging.subfolder_run_path),string("RunData__OUTPUT__",replace(replace(filesffx,"<" => "("),">" => ")"),".txt")), force=true)
                        end
                    end 
                end
            end 
        end 

        return err_flag, err_msg, wkscnt
    end 

    function (f::ct__Sensitivity_Problem)(rdat, pf_values) 
        
        # Check sensitivity parameters 
        global gbl_sns_chunk_ctr += 1 
        if f.sns_apply == true && f.sns_cnt > 0 && pf_values !== nothing 
            err_flag = false 
            err_msg = "" 

            # Initialize logging
            if err_flag == false 
                msgtxtprfx = f.msgtxtprfx
                msgprfx = (f.sns_chunkcnt > 1 ? "  " : "")
                if f.log_actions == true && f.sns_chunkcnt > 1
                    err_flag, err_msg = log_messageAB_msgopts(f.msgrslts, f.msgoptions, msgtxtprfx, err_flag, err_msg, true, true, 1, 1, string("chunk ",gbl_sns_chunk_ctr," of ",f.sns_chunkcnt,"...","factors ",(f.sns_setsize * (f.sns_setindex - 1) + f.sns_chunksize * (gbl_sns_chunk_ctr - 1) + 1)," to ",min((f.sns_setsize * (f.sns_setindex - 1) + f.sns_chunksize * (gbl_sns_chunk_ctr - 0) + 0),f.sns_tot)," of ",f.sns_tot))
                end 
                pf_pindxs = collect((f.sns_setsize * (f.sns_setindex - 1) + f.sns_chunksize * (gbl_sns_chunk_ctr - 1) + 1):min((f.sns_setsize * (f.sns_setindex - 1) + f.sns_chunksize * (gbl_sns_chunk_ctr - 0) + 0),f.sns_tot))
                pf_cindxs = collect((f.sns_chunksize * (gbl_sns_chunk_ctr - 1) + 1):min((f.sns_chunksize * (gbl_sns_chunk_ctr - 0) + 0),f.sns_cnt))
                pf_sindxs = get_view(view(f.sns_srcindxs, pf_cindxs)) 
                pf_pnames = get_view(view(f.sns_names, pf_cindxs)) 
                pf_pvalues = get_view(view(pf_values, pf_cindxs)) 
                pf_numtype = eltype(pf_values) 
                pf_pkfactors = ones(pf_numtype,f.temprun_rxnparams.rxns_cnt)
            end 

            # Solve system over specified timespan
            if err_flag == false 
                if f.log_actions == true 
                    err_flag, err_msg = log_messageAB_msgopts(f.msgrslts, f.msgoptions, string(msgtxtprfx,msgprfx), err_flag, err_msg, true, true, 1, 1, string("running solver")) 
                end 

                # Construct initial values 
                if err_flag == false 
                    if f.log_actions == true 
                        err_flag, err_msg = log_messageAB_msgopts(f.msgrslts, f.msgoptions, string(msgtxtprfx,msgprfx), err_flag, err_msg, true, true, 1, 1, string("  constructing initial values")) 
                    end 
                    x__u_o = convert.(pf_numtype,f.u_o) 
                    if f.sns_mode == "fractions" 
                        x__u_o[pf_sindxs] .= x__u_o[pf_sindxs] .+ view(pf_values,pf_cindxs)
                    end 
                    if f.use_scaling_uscale == true && f.temprun_odeparams.ode_scaling_uscale_flag == true
                        x__u_o .= x__u_o ./ f.temprun_odeparams.ode_scaling_uscale_factors
                    end 
                    ode_const_vals = convert.(pf_numtype,f.temprun_odeparams.ode_const_vals) 
                    if f.sns_mode == "fractions" 
                        ode_const_vals[pf_sindxs] .= ode_const_vals[pf_sindxs] .+ view(pf_values,pf_cindxs)
                    end 
                    x__du = zeros(pf_numtype,size(x__u_o)) 
                end 

                # Initialize perturbation factors 
                if err_flag == false 

                    # initial fractions perturbations 
                    if err_flag == false 
                        if f.sns_mode == "fractions" 

                            # initial gas pressures 
                            if f.temprun_odeparams.ode_krate_gaspress_flag == true
                                @inbounds for i in 1:f.temprun_rxnparams.rxns_cnt 
                                    if f.temprun_odeparams.ode_rxntypes[i] == "adsorb"
                                        x__gasodeindx = f.temprun_odeparams.ode_adsorb_gas_odeindxs[i] 
                                        if x__gasodeindx > 0 
                                            x__indx = get_elemindex(pf_sindxs,x__gasodeindx,0)
                                            x__n = abs(f.temprun_rxnparams.coeffs_alpha_t[i,x__gasodeindx])
                                            if x__indx > 0 && x__n != zero(x__n) 
                                                pf_pkfactors[i] = (((f.temprun_odeparams.ode_inifracs[x__gasodeindx] + pf_pvalues[x__indx]) / f.temprun_odeparams.ode_inifracs[x__gasodeindx]) ^ x__n) 
                                            end 
                                        end 
                                    end 
                                end 
                                @inbounds for i in 1:f.temprun_rxnparams.rxns_cnt  
                                    if f.temprun_odeparams.ode_rxntypes[i] == "desorb" 
