                        rxns_adsfluxfactors = zeros(pf_numtype,f.rxnsystem.reactions.cnt)
                        for i in 1:f.rxnsystem.reactions.cnt 
                            if get_elemindex(f.rxnsystem.reactions.rxntypes_ads_hke,i,0) > 0 
