                                    x__adssurfphsindx = get_elemindex(f.rxnsystem.phases.indxs_surfs,x__adsphaseindx,0)
                                    if x__gasodegasindx > 0 && x__adssurfphsindx > 0 
                                        x__n = abs(f.rxnsystem.reactions.coeffs_alpha[x__gasodeindx,i])
                                        rxns_adsfluxfactors[i] = convert(pf_numtype, 
