                                                                                    f.rxnsystem.phases.cellareas_m2[x__adssurfphsindx]
                                                                                ) / 
                                                                                (
                                                                                    x__n * 
                                                                                    f.temprun_odeparams.ode_gas_momentum[x__gasodegasindx] * 
                                                                                    f.temprun_constparams.nvs_kbt_hp_1_s
                                                                                )
                                                                            ) ^ x__n
                                                                        )
                                                                    ) 
                                    end 
                                end 
                            end 
                        end 
